        private object CanModifyCustomNPC(BaseEntity entity)
        {
            if (entity != null && (entity as RandomRaider) != null)
                return false;
            return null;
        }

        private void Init()
        {
            _ = this;
            permission.RegisterPermission(adminPerm, this);
            permission.RegisterPermission(usePerm, this);
            permission.RegisterPermission(joinPerm, this);
            cmd.AddChatCommand("cobaltwar", this, nameof(randomRaidChat));
            cmd.AddChatCommand("cw", this, nameof(randomRaidChat));

            PCDDATA = Interface.Oxide.DataFileSystem.GetFile(Name + "/PlayersTC");
            RAIDDATA = Interface.Oxide.DataFileSystem.GetFile(Name + "/RaidCooldownData");
            LOGDATA = Interface.Oxide.DataFileSystem.GetFile(Name + "/PlayerLog");
            LOGDATARB = Interface.Oxide.DataFileSystem.GetFile(Name + "/PlayerLogRaidableBases");
            LoadData();
            itemNameToConfig.Clear();
            entitySkinToConfig.Clear();
            itemLootSpawn.Clear();
            ItemConfig.Clear();
            Unsubscribe(nameof(OnLootSpawn));
            Unsubscribe(nameof(OnExplosiveDropped));
            Unsubscribe(nameof(OnExplosiveThrown));

            if (configData.cobaltWar == null)
            {
                configData.cobaltWar = GetBaseConfig().cobaltWar;
                SaveConfig();
            }

            if (configData.raidSettings.raidTypes.Count <= 0)
            {
                raidConfig easy = new raidConfig(20, 1, 7, true, 140f, 780, new List<string>(), new List<string>() { "explosive.satchel" }, 1, 0.95, false, new List<string>() { "easy" });
                easy.NextWaveSeconds = 165;
                easy.rockets = 1;
                easy.explosives = 1;
                easy.WinDrop = 1;
                easy.playerDamage = 0.95f;
                easy.AutoTurretDamage = 1f;
                easy.aimConeScale = 2.2f;
                easy.spawnTanks = false;
                easy.tankCount = 0;
                easy.notifyOwners = false;

                raidConfig medium = new raidConfig(28, 2, 14, true, 260f, 1100, new List<string>(), new List<string>() { "explosive.satchel", "explosive.timed" }, 2, 1.15, true, new List<string>() { "medium" });
                medium.NextWaveSeconds = 130;
                medium.rockets = 8;
                medium.explosives = 4;
                medium.WinDrop = 1;
                medium.playerDamage = 1.15f;
                medium.AutoTurretDamage = 0.8f;
                medium.aimConeScale = 1.3f;
                medium.spawnCopter = new List<string>() { "medium" };
                medium.spawnTanks = false;
                medium.tankCount = 0;
                medium.notifyOwners = false;

                raidConfig hard = new raidConfig(38, 3, 20, true, 360f, 1500, new List<string>(), new List<string>() { "explosive.satchel", "explosive.timed" }, 3, 1.25, true, new List<string>() { "hard" });
                hard.NextWaveSeconds = 120;
                hard.rockets = 14;
                hard.explosives = 7;
                hard.WinDrop = 2;
                hard.playerDamage = 1.25f;
                hard.AutoTurretDamage = 0.7f;
                hard.aimConeScale = 1.05f;
                hard.spawnCopter = new List<string>() { "hard" };
                hard.spawnTanks = true;
                hard.tankCount = 1;
                hard.notifyOwners = false;

                raidConfig expert = new raidConfig(55, 4, 26, true, 450f, 2100, new List<string>(), new List<string>() { "explosive.satchel", "explosive.timed" }, 4, 1.9, true, new List<string>() { "expert" });
                expert.NextWaveSeconds = 105;
                expert.rockets = 32;
                expert.explosives = 18;
                expert.WinDrop = 3;
                expert.playerDamage = 1.5f;
                expert.AutoTurretDamage = 0.6f;
                expert.aimConeScale = 0.8f;
                expert.FireMlrs = true;
                expert.spawnCopter = new List<string>() { "expert", "expert" };
                expert.spawnTanks = true;
                expert.tankCount = 1;
                expert.notifyOwners = false;

                raidConfig nightmare = new raidConfig(70, 5, 34, true, 600f, 2700, new List<string>(), new List<string>() { "explosive.satchel", "explosive.timed" }, 5, 2.4, true, new List<string>() { "nightmare" });
                nightmare.NextWaveSeconds = 90;
                nightmare.rockets = 48;
                nightmare.explosives = 26;
                nightmare.WinDrop = 4;
                nightmare.playerDamage = 1.75f;
                nightmare.AutoTurretDamage = 0.5f;
                nightmare.aimConeScale = 0.65f;
                nightmare.FireMlrs = true;
                nightmare.spawnCopter = new List<string>() { "nightmare", "nightmare" };
                nightmare.spawnTanks = true;
                nightmare.tankCount = 2;
                nightmare.notifyOwners = false;

                configData.raidSettings.raidTypes.Add("easy", easy);
                configData.raidSettings.raidTypes.Add("medium", medium);
                configData.raidSettings.raidTypes.Add("hard", hard);
                configData.raidSettings.raidTypes.Add("expert", expert);
                configData.raidSettings.raidTypes.Add("nightmare", nightmare);
                SaveConfig();
            }

            foreach (var jconfigs in configData.raidSettings.raidTypes.Values)
            {
                if (jconfigs.juggernaut == null)
                {
                    jconfigs.juggernaut = new List<string>() { "easy" };
                    SaveConfig();
                }
            }

            Action<raidConfig, bool, int> ensureTankDefaults = (raid, enabled, count) =>
            {
                if (raid == null)
                    return;

                if (raid.tankCount < 0)
                    raid.tankCount = 0;

                if (raid.spawnTanks && raid.tankCount == 0)
                    raid.tankCount = count;

                if (!raid.spawnTanks && raid.tankCount > 0)
                    raid.spawnTanks = enabled;
            };

            bool updatedTankDefaults = false;
            raidConfig existingRaid;
            if (configData.raidSettings.raidTypes.TryGetValue("easy", out existingRaid))
                ensureTankDefaults(existingRaid, false, 0);
            if (configData.raidSettings.raidTypes.TryGetValue("medium", out existingRaid))
                ensureTankDefaults(existingRaid, false, 0);
            if (configData.raidSettings.raidTypes.TryGetValue("hard", out existingRaid))
            {
                ensureTankDefaults(existingRaid, true, 1);
                if (!existingRaid.spawnTanks && existingRaid.tankCount <= 0)
                {
                    existingRaid.spawnTanks = true;
                    existingRaid.tankCount = 1;
                    updatedTankDefaults = true;
                }
            }
            if (configData.raidSettings.raidTypes.TryGetValue("expert", out existingRaid))
            {
                ensureTankDefaults(existingRaid, true, 1);
                if (!existingRaid.spawnTanks && existingRaid.tankCount <= 0)
                {
                    existingRaid.spawnTanks = true;
                    existingRaid.tankCount = 1;
                    updatedTankDefaults = true;
                }
            }
            if (configData.raidSettings.raidTypes.TryGetValue("nightmare", out existingRaid))
            {
                ensureTankDefaults(existingRaid, true, 2);
                if (!existingRaid.spawnTanks && existingRaid.tankCount <= 0)
                {
                    existingRaid.spawnTanks = true;
                    existingRaid.tankCount = 2;
                    updatedTankDefaults = true;
                }
            }
            if (updatedTankDefaults)
                SaveConfig();

            if (configData.copterSettings.copterProfile.Count <= 0)
            {
                configData.copterSettings.copterProfile.Add("easy", new copterConfig(1100, 1) { strafeTime = 55f, totalStrafe = 3 });
                configData.copterSettings.copterProfile.Add("medium", new copterConfig(1900, 1) { strafeTime = 50f, totalStrafe = 4 });
                configData.copterSettings.copterProfile.Add("hard", new copterConfig(2600, 2) { strafeTime = 45f, totalStrafe = 5 });
                configData.copterSettings.copterProfile.Add("expert", new copterConfig(3800, 3) { strafeTime = 30f, totalStrafe = 9 });
                configData.copterSettings.copterProfile.Add("nightmare", new copterConfig(5200, 4) { strafeTime = 25f, totalStrafe = 11 });
                SaveConfig();
            }

            if (configData.settingsRB.raidSettings.Count <= 0)
            {
                configData.settingsRB.raidSettings.Add(0, new RBConfig(3, true, 10, 320, new List<string>() { "easy" }));
                configData.settingsRB.raidSettings.Add(1, new RBConfig(3, true, 10, 320, new List<string>() { "easy", "medium" }));
                configData.settingsRB.raidSettings.Add(2, new RBConfig(3, true, 10, 320, new List<string>() { "easy", "medium" }));
                configData.settingsRB.raidSettings.Add(3, new RBConfig(3, true, 10, 320, new List<string>() { "easy", "medium", "hard" }));
                configData.settingsRB.raidSettings.Add(4, new RBConfig(3, true, 10, 320, new List<string>() { "hard", "expert", "nightmare" }));
                SaveConfig();
            }

            if (configData.settingsNPCKILLS == null)
                configData.settingsNPCKILLS = new ConfigData.SettingsNPCKILLS();
            if (configData.settingsNPCKILLS.npcSettings == null)
                configData.settingsNPCKILLS.npcSettings = new Dictionary<string, NPCConfig>();

            if (configData.settingsNPCKILLS.npcSettings.Count <= 0)
            {
                configData.settingsNPCKILLS.npcSettings.Add("scientistnpc_heavy", new NPCConfig(30, false, 10, 320, new List<string>() { "medium" }));
                configData.settingsNPCKILLS.npcSettings.Add("scientistnpc_oilrig", new NPCConfig(60, false, 10, 320, new List<string>() { "easy" }));
                configData.settingsNPCKILLS.npcSettings.Add("scientistnpc_patrol", new NPCConfig(60, false, 10, 320, new List<string>() { "easy" }));
                configData.settingsNPCKILLS.npcSettings.Add("scientistnpc_junkpile", new NPCConfig(60, false, 10, 320, new List<string>() { "easy" }));
                SaveConfig();
            }

            if (configData.juggernautProfile.Count <= 0)
            {
                configData.juggernautProfile.Add("easy", new juggernautConfig(new Dictionary<int, int>() { { 2, 1 } }, 520f, new List<string>()) { playerDamage = 1.05f, aimConeScale = 1.6f, NpcNames = new List<string>() { "Джаггернаут \"Кобальт\"" } });
                configData.juggernautProfile.Add("medium", new juggernautConfig(new Dictionary<int, int>() { { 1, 1 }, { 2, 1 } }, 750f, new List<string>()) { playerDamage = 1.25f, aimConeScale = 1.2f, NpcNames = new List<string>() { "Джаггернаут \"Кобальт\"" } });
                configData.juggernautProfile.Add("hard", new juggernautConfig(new Dictionary<int, int>() { { 1, 2 }, { 2, 1 } }, 950f, new List<string>()) { playerDamage = 1.35f, aimConeScale = 1.0f, NpcNames = new List<string>() { "Джаггернаут \"Кобальт\"" } });
                configData.juggernautProfile.Add("expert", new juggernautConfig(new Dictionary<int, int>() { { 1, 2 }, { 2, 2 }, { 3, 1 } }, 1200f, new List<string>()) { playerDamage = 1.5f, aimConeScale = 0.9f, NpcNames = new List<string>() { "Джаггернаут \"Кобальт\"" } });
