        private void OnServerShutdown()
        {
            ForceStopAndRestoreActiveDefenders();
        }

        private void ForceStopAndRestoreActiveDefenders()
        {
            EnsurePlayerDataStructures();

            StopAllRaids(false);

            foreach (BasePlayer current in BasePlayer.activePlayerList)
            {
                if (current == null)
                    continue;

                if (current.IsWounded())
                    current.StopWounded();

                if (current.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
                {
                    StopPlayerSpectating(current);

                    try
                    {
                        current.StopSpectating();
                    }
                    catch { }

                    try
                    {
                        current.SetPlayerFlag(BasePlayer.PlayerFlags.Spectating, false);
                        current.UpdateNetworkGroup();
                        current.SendNetworkUpdateImmediate();
                    }
                    catch { }
                }

                if (defenderSnapshots.ContainsKey(current.userID))
                    RestoreDefenderSnapshotNow(current);

                CuiHelper.DestroyUi(current, "RtimerS" + BlockName);
                CuiHelper.DestroyUi(current, JoinUiName);
                current.SendConsoleCommand("gametip.hidegametip");
            }

            SaveData();
            SaveRaidData();
            SaveLogData();
            SaveRBLogData();
        }

        private void StopAllRaids(bool notifyOwners = true)
        {
            stopSearch();
            triggeredRaidScheduleGeneration++;

            foreach (var war in activeCobaltWars.Values.ToList())
                war?.CancelWar(notifyOwners ? "CobaltWarCancelledAdmin" : null, notifyOwners);

            foreach (var war in activeCobaltWars.Values.ToList())
            {
                if (war != null)
                    DestroyCobaltSupportDronesForWar(war.warId);
            }

            List<EventRandomManager> list = Facepunch.Pool.Get<List<EventRandomManager>>();
            list.AddRange(EventRandomManager._AllRaids);

            foreach (var eventRunning in list)
            {
                eventRunning.Destroy();
            }
            EventRandomManager._AllRaids.Clear();
            Facepunch.Pool.FreeUnmanaged<EventRandomManager>(ref list);
        }

        private CobaltWarSession FindWarForAdminStop()
        {
            return GetActiveWars()
                .Where(x => x != null && !x.IsEnded && x.phase != CobaltWarPhase.Cleanup)
                .OrderByDescending(x => x.phase == CobaltWarPhase.Active ? 4 : x.phase == CobaltWarPhase.Preparation ? 3 : x.phase == CobaltWarPhase.Registration ? 2 : x.phase == CobaltWarPhase.Buyout ? 1 : 0)
                .ThenByDescending(x => x.warId)
                .FirstOrDefault();
        }

        private void StopCurrentWarForAdmin(BasePlayer player)
        {
            if (player == null)
                return;

            CobaltWarSession war = FindWarForAdminStop();
            if (war == null)
            {
                SendReply(player, lang.GetMessage("CobaltAdminStopNoWar", this, player.UserIDString));
                return;
            }

            bool useGracefulCleanup = war.phase == CobaltWarPhase.Active;
            war.CancelWarForAdmin("CobaltWarCancelledAdmin", true, useGracefulCleanup ? CobaltAdminCancelReturnDelaySeconds : 0f);

            if (useGracefulCleanup)
                SendReply(player, lang.GetMessage("CobaltAdminStopGraceStarted", this, player.UserIDString), war.targetName, GetGrid(war.location), Mathf.CeilToInt(CobaltAdminCancelReturnDelaySeconds));
            else
                SendReply(player, lang.GetMessage("CobaltAdminStopStarted", this, player.UserIDString), war.targetName, GetGrid(war.location));
        }

        private void OnServerInitialized()
        {
            groundLayer = LayerMask.GetMask("Construction", "Terrain", "World");
            terrainLayer = LayerMask.GetMask("Terrain", "World", "Water");
            BuildingLayer = LayerMask.GetMask("Construction");
            spawnObstacleLayer = LayerMask.GetMask("Construction", "World", "Default", "Deployed", "Deployable", "Tree", "Resource", "Vehicle_Large", "Vehicle_Movement");
            Vector3Down = new Vector3(0f, -1f, 0f);

            EnsurePlayerDataStructures();
            pcdData.tcData.Clear();

            foreach (BuildingPrivlidge find in BaseNetworkable.serverEntities.OfType<BuildingPrivlidge>())
            {
                if (Convert.ToBoolean(RaidableBases?.CallHook("EventTerritory", find.transform.position)))
                    continue;

                foreach (var playerNameID in find.authorizedPlayers)
                {
                    if (!pcdData.tcData.ContainsKey(playerNameID))
                        pcdData.tcData.Add(playerNameID, new List<ulong>() { find.net.ID.Value });
                    else if (!pcdData.tcData[playerNameID].Contains(find.net.ID.Value))
                        pcdData.tcData[playerNameID].Add(find.net.ID.Value);
                }
            }

            BackfillExistingPlayersForProtection();
            SaveData();
            CobaltDiagnosticLog("idle", $"Инициализация завершена: tcData={pcdData?.tcData?.Count ?? 0}, randomTimer={configData?.settings?.randomTimer == true}, wealthScanner={configData?.cobaltWar?.enabled == true && configData.cobaltWar.enableWealthScanner}, raidEsp={configData?.cobaltWar?.enabled == true && configData.cobaltWar.enableRaidAreaPlayerEsp}, activePlayers={BasePlayer.activePlayerList.Count}.");
            if (configData.settings.randomTimer)
            {
                float automaticSearchInterval = GetAutomaticRaidSearchIntervalSeconds();
                CobaltDiagnosticLog("idle", $"Регистрация таймера автопоиска: interval={automaticSearchInterval:0.##}с.");
                timer.Every(automaticSearchInterval, () => startRestartSearch());
            }
            if (configData.cobaltWar != null && configData.cobaltWar.enabled && configData.cobaltWar.enableWealthScanner)
            {
                float wealthScanInterval = GetWealthScanIntervalSeconds();
                CobaltDiagnosticLog("idle", $"Регистрация таймера wealth scan: interval={wealthScanInterval:0.##}с.");
                timer.Every(wealthScanInterval, () => ScanWealthTargets());
            }
            timer.Every(30f, () => AuditTransientRuntimeState());

            if (!configData.settings.lockAirdrop)
            {
                Unsubscribe(nameof(CanLootEntity));
            }

            timer.Once(2f, () =>
            {
                foreach (var player in BasePlayer.activePlayerList)
                {
                    if (player != null && player.IsConnected)
                    {
                        if (ShouldTrackRaidTargetActivityNow())
                            TouchRaidTargetActivity(player, true);
                        if (HasAnyPendingRaidPlayerState(player.userID.Get()))
                        {
                            TryAwardDeferredCobaltXp(player);
                            TryRestoreDeferredPlayer(player);
                        }
                    }
                }
            });

            RefreshIdleOptimizationState();

        }

