        private void SyncDefenderSnapshotsFromData()
        {
            defenderSnapshots.Clear();
            snapshotSavemen.Clear();
            EnsurePlayerDataStructures();

            foreach (var entry in pcdData.defenderSnapshots)
            {
                if (entry.Value != null)
                {
                    defenderSnapshots[entry.Key] = entry.Value;
                    BasePlayer saveman = FindStoredSaveman(entry.Value);
                    if (saveman != null)
                        snapshotSavemen.Add(saveman.userID.Get());
                }
            }
        }

        private void BackfillExistingPlayersForProtection()
        {
            EnsurePlayerDataStructures();

            if (pcdData.firstSeenBackfilled)
                return;

            bool changed = false;
            DateTime veteranTime = DateTime.UtcNow.Subtract(TimeSpan.FromHours(Math.Max(1f, configData?.cobaltWar?.newPlayerProtectionHours ?? 48f) + 1f));

            foreach (BasePlayer player in BasePlayer.activePlayerList)
                changed |= RecordPlayerFirstSeen(player, veteranTime);

            foreach (BasePlayer player in BasePlayer.sleepingPlayerList)
                changed |= RecordPlayerFirstSeen(player, veteranTime);

            pcdData.firstSeenBackfilled = true;

            if (changed)
                SaveData();
        }

        private bool RecordPlayerFirstSeen(BasePlayer player, DateTime? overrideTime = null)
        {
            if (player == null || player.IsNpc)
                return false;

            EnsurePlayerDataStructures();

            if (pcdData.firstSeen.ContainsKey(player.userID.Get()))
                return false;

            pcdData.firstSeen[player.userID.Get()] = overrideTime ?? DateTime.UtcNow;
            return true;
        }

