        private bool IsCobaltDiagnosticEnabled(string category)
        {
            if (configData?.diagnostics == null || !configData.diagnostics.enabled)
                return false;

            switch ((category ?? string.Empty).Trim().ToLowerInvariant())
            {
                case "idle":
                    return configData.diagnostics.idleScan;
                case "raid":
                    return configData.diagnostics.activeRaid;
                case "purchase":
                    return configData.diagnostics.purchases;
                case "external":
                    return configData.diagnostics.externalCalls;
                default:
                    return false;
            }
        }

        private void CobaltDiagnosticLog(string category, string message)
        {
            if (!IsCobaltDiagnosticEnabled(category) || string.IsNullOrWhiteSpace(message))
                return;

            string normalizedCategory = (category ?? "other").Trim().ToLowerInvariant();
            string line = $"[{DateTime.Now:HH:mm:ss}] {message}";
            try
            {
                Directory.CreateDirectory(CobaltDiagnosticsDirectory);
                string filePath = Path.Combine(CobaltDiagnosticsDirectory, $"CobaltWar_{normalizedCategory}_{DateTime.Now:yyyy-MM-dd}.txt");
                File.AppendAllText(filePath, line + System.Environment.NewLine, System.Text.Encoding.UTF8);
            }
            catch (Exception ex)
            {
                PrintError($"CobaltDiagnosticLog write failed: {ex.Message}");
            }

            if (configData?.diagnostics?.console == true)
                Puts($"[CobaltWar:{normalizedCategory}] {message}");
        }

        private string SummarizeExternalValue(object value)
        {
            if (value == null)
                return "null";

            if (value is BasePlayer basePlayer)
                return $"BasePlayer:{basePlayer.displayName}({basePlayer.userID})";

            if (value is BaseEntity baseEntity)
                return $"{baseEntity.GetType().Name}[{(baseEntity.net != null ? baseEntity.net.ID.Value.ToString() : "no-net")}]";

            if (value is IPlayer iPlayer)
                return $"IPlayer:{iPlayer.Id}";

            if (value is string stringValue)
                return stringValue.Length > 80 ? stringValue.Substring(0, 80) + "..." : stringValue;

            if (value is bool || value is int || value is uint || value is ulong || value is float || value is double || value is decimal)
                return Convert.ToString(value, System.Globalization.CultureInfo.InvariantCulture);

            if (value is Vector3 vector)
                return $"Vector3({vector.x:0.##},{vector.y:0.##},{vector.z:0.##})";

            if (value is Array array)
                return $"{value.GetType().Name}[{array.Length}]";

            if (value is System.Collections.ICollection collection)
                return $"{value.GetType().Name}[{collection.Count}]";

            return value.GetType().Name;
        }

        private string SummarizeExternalArgs(object[] args)
        {
            if (args == null || args.Length == 0)
                return "none";

            int take = Math.Min(args.Length, 5);
            List<string> parts = new List<string>(take + (args.Length > take ? 1 : 0));
            for (int i = 0; i < take; i++)
                parts.Add($"{i}={SummarizeExternalValue(args[i])}");

            if (args.Length > take)
                parts.Add($"+{args.Length - take} more");

            return string.Join(", ", parts);
        }

        private object TraceExternalPluginCall(string category, Plugin plugin, string hookName, params object[] args)
        {
            string pluginName = plugin?.Name ?? "null";
            string normalizedHook = string.IsNullOrEmpty(hookName) ? "unknown" : hookName;
            string argsSummary = SummarizeExternalArgs(args);

            if (plugin == null)
            {
                CobaltDiagnosticLog(category, $"External plugin call skipped: plugin={pluginName}, hook={normalizedHook}, args=[{argsSummary}].");
                return null;
            }

            long started = DateTime.UtcNow.Ticks;
            CobaltDiagnosticLog(category, $"External plugin call begin: plugin={pluginName}, hook={normalizedHook}, args=[{argsSummary}].");
            try
            {
                object result = plugin.Call(normalizedHook, args);
                double elapsedMs = TimeSpan.FromTicks(DateTime.UtcNow.Ticks - started).TotalMilliseconds;
                CobaltDiagnosticLog(category, $"External plugin call end: plugin={pluginName}, hook={normalizedHook}, elapsedMs={elapsedMs:0.###}, result={SummarizeExternalValue(result)}.");
                return result;
            }
            catch (Exception ex)
            {
                double elapsedMs = TimeSpan.FromTicks(DateTime.UtcNow.Ticks - started).TotalMilliseconds;
                CobaltDiagnosticLog(category, $"External plugin call failed: plugin={pluginName}, hook={normalizedHook}, elapsedMs={elapsedMs:0.###}, error={ex.GetType().Name}: {ex.Message}.");
                throw;
            }
        }

        private object TraceExternalHookCall(string category, string hookName, params object[] args)
        {
            string normalizedHook = string.IsNullOrEmpty(hookName) ? "unknown" : hookName;
            string argsSummary = SummarizeExternalArgs(args);
            long started = DateTime.UtcNow.Ticks;
            CobaltDiagnosticLog(category, $"External hook begin: hook={normalizedHook}, args=[{argsSummary}].");
            try
            {
                object result = Interface.CallHook(normalizedHook, args);
                double elapsedMs = TimeSpan.FromTicks(DateTime.UtcNow.Ticks - started).TotalMilliseconds;
                CobaltDiagnosticLog(category, $"External hook end: hook={normalizedHook}, elapsedMs={elapsedMs:0.###}, result={SummarizeExternalValue(result)}.");
                return result;
            }
            catch (Exception ex)
            {
                double elapsedMs = TimeSpan.FromTicks(DateTime.UtcNow.Ticks - started).TotalMilliseconds;
                CobaltDiagnosticLog(category, $"External hook failed: hook={normalizedHook}, elapsedMs={elapsedMs:0.###}, error={ex.GetType().Name}: {ex.Message}.");
                throw;
            }
        }

        private bool HasAnyTransientRuntimeWork()
        {
            if (activeCobaltWars.Count > 0 || pendingRedeploys.Count > 0 || defenderSnapshots.Count > 0)
                return true;

            if (defenderRespawnProtection.Count > 0 || cobaltTankDebrisCleanupWindows.Count > 0 || cobaltHeliDebrisCleanupWindows.Count > 0)
                return true;

            if (defenderActivity.Count > 0 || raidTargetActivity.Count > 0)
                return true;

            if (displayedWarUi.Count > 0 || minimizedWarUi.Count > 0 || renderedWarUiState.Count > 0 || minimizedRenderedWarUiState.Count > 0)
                return true;

            if (pcdData?.deferredXpDamage != null && pcdData.deferredXpDamage.Count > 0)
                return true;

            if (pcdData?.deferredXpRewards != null && pcdData.deferredXpRewards.Count > 0)
                return true;

            return false;
        }

        private bool HasAnyRaidRuntimeOrSearchWork()
        {
            return activeCobaltWars.Count > 0
                || pendingRedeploys.Count > 0
                || defenderSnapshots.Count > 0
                || QueuedRoutine != null
                || QueuedRoutinePlayer != null
                || wealthScanInProgress;
        }

        private bool ShouldKeepPlayerInputHookSubscribed()
        {
            return ShouldTrackRaidTargetActivityNow()
                || activeCobaltWars.Count > 0
                || pendingRedeploys.Count > 0
                || defenderSnapshots.Count > 0;
        }

        private bool ShouldKeepIdleInventoryHooksSubscribed()
        {
            return activeCobaltWars.Count > 0
                || pendingRedeploys.Count > 0
                || defenderSnapshots.Count > 0
                || protectedDefenderItems.Count > 0
                || pendingProtectedSplits.Count > 0;
        }

        private bool ShouldRunProtectedItemAuditTimer()
        {
            return protectedDefenderItems.Count > 0;
        }

        private bool ShouldRunMinimizedUiTimer()
        {
            return minimizedWarUi.Count > 0;
        }

        private bool ShouldRunRaidAreaEspTimer()
        {
            if (configData?.cobaltWar == null || !configData.cobaltWar.enabled || !configData.cobaltWar.enableRaidAreaPlayerEsp)
                return false;

            return activeCobaltWars.Values.Any(war => ShouldRenderRaidAreaPlayerEsp(war));
        }

        private void RefreshPlayerInputHookSubscription()
        {
            bool shouldSubscribe = ShouldKeepPlayerInputHookSubscribed();
            if (shouldSubscribe == playerInputHookSubscribed)
                return;

            if (shouldSubscribe)
                Subscribe(nameof(OnPlayerInput));
            else
                Unsubscribe(nameof(OnPlayerInput));

            playerInputHookSubscribed = shouldSubscribe;
        }

        private void RefreshIdleInventoryHookSubscriptions()
        {
            bool shouldSubscribe = ShouldKeepIdleInventoryHooksSubscribed();
            if (shouldSubscribe == idleInventoryHooksSubscribed)
                return;

            string[] hookNames =
            {
                nameof(CanDropActiveItem),
                nameof(CanMoveItem),
                nameof(CanAcceptItem),
                nameof(OnItemDropped),
                nameof(OnItemAddedToContainer),
                nameof(OnItemSplit),
                nameof(OnItemRemovedFromContainer),
                nameof(OnItemStacked),
                nameof(OnItemAction)
            };

            foreach (string hookName in hookNames)
            {
                if (shouldSubscribe)
                    Subscribe(hookName);
                else
                    Unsubscribe(hookName);
            }

            idleInventoryHooksSubscribed = shouldSubscribe;
        }

        private void RefreshMinimizedUiTimerState()
        {
            bool shouldRun = ShouldRunMinimizedUiTimer();
            if (shouldRun)
            {
                if (minimizedUiTimer == null)
                    minimizedUiTimer = timer.Every(2f, UpdateMinimizedUis);
            }
            else if (minimizedUiTimer != null)
            {
                minimizedUiTimer.Destroy();
                minimizedUiTimer = null;
            }
        }

        private void RefreshRaidAreaEspTimerState()
        {
            bool shouldRun = ShouldRunRaidAreaEspTimer();
            if (shouldRun)
            {
                if (raidAreaEspTimer == null)
                    raidAreaEspTimer = timer.Every(GetRaidAreaPlayerEspUpdateInterval(), () => UpdateRaidAreaPlayerEsp());
            }
            else if (raidAreaEspTimer != null)
            {
                raidAreaEspTimer.Destroy();
                raidAreaEspTimer = null;
            }
        }

        private void RefreshProtectedItemAuditTimerState()
        {
            bool shouldRun = ShouldRunProtectedItemAuditTimer();
            if (shouldRun)
            {
                if (protectedItemAuditTimer == null)
                    protectedItemAuditTimer = timer.Every(0.75f, () => AuditProtectedDefenderItems());
            }
            else if (protectedItemAuditTimer != null)
            {
                protectedItemAuditTimer.Destroy();
                protectedItemAuditTimer = null;
            }
        }

        private void RefreshIdleOptimizationState()
        {
            RefreshPlayerInputHookSubscription();
            RefreshIdleInventoryHookSubscriptions();
            RefreshMinimizedUiTimerState();
            RefreshRaidAreaEspTimerState();
            RefreshProtectedItemAuditTimerState();
        }

        private bool ShouldTrackRaidTargetActivityNow()
        {
            if (configData?.cobaltWar == null || !configData.cobaltWar.protectAfkRaidTargets || configData.cobaltWar.afkRaidTargetSeconds <= 0f)
                return false;

            return HasAnyRaidRuntimeOrSearchWork();
        }

        private bool TryGetCachedWealthBalance(ulong userId, out int balance, float cacheSeconds = 15f)
        {
            balance = 0;
            if (userId == 0UL || ServerRewards == null)
                return false;

            double now = GrabCurrentTime();
            CachedWealthBalanceState cached;
            if (cachedWealthBalances.TryGetValue(userId, out cached))
            {
                if (cached != null && cached.expiresAt > now)
                {
                    balance = cached.balance;
                    return true;
                }

                cachedWealthBalances.Remove(userId);
            }

            try
            {
                balance = Convert.ToInt32(ServerRewards.Call("CheckPoints", userId));
                cachedWealthBalances[userId] = new CachedWealthBalanceState
                {
                    balance = balance,
                    expiresAt = now + Mathf.Max(1f, cacheSeconds)
                };
                return true;
            }
            catch
            {
                return false;
            }
        }
