            public class PluginVersionData
            {
                [JsonProperty(PropertyName = "Основная версия")]
                public int Major { get; set; }

                [JsonProperty(PropertyName = "Дополнительная версия")]
                public int Minor { get; set; }

                [JsonProperty(PropertyName = "Исправление")]
                public int Patch { get; set; }

                [JsonProperty(PropertyName = "Major")]
                private int LegacyMajor
                {
                    set => Major = value;
                }

                [JsonProperty(PropertyName = "Minor")]
                private int LegacyMinor
                {
                    set => Minor = value;
                }

                [JsonProperty(PropertyName = "Patch")]
                private int LegacyPatch
                {
                    set => Patch = value;
                }

                public bool ShouldSerializeLegacyMajor() => false;

                public bool ShouldSerializeLegacyMinor() => false;

                public bool ShouldSerializeLegacyPatch() => false;

                public PluginVersionData()
                {
                }

                public PluginVersionData(VersionNumber version)
                {
                    Major = version.Major;
                    Minor = version.Minor;
                    Patch = version.Patch;
                }

                public VersionNumber ToVersionNumber()
                {
                    return new VersionNumber(Major, Minor, Patch);
                }
            }

            [JsonProperty(PropertyName = "Версия плагина")]
            public PluginVersionData Version { get; set; }
        }

