        private bool MatchesLegacyAutoSupportDroneDefaults(Dictionary<string, int> values)
        {
            if (values == null)
                return false;

            return GetConfiguredRaidTypeValue(values, "easy", -1) == 1
                && GetConfiguredRaidTypeValue(values, "medium", -1) == 2
                && GetConfiguredRaidTypeValue(values, "hard", -1) == 2
                && GetConfiguredRaidTypeValue(values, "expert", -1) == 3
                && GetConfiguredRaidTypeValue(values, "nightmare", -1) == 4;
        }

        private bool MatchesLegacyMinOnlineDefaults(Dictionary<string, int> values)
        {
            if (values == null)
                return false;

            return GetConfiguredRaidTypeValue(values, "easy", -1) == 4
                && GetConfiguredRaidTypeValue(values, "medium", -1) == 4
                && GetConfiguredRaidTypeValue(values, "hard", -1) == 7
                && GetConfiguredRaidTypeValue(values, "expert", -1) == 10
                && GetConfiguredRaidTypeValue(values, "nightmare", -1) == 10;
        }

