        protected override void LoadConfig()
        {
            base.LoadConfig();
            configData = Config.ReadObject<ConfigData>();

            if ((configData.Version?.ToVersionNumber() ?? default(VersionNumber)) < Version)
                UpdateConfigValues();

            if (configData?.settings != null)
                configData.settings.totalRaids = 1;

            NormalizeRuntimeConfigValues();

            Config.WriteObject(configData, true);
        }

