        protected override void SaveConfig() => Config.WriteObject(configData, true);

        private void NormalizeRuntimeConfigValues()
        {
            ConfigData baseConfig = GetBaseConfig();

            if (configData == null)
            {
                configData = baseConfig;
                return;
            }

            if (configData.diagnostics == null)
                configData.diagnostics = baseConfig.diagnostics;

            if (configData.cobaltWar == null)
            {
                configData.cobaltWar = baseConfig.cobaltWar;
                return;
            }

            if (configData.cobaltWar.walkInNaturalRespawnActivationSeconds < 0f)
                configData.cobaltWar.walkInNaturalRespawnActivationSeconds = baseConfig.cobaltWar.walkInNaturalRespawnActivationSeconds;
            if (configData.cobaltWar.cleanupFinalizeRetrySeconds <= 0f)
                configData.cobaltWar.cleanupFinalizeRetrySeconds = baseConfig.cobaltWar.cleanupFinalizeRetrySeconds;
            if (configData.cobaltWar.cleanupFinalizeMaxRetries < 0)
                configData.cobaltWar.cleanupFinalizeMaxRetries = baseConfig.cobaltWar.cleanupFinalizeMaxRetries;
            if (configData.cobaltWar.minimumAutoRaidTargetTurrets <= 0)
                configData.cobaltWar.minimumAutoRaidTargetTurrets = baseConfig.cobaltWar.minimumAutoRaidTargetTurrets;
        }

        private void UpdateConfigValues()
        {
            PrintWarning("Обнаружено обновление версии конфига.");

            ConfigData baseConfig = GetBaseConfig();

            if ((configData.Version?.ToVersionNumber() ?? default(VersionNumber)) < new VersionNumber(1, 4, 6))
            {
                configData = baseConfig;
                PrintWarning("Конфиг был обновлен до актуальной версии.");
            }
            else
            {
                if (configData.cobaltWar == null)
                    configData.cobaltWar = baseConfig.cobaltWar;
                else
                {
                    if (string.IsNullOrEmpty(configData.cobaltWar.factionName))
                        configData.cobaltWar.factionName = baseConfig.cobaltWar.factionName;
                    if (configData.cobaltWar.ownerBuyoutSeconds <= 0f)
                        configData.cobaltWar.ownerBuyoutSeconds = baseConfig.cobaltWar.ownerBuyoutSeconds;
                    if (configData.cobaltWar.ownerBuyoutAutoRaidCooldownMinutes <= 0)
                        configData.cobaltWar.ownerBuyoutAutoRaidCooldownMinutes = baseConfig.cobaltWar.ownerBuyoutAutoRaidCooldownMinutes;
                    if (!configData.cobaltWar.protectNewPlayers && baseConfig.cobaltWar.protectNewPlayers)
                        configData.cobaltWar.protectNewPlayers = baseConfig.cobaltWar.protectNewPlayers;
                    if (!configData.cobaltWar.removeAfkDefenders && baseConfig.cobaltWar.removeAfkDefenders)
                        configData.cobaltWar.removeAfkDefenders = baseConfig.cobaltWar.removeAfkDefenders;
                    if (!configData.cobaltWar.blockDuringArenaTournamentRegistration && baseConfig.cobaltWar.blockDuringArenaTournamentRegistration)
                        configData.cobaltWar.blockDuringArenaTournamentRegistration = baseConfig.cobaltWar.blockDuringArenaTournamentRegistration;
                    if (!configData.cobaltWar.blockArenaTournamentParticipants && baseConfig.cobaltWar.blockArenaTournamentParticipants)
                        configData.cobaltWar.blockArenaTournamentParticipants = baseConfig.cobaltWar.blockArenaTournamentParticipants;

                    if (configData.cobaltWar.enabledRaidTypes == null)
                        configData.cobaltWar.enabledRaidTypes = new Dictionary<string, bool>(baseConfig.cobaltWar.enabledRaidTypes);
                    else
                    {
                        Dictionary<string, bool> normalizedEnabledRaidTypes = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase);
                        foreach (var enabledEntry in configData.cobaltWar.enabledRaidTypes)
                        {
                            string raidTypeKey = enabledEntry.Key?.Trim().ToLowerInvariant();
                            if (string.IsNullOrEmpty(raidTypeKey))
                                continue;

                            normalizedEnabledRaidTypes[raidTypeKey] = enabledEntry.Value;
                        }

                        foreach (var defaultEnabledEntry in baseConfig.cobaltWar.enabledRaidTypes)
                        {
                            if (!normalizedEnabledRaidTypes.ContainsKey(defaultEnabledEntry.Key))
                                normalizedEnabledRaidTypes.Add(defaultEnabledEntry.Key, defaultEnabledEntry.Value);
                        }

                        configData.cobaltWar.enabledRaidTypes = normalizedEnabledRaidTypes;
                    }

                    if (configData.cobaltWar.minOnlineByRaidType == null)
                        configData.cobaltWar.minOnlineByRaidType = new Dictionary<string, int>(baseConfig.cobaltWar.minOnlineByRaidType);
                    else
                    {
                        Dictionary<string, int> normalizedThresholds = new Dictionary<string, int>();
                        foreach (var thresholdEntry in configData.cobaltWar.minOnlineByRaidType)
                        {
                            string thresholdKey = thresholdEntry.Key?.Trim().ToLowerInvariant();
                            if (string.IsNullOrEmpty(thresholdKey))
                                continue;

                            normalizedThresholds[thresholdKey] = Mathf.Max(0, thresholdEntry.Value);
                        }

                        foreach (var defaultThreshold in baseConfig.cobaltWar.minOnlineByRaidType)
                        {
                            if (!normalizedThresholds.ContainsKey(defaultThreshold.Key))
                                normalizedThresholds.Add(defaultThreshold.Key, defaultThreshold.Value);
                        }

                        if (MatchesLegacyMinOnlineDefaults(normalizedThresholds))
                            normalizedThresholds = new Dictionary<string, int>(baseConfig.cobaltWar.minOnlineByRaidType);

                        configData.cobaltWar.minOnlineByRaidType = normalizedThresholds;
                    }

                    double legacySuccessDefenseXp = configData.cobaltWar.successDefenseXp > 0d
                        ? configData.cobaltWar.successDefenseXp
                        : baseConfig.cobaltWar.successDefenseXp;
                    if (configData.cobaltWar.successDefenseXpByRaidType == null)
                    {
                        configData.cobaltWar.successDefenseXpByRaidType = baseConfig.cobaltWar.successDefenseXpByRaidType
                            .ToDictionary(x => x.Key, x => legacySuccessDefenseXp);
                    }
                    else
                    {
                        Dictionary<string, double> normalizedVictoryXpByRaidType = new Dictionary<string, double>();
                        foreach (var xpEntry in configData.cobaltWar.successDefenseXpByRaidType)
                        {
                            string raidTypeKey = xpEntry.Key?.Trim().ToLowerInvariant();
                            if (string.IsNullOrEmpty(raidTypeKey))
                                continue;

                            normalizedVictoryXpByRaidType[raidTypeKey] = Math.Max(0d, xpEntry.Value);
                        }

                        foreach (var defaultXpEntry in baseConfig.cobaltWar.successDefenseXpByRaidType)
                        {
                            if (!normalizedVictoryXpByRaidType.ContainsKey(defaultXpEntry.Key))
                                normalizedVictoryXpByRaidType.Add(defaultXpEntry.Key, legacySuccessDefenseXp);
                        }

                        configData.cobaltWar.successDefenseXpByRaidType = normalizedVictoryXpByRaidType;
                    }

                    if ((configData.Version?.ToVersionNumber() ?? default(VersionNumber)) < new VersionNumber(3, 0, 1))
                    {
                        configData.cobaltWar.adaptRockBases = baseConfig.cobaltWar.adaptRockBases;
                        configData.cobaltWar.rockBaseExtraCopters = baseConfig.cobaltWar.rockBaseExtraCopters;
                    }
                    if (configData.cobaltWar.newPlayerProtectionHours <= 0f)
                        configData.cobaltWar.newPlayerProtectionHours = baseConfig.cobaltWar.newPlayerProtectionHours;
                    if (configData.cobaltWar.afkDefenderSeconds <= 0f)
                        configData.cobaltWar.afkDefenderSeconds = baseConfig.cobaltWar.afkDefenderSeconds;
                    if (configData.cobaltWar.afkMoveThreshold <= 0f)
                        configData.cobaltWar.afkMoveThreshold = baseConfig.cobaltWar.afkMoveThreshold;
                    if (configData.cobaltWar.afkRaidTargetSeconds <= 0f)
                    {
                        configData.cobaltWar.afkRaidTargetSeconds = baseConfig.cobaltWar.afkRaidTargetSeconds;
                        configData.cobaltWar.protectAfkRaidTargets = baseConfig.cobaltWar.protectAfkRaidTargets;
                    }
                    if (!configData.cobaltWar.preventSkillTreeXpLossDuringRaid.HasValue)
                        configData.cobaltWar.preventSkillTreeXpLossDuringRaid = baseConfig.cobaltWar.preventSkillTreeXpLossDuringRaid;
                    if (configData.cobaltWar.rockBaseHeightDelta <= 0f)
                        configData.cobaltWar.rockBaseHeightDelta = baseConfig.cobaltWar.rockBaseHeightDelta;
                    if (configData.cobaltWar.rockBaseSlopeAngle <= 0f)
                        configData.cobaltWar.rockBaseSlopeAngle = baseConfig.cobaltWar.rockBaseSlopeAngle;
                    if (configData.cobaltWar.rockBaseMinElevatedSamples <= 0)
                        configData.cobaltWar.rockBaseMinElevatedSamples = baseConfig.cobaltWar.rockBaseMinElevatedSamples;
                    if (configData.cobaltWar.tankSpawnRadiusMin <= 0f)
                        configData.cobaltWar.tankSpawnRadiusMin = baseConfig.cobaltWar.tankSpawnRadiusMin;
                    if (configData.cobaltWar.tankSpawnRadiusMax <= 0f)
                        configData.cobaltWar.tankSpawnRadiusMax = baseConfig.cobaltWar.tankSpawnRadiusMax;
                    if (configData.cobaltWar.rockBaseTankSpawnRadiusMin <= 0f)
                        configData.cobaltWar.rockBaseTankSpawnRadiusMin = baseConfig.cobaltWar.rockBaseTankSpawnRadiusMin;
                    if (configData.cobaltWar.rockBaseTankSpawnRadiusMax <= 0f)
                        configData.cobaltWar.rockBaseTankSpawnRadiusMax = baseConfig.cobaltWar.rockBaseTankSpawnRadiusMax;
                    if (configData.cobaltWar.maxTankSpawnSlopeAngle <= 0f)
                        configData.cobaltWar.maxTankSpawnSlopeAngle = baseConfig.cobaltWar.maxTankSpawnSlopeAngle;
                    if (configData.cobaltWar.tankAttackDistance <= 0f)
                        configData.cobaltWar.tankAttackDistance = baseConfig.cobaltWar.tankAttackDistance;
                    if (configData.cobaltWar.tankShellIntervalSeconds <= 0f)
                        configData.cobaltWar.tankShellIntervalSeconds = baseConfig.cobaltWar.tankShellIntervalSeconds;
                    if (configData.cobaltWar.tankShellExplosionRadius <= 0f)
                        configData.cobaltWar.tankShellExplosionRadius = baseConfig.cobaltWar.tankShellExplosionRadius;
                    if (configData.cobaltWar.tankShellDamageBuildings <= 0f)
                        configData.cobaltWar.tankShellDamageBuildings = baseConfig.cobaltWar.tankShellDamageBuildings;
                    if (configData.cobaltWar.tankShellDamagePlayers <= 0f)
                        configData.cobaltWar.tankShellDamagePlayers = baseConfig.cobaltWar.tankShellDamagePlayers;
                    if (configData.cobaltWar.tankHealth <= 0f)
                        configData.cobaltWar.tankHealth = baseConfig.cobaltWar.tankHealth;
                    if (configData.cobaltWar.tankCoaxDamage <= 0f)
                        configData.cobaltWar.tankCoaxDamage = baseConfig.cobaltWar.tankCoaxDamage;
                    if (configData.cobaltWar.tankRepositionIntervalSeconds <= 0f)
                        configData.cobaltWar.tankRepositionIntervalSeconds = baseConfig.cobaltWar.tankRepositionIntervalSeconds;
                    if (configData.cobaltWar.tankMinimumMoveDistance <= 0f)
                        configData.cobaltWar.tankMinimumMoveDistance = baseConfig.cobaltWar.tankMinimumMoveDistance;
                    if (configData.cobaltWar.tankDestinationTolerance <= 0f)
                        configData.cobaltWar.tankDestinationTolerance = baseConfig.cobaltWar.tankDestinationTolerance;
                    if (!configData.cobaltWar.enableTankReverseRecovery
                        && configData.cobaltWar.tankReverseRecoverySeconds <= 0f
                        && configData.cobaltWar.tankReverseRecoveryThrottle <= 0f
                        && configData.cobaltWar.tankReverseRecoveryTurnStrength <= 0f
                        && configData.cobaltWar.tankReverseRecoveryMaxAttempts <= 0)
                    {
                        configData.cobaltWar.enableTankReverseRecovery = baseConfig.cobaltWar.enableTankReverseRecovery;
                    }
                    if (configData.cobaltWar.tankReverseRecoverySeconds <= 0f)
                        configData.cobaltWar.tankReverseRecoverySeconds = baseConfig.cobaltWar.tankReverseRecoverySeconds;
                    if (configData.cobaltWar.tankReverseRecoveryThrottle <= 0f)
                        configData.cobaltWar.tankReverseRecoveryThrottle = baseConfig.cobaltWar.tankReverseRecoveryThrottle;
                    if (configData.cobaltWar.tankReverseRecoveryTurnStrength <= 0f)
                        configData.cobaltWar.tankReverseRecoveryTurnStrength = baseConfig.cobaltWar.tankReverseRecoveryTurnStrength;
                    if (configData.cobaltWar.tankReverseRecoveryMaxAttempts <= 0)
                        configData.cobaltWar.tankReverseRecoveryMaxAttempts = baseConfig.cobaltWar.tankReverseRecoveryMaxAttempts;
                    configData.cobaltWar.tankReverseRecoverySeconds = Mathf.Clamp(configData.cobaltWar.tankReverseRecoverySeconds, 0.5f, 5f);
                    configData.cobaltWar.tankReverseRecoveryThrottle = Mathf.Clamp(configData.cobaltWar.tankReverseRecoveryThrottle, 0.1f, 1f);
                    configData.cobaltWar.tankReverseRecoveryTurnStrength = Mathf.Clamp(configData.cobaltWar.tankReverseRecoveryTurnStrength, 0f, 1f);
                    configData.cobaltWar.tankReverseRecoveryMaxAttempts = Mathf.Clamp(configData.cobaltWar.tankReverseRecoveryMaxAttempts, 1, 4);
                    if (configData.cobaltWar.npcSiegeRocketMinDistance <= 0f)
                        configData.cobaltWar.npcSiegeRocketMinDistance = baseConfig.cobaltWar.npcSiegeRocketMinDistance;
                    if (configData.cobaltWar.npcSiegeRocketMaxDistance <= 0f)
                        configData.cobaltWar.npcSiegeRocketMaxDistance = baseConfig.cobaltWar.npcSiegeRocketMaxDistance;
                    if (configData.cobaltWar.npcSiegeRocketIntervalSeconds <= 0f)
                        configData.cobaltWar.npcSiegeRocketIntervalSeconds = baseConfig.cobaltWar.npcSiegeRocketIntervalSeconds;
                    if (configData.cobaltWar.npcSiegeRepositionIntervalSeconds <= 0f)
                        configData.cobaltWar.npcSiegeRepositionIntervalSeconds = baseConfig.cobaltWar.npcSiegeRepositionIntervalSeconds;
                    if (configData.cobaltWar.mlrsBurstCount <= 0)
                        configData.cobaltWar.mlrsBurstCount = baseConfig.cobaltWar.mlrsBurstCount;
                    if (configData.cobaltWar.mlrsRocketsPerBurst <= 0)
                        configData.cobaltWar.mlrsRocketsPerBurst = baseConfig.cobaltWar.mlrsRocketsPerBurst;
                    if (configData.cobaltWar.mlrsRocketIntervalSeconds <= 0f)
                        configData.cobaltWar.mlrsRocketIntervalSeconds = baseConfig.cobaltWar.mlrsRocketIntervalSeconds;
                    if (configData.cobaltWar.mlrsBurstIntervalSeconds <= 0f)
                        configData.cobaltWar.mlrsBurstIntervalSeconds = baseConfig.cobaltWar.mlrsBurstIntervalSeconds;
                    if (configData.cobaltWar.mlrsSpreadRadius <= 0f)
                        configData.cobaltWar.mlrsSpreadRadius = baseConfig.cobaltWar.mlrsSpreadRadius;
                    if (configData.cobaltWar.mlrsCallsPerWave <= 0)
                        configData.cobaltWar.mlrsCallsPerWave = baseConfig.cobaltWar.mlrsCallsPerWave;
                    if (configData.cobaltWar.mlrsCallIntervalSeconds <= 0f)
                        configData.cobaltWar.mlrsCallIntervalSeconds = baseConfig.cobaltWar.mlrsCallIntervalSeconds;
                    if (configData.cobaltWar.rockBaseDefenderSpawnRadiusMin <= 0f)
                        configData.cobaltWar.rockBaseDefenderSpawnRadiusMin = baseConfig.cobaltWar.rockBaseDefenderSpawnRadiusMin;
                    if (configData.cobaltWar.rockBaseDefenderSpawnRadiusMax <= 0f)
                        configData.cobaltWar.rockBaseDefenderSpawnRadiusMax = baseConfig.cobaltWar.rockBaseDefenderSpawnRadiusMax;
                    if (configData.cobaltWar.maxDefenderSpawnSlopeAngle <= 0f)
                        configData.cobaltWar.maxDefenderSpawnSlopeAngle = baseConfig.cobaltWar.maxDefenderSpawnSlopeAngle;
                    if (configData.cobaltWar.successDefenseXp < 0d)
                        configData.cobaltWar.successDefenseXp = baseConfig.cobaltWar.successDefenseXp;
                    if (configData.cobaltWar.respawnProtectionSeconds <= 0f)
                        configData.cobaltWar.respawnProtectionSeconds = baseConfig.cobaltWar.respawnProtectionSeconds;
                    if (configData.cobaltWar.rockBaseFallbackCopterProfiles == null || configData.cobaltWar.rockBaseFallbackCopterProfiles.Count == 0)
                        configData.cobaltWar.rockBaseFallbackCopterProfiles = baseConfig.cobaltWar.rockBaseFallbackCopterProfiles;
                    if (configData.cobaltWar.copterWaveInterval < 0)
                        configData.cobaltWar.copterWaveInterval = baseConfig.cobaltWar.copterWaveInterval;
                    if (configData.cobaltWar.maxActiveCopters <= 0)
                        configData.cobaltWar.maxActiveCopters = baseConfig.cobaltWar.maxActiveCopters;
                    if (configData.cobaltWar.tankWaveInterval < 0)
                        configData.cobaltWar.tankWaveInterval = baseConfig.cobaltWar.tankWaveInterval;
                    if (configData.cobaltWar.maxActiveTanks <= 0)
                        configData.cobaltWar.maxActiveTanks = baseConfig.cobaltWar.maxActiveTanks;
                    if (configData.cobaltWar.extraNpcPerActiveHelper < 0)
                        configData.cobaltWar.extraNpcPerActiveHelper = baseConfig.cobaltWar.extraNpcPerActiveHelper;
                    if (configData.cobaltWar.maxExtraNpcPerWaveFromHelpers <= 0)
                        configData.cobaltWar.maxExtraNpcPerWaveFromHelpers = baseConfig.cobaltWar.maxExtraNpcPerWaveFromHelpers;
                    if (configData.cobaltWar.activeHelpersPerExtraWave <= 0)
                        configData.cobaltWar.activeHelpersPerExtraWave = baseConfig.cobaltWar.activeHelpersPerExtraWave;
                    if (configData.cobaltWar.maxExtraWavesFromHelpers < 0)
                        configData.cobaltWar.maxExtraWavesFromHelpers = baseConfig.cobaltWar.maxExtraWavesFromHelpers;
                    if (configData.cobaltWar.extraSecondsPerActiveHelper < 0)
                        configData.cobaltWar.extraSecondsPerActiveHelper = baseConfig.cobaltWar.extraSecondsPerActiveHelper;
                    if (configData.cobaltWar.maxExtraSecondsFromHelpers < 0)
                        configData.cobaltWar.maxExtraSecondsFromHelpers = baseConfig.cobaltWar.maxExtraSecondsFromHelpers;
                    bool supportDroneConfigMissing = configData.cobaltWar.autoSupportDronesByRaidType == null
                        || configData.cobaltWar.maxPurchasedSupportDronesByRaidType == null
                        || configData.cobaltWar.supportDronePurchaseCostByRaidType == null
                        || configData.cobaltWar.supportDroneTierChancesByRaidType == null
                        || configData.cobaltWar.supportDroneTiers == null;
                    if (supportDroneConfigMissing)
                    {
                        configData.cobaltWar.enableSupportDrones = baseConfig.cobaltWar.enableSupportDrones;
                        configData.cobaltWar.autoSpawnSupportDronesWithoutHelpers = baseConfig.cobaltWar.autoSpawnSupportDronesWithoutHelpers;
                    }
                    if (configData.cobaltWar.autoSupportDroneDelaySeconds < 0f)
                        configData.cobaltWar.autoSupportDroneDelaySeconds = baseConfig.cobaltWar.autoSupportDroneDelaySeconds;
                    if (configData.cobaltWar.supportDroneSpawnRadiusMin <= 0f)
                        configData.cobaltWar.supportDroneSpawnRadiusMin = baseConfig.cobaltWar.supportDroneSpawnRadiusMin;
                    if (configData.cobaltWar.supportDroneSpawnRadiusMax <= 0f || configData.cobaltWar.supportDroneSpawnRadiusMax < configData.cobaltWar.supportDroneSpawnRadiusMin)
                        configData.cobaltWar.supportDroneSpawnRadiusMax = baseConfig.cobaltWar.supportDroneSpawnRadiusMax;
                    if (configData.cobaltWar.maxTotalSupportDronesPerWar <= 0)
                        configData.cobaltWar.maxTotalSupportDronesPerWar = baseConfig.cobaltWar.maxTotalSupportDronesPerWar;
                    if (configData.cobaltWar.freePurchasedSupportDronesPerWar < 0)
                        configData.cobaltWar.freePurchasedSupportDronesPerWar = baseConfig.cobaltWar.freePurchasedSupportDronesPerWar;
                    if (configData.cobaltWar.autoSupportDronesByRaidType == null || configData.cobaltWar.autoSupportDronesByRaidType.Count == 0)
                        configData.cobaltWar.autoSupportDronesByRaidType = baseConfig.cobaltWar.autoSupportDronesByRaidType;
                    else if (MatchesLegacyAutoSupportDroneDefaults(configData.cobaltWar.autoSupportDronesByRaidType))
                        configData.cobaltWar.autoSupportDronesByRaidType = new Dictionary<string, int>(baseConfig.cobaltWar.autoSupportDronesByRaidType);
                    if (configData.cobaltWar.maxPurchasedSupportDronesByRaidType == null || configData.cobaltWar.maxPurchasedSupportDronesByRaidType.Count == 0)
                        configData.cobaltWar.maxPurchasedSupportDronesByRaidType = baseConfig.cobaltWar.maxPurchasedSupportDronesByRaidType;
                    if (configData.cobaltWar.supportDronePurchaseCostByRaidType == null || configData.cobaltWar.supportDronePurchaseCostByRaidType.Count == 0)
                        configData.cobaltWar.supportDronePurchaseCostByRaidType = baseConfig.cobaltWar.supportDronePurchaseCostByRaidType;
                    if (configData.cobaltWar.supportDroneTierChancesByRaidType == null || configData.cobaltWar.supportDroneTierChancesByRaidType.Count == 0)
                        configData.cobaltWar.supportDroneTierChancesByRaidType = baseConfig.cobaltWar.supportDroneTierChancesByRaidType;
                    if (configData.cobaltWar.supportDroneTiers == null || configData.cobaltWar.supportDroneTiers.Count == 0)
                        configData.cobaltWar.supportDroneTiers = baseConfig.cobaltWar.supportDroneTiers;
                    else
                    {
                        foreach (var tierEntry in baseConfig.cobaltWar.supportDroneTiers)
                        {
                            SupportDroneTierConfig configuredTier;
                            if (!configData.cobaltWar.supportDroneTiers.TryGetValue(tierEntry.Key, out configuredTier) || configuredTier == null)
                            {
                                configData.cobaltWar.supportDroneTiers[tierEntry.Key] = tierEntry.Value;
                                continue;
                            }

                            if (configuredTier.purchaseSlots <= 0)
                                configuredTier.purchaseSlots = Mathf.Max(1, tierEntry.Value?.purchaseSlots ?? 1);
                        }
                    }
                    bool raidAreaEspConfigMissing = configData.cobaltWar.raidAreaPlayerEspUpdateSeconds <= 0f
                        && configData.cobaltWar.raidAreaPlayerEspDrawDurationSeconds <= 0f
                        && configData.cobaltWar.raidAreaPlayerEspTextSize <= 0;
                    if (raidAreaEspConfigMissing)
                    {
                        configData.cobaltWar.enableRaidAreaPlayerEsp = baseConfig.cobaltWar.enableRaidAreaPlayerEsp;
                        configData.cobaltWar.raidAreaPlayerEspUpdateSeconds = baseConfig.cobaltWar.raidAreaPlayerEspUpdateSeconds;
                        configData.cobaltWar.raidAreaPlayerEspDrawDurationSeconds = baseConfig.cobaltWar.raidAreaPlayerEspDrawDurationSeconds;
                        configData.cobaltWar.raidAreaPlayerEspTextSize = baseConfig.cobaltWar.raidAreaPlayerEspTextSize;
                    }
                    if (configData.cobaltWar.raidAreaPlayerEspUpdateSeconds <= 0f)
                        configData.cobaltWar.raidAreaPlayerEspUpdateSeconds = baseConfig.cobaltWar.raidAreaPlayerEspUpdateSeconds;
                    if (configData.cobaltWar.raidAreaPlayerEspDrawDurationSeconds <= 0f)
                        configData.cobaltWar.raidAreaPlayerEspDrawDurationSeconds = baseConfig.cobaltWar.raidAreaPlayerEspDrawDurationSeconds;
                    if (configData.cobaltWar.raidAreaPlayerEspDrawDurationSeconds < configData.cobaltWar.raidAreaPlayerEspUpdateSeconds)
                        configData.cobaltWar.raidAreaPlayerEspDrawDurationSeconds = Mathf.Max(configData.cobaltWar.raidAreaPlayerEspUpdateSeconds + 0.05f, baseConfig.cobaltWar.raidAreaPlayerEspDrawDurationSeconds);
                    if (configData.cobaltWar.raidAreaPlayerEspTextSize <= 0)
                        configData.cobaltWar.raidAreaPlayerEspTextSize = baseConfig.cobaltWar.raidAreaPlayerEspTextSize;
                    if (configData.cobaltWar.balanceTiers == null || configData.cobaltWar.balanceTiers.Count == 0)
                        configData.cobaltWar.balanceTiers = baseConfig.cobaltWar.balanceTiers;
                    if (configData.cobaltWar.easyDefenderKits == null || configData.cobaltWar.easyDefenderKits.Count == 0)
                        configData.cobaltWar.easyDefenderKits = baseConfig.cobaltWar.easyDefenderKits;
                    if (configData.cobaltWar.mediumDefenderKits == null || configData.cobaltWar.mediumDefenderKits.Count == 0)
                        configData.cobaltWar.mediumDefenderKits = baseConfig.cobaltWar.mediumDefenderKits;
                    if (configData.cobaltWar.defenderKits == null || configData.cobaltWar.defenderKits.Count == 0)
                        configData.cobaltWar.defenderKits = baseConfig.cobaltWar.defenderKits;
                }

                if ((configData.Version?.ToVersionNumber() ?? default(VersionNumber)) < new VersionNumber(3, 0, 2))
                {
                    foreach (var entry in baseConfig.raidSettings.raidTypes)
                    {
                        raidConfig current;
                        if (!configData.raidSettings.raidTypes.TryGetValue(entry.Key, out current) || current == null)
                            continue;

                        current.spawnTanks = entry.Value.spawnTanks;
                        current.tankCount = entry.Value.tankCount;
                    }

                    configData.cobaltWar.enableTanks = baseConfig.cobaltWar.enableTanks;
                    configData.cobaltWar.tankSpawnRadiusMin = baseConfig.cobaltWar.tankSpawnRadiusMin;
                    configData.cobaltWar.tankSpawnRadiusMax = baseConfig.cobaltWar.tankSpawnRadiusMax;
                    configData.cobaltWar.rockBaseTankSpawnRadiusMin = baseConfig.cobaltWar.rockBaseTankSpawnRadiusMin;
                    configData.cobaltWar.rockBaseTankSpawnRadiusMax = baseConfig.cobaltWar.rockBaseTankSpawnRadiusMax;
                    configData.cobaltWar.rockBaseExtraTanks = baseConfig.cobaltWar.rockBaseExtraTanks;
                    configData.cobaltWar.maxTankSpawnSlopeAngle = baseConfig.cobaltWar.maxTankSpawnSlopeAngle;
                    configData.cobaltWar.tankAttackDistance = baseConfig.cobaltWar.tankAttackDistance;
                    configData.cobaltWar.tankShellIntervalSeconds = baseConfig.cobaltWar.tankShellIntervalSeconds;
                    configData.cobaltWar.tankShellExplosionRadius = baseConfig.cobaltWar.tankShellExplosionRadius;
                    configData.cobaltWar.tankShellDamageBuildings = baseConfig.cobaltWar.tankShellDamageBuildings;
                    configData.cobaltWar.tankShellDamagePlayers = baseConfig.cobaltWar.tankShellDamagePlayers;
                    configData.cobaltWar.tankHealth = baseConfig.cobaltWar.tankHealth;
                    configData.cobaltWar.tankCoaxDamage = baseConfig.cobaltWar.tankCoaxDamage;
                    if (configData.cobaltWar.defenderKits == null || configData.cobaltWar.defenderKits.Count == 0)
                        configData.cobaltWar.defenderKits = baseConfig.cobaltWar.defenderKits;
                }

                if ((configData.Version?.ToVersionNumber() ?? default(VersionNumber)) < new VersionNumber(3, 0, 5))
                {
                    configData.settings.worldMarker = false;
                    configData.cobaltWar.successDefenseXp = baseConfig.cobaltWar.successDefenseXp;
                    configData.cobaltWar.successDefenseXpByRaidType = baseConfig.cobaltWar.successDefenseXpByRaidType;
                    configData.cobaltWar.respawnProtectionSeconds = baseConfig.cobaltWar.respawnProtectionSeconds;
                    configData.cobaltWar.preventRegisteredDefenderDrops = baseConfig.cobaltWar.preventRegisteredDefenderDrops;
                    configData.cobaltWar.extraNpcPerActiveHelper = baseConfig.cobaltWar.extraNpcPerActiveHelper;
                    configData.cobaltWar.maxExtraNpcPerWaveFromHelpers = baseConfig.cobaltWar.maxExtraNpcPerWaveFromHelpers;
                    configData.cobaltWar.activeHelpersPerExtraWave = baseConfig.cobaltWar.activeHelpersPerExtraWave;
                    configData.cobaltWar.maxExtraWavesFromHelpers = baseConfig.cobaltWar.maxExtraWavesFromHelpers;
                    configData.cobaltWar.extraSecondsPerActiveHelper = baseConfig.cobaltWar.extraSecondsPerActiveHelper;
                    configData.cobaltWar.maxExtraSecondsFromHelpers = baseConfig.cobaltWar.maxExtraSecondsFromHelpers;
                }

                if ((configData.Version?.ToVersionNumber() ?? default(VersionNumber)) < new VersionNumber(3, 0, 6))
                {
                    if (configData.cobaltWar.easyDefenderKits == null || configData.cobaltWar.easyDefenderKits.Count == 0)
                        configData.cobaltWar.easyDefenderKits = baseConfig.cobaltWar.easyDefenderKits;
                    if (configData.cobaltWar.mediumDefenderKits == null || configData.cobaltWar.mediumDefenderKits.Count == 0)
                        configData.cobaltWar.mediumDefenderKits = baseConfig.cobaltWar.mediumDefenderKits;
                }

                if ((configData.Version?.ToVersionNumber() ?? default(VersionNumber)) < new VersionNumber(3, 0, 7))
                {
                    configData.cobaltWar.enableOwnerBuyout = baseConfig.cobaltWar.enableOwnerBuyout;
                    configData.cobaltWar.ownerBuyoutSeconds = baseConfig.cobaltWar.ownerBuyoutSeconds;
                }

                if ((configData.Version?.ToVersionNumber() ?? default(VersionNumber)) < new VersionNumber(3, 0, 8))
                {
                    configData.cobaltWar.enableOwnerNaturalCombatRespawn = baseConfig.cobaltWar.enableOwnerNaturalCombatRespawn;
                    configData.cobaltWar.enableWalkInNaturalCombatRespawn = baseConfig.cobaltWar.enableWalkInNaturalCombatRespawn;
                    configData.cobaltWar.walkInNaturalRespawnActivationSeconds = baseConfig.cobaltWar.walkInNaturalRespawnActivationSeconds;
                    configData.cobaltWar.cleanupFinalizeRetrySeconds = baseConfig.cobaltWar.cleanupFinalizeRetrySeconds;
                    configData.cobaltWar.cleanupFinalizeMaxRetries = baseConfig.cobaltWar.cleanupFinalizeMaxRetries;
                }

                if ((configData.Version?.ToVersionNumber() ?? default(VersionNumber)) < new VersionNumber(3, 0, 9))
                {
                    configData.cobaltWar.requireTurretsForAutomaticRaidTargets = baseConfig.cobaltWar.requireTurretsForAutomaticRaidTargets;
                    configData.cobaltWar.minimumAutoRaidTargetTurrets = baseConfig.cobaltWar.minimumAutoRaidTargetTurrets;
                }
            }
            configData.Version = new ConfigData.PluginVersionData(Version);
            PrintWarning("Обновление версии конфига завершено.");
        }

