        #region Cobalt War
        private int GetNextWarId() => nextWarId++;

        private void RegisterWar(CobaltWarSession war)
        {
            if (war != null)
                activeCobaltWars[war.warId] = war;

            RefreshIdleOptimizationState();
        }

        private void UnregisterWar(CobaltWarSession war)
        {
            if (war != null)
                activeCobaltWars.Remove(war.warId);

            RefreshIdleOptimizationState();
        }

        private CobaltWarSession FindWar(int warId)
        {
            CobaltWarSession war;
            return activeCobaltWars.TryGetValue(warId, out war) ? war : null;
        }

        private IEnumerable<CobaltWarSession> GetActiveWars()
        {
            return activeCobaltWars.Values
                .Where(x => x != null && !x.IsEnded)
                .OrderByDescending(x => x.warId);
        }

        private CobaltWarSession FindWarByRegisteredPlayer(ulong userId)
        {
            return GetActiveWars()
                .Where(x => x.IsUiRegisteredDefender(userId))
                .OrderByDescending(x => x.phase == CobaltWarPhase.Active ? 3 : x.phase == CobaltWarPhase.Preparation ? 2 : x.phase == CobaltWarPhase.Registration ? 1 : 0)
                .ThenByDescending(x => x.warId)
                .FirstOrDefault();
        }

        private CobaltWarSession FindWarByUiRegisteredPlayer(ulong userId)
        {
            return GetActiveWars()
                .Where(x => x.IsUiRegisteredDefender(userId))
                .OrderByDescending(x => x.phase == CobaltWarPhase.Cleanup ? 4 : x.phase == CobaltWarPhase.Active ? 3 : x.phase == CobaltWarPhase.Preparation ? 2 : x.phase == CobaltWarPhase.Registration ? 1 : 0)
                .ThenByDescending(x => x.warId)
                .FirstOrDefault();
        }

        private CobaltWarSession FindWarByParticipant(ulong userId)
        {
            return GetActiveWars()
                .Where(x => x.IsFriendlyParticipant(userId))
                .OrderByDescending(x => x.IsRegisteredDefender(userId) ? 4 : x.owners.Contains(userId) ? 3 : x.phase == CobaltWarPhase.Active ? 2 : x.phase == CobaltWarPhase.Preparation ? 1 : 0)
                .ThenByDescending(x => x.warId)
                .FirstOrDefault();
        }

        private CobaltWarSession FindWarByParticipant(ulong userId, Vector3 position)
        {
            return GetActiveWars()
                .Where(x => x.IsFriendlyParticipant(userId))
                .OrderByDescending(x => x.IsRegisteredDefender(userId) ? 3 : x.owners.Contains(userId) ? 2 : x.IsInsideCombatArea(position) ? 1 : 0)
                .ThenBy(x => Vector3.Distance(x.location, position))
                .ThenByDescending(x => x.warId)
                .FirstOrDefault();
        }

        private CobaltWarSession FindWarByOwner(ulong userId, bool onlyJoinable = false)
        {
            return GetActiveWars()
                .Where(x => x.owners.Contains(userId) && (!onlyJoinable || x.phase == CobaltWarPhase.Buyout || x.phase == CobaltWarPhase.Registration || x.phase == CobaltWarPhase.Preparation || x.phase == CobaltWarPhase.Active))
                .OrderByDescending(x => x.warId)
                .FirstOrDefault();
        }

        private CobaltWarSession FindJoinableWarForPlayer(BasePlayer player)
        {
            if (player == null)
                return null;

            ulong userId = player.userID.Get();
            return GetActiveWars()
                .Where(x => x.phase == CobaltWarPhase.Registration || x.phase == CobaltWarPhase.Preparation || x.phase == CobaltWarPhase.Active)
                .Where(x =>
                {
                    string arenaMessageKey;
                    return x.IsFriendlyParticipant(userId) || x.IsUiRegisteredDefender(userId) || !IsArenaTournamentBlockingCobalt(player, true, out arenaMessageKey);
                })
                .OrderByDescending(x => x.owners.Contains(userId) ? 3 : x.IsUiRegisteredDefender(userId) ? 2 : x.phase == CobaltWarPhase.Registration ? 1 : 0)
                .ThenBy(x => Vector3.Distance(x.location, player.transform.position))
                .ThenByDescending(x => x.warId)
                .FirstOrDefault();
        }

        private float GetRaidAreaPlayerEspUpdateInterval()
        {
            if (configData?.cobaltWar == null)
                return 0.3f;

            return Mathf.Clamp(configData.cobaltWar.raidAreaPlayerEspUpdateSeconds, RaidAreaPlayerEspMinUpdateSeconds, RaidAreaPlayerEspMaxUpdateSeconds);
        }

        private float GetAutomaticRaidSearchIntervalSeconds()
        {
            float configured = configData?.settings != null ? configData.settings.cooldownSeconds : 3600f;
            return Mathf.Clamp(configured, 30f, 86400f);
        }

        private float GetWealthScanIntervalSeconds()
        {
            float configured = configData?.cobaltWar != null ? configData.cobaltWar.wealthScanIntervalSeconds : 600f;
            return Mathf.Clamp(configured, 60f, 86400f);
        }

        private float GetRaidAreaPlayerEspDrawDuration()
        {
            float updateInterval = GetRaidAreaPlayerEspUpdateInterval();
            float configuredDuration = configData?.cobaltWar?.raidAreaPlayerEspDrawDurationSeconds ?? (updateInterval + RaidAreaPlayerEspDurationPaddingSeconds);
            return Mathf.Clamp(configuredDuration, updateInterval + 0.02f, updateInterval + RaidAreaPlayerEspMaxDurationPaddingSeconds);
        }

        private float GetRaidAreaPlayerEspMaxViewerDistance()
        {
            float configuredCombatRadius = configData?.cobaltWar?.combatRadius ?? RaidAreaPlayerEspMaxViewerDistance;
            return Mathf.Clamp(configuredCombatRadius, 55f, RaidAreaPlayerEspMaxViewerDistance);
        }

        private Vector3 GetRaidAreaPlayerEspDrawPosition(BasePlayer target)
        {
            if (target == null)
                return Vector3.zero;

            float drawHeight = Mathf.Max(1.45f, target.GetHeight() + 0.2f);
            if (target.IsDucked())
                drawHeight = Mathf.Max(1.2f, drawHeight - 0.35f);

            return target.transform.position + new Vector3(0f, drawHeight, 0f);
        }

        private bool ShouldRenderRaidAreaPlayerEsp(CobaltWarSession war)
        {
            if (war == null || war.IsEnded || configData?.cobaltWar == null || !configData.cobaltWar.enableRaidAreaPlayerEsp)
                return false;

            return war.phase == CobaltWarPhase.Registration
                || war.phase == CobaltWarPhase.Preparation
                || war.phase == CobaltWarPhase.Active
                || war.phase == CobaltWarPhase.Cleanup;
        }

        private bool IsAdminEspActiveForPlayer(BasePlayer player)
        {
            if (player == null || AdminESP == null)
                return false;

            try
            {
                object result = AdminESP.Call("HasActive", player.userID.Get());
                return result is bool && (bool)result;
            }
            catch
            {
                return false;
            }
        }

        private bool CanReceiveRaidAreaPlayerEsp(BasePlayer player, CobaltWarSession war)
        {
            if (player == null || war == null || !player.IsConnected || player.IsNpc || player.IsDead() || player.IsSleeping())
                return false;
            if (player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
                return false;
            if (IsAdminEspActiveForPlayer(player))
                return false;

            return war.IsInsideCombatArea(player.transform.position);
        }

        private bool CanBeRaidAreaPlayerEspTarget(BasePlayer player, CobaltWarSession war)
        {
            if (player == null || war == null || !player.IsConnected || player.IsNpc || player.IsDead() || player.IsSleeping())
                return false;
            if (player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
                return false;

            return war.IsInsideCombatArea(player.transform.position);
        }

        private string GetRaidAreaPlayerEspText(BasePlayer target, CobaltWarSession war)
        {
            int hp = Mathf.Clamp(Mathf.CeilToInt(target.health), 0, Mathf.CeilToInt(Mathf.Max(1f, target.MaxHealth())));
            int maxHp = Mathf.Max(1, Mathf.CeilToInt(target.MaxHealth()));
            int textSize = Mathf.Max(8, configData.cobaltWar.raidAreaPlayerEspTextSize);
            string nameColor = war != null && war.IsFriendlyParticipant(target.userID.Get()) ? "#FFB55A" : "#FF9D6B";
            return $"<size={textSize}><color={nameColor}>{target.displayName}</color> <color=#FFF1D9>{hp}/{maxHp} HP</color></size>";
        }

        private void WithTemporaryDdrawAccess(BasePlayer player, Action action)
        {
            if (player == null || action == null)
                return;

            bool hadAdminFlag = player.HasPlayerFlag(BasePlayer.PlayerFlags.IsAdmin);
            if (!hadAdminFlag)
            {
                player.playerFlags |= BasePlayer.PlayerFlags.IsAdmin;
                player.SendNetworkUpdateImmediate();
            }

            try
            {
                action();
            }
            finally
            {
                if (!hadAdminFlag)
                {
                    player.playerFlags &= ~BasePlayer.PlayerFlags.IsAdmin;
                    player.SendNetworkUpdateImmediate();
                }
            }
        }

        private void RenderRaidAreaPlayerEspForViewer(BasePlayer viewer, CobaltWarSession war, List<BasePlayer> playersInArea, List<Vector3> drawPositions, List<string> drawTexts, float duration, float maxViewerDistanceSqr)
        {
            if (viewer == null || war == null || playersInArea == null || playersInArea.Count <= 1)
                return;
            if (!CanReceiveRaidAreaPlayerEsp(viewer, war))
                return;

            bool hasAnyTarget = false;
            Vector3 viewerPosition = viewer.transform.position;
            foreach (BasePlayer candidate in playersInArea)
            {
                if (candidate == null || candidate == viewer)
                    continue;

                if ((candidate.transform.position - viewerPosition).sqrMagnitude > maxViewerDistanceSqr)
                    continue;

                hasAnyTarget = true;
                break;
            }

            if (!hasAnyTarget)
                return;

            WithTemporaryDdrawAccess(viewer, () =>
            {
                for (int index = 0; index < playersInArea.Count; index++)
                {
                    BasePlayer target = playersInArea[index];
                    if (target == null || target == viewer)
                        continue;

                    if ((target.transform.position - viewerPosition).sqrMagnitude > maxViewerDistanceSqr)
                        continue;

                    viewer.SendConsoleCommand("ddraw.text", duration, new Color(1f, 0.71f, 0.35f, 1f), drawPositions[index], drawTexts[index]);
                }
            });
        }

        private void UpdateRaidAreaPlayerEsp()
        {
            if (configData?.cobaltWar == null || !configData.cobaltWar.enabled || !configData.cobaltWar.enableRaidAreaPlayerEsp)
                return;

            if (activeCobaltWars.Count <= 0)
            {
                RefreshRaidAreaEspTimerState();
                return;
            }

            float duration = GetRaidAreaPlayerEspDrawDuration();
            float maxViewerDistanceSqr = Mathf.Pow(GetRaidAreaPlayerEspMaxViewerDistance(), 2f);

            foreach (CobaltWarSession war in activeCobaltWars.Values.ToList())
            {
                if (!ShouldRenderRaidAreaPlayerEsp(war))
                    continue;

                List<BasePlayer> playersInArea = Pool.Get<List<BasePlayer>>();
                List<Vector3> drawPositions = Pool.Get<List<Vector3>>();
                List<string> drawTexts = Pool.Get<List<string>>();
                playersInArea.Clear();
                drawPositions.Clear();
                drawTexts.Clear();

                try
                {
                    foreach (BasePlayer player in BasePlayer.activePlayerList)
                    {
                        if (CanBeRaidAreaPlayerEspTarget(player, war))
                        {
                            playersInArea.Add(player);
                            drawPositions.Add(GetRaidAreaPlayerEspDrawPosition(player));
                            drawTexts.Add(GetRaidAreaPlayerEspText(player, war));
                        }
                    }

                    if (playersInArea.Count <= 1)
                        continue;

                    foreach (BasePlayer viewer in playersInArea)
                        RenderRaidAreaPlayerEspForViewer(viewer, war, playersInArea, drawPositions, drawTexts, duration, maxViewerDistanceSqr);
                }
                finally
                {
                    Pool.FreeUnmanaged(ref playersInArea);
                    Pool.FreeUnmanaged(ref drawPositions);
                    Pool.FreeUnmanaged(ref drawTexts);
                }
            }

            RefreshRaidAreaEspTimerState();
        }

        private CobaltWarSession FindPreferredWarForPlayer(BasePlayer player)
        {
            if (player == null)
                return null;

            DefenderRedeployState redeploy;
            if (pendingRedeploys.TryGetValue(player.userID, out redeploy))
            {
                CobaltWarSession redeployWar = FindWar(redeploy.warId);
                if (redeployWar != null && !redeployWar.IsEnded)
                    return redeployWar;
            }

            CobaltWarSession registeredWar = FindWarByRegisteredPlayer(player.userID);
            if (registeredWar != null)
                return registeredWar;

            CobaltWarSession uiRegisteredWar = FindWarByUiRegisteredPlayer(player.userID);
            if (uiRegisteredWar != null)
                return uiRegisteredWar;

            CobaltWarSession ownerWar = FindWarByOwner(player.userID, true);
            if (ownerWar != null)
                return ownerWar;

            CobaltWarSession participantWar = FindWarByParticipant(player.userID, player.transform.position);
            if (participantWar != null)
                return participantWar;

            return FindJoinableWarForPlayer(player);
        }

        private CobaltWarSession FindNaturalCombatRespawnWar(BasePlayer player)
        {
            if (player == null)
                return null;

            return GetActiveWars()
                .Where(x => x != null && !x.IsEnded && x.CanUseNaturalCombatRespawn(player))
                .OrderByDescending(x => x.owners.Contains(player.userID.Get()) ? 2 : x.walkInDefenders.Contains(player.userID.Get()) ? 1 : 0)
                .ThenBy(x => Vector3.Distance(x.location, player.transform.position))
                .ThenByDescending(x => x.warId)
                .FirstOrDefault();
        }

        private bool TryGetCombatRespawnWarState(BasePlayer player, out CobaltWarSession war, out bool useDefenderLoadout)
        {
            war = null;
            useDefenderLoadout = false;

            if (player == null)
                return false;

            DefenderRedeployState pendingRedeploy;
            if (pendingRedeploys.TryGetValue(player.userID.Get(), out pendingRedeploy))
            {
                CobaltWarSession pendingWar = FindWar(pendingRedeploy.warId);
                if (pendingWar != null && pendingWar.IsCombatRespawnWindowOpen())
                {
                    war = pendingWar;
                    useDefenderLoadout = pendingRedeploy.useDefenderLoadout;
                    return true;
                }
            }

            CobaltWarSession registeredWar = FindWarByRegisteredPlayer(player.userID);
            if (registeredWar != null && (registeredWar.phase == CobaltWarPhase.Preparation || registeredWar.IsCombatRespawnWindowOpen()))
            {
                war = registeredWar;
                useDefenderLoadout = true;
                return true;
            }

            CobaltWarSession naturalWar = FindNaturalCombatRespawnWar(player);
            if (naturalWar != null && naturalWar.IsCombatRespawnWindowOpen())
            {
                war = naturalWar;
                useDefenderLoadout = false;
                return true;
            }

            return false;
        }

        private bool TryRecoverCombatRespawnParticipant(BasePlayer player)
        {
            CobaltWarSession war;
            bool useDefenderLoadout;
            if (!TryGetCombatRespawnWarState(player, out war, out useDefenderLoadout))
                return false;

            if (war == null || war.IsEnded || player == null || !player.IsConnected || player.IsDead())
                return false;

            if (war.IsInsideCombatArea(player.transform.position))
                return false;

            if (useDefenderLoadout)
                PrepareRegisteredDefender(war, player, true);
            else
                PrepareNaturalFriendlyDefender(war, player, true);

            return true;
        }

        private void QueueCombatRespawnLocationAudit(BasePlayer player)
        {
            if (player == null)
                return;

            timer.Once(1f, () =>
            {
                if (player == null || !player.IsConnected || player.IsDead())
                    return;

                TryRecoverCombatRespawnParticipant(player);
            });
        }

        private object ShouldBypassSafeZoneSpawner(BasePlayer player)
        {
            CobaltWarSession war;
            bool useDefenderLoadout;
            return TryGetCombatRespawnWarState(player, out war, out useDefenderLoadout) ? (object)true : null;
        }

        private bool IsInsideAnyRandomRaidArea(Vector3 position)
        {
            foreach (CobaltWarSession war in activeCobaltWars.Values)
            {
                if (war == null || war.IsEnded)
                    continue;

                if (war.IsInsideCombatArea(position))
                    return true;
            }

            foreach (EventRandomManager raid in EventRandomManager._AllRaids)
            {
                if (raid == null || raid.isDestroyed)
                    continue;

                CobaltWarSession warSession = raid.warSession;
                if (warSession != null && !warSession.IsEnded)
                {
                    if (warSession.IsInsideCombatArea(position))
                        return true;

                    continue;
                }

                if (Vector3.Distance(raid.location, position) <= 150f)
                    return true;
            }

            return false;
        }

        private object ShouldBypassProtectiveDomeAtPosition(Vector3 position)
        {
            return IsInsideAnyRandomRaidArea(position) ? (object)true : null;
        }

        private bool ShouldDisplayWarUi(CobaltWarSession war, BasePlayer player)
        {
            if (war == null || player == null || !player.IsConnected || war.IsEnded)
                return false;

            if (war.phase == CobaltWarPhase.Buyout)
                return war.owners.Contains(player.userID.Get()) && FindPreferredWarForPlayer(player)?.warId == war.warId;

            if (war.phase == CobaltWarPhase.Cleanup)
                return war.CanLeaveDefender(player.userID);

            bool isUiParticipant = war.IsFriendlyParticipant(player.userID) || war.IsUiRegisteredDefender(player.userID);

            if (war.phase == CobaltWarPhase.Active && !isUiParticipant)
                return false;

            string arenaMessageKey;
            if (!isUiParticipant && IsArenaTournamentBlockingCobalt(player, true, out arenaMessageKey))
                return false;

            CobaltWarSession preferredWar = FindPreferredWarForPlayer(player);
            return preferredWar != null && preferredWar.warId == war.warId;
        }

        private bool ShouldDefaultToMinimizedWarUi(CobaltWarSession war, BasePlayer player)
        {
            if (war == null || player == null || !player.IsConnected || war.IsEnded)
                return false;

            if (war.phase == CobaltWarPhase.Buyout || war.phase == CobaltWarPhase.Cleanup)
                return false;

            return GetWarUiMinimizedPreference(player.userID.Get());
        }

        private bool GetWarUiMinimizedPreference(ulong userId)
        {
            if (userId == 0UL)
                return false;

            EnsurePlayerDataStructures();

            bool minimized;
            if (pcdData.warUiMinimizedPreference.TryGetValue(userId, out minimized))
                return minimized;

            return false;
        }

        private void SetWarUiMinimizedPreference(ulong userId, bool minimized)
        {
            if (userId == 0UL)
                return;

            EnsurePlayerDataStructures();

            bool currentValue;
            if (pcdData.warUiMinimizedPreference.TryGetValue(userId, out currentValue) && currentValue == minimized)
                return;

            pcdData.warUiMinimizedPreference[userId] = minimized;
            QueuePlayerDataSave();
        }

        private bool IsWindowJoinedDefenderRestricted(ulong userId)
        {
            if (userId == 0UL || configData?.cobaltWar == null || !configData.cobaltWar.preventRegisteredDefenderDrops || !defenderSnapshots.ContainsKey(userId))
                return false;

            CobaltWarSession war = FindWarByRegisteredPlayer(userId);
            if (war == null || war.IsEnded)
                return false;

            return war.IsUiRegisteredDefender(userId) && (war.phase == CobaltWarPhase.Preparation || war.phase == CobaltWarPhase.Active || war.phase == CobaltWarPhase.Cleanup);
        }

        private bool HasAnyPendingRaidPlayerState(ulong userId)
        {
            if (userId == 0UL)
                return false;

            EnsurePlayerDataStructures();

            if (pendingRedeploys.ContainsKey(userId))
                return true;

            if (defenderSnapshots.ContainsKey(userId))
                return true;

            if (pcdData?.defenderSnapshots != null && pcdData.defenderSnapshots.ContainsKey(userId))
                return true;

            if (pcdData?.disconnectRaidBackups != null && pcdData.disconnectRaidBackups.ContainsKey(userId))
                return true;

            if (pcdData?.deferredXpDamage != null && pcdData.deferredXpDamage.ContainsKey(userId))
                return true;

            if (pcdData?.deferredXpRewards != null && pcdData.deferredXpRewards.ContainsKey(userId))
                return true;

            if (FindWarByParticipant(userId) != null)
                return true;

            if (FindWarByRegisteredPlayer(userId) != null)
                return true;

            if (FindWarByOwner(userId, true) != null)
                return true;

            return false;
        }

        private bool HasActiveWarForSnapshot(DefenderSnapshot snapshot)
        {
            if (snapshot == null || snapshot.warId <= 0)
                return false;

            CobaltWarSession war = FindWar(snapshot.warId);
            // Once cleanup starts, the raid is already over from the defender's perspective.
            // Do not keep original inventory restore blocked for reconnecting players who return
            // after the raid has effectively finished.
            return war != null && !war.IsEnded && war.phase != CobaltWarPhase.Cleanup;
        }

        private static uint NormalizeContainerUid(object value)
        {
            if (value == null)
                return 0u;

            if (value is uint rawUid)
                return rawUid;

            try
            {
                Type type = value.GetType();
                PropertyInfo property = type.GetProperty("Value") ?? type.GetProperty("value");
                if (property != null && property.PropertyType == typeof(uint))
                    return (uint)property.GetValue(value, null);

                FieldInfo field = type.GetField("Value") ?? type.GetField("value");
                if (field != null && field.FieldType == typeof(uint))
                    return (uint)field.GetValue(value);

                if (type.IsEnum)
                    return Convert.ToUInt32(value);

                return Convert.ToUInt32(value);
            }
            catch
            {
                return 0u;
            }
        }

        private static uint GetContainerUid(ItemContainer container)
        {
            return container == null ? 0u : NormalizeContainerUid(container.uid);
        }

        private static uint GetItemUid(Item item)
        {
            return item == null ? 0u : NormalizeContainerUid(item.uid);
        }

        private void TrackProtectedDefenderItem(Item item, ulong ownerUserId, int warId)
        {
            uint itemUid = GetItemUid(item);
            if (item == null || itemUid == 0u || ownerUserId == 0UL)
                return;

            protectedDefenderItems[itemUid] = new ProtectedDefenderItemState
            {
                ownerUserId = ownerUserId,
                warId = warId,
                itemRef = item
            };

            HashSet<uint> ownerItems;
            if (!protectedDefenderItemsByOwner.TryGetValue(ownerUserId, out ownerItems))
            {
                ownerItems = new HashSet<uint>();
                protectedDefenderItemsByOwner[ownerUserId] = ownerItems;
            }

            ownerItems.Add(itemUid);
            RefreshIdleOptimizationState();
        }

        private void TrackProtectedDefenderItemRecursive(Item item, ulong ownerUserId, int warId)
        {
            if (item == null)
                return;

            TrackProtectedDefenderItem(item, ownerUserId, warId);

            if (item.contents == null || item.contents.itemList == null)
                return;

            foreach (Item child in item.contents.itemList.ToList())
                TrackProtectedDefenderItemRecursive(child, ownerUserId, warId);
        }

        private void UntrackProtectedDefenderItem(Item item)
        {
            uint itemUid = GetItemUid(item);
            if (itemUid == 0u)
                return;

            ProtectedDefenderItemState state;
            if (!protectedDefenderItems.TryGetValue(itemUid, out state))
                return;

            protectedDefenderItems.Remove(itemUid);

            HashSet<uint> ownerItems;
            if (protectedDefenderItemsByOwner.TryGetValue(state.ownerUserId, out ownerItems))
            {
                ownerItems.Remove(itemUid);
                if (ownerItems.Count == 0)
                    protectedDefenderItemsByOwner.Remove(state.ownerUserId);
            }

            RefreshIdleOptimizationState();
        }

        private void ClearProtectedDefenderItems(ulong ownerUserId)
        {
            HashSet<uint> ownerItems;
            if (!protectedDefenderItemsByOwner.TryGetValue(ownerUserId, out ownerItems))
            {
                pendingProtectedSplits.RemoveAll(x => x.ownerUserId == ownerUserId);
                RefreshIdleOptimizationState();
                return;
            }

            foreach (uint itemUid in ownerItems.ToList())
                protectedDefenderItems.Remove(itemUid);

            protectedDefenderItemsByOwner.Remove(ownerUserId);
            pendingProtectedSplits.RemoveAll(x => x.ownerUserId == ownerUserId);
            RefreshIdleOptimizationState();
        }

        private bool TryGetProtectedDefenderItemState(Item item, out ProtectedDefenderItemState state)
        {
            state = null;
            uint itemUid = GetItemUid(item);
            if (itemUid == 0u)
                return false;

            if (!protectedDefenderItems.TryGetValue(itemUid, out state) || state == null)
                return false;

            return true;
        }

        private bool IsProtectedDefenderItem(Item item)
        {
            ProtectedDefenderItemState state;
            return TryGetProtectedDefenderItemState(item, out state);
        }

        private void RegisterPendingProtectedSplit(Item item, int splitAmount)
        {
            ProtectedDefenderItemState state;
            if (item == null || splitAmount <= 0 || !TryGetProtectedDefenderItemState(item, out state) || item.info == null)
                return;

            pendingProtectedSplits.RemoveAll(x => x.ownerUserId == state.ownerUserId && x.expiresAt <= Time.realtimeSinceStartup);
            pendingProtectedSplits.Add(new PendingProtectedSplitState
            {
                ownerUserId = state.ownerUserId,
                warId = state.warId,
                shortname = item.info.shortname,
                skin = item.skin,
                amount = splitAmount,
                expiresAt = Time.realtimeSinceStartup + 1.5f
            });
            RefreshIdleOptimizationState();
        }

        private bool TryConsumePendingProtectedSplit(Item item, ItemContainer container, out PendingProtectedSplitState state)
        {
            state = null;
            if (item == null || item.info == null || container == null)
                return false;

            BasePlayer owner = GetContainerOwnerPlayer(container);
            if (owner == null)
                return false;

            pendingProtectedSplits.RemoveAll(x => x.expiresAt <= Time.realtimeSinceStartup);

            state = pendingProtectedSplits.FirstOrDefault(x =>
                x.ownerUserId == owner.userID.Get() &&
                x.shortname == item.info.shortname &&
                x.skin == item.skin &&
                x.amount == item.amount);

            if (state == null)
                return false;

            pendingProtectedSplits.Remove(state);
            RefreshIdleOptimizationState();
            return true;
        }

        private BasePlayer GetContainerOwnerPlayer(ItemContainer container)
        {
            if (container == null)
                return null;

            if (container.playerOwner != null)
                return container.playerOwner;

            if (container.parent != null)
                return container.parent.GetOwnerPlayer();

            return null;
        }

        private bool IsAllowedProtectedItemContainer(ItemContainer container, ProtectedDefenderItemState state)
        {
            if (container == null || state == null)
                return false;

            BasePlayer containerOwner = GetContainerOwnerPlayer(container);
            if (containerOwner != null && containerOwner.userID.Get() == state.ownerUserId)
            {
                PlayerInventory inventory = containerOwner.inventory;
                if (IsPlayerInventoryContainer(inventory, container))
                    return true;
            }

            if (container.parent != null)
            {
                ProtectedDefenderItemState parentState;
                if (TryGetProtectedDefenderItemState(container.parent, out parentState) && parentState.ownerUserId == state.ownerUserId)
                    return true;
            }

            return false;
        }

        private IEnumerable<Item> EnumeratePlayerInventoryItemsRecursive(BasePlayer player)
        {
            if (player?.inventory == null)
                yield break;

            List<ItemContainer> containers = new List<ItemContainer>
            {
                player.inventory.containerBelt,
                player.inventory.containerMain,
                player.inventory.containerWear
            };

            foreach (ItemContainer container in containers)
            {
                if (container == null)
                    continue;

                foreach (Item item in container.itemList.ToList())
                {
                    if (item == null)
                        continue;

                    yield return item;

                    if (item.contents == null || item.contents.itemList == null)
                        continue;

                    foreach (Item child in item.contents.itemList.ToList())
                    {
                        if (child != null)
                            yield return child;
                    }
                }
            }
        }

        private void TrackProtectedDefenderInventory(BasePlayer player, int warId)
        {
            if (player == null)
                return;

            ClearProtectedDefenderItems(player.userID);

            if (configData?.cobaltWar == null || !configData.cobaltWar.preventRegisteredDefenderDrops)
                return;

            foreach (Item item in EnumeratePlayerInventoryItemsRecursive(player))
                TrackProtectedDefenderItemRecursive(item, player.userID.Get(), warId);
        }

        private void AuditProtectedDefenderItems()
        {
            if (protectedDefenderItems.Count <= 0)
            {
                RefreshProtectedItemAuditTimerState();
                return;
            }

            foreach (var entry in protectedDefenderItems.ToList())
            {
                uint itemUid = entry.Key;
                ProtectedDefenderItemState state = entry.Value;
                if (state == null)
                {
                    protectedDefenderItems.Remove(itemUid);
                    continue;
                }

                Item item = state.itemRef;
                if (item == null || item.amount <= 0 || item.info == null)
                {
                    UntrackProtectedDefenderItem(item);
                    protectedDefenderItems.Remove(itemUid);
                    continue;
                }

                if (item.parent != null)
                {
                    if (IsAllowedProtectedItemContainer(item.parent, state))
                        continue;

                    BasePlayer owner = BasePlayer.FindByID(state.ownerUserId);
                    if (owner != null && owner.IsConnected)
                        NotifyDefenderDropBlocked(owner);

                    DeleteProtectedDefenderItem(item);
                    continue;
                }

                BaseEntity worldEntity = item.GetWorldEntity();
                if (worldEntity != null && !worldEntity.IsDestroyed)
                {
                    BasePlayer owner = BasePlayer.FindByID(state.ownerUserId);
                    if (owner != null && owner.IsConnected)
                        NotifyDefenderDropBlocked(owner);

                    DeleteProtectedDefenderItem(item, worldEntity);
                    continue;
                }

                BasePlayer itemOwner = item.GetOwnerPlayer();
                if (itemOwner != null && itemOwner.userID.Get() != state.ownerUserId)
                {
                    BasePlayer owner = BasePlayer.FindByID(state.ownerUserId);
                    if (owner != null && owner.IsConnected)
                        NotifyDefenderDropBlocked(owner);

                    DeleteProtectedDefenderItem(item);
                }
            }

            RefreshProtectedItemAuditTimerState();
        }

        private bool IsPlayerInventoryContainer(PlayerInventory inventory, ItemContainer container)
        {
            if (inventory == null || container == null)
                return false;

            uint containerUid = GetContainerUid(container);
            return containerUid != 0u && IsPlayerInventoryContainer(inventory, containerUid);
        }

        private bool IsPlayerInventoryContainer(PlayerInventory inventory, ItemContainerId targetContainerId)
        {
            return IsPlayerInventoryContainer(inventory, NormalizeContainerUid(targetContainerId));
        }

        private bool IsPlayerInventoryContainer(PlayerInventory inventory, uint targetContainerUid)
        {
            if (inventory == null || targetContainerUid == 0u)
                return false;

            return (inventory.containerMain != null && GetContainerUid(inventory.containerMain) == targetContainerUid)
                || (inventory.containerBelt != null && GetContainerUid(inventory.containerBelt) == targetContainerUid)
                || (inventory.containerWear != null && GetContainerUid(inventory.containerWear) == targetContainerUid);
        }

        private bool ShouldBlockRestrictedInventoryMove(Item item, PlayerInventory playerInventory, uint targetContainerUid)
        {
            if (item == null || playerInventory == null)
                return false;

            BasePlayer player = playerInventory.baseEntity;
            if (player == null || !player.IsConnected)
                return false;

            if (IsWindowJoinedDefenderRestricted(player.userID.Get()))
            {
                if (IsPlayerInventoryContainer(playerInventory, targetContainerUid))
                    return false;

                NotifyDefenderDropBlocked(player);
                return true;
            }

            ProtectedDefenderItemState state;
            if (!TryGetProtectedDefenderItemState(item, out state) || state.ownerUserId != player.userID.Get())
                return false;

            if (IsPlayerInventoryContainer(playerInventory, targetContainerUid))
                return false;

            NotifyDefenderDropBlocked(player);
            return true;
        }

        private void NullifyHitInfo(HitInfo hitinfo)
        {
            if (hitinfo == null)
                return;

            try
            {
                hitinfo.damageTypes?.ScaleAll(0f);
                hitinfo.DoHitEffects = false;
                hitinfo.HitMaterial = 0U;
                hitinfo.PointStart = Vector3.zero;
                hitinfo.PointEnd = Vector3.zero;
            }
            catch
            {
            }
        }

        private bool ShouldBlockCobaltParticipantDamage(BasePlayer targetPlayer, HitInfo hitinfo)
        {
            if (targetPlayer == null || hitinfo == null)
                return false;

            BasePlayer initiatorPlayer = hitinfo.InitiatorPlayer;
            float protectionRemaining;
            if (HasDefenderRespawnProtection(targetPlayer.userID, out protectionRemaining) && (initiatorPlayer == null || initiatorPlayer.userID != targetPlayer.userID))
                return true;

            CobaltWarSession targetWar = FindWarByParticipant(targetPlayer.userID, targetPlayer.transform.position);
            if (targetWar == null || targetWar.IsEnded || targetWar.phase != CobaltWarPhase.Active || !targetWar.IsInsideCombatArea(targetPlayer.transform.position))
                return false;

            if (initiatorPlayer != null && targetWar.IsFriendlyParticipant(initiatorPlayer.userID) && targetWar.IsFriendlyParticipant(targetPlayer.userID))
                return true;

            if (hitinfo.Initiator is AutoTurret && targetWar.IsFriendlyParticipant(targetPlayer.userID))
                return true;

            return false;
        }

        private void NotifyDefenderDropBlocked(BasePlayer player)
        {
            if (player == null)
                return;

            float lastShown;
            if (defenderDropNoticeTime.TryGetValue(player.userID, out lastShown) && lastShown > Time.realtimeSinceStartup)
                return;

            defenderDropNoticeTime[player.userID] = Time.realtimeSinceStartup + 2f;
            SendReply(player, lang.GetMessage("CobaltDropBlocked", this, player.UserIDString));
        }

        private void DeleteProtectedDefenderItem(Item item, BaseEntity worldEntity = null)
        {
            if (item == null)
                return;

            try
            {
                UntrackProtectedDefenderItem(item);

                if (item.parent != null)
                    item.RemoveFromContainer();

                item.RemoveFromWorld();

                if (worldEntity != null && !worldEntity.IsDestroyed)
                    worldEntity.Kill();

                item.Remove();
            }
            catch
            {
            }
        }

        private void ClearWarUiDismiss(ulong userId, int? warId = null)
        {
            WarUiDismissState dismissState;
            if (!dismissedWarUi.TryGetValue(userId, out dismissState))
                return;

            if (warId.HasValue && dismissState.warId != warId.Value)
                return;

            dismissedWarUi.Remove(userId);
        }

        private void ClearRenderedWarUiState(ulong userId, int? warId = null)
        {
            WarUiRenderState renderState;
            if (!renderedWarUiState.TryGetValue(userId, out renderState))
                return;

            if (warId.HasValue && renderState.warId != warId.Value)
                return;

            renderedWarUiState.Remove(userId);
        }

        private void ClearMinimizedWarUiRenderState(ulong userId, int? warId = null)
        {
            WarUiRenderState renderState;
            if (!minimizedRenderedWarUiState.TryGetValue(userId, out renderState))
                return;

            if (warId.HasValue && renderState.warId != warId.Value)
                return;

            minimizedRenderedWarUiState.Remove(userId);
        }

        private void SetWarUiDismiss(ulong userId, int warId, CobaltWarPhase phase, bool canJoin, bool canLeave)
        {
            dismissedWarUi[userId] = new WarUiDismissState
            {
                warId = warId,
                phase = phase,
                canJoin = canJoin,
                canLeave = canLeave
            };
        }

        private bool IsWarUiDismissed(ulong userId, int warId, CobaltWarPhase phase, bool canJoin, bool canLeave)
        {
            WarUiDismissState dismissState;
            if (!dismissedWarUi.TryGetValue(userId, out dismissState) || dismissState == null)
                return false;

            if (dismissState.warId != warId)
                return false;

            if (dismissState.phase != phase || dismissState.canJoin != canJoin || dismissState.canLeave != canLeave)
            {
                dismissedWarUi.Remove(userId);
                return false;
            }

            return true;
        }

        private void AuditTransientRuntimeState()
        {
            if (!HasAnyTransientRuntimeWork())
            {
                RefreshIdleOptimizationState();
                return;
            }

            CleanupActivityTracker(defenderActivity, true);
            CleanupActivityTracker(raidTargetActivity, false);
            CleanupExpiredRespawnProtection();
            CleanupExpiredCobaltTankDebrisWindows();
            CleanupExpiredCobaltHeliDebrisWindows();
            CleanupCobaltSupportDroneRegistry();
            CleanupUiStateForDisconnectedPlayers();
            RetryDeferredCobaltXpForConnectedPlayers();
            RefreshIdleOptimizationState();
        }

        private void RetryDeferredCobaltXpForConnectedPlayers()
        {
            if (SkillTree == null || pcdData == null)
                return;

            bool hasDeferredDamage = pcdData.deferredXpDamage != null && pcdData.deferredXpDamage.Count > 0;
            bool hasDeferredRewards = pcdData.deferredXpRewards != null && pcdData.deferredXpRewards.Count > 0;
            if (!hasDeferredDamage && !hasDeferredRewards)
                return;

            HashSet<ulong> usersToRetry = new HashSet<ulong>();

            if (pcdData.deferredXpDamage != null)
            {
                foreach (ulong userId in pcdData.deferredXpDamage.Keys)
                    usersToRetry.Add(userId);
            }

            if (pcdData.deferredXpRewards != null)
            {
                foreach (ulong userId in pcdData.deferredXpRewards.Keys)
                    usersToRetry.Add(userId);
            }

            foreach (ulong userId in usersToRetry)
            {
                BasePlayer player = BasePlayer.FindByID(userId);
                if (player == null || !player.IsConnected)
                    continue;

                TryAwardDeferredCobaltXp(player);
            }
        }

        private void CleanupActivityTracker(Dictionary<ulong, DefenderActivityState> tracker, bool defenderTracker)
        {
            if (tracker == null || tracker.Count <= 0)
                return;

            double now = GrabCurrentTime();
            double staleSeconds = defenderTracker ? 1800d : 7200d;

            foreach (ulong userId in tracker.Keys.ToList())
            {
                DefenderActivityState state;
                if (!tracker.TryGetValue(userId, out state) || state == null)
                {
                    tracker.Remove(userId);
                    continue;
                }

                BasePlayer player = BasePlayer.FindByID(userId);
                bool hasLiveCombatState = pendingRedeploys.ContainsKey(userId)
                    || defenderSnapshots.ContainsKey(userId)
                    || FindWarByParticipant(userId) != null
                    || FindWarByRegisteredPlayer(userId) != null;

                if (player == null || !player.IsConnected)
                {
                    if (!hasLiveCombatState)
                        tracker.Remove(userId);
                    continue;
                }

                if (state.initialized && now - state.lastActivityAt >= staleSeconds && !hasLiveCombatState)
                    tracker.Remove(userId);
            }
        }

        private void CleanupExpiredRespawnProtection()
        {
            if (defenderRespawnProtection.Count <= 0)
                return;

            DateTime now = DateTime.UtcNow;
            foreach (ulong userId in defenderRespawnProtection.Keys.ToList())
            {
                DateTime expiresAt;
                if (!defenderRespawnProtection.TryGetValue(userId, out expiresAt) || expiresAt <= now)
                    defenderRespawnProtection.Remove(userId);
            }
        }

        private void CleanupUiStateForDisconnectedPlayers()
        {
            if (displayedWarUi.Count > 0)
            {
                foreach (ulong userId in displayedWarUi.Keys.ToList())
                {
                    BasePlayer player = BasePlayer.FindByID(userId);
                    if (player == null || !player.IsConnected)
                        displayedWarUi.Remove(userId);
                }
            }

            if (dismissedWarUi.Count > 0)
            {
                foreach (ulong userId in dismissedWarUi.Keys.ToList())
                {
                    BasePlayer player = BasePlayer.FindByID(userId);
                    if (player == null || !player.IsConnected)
                        dismissedWarUi.Remove(userId);
                }
            }

            if (renderedWarUiState.Count > 0)
            {
                foreach (ulong userId in renderedWarUiState.Keys.ToList())
                {
                    BasePlayer player = BasePlayer.FindByID(userId);
                    if (player == null || !player.IsConnected)
                        renderedWarUiState.Remove(userId);
                }
            }

            if (minimizedRenderedWarUiState.Count > 0)
            {
                foreach (ulong userId in minimizedRenderedWarUiState.Keys.ToList())
                {
                    BasePlayer player = BasePlayer.FindByID(userId);
                    if (player == null || !player.IsConnected)
                        minimizedRenderedWarUiState.Remove(userId);
                }
            }
        }

        private bool IsSelfRaidJoinKeyword(string value)
        {
            if (string.IsNullOrEmpty(value))
                return false;

            switch (value.ToLower())
            {
                case "join":
                case "reg":
                case "register":
                case "solo":
                case "defend":
                case "helper":
                    return true;
                default:
                    return false;
            }
        }

        private bool IsImmediateRaidKeyword(string value)
        {
            if (string.IsNullOrEmpty(value))
                return false;

            switch (value.ToLower())
            {
                case InstantRaidKeywordNow:
                case InstantRaidKeywordInstant:
                case InstantRaidKeywordFast:
                    return true;
                default:
                    return false;
            }
        }

        private bool HasImmediateRaidFlag(string[] args, int startIndex = 0)
        {
            if (args == null || args.Length <= startIndex)
                return false;

            for (int i = Mathf.Max(0, startIndex); i < args.Length; i++)
            {
                if (IsImmediateRaidKeyword(args[i]))
                    return true;
            }

            return false;
        }

        private bool HasStagedWarNear(Vector3 position, float radius = 175f)
        {
            return activeCobaltWars.Values.Any(x => x != null && !x.IsEnded && Vector3.Distance(x.location, position) <= radius);
        }

        private bool HasAnyRaidEventInProgress(CobaltWarSession excludedWar = null)
        {
            if (activeCobaltWars.Values.Any(x => x != null && !x.IsEnded && x != excludedWar))
                return true;

            return EventRandomManager._AllRaids.Any(x => x != null && !x.isDestroyed && (excludedWar == null || x.warSession != excludedWar));
        }

        private string GetRaidStartFailureMessageKey(List<ulong> authedPlayers, string raidType, raidConfig overrideConfig, CobaltWarSession excludedWar = null, bool bypassOnlineRequirement = false)
        {
            if (HasAnyRaidEventInProgress(excludedWar))
                return "CobaltWarCancelledAnotherRaidActive";

            if (!string.IsNullOrEmpty(raidType) && !IsRaidTypeEnabled(raidType))
                return "CobaltRaidTypeDisabled";

            if (!bypassOnlineRequirement && configData.settings.mustBeOnlinePlayer && authedPlayers != null && authedPlayers.Count > 0)
            {
                string availabilityMessageKey = GetAuthorizedRaidAvailabilityMessageKey(null, authedPlayers, false);
                if (!string.IsNullOrEmpty(availabilityMessageKey))
                    return availabilityMessageKey;
            }

            if (!bypassOnlineRequirement)
            {
                int currentOnline = GetOnlineRaidPlayerCount();
                if (!IsRaidTypeAllowedByOnline(raidType, currentOnline))
                    return "CobaltWarCancelledMinOnline";
            }

            if (!(configData.raidSettings.raidTypes.ContainsKey(raidType) || overrideConfig != null))
                return "CobaltWarCancelledMissingProfile";

            return null;
        }

        private int GetOnlineRaidPlayerCount()
        {
            return BasePlayer.activePlayerList.Count(player => player != null && player.IsConnected && !player.IsNpc);
        }

        private bool IsRaidTypeEnabled(string raidType)
        {
            if (string.IsNullOrWhiteSpace(raidType))
                return false;

            Dictionary<string, bool> enabledRaidTypes = configData?.cobaltWar?.enabledRaidTypes;
            if (enabledRaidTypes == null || enabledRaidTypes.Count == 0)
                return true;

            string normalizedType = raidType.Trim().ToLowerInvariant();
            bool enabled;
            if (enabledRaidTypes.TryGetValue(normalizedType, out enabled))
                return enabled;

            foreach (var entry in enabledRaidTypes)
            {
                if (!string.IsNullOrEmpty(entry.Key) && string.Equals(entry.Key.Trim(), normalizedType, StringComparison.OrdinalIgnoreCase))
                    return entry.Value;
            }

            return true;
        }

        [HookMethod("IsCobaltRaidTypeEnabled")]
        private object IsCobaltRaidTypeEnabledHook(string raidType)
        {
            return IsRaidTypeEnabled(raidType);
        }

        private int GetMinOnlineForRaidType(string raidType)
        {
            if (string.IsNullOrEmpty(raidType) || configData?.cobaltWar?.minOnlineByRaidType == null)
                return 0;

            string normalizedType = raidType.Trim().ToLowerInvariant();
            int requiredOnline;
            if (configData.cobaltWar.minOnlineByRaidType.TryGetValue(normalizedType, out requiredOnline))
                return Mathf.Max(0, requiredOnline);

            foreach (var entry in configData.cobaltWar.minOnlineByRaidType)
            {
                if (!string.IsNullOrEmpty(entry.Key) && string.Equals(entry.Key.Trim(), normalizedType, StringComparison.OrdinalIgnoreCase))
                    return Mathf.Max(0, entry.Value);
            }

            return 0;
        }

        private bool IsRaidTypeAllowedByOnline(string raidType, int currentOnline)
        {
            int requiredOnline = GetMinOnlineForRaidType(raidType);
            return requiredOnline <= 0 || currentOnline >= requiredOnline;
        }

        private bool MeetsRaidTypeOnlineRequirement(string raidType, out int currentOnline, out int requiredOnline)
        {
            currentOnline = GetOnlineRaidPlayerCount();
            requiredOnline = GetMinOnlineForRaidType(raidType);
            return requiredOnline <= 0 || currentOnline >= requiredOnline;
        }

        private List<string> FilterRaidTypesByOnline(IEnumerable<string> raidTypes)
        {
            List<string> filtered = new List<string>();
            if (raidTypes == null)
                return filtered;

            int currentOnline = GetOnlineRaidPlayerCount();
            foreach (string raidType in raidTypes)
            {
                if (string.IsNullOrEmpty(raidType) || filtered.Contains(raidType))
                    continue;

                if (IsRaidTypeEnabled(raidType) && IsRaidTypeAllowedByOnline(raidType, currentOnline))
                    filtered.Add(raidType);
            }

            return filtered;
        }

        private ConfigData.BalanceTierConfig GetBalanceTierFor(int balance)
        {
            if (configData?.cobaltWar?.balanceTiers == null || configData.cobaltWar.balanceTiers.Count == 0)
                return null;

            int currentOnline = GetOnlineRaidPlayerCount();

            return configData.cobaltWar.balanceTiers
                .Where(x => x != null && balance >= x.minBalance && !string.IsNullOrEmpty(x.raidType) && IsRaidTypeEnabled(x.raidType) && IsRaidTypeAllowedByOnline(x.raidType, currentOnline))
                .OrderByDescending(x => x.minBalance)
                .FirstOrDefault();
        }

        private object GetPluginScriptInstance(Plugin plugin)
        {
            if (plugin == null)
                return null;

            try
            {
                Type type = plugin.GetType();
                PropertyInfo property = type.GetProperty("Object", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                if (property != null)
                    return property.GetValue(plugin, null);

                FieldInfo field = type.GetField("Object", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                if (field != null)
                    return field.GetValue(plugin);
            }
            catch
            {
            }

            return null;
        }

        private GameObject GetArenaTournamentRegistrationEvent()
        {
            if (ArenaTournament == null || configData?.cobaltWar == null || !configData.cobaltWar.blockDuringArenaTournamentRegistration)
                return null;

            try
            {
                object script = GetPluginScriptInstance(ArenaTournament);
                if (script == null)
                    return null;

                FieldInfo field = script.GetType().GetField("_currentevent", BindingFlags.NonPublic | BindingFlags.Instance);
                if (field == null)
                    return null;

                return field.GetValue(script) as GameObject;
            }
            catch
            {
                return null;
            }
        }

        private bool IsArenaTournamentRegistrationOpen()
        {
            return GetArenaTournamentRegistrationEvent() != null;
        }

        private bool IsPlayerOnArenaTournament(BasePlayer player)
        {
            if (player == null || ArenaTournament == null)
                return false;

            try
            {
                object hook = ArenaTournament.Call("IsOnTournament", player.userID.Get());
                return hook is bool && (bool)hook;
            }
            catch
            {
                return false;
            }
        }

        private bool IsPlayerRegisteredForArenaTournament(BasePlayer player)
        {
            if (player == null || ArenaTournament == null)
                return false;

            GameObject currentEvent = GetArenaTournamentRegistrationEvent();
            if (currentEvent == null)
                return false;

            try
            {
                Component arenaComponent = currentEvent.GetComponents<Component>().FirstOrDefault(x => x != null && x.GetType().Name == "Arena");
                if (arenaComponent == null)
                    return false;

                MethodInfo method = arenaComponent.GetType().GetMethod("IsWList", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                if (method != null)
                {
                    object result = method.Invoke(arenaComponent, new object[] { player });
                    if (result is bool && (bool)result)
                        return true;
                }
            }
            catch
            {
            }

            return false;
        }

        private bool IsArenaTournamentBlockingCobalt(BasePlayer player, bool includeRegistrationWindow, out string messageKey)
        {
            messageKey = null;

            if (player == null || configData?.cobaltWar == null || ArenaTournament == null)
                return false;

            if (configData.cobaltWar.blockArenaTournamentParticipants && IsPlayerOnArenaTournament(player))
            {
                messageKey = "CobaltJoinArenaBusy";
                return true;
            }

            if (includeRegistrationWindow && configData.cobaltWar.blockDuringArenaTournamentRegistration && IsPlayerRegisteredForArenaTournament(player))
            {
                messageKey = "CobaltJoinArenaRegistrationBusy";
                return true;
            }

            return false;
        }

        private bool HasEligibleOnlineAuthorizedPlayer(BuildingPrivlidge privilege, bool includeArenaFilters = true)
        {
            if (privilege == null)
                return false;

            foreach (ulong userId in privilege.authorizedPlayers)
            {
                BasePlayer player = BasePlayer.FindByID(userId);
                if (player == null || !player.IsConnected)
                    continue;

                string arenaMessageKey;
                if (includeArenaFilters && IsArenaTournamentBlockingCobalt(player, true, out arenaMessageKey))
                    continue;

                if (IsBusyWithRaidableBases(player))
                    continue;

                if (IsRaidTargetAfk(player))
                    continue;

                return true;
            }

            return false;
        }

        private string GetAuthorizedRaidAvailabilityMessageKey(BuildingPrivlidge privilege, IEnumerable<ulong> authPlayers = null, bool includeArenaFilters = true)
        {
            List<ulong> candidates = Pool.Get<List<ulong>>();
            try
            {
                if (authPlayers != null)
                {
                    foreach (ulong userId in authPlayers)
                    {
                        if (userId == 0UL || candidates.Contains(userId))
                            continue;

                        candidates.Add(userId);
                    }
                }

                if (privilege != null && privilege.authorizedPlayers != null)
                {
                    foreach (ulong userId in privilege.authorizedPlayers)
                    {
                        if (userId == 0UL || candidates.Contains(userId))
                            continue;

                        candidates.Add(userId);
                    }
                }

                bool hasConnectedEligibleAuthorized = false;
                bool hasConnectedRaidableBasesBusyAuthorized = false;
                foreach (ulong userId in candidates)
                {
                    BasePlayer player = BasePlayer.FindByID(userId);
                    if (player == null || !player.IsConnected || player.IsNpc)
                        continue;

                    string arenaMessageKey;
                    if (includeArenaFilters && IsArenaTournamentBlockingCobalt(player, true, out arenaMessageKey))
                        continue;

                    if (IsBusyWithRaidableBases(player))
                    {
                        hasConnectedRaidableBasesBusyAuthorized = true;
                        continue;
                    }

                    hasConnectedEligibleAuthorized = true;
                    if (!IsRaidTargetAfk(player))
                        return null;
                }

                if (hasConnectedEligibleAuthorized)
                    return "CobaltWarCancelledOwnersAfk";

                if (hasConnectedRaidableBasesBusyAuthorized)
                    return "CobaltWarCancelledOwnersRaidableBases";

                return "CobaltWarCancelledOwnersOffline";
            }
            finally
            {
                Pool.FreeUnmanaged(ref candidates);
            }
        }

        private string MapTriggeredRaidCancellationMessageKey(string messageKey)
        {
            switch (messageKey)
            {
                case "CobaltWarCancelledOwnersOffline":
                    return "TriggeredRaidCancelledOwnersOffline";
                case "CobaltWarCancelledOwnersAfk":
                    return "TriggeredRaidCancelledAfk";
                case "CobaltWarCancelledOwnersRaidableBases":
                    return "TriggeredRaidCancelledOwnersRaidableBases";
                default:
                    return messageKey;
            }
        }

        private bool IsBusyWithRaidableBases(BasePlayer player)
        {
            if (RaidableBases == null || player == null || player.IsNpc || !player.IsConnected || player.transform == null)
                return false;

            try
            {
                if (Convert.ToBoolean(RaidableBases.CallHook("EventTerritory", player.transform.position)))
                    return true;

                return Convert.ToBoolean(RaidableBases.CallHook("HasPVPDelay", player.userID.Get()));
            }
            catch (Exception ex)
            {
                CobaltDiagnosticLog("idle", $"RaidableBases busy check failed: player={player.displayName}, error={ex.GetType().Name}: {ex.Message}.");
                return false;
            }
        }

        private bool IsUnderNewPlayerRaidProtection(ulong userId, out TimeSpan remaining)
        {
            remaining = TimeSpan.Zero;

            if (configData?.cobaltWar == null || !configData.cobaltWar.protectNewPlayers || configData.cobaltWar.newPlayerProtectionHours <= 0f)
                return false;

            EnsurePlayerDataStructures();

            DateTime firstSeen;
            if (!pcdData.firstSeen.TryGetValue(userId, out firstSeen))
                return false;

            remaining = firstSeen.AddHours(configData.cobaltWar.newPlayerProtectionHours) - DateTime.UtcNow;
            return remaining > TimeSpan.Zero;
        }

        private bool IsProtectedRaidTarget(BasePlayer targetPlayer, out TimeSpan remaining)
        {
            if (targetPlayer == null)
            {
                remaining = TimeSpan.Zero;
                return false;
            }

            return IsUnderNewPlayerRaidProtection(targetPlayer.userID.Get(), out remaining);
        }

        private void QueueDeferredCobaltXp(ulong userId, float damage, bool saveImmediately = true)
        {
            if (userId == 0UL || damage <= 0f)
                return;

            EnsurePlayerDataStructures();

            float current;
            pcdData.deferredXpDamage.TryGetValue(userId, out current);
            pcdData.deferredXpDamage[userId] = current + damage;

            if (saveImmediately)
                SaveData();
        }

        private void QueueDeferredCobaltRewardXp(ulong userId, double xp, bool saveImmediately = true)
        {
            if (userId == 0UL || xp <= 0d)
                return;

            EnsurePlayerDataStructures();

            double current;
            pcdData.deferredXpRewards.TryGetValue(userId, out current);
            pcdData.deferredXpRewards[userId] = current + xp;

            if (saveImmediately)
                SaveData();
        }

        private double GetCobaltDamageXp(float damage)
        {
            if (damage <= 0f || configData?.cobaltWar == null)
                return 0d;

            return damage * configData.cobaltWar.xpPerDamage;
        }

        private void SendCobaltXpSummary(BasePlayer player, double damageXp, double victoryXp, bool deferred = false)
        {
            if (player == null)
                return;

            double totalXp = damageXp + victoryXp;
            if (totalXp <= 0d)
                return;

            string messageKey = deferred ? "CobaltXpSummaryDeferred" : "CobaltXpSummary";
            SendReply(player, lang.GetMessage(messageKey, this, player.UserIDString), Math.Round(damageXp, 2), Math.Round(victoryXp, 2), Math.Round(totalXp, 2));
        }

        private bool TryAwardSkillTreeXp(ulong userId, double xp)
        {
            if (userId == 0UL || xp <= 0d || SkillTree == null)
                return false;

            try
            {
                CobaltDiagnosticLog("idle", $"SkillTree AwardXP attempt: userId={userId}, xp={Math.Round(xp, 2)}, mode=userId.");
                TraceExternalPluginCall("external", SkillTree, "AwardXP", userId, xp, Name, false);
                CobaltDiagnosticLog("idle", $"SkillTree AwardXP success: userId={userId}, xp={Math.Round(xp, 2)}, mode=userId.");
                return true;
            }
            catch
            {
            }

            BasePlayer player = BasePlayer.FindByID(userId);
            if (player == null || !player.IsConnected)
                return false;

            try
            {
                CobaltDiagnosticLog("idle", $"SkillTree AwardXP fallback attempt: userId={userId}, xp={Math.Round(xp, 2)}, mode=player.");
                TraceExternalPluginCall("external", SkillTree, "AwardXP", player, xp, Name, false);
                CobaltDiagnosticLog("idle", $"SkillTree AwardXP fallback success: userId={userId}, xp={Math.Round(xp, 2)}, mode=player.");
                return true;
            }
            catch
            {
                return false;
            }
        }

        private void TryAwardDeferredCobaltXp(BasePlayer player)
        {
            if (player == null || SkillTree == null || configData?.cobaltWar == null)
                return;

            EnsurePlayerDataStructures();

            bool changed = false;
            double awardedDamageXp = 0d;
            double awardedVictoryXp = 0d;

            float damage;
            if (pcdData.deferredXpDamage.TryGetValue(player.userID.Get(), out damage) && damage > 0f)
            {
                try
                {
                    if (AwardDamageXp(player, damage, out awardedDamageXp))
                    {
                        pcdData.deferredXpDamage.Remove(player.userID.Get());
                        changed = true;
                    }
                }
                catch
                {
                }
            }

            double rewardXp;
            if (pcdData.deferredXpRewards.TryGetValue(player.userID.Get(), out rewardXp) && rewardXp > 0d)
            {
                try
                {
                    if (TryAwardSkillTreeXp(player.userID, rewardXp))
                    {
                        awardedVictoryXp = rewardXp;
                        pcdData.deferredXpRewards.Remove(player.userID.Get());
                        changed = true;
                    }
                }
                catch
                {
                }
            }

            if (changed)
            {
                CobaltDiagnosticLog("idle", $"SkillTree deferred XP applied: player={player.displayName}({player.userID}), damageXp={Math.Round(awardedDamageXp, 2)}, rewardXp={Math.Round(awardedVictoryXp, 2)}.");
                SaveData();
            }

            SendCobaltXpSummary(player, awardedDamageXp, awardedVictoryXp, true);
        }

        private bool ShouldSuppressSkillTreeXpLoss(BasePlayer player)
        {
            if (player == null || SkillTree == null || configData?.cobaltWar == null || !(configData.cobaltWar.preventSkillTreeXpLossDuringRaid ?? true))
                return false;

            CobaltWarSession war;
            bool useDefenderLoadout;
            if (TryGetCombatRespawnWarState(player, out war, out useDefenderLoadout) && war != null && !war.IsEnded)
                return true;

            CobaltWarSession registeredWar = FindWarByRegisteredPlayer(player.userID);
            if (registeredWar != null && !registeredWar.IsEnded && (registeredWar.phase == CobaltWarPhase.Preparation || registeredWar.phase == CobaltWarPhase.Active || registeredWar.phase == CobaltWarPhase.Cleanup))
                return true;

            Vector3 playerPosition = player.transform != null ? player.transform.position : Vector3.zero;
            CobaltWarSession participantWar = FindWarByParticipant(player.userID, playerPosition);
            if (participantWar == null || participantWar.IsEnded)
                return false;

            if (participantWar.phase != CobaltWarPhase.Preparation && participantWar.phase != CobaltWarPhase.Active && participantWar.phase != CobaltWarPhase.Cleanup)
                return false;

            return participantWar.IsInsideCombatArea(playerPosition);
        }

        private object STOnLoseXP(BasePlayer player)
        {
            bool suppress = ShouldSuppressSkillTreeXpLoss(player);
            if (suppress && player != null)
                CobaltDiagnosticLog("idle", $"SkillTree STOnLoseXP suppressed for player={player.displayName}({player.userID}).");
            return suppress ? (object)true : null;
        }

        private void SetDefenderRespawnProtection(ulong userId, float seconds)
        {
            if (userId == 0UL || seconds <= 0f)
                return;

            defenderRespawnProtection[userId] = DateTime.UtcNow.AddSeconds(seconds);
        }

        private void RefreshDefenderRespawnProtection(ulong userId, float seconds)
        {
            if (userId == 0UL || seconds <= 0f)
                return;

            defenderRespawnProtection[userId] = DateTime.UtcNow.AddSeconds(seconds);
        }

        private void ArmPendingDefenderRespawnProtection(ulong userId)
        {
            if (userId == 0UL || configData?.cobaltWar == null)
                return;

            float protectionSeconds = Mathf.Max(0f, configData.cobaltWar.respawnProtectionSeconds);
            if (protectionSeconds <= 0f)
                return;

            // Cover the short gap between actual respawn and the later combat-prepare step.
            defenderRespawnProtection[userId] = DateTime.UtcNow.AddSeconds(Mathf.Max(protectionSeconds + 1f, 1.5f));
        }

        private void ClearDefenderRespawnProtection(ulong userId)
        {
            if (userId == 0UL)
                return;

            defenderRespawnProtection.Remove(userId);
        }

        private bool HasDefenderRespawnProtection(ulong userId, out float remainingSeconds)
        {
            remainingSeconds = 0f;
            if (userId == 0UL)
                return false;

            DateTime expiresAt;
            if (!defenderRespawnProtection.TryGetValue(userId, out expiresAt))
                return false;

            remainingSeconds = Mathf.Max(0f, (float)(expiresAt - DateTime.UtcNow).TotalSeconds);
            if (remainingSeconds <= 0f)
            {
                defenderRespawnProtection.Remove(userId);
                return false;
            }

            return true;
        }

        private int GetConfiguredRaidTypeValue(Dictionary<string, int> map, string raidType, int fallback = 0)
        {
            if (map == null || map.Count == 0)
                return fallback;

            int value;
            if (!string.IsNullOrEmpty(raidType) && map.TryGetValue(raidType, out value))
                return value;

            return map.Values.FirstOrDefault();
        }

        private double GetConfiguredRaidTypeValue(Dictionary<string, double> map, string raidType, double fallback = 0d)
        {
            if (map == null || map.Count == 0)
                return fallback;

            double value;
            if (!string.IsNullOrEmpty(raidType) && map.TryGetValue(raidType, out value))
                return value;

            return map.Values.FirstOrDefault();
        }

        private double GetSuccessDefenseXpForRaidType(string raidType)
        {
            return Math.Max(0d, GetConfiguredRaidTypeValue(configData?.cobaltWar?.successDefenseXpByRaidType, raidType, configData?.cobaltWar?.successDefenseXp ?? 0d));
        }

        private string NormalizeRouletteDifficulty(string raidType)
        {
            string normalized = (raidType ?? string.Empty).Trim().ToLowerInvariant()
                .Replace("ё", "е")
                .Replace("_", string.Empty)
                .Replace("-", string.Empty)
                .Replace(" ", string.Empty);
            switch (normalized)
            {
                case "1":
                case "easy":
                case "light":
                case "легкая":
                case "легкий":
                    return "easy";

                case "2":
                case "medium":
                case "normal":
                case "средняя":
                case "средний":
                case "обычная":
                case "обычный":
                    return "medium";

                case "3":
                case "hard":
                case "сложная":
                case "сложный":
                case "тяжелая":
                case "тяжелый":
                case "хард":
                    return "hard";

                case "4":
                case "expert":
                case "elite":
                case "эксперт":
                case "экспертная":
                case "элитная":
                case "элитный":
                    return "expert";

                case "5":
                case "nightmare":
                case "unfair":
                case "insane":
                case "кошмарная":
                case "кошмарный":
                case "нечестная":
                case "нечестный":
                    return "nightmare";

                default:
                    return string.IsNullOrEmpty(normalized) ? "medium" : normalized;
            }
        }

        private bool HasPendingDefenderSnapshotForWar(ulong userId, int warId)
        {
            DefenderSnapshot snapshot;
            return userId != 0UL
                && TryGetDefenderSnapshot(userId, out snapshot)
                && snapshot != null
                && snapshot.warId == warId;
        }

        private bool HasPendingDefenderSnapshotForWar(ulong userId)
        {
            DefenderSnapshot snapshot;
            return userId != 0UL
                && TryGetDefenderSnapshot(userId, out snapshot)
                && snapshot != null;
        }

        private void QueueVictoryLootRouletteRewards(int warId, string raidType, bool isExternalRaidBase, string externalSourceId, List<ulong> rewardPlayers)
        {
            if (rewardPlayers == null || rewardPlayers.Count == 0)
                return;

            string difficulty = NormalizeRouletteDifficulty(raidType);
            string source = string.IsNullOrEmpty(externalSourceId)
                ? Name
                : $"{Name}:{externalSourceId}";

            List<ulong> uniquePlayers = rewardPlayers
                .Where(userId => userId != 0UL)
                .Distinct()
                .ToList();

            CobaltDiagnosticLog("raid", $"Война #{warId}: очередь рулетки победы, difficulty={difficulty}, players={uniquePlayers.Count}, external={isExternalRaidBase}.");

            for (int i = 0; i < uniquePlayers.Count; i++)
            {
                ulong userId = uniquePlayers[i];
                float delay = Mathf.Min(8f, 0.75f + (i * 0.15f));
                timer.Once(delay, () => TryOpenVictoryLootRoulette(userId, warId, difficulty, source, 0));
            }
        }

        private void TryOpenVictoryLootRoulette(ulong userId, int warId, string difficulty, string source, int attempt)
        {
            if (userId == 0UL)
                return;

            BasePlayer player = BasePlayer.FindByID(userId);
            if (player == null || !player.IsConnected)
            {
                CobaltDiagnosticLog("raid", $"Война #{warId}: рулетка победы пропущена, игрок не онлайн: userId={userId}, difficulty={difficulty}.");
                return;
            }

            if (player.IsDead() || player.IsWounded() || player.IsSleeping())
            {
                if (attempt < 30)
                {
                    timer.Once(0.5f, () => TryOpenVictoryLootRoulette(userId, warId, difficulty, source, attempt + 1));
                    return;
                }

                CobaltDiagnosticLog("raid", $"Война #{warId}: рулетка победы пропущена, игрок не готов к открытию: player={player.displayName}({player.userID}), difficulty={difficulty}.");
                return;
            }

            if (RandomLootRoulette == null)
            {
                CobaltDiagnosticLog("raid", $"Война #{warId}: рулетка победы пропущена, RandomLootRoulette не загружен: player={player.displayName}({player.userID}), difficulty={difficulty}.");
                return;
            }

            object result = OpenVictoryLootRoulette(player, warId, difficulty, source);
            if (result is string message && !string.IsNullOrEmpty(message))
                CobaltDiagnosticLog("raid", $"Война #{warId}: RandomLootRoulette вернул сообщение: player={player.displayName}({player.userID}), difficulty={difficulty}, result={message}.");
            else if (result is bool && !(bool)result)
                CobaltDiagnosticLog("raid", $"Война #{warId}: RandomLootRoulette не открыл рулетку: player={player.displayName}({player.userID}), difficulty={difficulty}, result=false.");
            else if (result is bool && (bool)result)
            {
                CobaltDiagnosticLog("raid", $"Война #{warId}: рулетка победы открыта: player={player.displayName}({player.userID}), difficulty={difficulty}.");
                ScheduleVictoryLootRouletteStartCheck(userId, warId, difficulty, source, 0);
            }
            else
                CobaltDiagnosticLog("raid", $"Война #{warId}: RandomLootRoulette вернул null всеми способами: player={player.displayName}({player.userID}), difficulty={difficulty}, source={source}. Проверьте, что обновленный RandomLootRoulette загружен.");
        }

        private object OpenVictoryLootRoulette(BasePlayer player, int warId, string difficulty, string source)
        {
            object result = TraceExternalPluginCall("external", RandomLootRoulette, "API_CobaltWarEventFinished", player, true, difficulty, source);
            if (result != null)
                return result;

            CobaltDiagnosticLog("raid", $"Война #{warId}: API_CobaltWarEventFinished вернул null, пробую совместимые способы запуска RandomLootRoulette.");

            result = TraceExternalPluginCall("external", RandomLootRoulette, "API_OpenLootRouletteByDifficulty", player, difficulty, source);
            if (result != null)
                return result;

            result = TraceExternalPluginCall("external", RandomLootRoulette, "API_EventFinishedByDifficulty", player, true, difficulty, source);
            if (result != null)
                return result;

            return TraceExternalHookCall("external", "OnRandomLootBaseFinished", player, true, difficulty, source);
        }

        private void ScheduleVictoryLootRouletteStartCheck(ulong userId, int warId, string difficulty, string source, int attempt)
        {
            timer.Once(attempt == 0 ? 1.25f : 0.75f, () => VerifyVictoryLootRouletteStarted(userId, warId, difficulty, source, attempt));
        }

        private void VerifyVictoryLootRouletteStarted(ulong userId, int warId, string difficulty, string source, int attempt)
        {
            if (RandomLootRoulette == null || userId == 0UL)
                return;

            BasePlayer player = BasePlayer.FindByID(userId);
            if (player == null || !player.IsConnected)
                return;

            object activeResult = TraceExternalPluginCall("external", RandomLootRoulette, "API_HasActiveRoulette", player);
            if (activeResult is bool && (bool)activeResult)
            {
                CobaltDiagnosticLog("raid", $"Война #{warId}: автозапуск рулетки подтвержден: player={player.displayName}({player.userID}), difficulty={difficulty}.");
                return;
            }

            object startResult = TraceExternalPluginCall("external", RandomLootRoulette, "API_CobaltWarStartEventReward", player);
            if (startResult is bool && (bool)startResult)
            {
                CobaltDiagnosticLog("raid", $"Война #{warId}: автозапуск рулетки восстановлен вручную: player={player.displayName}({player.userID}), difficulty={difficulty}.");
                return;
            }

            if (attempt < 2)
            {
                ScheduleVictoryLootRouletteStartCheck(userId, warId, difficulty, source, attempt + 1);
                return;
            }

            CobaltDiagnosticLog("raid", $"Война #{warId}: рулетка открыта, но старт не подтвержден: player={player.displayName}({player.userID}), difficulty={difficulty}, source={source}, active={SummarizeExternalValue(activeResult)}, start={SummarizeExternalValue(startResult)}.");
        }

