        private void QueueRouletteRewardReplayIfNeeded(BasePlayer player, object wonItems, string source, int caseID)
        {
            if (player == null || wonItems == null)
                return;

            ulong userId = player.userID.Get();
            if (userId == 0UL || !HasPendingDefenderSnapshotForWar(userId))
                return;

            IEnumerable rewards = wonItems as IEnumerable;
            if (rewards == null)
                return;

            List<object> replayItems;
            if (!pendingRouletteRewardReplays.TryGetValue(userId, out replayItems))
            {
                replayItems = new List<object>();
                pendingRouletteRewardReplays[userId] = replayItems;
            }

            int added = 0;
            foreach (object reward in rewards)
            {
                if (!IsRouletteInventoryReward(reward))
                    continue;

                replayItems.Add(reward);
                added++;
            }

            if (added > 0)
                CobaltDiagnosticLog("raid", $"RandomLootRoulette reward replay queued: player={GetRoulettePlayerLabel(player)}, caseID={caseID}, items={added}, source={source}.");
        }

        private bool IsRouletteInventoryReward(object reward)
        {
            if (reward == null)
                return false;

            FieldInfo typeField = reward.GetType().GetField("Type", BindingFlags.Public | BindingFlags.Instance);
            object typeValue = typeField?.GetValue(reward);
            return typeValue != null && string.Equals(typeValue.ToString(), "Item", StringComparison.OrdinalIgnoreCase);
        }

        private void ReplayPendingRouletteItemRewards(BasePlayer player)
        {
            if (player == null)
                return;

            List<object> replayItems;
            if (!pendingRouletteRewardReplays.TryGetValue(player.userID.Get(), out replayItems) || replayItems == null || replayItems.Count == 0)
                return;

            pendingRouletteRewardReplays.Remove(player.userID.Get());

            int given = 0;
            foreach (object reward in replayItems)
            {
                if (!IsRouletteInventoryReward(reward))
                    continue;

                MethodInfo getMethod = reward.GetType().GetMethod("Get", BindingFlags.Public | BindingFlags.Instance, null, new[] { typeof(BasePlayer), typeof(int) }, null);
                try
                {
                    if (getMethod != null)
                    {
                        getMethod.Invoke(reward, new object[] { player, 1 });
                        given++;
                    }
                }
                catch (Exception ex)
                {
                    CobaltDiagnosticLog("raid", $"RandomLootRoulette reward replay failed: player={GetRoulettePlayerLabel(player)}, error={ex.GetType().Name}: {ex.Message}.");
                }
            }

            if (given > 0)
                CobaltDiagnosticLog("raid", $"RandomLootRoulette reward replay restored after inventory return: player={GetRoulettePlayerLabel(player)}, items={given}.");
        }

