        private string NormalizeSupportDroneTierKey(string tierKey)
        {
            if (string.IsNullOrWhiteSpace(tierKey))
                return null;

            string normalized = tierKey.Trim().ToLowerInvariant();
            switch (normalized)
            {
                case "light":
                case "easy":
                    return "lite";
                case "medium":
                case "mid":
                case "assault":
                    return "middle";
                case "heavy":
                case "elite":
                    return "hard";
                default:
                    return normalized;
            }
        }

        private IEnumerable<KeyValuePair<string, SupportDroneTierConfig>> GetOrderedSupportDroneTiers()
        {
            var tiers = configData?.cobaltWar?.supportDroneTiers;
            if (tiers == null || tiers.Count == 0)
                yield break;

            HashSet<string> yielded = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (string tierKey in SupportDroneTierOrder)
            {
                SupportDroneTierConfig tier;
                if (tiers.TryGetValue(tierKey, out tier) && tier != null)
                {
                    yielded.Add(tierKey);
                    yield return new KeyValuePair<string, SupportDroneTierConfig>(tierKey, tier);
                }
            }

            foreach (var entry in tiers)
            {
                if (entry.Value == null || yielded.Contains(entry.Key))
                    continue;

                yield return entry;
            }
        }

        private string GetDefaultPurchasableSupportDroneTierKey()
        {
            foreach (var entry in GetOrderedSupportDroneTiers())
                return entry.Key;

            return null;
        }

        private int GetMaxPurchasedSupportDrones(string raidType)
        {
            return Mathf.Max(0, GetConfiguredRaidTypeValue(configData?.cobaltWar?.maxPurchasedSupportDronesByRaidType, raidType, 0));
        }

        private string ChooseSupportDroneTierKey(string raidType)
        {
            var warConfig = configData?.cobaltWar;
            if (warConfig?.supportDroneTiers == null || warConfig.supportDroneTiers.Count == 0)
                return null;

            Dictionary<string, int> chances = null;
            if (!string.IsNullOrEmpty(raidType) && warConfig.supportDroneTierChancesByRaidType != null)
                warConfig.supportDroneTierChancesByRaidType.TryGetValue(raidType, out chances);

            if (chances == null || chances.Count == 0)
                return warConfig.supportDroneTiers.Keys.FirstOrDefault();

            int totalChance = chances.Where(x => x.Value > 0 && warConfig.supportDroneTiers.ContainsKey(x.Key)).Sum(x => x.Value);
            if (totalChance <= 0)
                return warConfig.supportDroneTiers.Keys.FirstOrDefault();

            int roll = UnityEngine.Random.Range(1, totalChance + 1);
            int current = 0;
            foreach (var entry in chances)
            {
                if (entry.Value <= 0 || !warConfig.supportDroneTiers.ContainsKey(entry.Key))
                    continue;

                current += entry.Value;
                if (roll <= current)
                    return entry.Key;
            }

            return warConfig.supportDroneTiers.Keys.FirstOrDefault();
        }

        private SupportDroneTierConfig GetSupportDroneTier(string tierKey)
        {
            tierKey = NormalizeSupportDroneTierKey(tierKey);
            if (string.IsNullOrEmpty(tierKey) || configData?.cobaltWar?.supportDroneTiers == null)
                return null;

            SupportDroneTierConfig tier;
            return configData.cobaltWar.supportDroneTiers.TryGetValue(tierKey, out tier) ? tier : null;
        }

        private int GetSupportDroneTierSlots(string tierKey)
        {
            string normalizedTierKey = NormalizeSupportDroneTierKey(tierKey);
            SupportDroneTierConfig tier = GetSupportDroneTier(tierKey);
            int configuredSlots = Mathf.Max(1, tier?.purchaseSlots ?? 1);

            switch (normalizedTierKey)
            {
                case "middle":
                    return Mathf.Max(2, configuredSlots);
                case "hard":
                    return Mathf.Max(3, configuredSlots);
                case "lite":
                default:
                    return Mathf.Max(1, configuredSlots);
            }
        }

        private int GetSupportDroneTierCost(string raidType, string tierKey)
        {
            return Mathf.Max(0, GetSupportDronePurchaseCost(raidType) * GetSupportDroneTierSlots(tierKey));
        }

        private string GetSupportDroneTierDisplayName(string tierKey)
        {
            SupportDroneTierConfig tier = GetSupportDroneTier(tierKey);
            if (!string.IsNullOrEmpty(tier?.displayName))
                return tier.displayName;

            return NormalizeSupportDroneTierKey(tierKey) ?? string.Empty;
        }

        private string GetSupportDroneTierUiName(string tierKey)
        {
            switch (NormalizeSupportDroneTierKey(tierKey))
            {
                case "lite":
                    return "Легкий";
                case "middle":
                    return "Штурмовой";
                case "hard":
                    return "Тяжелый";
                default:
                    return GetSupportDroneTierDisplayName(tierKey);
            }
        }

        private string GetSupportDroneTierCostLabel(string raidType, string tierKey, string userId = null, bool forcePaid = false)
        {
            int cost = GetSupportDroneTierCost(raidType, tierKey);
            if (!forcePaid && cost <= 0)
                return lang.GetMessage("CobaltSupportDroneCostFree", this, userId);

            return string.Format(lang.GetMessage("CobaltSupportDroneCostPaid", this, userId), cost);
        }

        private string GetSupportDroneTierPlainCostText(string raidType, string tierKey, string userId = null, bool forcePaid = false)
        {
            int cost = GetSupportDroneTierCost(raidType, tierKey);
            if (!forcePaid && cost <= 0)
                return "бесплатно";

            return $"{cost} Р";
        }

        private bool IsValidCobaltSupportDrone(Drone drone)
        {
            return drone != null && drone.net != null && cobaltSupportDrones.ContainsKey((uint)drone.net.ID.Value);
        }

        private bool IsValidCobaltSupportDroneTurret(AutoTurret turret)
        {
            return FindCobaltSupportDroneState(turret) != null;
        }

        private CobaltSupportDroneState FindCobaltSupportDroneState(BaseNetworkable entity)
        {
            if (entity == null || entity.net == null)
                return null;

            uint netId = (uint)entity.net.ID.Value;
            CobaltSupportDroneState state;
            if (cobaltSupportDrones.TryGetValue(netId, out state))
                return state;

            return cobaltSupportDroneLinkedEntities.TryGetValue(netId, out state) ? state : null;
        }

        private List<CobaltSupportDroneState> GetSupportDroneStatesForWar(int warId)
        {
            CleanupCobaltSupportDroneRegistry();
            return cobaltSupportDrones.Values
                .Where(x => x != null && x.warId == warId)
                .OrderBy(x => x.droneNetId)
                .ToList();
        }

        private int GetSupportDroneFormationIndex(int warId, uint droneNetId, out int totalCount)
        {
            totalCount = 0;
            if (droneNetId == 0U)
                return 0;

            int index = 0;
            foreach (CobaltSupportDroneState state in cobaltSupportDrones.Values)
            {
                if (state == null || state.warId != warId || state.droneNetId == 0U)
                    continue;

                totalCount++;
                if (state.droneNetId < droneNetId)
                    index++;
            }

            if (totalCount <= 0)
                return 0;

            return Mathf.Clamp(index, 0, totalCount - 1);
        }

        private List<CobaltSupportDroneController> GetSupportDroneControllersForWar(int warId)
        {
            List<CobaltSupportDroneController> controllers = new List<CobaltSupportDroneController>();
            foreach (CobaltSupportDroneState state in GetSupportDroneStatesForWar(warId))
            {
                Drone drone = BaseNetworkable.serverEntities.Find(new NetworkableId(state.droneNetId)) as Drone;
                if (drone == null || drone.IsDestroyed)
                    continue;

                CobaltSupportDroneController controller = drone.GetComponent<CobaltSupportDroneController>();
                if (controller == null)
                    continue;

                controllers.Add(controller);
            }

            return controllers;
        }

