        private void CleanupExpiredCobaltTankDebrisWindows()
        {
            float now = Time.realtimeSinceStartup;
            for (int i = cobaltTankDebrisCleanupWindows.Count - 1; i >= 0; i--)
            {
                if (cobaltTankDebrisCleanupWindows[i] == null || cobaltTankDebrisCleanupWindows[i].expiresAt <= now)
                    cobaltTankDebrisCleanupWindows.RemoveAt(i);
            }
        }

        private void CleanupExpiredCobaltHeliDebrisWindows()
        {
            float now = Time.realtimeSinceStartup;
            for (int i = cobaltHeliDebrisCleanupWindows.Count - 1; i >= 0; i--)
            {
                if (cobaltHeliDebrisCleanupWindows[i] == null || cobaltHeliDebrisCleanupWindows[i].expiresAt <= now)
                    cobaltHeliDebrisCleanupWindows.RemoveAt(i);
            }
        }

        private bool IsCobaltTankDebrisCandidate(BaseNetworkable entity)
        {
            BaseEntity baseEntity = entity as BaseEntity;
            if (baseEntity == null || baseEntity.IsDestroyed || baseEntity is BradleyAPC)
                return false;

            string shortPrefabName = (baseEntity.ShortPrefabName ?? string.Empty).ToLowerInvariant();
            string entityName = (baseEntity.name ?? string.Empty).ToLowerInvariant();
            return shortPrefabName.Contains("bradley") || entityName.Contains("bradley");
        }

        private bool IsCobaltHeliDebrisCandidate(BaseNetworkable entity)
        {
            BaseEntity baseEntity = entity as BaseEntity;
            if (baseEntity == null || baseEntity.IsDestroyed || baseEntity is PatrolHelicopter)
                return false;

            string shortPrefabName = (baseEntity.ShortPrefabName ?? string.Empty).ToLowerInvariant();
            string entityName = (baseEntity.name ?? string.Empty).ToLowerInvariant();

            bool looksLikeHeli = shortPrefabName.Contains("patrolhelicopter")
                || entityName.Contains("patrolhelicopter")
                || shortPrefabName.Contains("patrolheli")
                || entityName.Contains("patrolheli")
                || shortPrefabName.Contains("helicopter")
                || entityName.Contains("helicopter")
                || shortPrefabName.Contains("heli")
                || entityName.Contains("heli");
            if (!looksLikeHeli)
                return false;

            return shortPrefabName.Contains("gib")
                || entityName.Contains("gib")
                || shortPrefabName.Contains("debris")
                || entityName.Contains("debris")
                || shortPrefabName.Contains("wreck")
                || entityName.Contains("wreck");
        }

        private bool IsInsideCobaltTankDebrisCleanupWindow(Vector3 position)
        {
            CleanupExpiredCobaltTankDebrisWindows();

            foreach (CobaltTankDebrisCleanupWindow window in cobaltTankDebrisCleanupWindows)
            {
                if (window == null)
                    continue;

                if ((position - window.position).sqrMagnitude <= window.radius * window.radius)
                    return true;
            }

            return false;
        }

        private bool IsInsideCobaltHeliDebrisCleanupWindow(Vector3 position)
        {
            CleanupExpiredCobaltHeliDebrisWindows();

            foreach (CobaltHeliDebrisCleanupWindow window in cobaltHeliDebrisCleanupWindows)
            {
                if (window == null)
                    continue;

                if ((position - window.position).sqrMagnitude <= window.radius * window.radius)
                    return true;
            }

            return false;
        }

        private void CleanupCobaltTankDebrisNear(Vector3 position, float radius)
        {
            List<BaseEntity> nearbyEntities = Pool.Get<List<BaseEntity>>();
            try
            {
                Vis.Entities(position, radius, nearbyEntities);

                foreach (BaseEntity entity in nearbyEntities)
                {
                    if (entity == null || entity.IsDestroyed || !IsCobaltTankDebrisCandidate(entity))
                        continue;

                    entity.Kill(BaseNetworkable.DestroyMode.None);
                }
            }
            finally
            {
                Pool.FreeUnmanaged(ref nearbyEntities);
            }
        }

        private void CleanupCobaltHeliDebrisNear(Vector3 position, float radius)
        {
            List<BaseEntity> nearbyEntities = Pool.Get<List<BaseEntity>>();
            try
            {
                Vis.Entities(position, radius, nearbyEntities);

                foreach (BaseEntity entity in nearbyEntities)
                {
                    if (entity == null || entity.IsDestroyed || !IsCobaltHeliDebrisCandidate(entity))
                        continue;

                    entity.Kill(BaseNetworkable.DestroyMode.None);
                }
            }
            finally
            {
                Pool.FreeUnmanaged(ref nearbyEntities);
            }
        }

        private void ScheduleCobaltTankDebrisCleanup(Vector3 position)
        {
            const float cleanupRadius = 35f;
            const float cleanupWindowSeconds = 12f;

            CleanupExpiredCobaltTankDebrisWindows();

            CobaltTankDebrisCleanupWindow existingWindow = cobaltTankDebrisCleanupWindows.FirstOrDefault(x => x != null && (x.position - position).sqrMagnitude <= 64f);
            if (existingWindow != null)
            {
                existingWindow.position = position;
                existingWindow.radius = Mathf.Max(existingWindow.radius, cleanupRadius);
                existingWindow.expiresAt = Time.realtimeSinceStartup + cleanupWindowSeconds;
            }
            else
            {
                cobaltTankDebrisCleanupWindows.Add(new CobaltTankDebrisCleanupWindow
                {
                    position = position,
                    radius = cleanupRadius,
                    expiresAt = Time.realtimeSinceStartup + cleanupWindowSeconds
                });
            }

            CleanupCobaltTankDebrisNear(position, cleanupRadius);

            timer.Once(0.4f, () => CleanupCobaltTankDebrisNear(position, cleanupRadius));
            timer.Once(1.5f, () => CleanupCobaltTankDebrisNear(position, cleanupRadius));
            timer.Once(4f, () => CleanupCobaltTankDebrisNear(position, cleanupRadius));
            timer.Once(8f, () => CleanupCobaltTankDebrisNear(position, cleanupRadius));
        }

        private void ScheduleCobaltHeliDebrisCleanup(Vector3 position)
        {
            const float cleanupRadius = 60f;
            const float cleanupWindowSeconds = 16f;

            CleanupExpiredCobaltHeliDebrisWindows();

            CobaltHeliDebrisCleanupWindow existingWindow = cobaltHeliDebrisCleanupWindows.FirstOrDefault(x => x != null && (x.position - position).sqrMagnitude <= 144f);
            if (existingWindow != null)
            {
                existingWindow.position = position;
                existingWindow.radius = Mathf.Max(existingWindow.radius, cleanupRadius);
                existingWindow.expiresAt = Time.realtimeSinceStartup + cleanupWindowSeconds;
            }
            else
            {
                cobaltHeliDebrisCleanupWindows.Add(new CobaltHeliDebrisCleanupWindow
                {
                    position = position,
                    radius = cleanupRadius,
                    expiresAt = Time.realtimeSinceStartup + cleanupWindowSeconds
                });
            }

            CleanupCobaltHeliDebrisNear(position, cleanupRadius);

            timer.Once(0.4f, () => CleanupCobaltHeliDebrisNear(position, cleanupRadius));
            timer.Once(1.5f, () => CleanupCobaltHeliDebrisNear(position, cleanupRadius));
            timer.Once(4f, () => CleanupCobaltHeliDebrisNear(position, cleanupRadius));
            timer.Once(8f, () => CleanupCobaltHeliDebrisNear(position, cleanupRadius));
            timer.Once(12f, () => CleanupCobaltHeliDebrisNear(position, cleanupRadius));
        }

        private int GetSupportDroneTargetOccupancy(int warId, uint droneNetId, BaseCombatEntity target, out int slotIndex)
        {
            slotIndex = 0;
            if (target == null || target.IsDestroyed)
                return 0;

            uint targetNetId = target.net != null ? (uint)target.net.ID.Value : 0U;
            if (targetNetId == 0U)
                return 0;

            int count = 0;
            foreach (CobaltSupportDroneState state in cobaltSupportDrones.Values)
            {
                if (state == null || state.warId != warId || state.droneNetId == 0U)
                    continue;

                if (state.currentTargetNetId == 0U || state.currentTargetNetId != targetNetId)
                    continue;

                if (state.droneNetId < droneNetId)
                    slotIndex++;

                count++;
            }

            return count;
        }

        private float GetSupportDroneTargetPenalty(int warId, uint droneNetId, BaseCombatEntity target, Vector3 center)
        {
            if (target == null || target.IsDestroyed)
                return 0f;

            uint targetNetId = target.net != null ? (uint)target.net.ID.Value : 0U;
            int otherAssignments = 0;
            if (targetNetId != 0U)
            {
                foreach (CobaltSupportDroneState state in cobaltSupportDrones.Values)
                {
                    if (state == null || state.warId != warId || state.droneNetId == 0U || state.droneNetId == droneNetId)
                        continue;

                    if (state.currentTargetNetId == targetNetId)
                        otherAssignments++;
                }
            }

            int formationCount;
            int formationIndex = GetSupportDroneFormationIndex(warId, droneNetId, out formationCount);
            formationCount = Mathf.Max(1, formationCount);

            Vector3 horizontalOffset = target.transform.position - center;
            horizontalOffset.y = 0f;
            float targetAngle = horizontalOffset.sqrMagnitude <= 0.01f ? 0f : Mathf.Atan2(horizontalOffset.x, horizontalOffset.z) * Mathf.Rad2Deg;
            float preferredAngle = (360f / formationCount) * formationIndex;
            float anglePenalty = Mathf.Abs(Mathf.DeltaAngle(preferredAngle, targetAngle)) * 0.045f;
            float occupancyPenalty = otherAssignments * 14f;

            return occupancyPenalty + anglePenalty;
        }

        private Vector3 GetSupportDroneSeparationOffset(int warId, uint droneNetId, Vector3 currentPosition, float desiredSpacing)
        {
            if (desiredSpacing <= 0f)
                return Vector3.zero;

            Vector3 horizontalCurrent = currentPosition;
            horizontalCurrent.y = 0f;
            Vector3 accumulated = Vector3.zero;
            int neighbors = 0;

            foreach (CobaltSupportDroneState state in cobaltSupportDrones.Values)
            {
                if (state == null || state.warId != warId || state.droneNetId == 0U || state.droneNetId == droneNetId)
                    continue;

                if (state.lastRuntimeUpdateAt <= 0f)
                    continue;

                Vector3 otherPosition = state.lastPosition;
                otherPosition.y = 0f;
                Vector3 away = horizontalCurrent - otherPosition;
                float distance = away.magnitude;
                if (distance <= 0.01f || distance >= desiredSpacing)
                    continue;

                float strength = 1f - (distance / desiredSpacing);
                accumulated += away.normalized * strength * desiredSpacing * 0.75f;
                neighbors++;
            }

            if (neighbors <= 0)
                return Vector3.zero;

            accumulated /= neighbors;
            accumulated.y = 0f;
            return accumulated;
        }

        private bool IsSupportDroneEnemy(CobaltWarSession war, BaseCombatEntity target)
        {
            if (war == null || target == null || target.IsDestroyed || target.Health() <= 0f)
                return false;

            RandomRaider raider = target as RandomRaider;
            if (raider == null)
                raider = (target as RandomRaider);

            if (raider == null || raider.manager == null || raider.IsDestroyed || raider.Health() <= 0f)
            {
                BasePlayer player = target as BasePlayer;
                if (player != null)
                    return player.IsConnected && !player.IsNpc && !player.IsDead() && !player.InSafeZone() && !war.IsFriendlyParticipant(player.userID) && war.IsInsideCombatArea(player.transform.position);

                return false;
            }

            if (raider.manager.warSession != null)
                return raider.manager.warSession.warId == war.warId;

            return war.raidManager == raider.manager;
        }

        private void EnsureSupportDroneTurretReady(AutoTurret turret, SupportDroneTierConfig tier = null)
        {
            if (turret == null || turret.IsDestroyed)
                return;

            turret.SetFlag(IOEntity.Flag_HasPower, true);
            turret.SetPeacekeepermode(false);
            turret.SetIsOnline(true);

            if (tier != null)
            {
                turret.sightRange = Mathf.Max(15f, tier.sightRange);
                turret.aimCone = Mathf.Max(0.1f, tier.aimCone);
            }

            if (turret.targetTrigger != null)
            {
                SphereCollider sphereCollider = turret.targetTrigger.GetComponent<SphereCollider>();
                if (sphereCollider != null)
                    sphereCollider.radius = turret.sightRange;

                Rigidbody rigidbody = turret.targetTrigger.GetComponent<Rigidbody>();
                if (rigidbody == null)
                    rigidbody = turret.targetTrigger.gameObject.AddComponent<Rigidbody>();

                rigidbody.isKinematic = true;
                rigidbody.useGravity = false;
            }

            BaseProjectile attachedWeapon = turret.GetAttachedWeapon() as BaseProjectile;
            if (attachedWeapon == null)
            {
                turret.CancelInvoke(turret.UpdateAttachedWeapon);
                turret.UpdateAttachedWeapon();
                attachedWeapon = turret.GetAttachedWeapon() as BaseProjectile;
            }

            if (attachedWeapon != null && attachedWeapon.primaryMagazine != null && attachedWeapon.primaryMagazine.contents <= 0)
            {
                turret.UpdateTotalAmmo();
                turret.EnsureReloaded();
                turret.Reload();
            }

            turret.SendNetworkUpdate();
        }

        private void CleanupCobaltSupportDroneRegistry()
        {
            foreach (uint key in cobaltSupportDrones.Keys.ToList())
            {
                CobaltSupportDroneState state = cobaltSupportDrones[key];
                if (state == null)
                {
                    cobaltSupportDroneLinkedEntities.Remove(key);
                    cobaltSupportDrones.Remove(key);
                    continue;
                }

                Drone drone = BaseNetworkable.serverEntities.Find(new NetworkableId(state.droneNetId)) as Drone;
                AutoTurret turret = BaseNetworkable.serverEntities.Find(new NetworkableId(state.turretNetId)) as AutoTurret;
                if ((drone == null || drone.IsDestroyed) && (turret == null || turret.IsDestroyed))
                {
                    cobaltSupportDroneLinkedEntities.Remove(state.turretNetId);
                    cobaltSupportDroneLinkedEntities.Remove(state.sphereNetId);
                    cobaltSupportDrones.Remove(key);
                }
            }
        }

        private int GetActiveSupportDroneCount(int warId)
        {
            CleanupCobaltSupportDroneRegistry();
            return cobaltSupportDrones.Values.Count(x => x != null && x.warId == warId);
        }

        private int GetActivePurchasedSupportDroneCount(int warId)
        {
            CleanupCobaltSupportDroneRegistry();
            return cobaltSupportDrones.Values.Count(x => x != null && x.warId == warId && x.purchased);
        }

        private int GetActivePurchasedSupportDroneSlots(int warId)
        {
            CleanupCobaltSupportDroneRegistry();
            int totalSlots = 0;
            foreach (CobaltSupportDroneState state in cobaltSupportDrones.Values)
            {
                if (state == null || state.warId != warId || !state.purchased)
                    continue;

                int slotCost = state.slotCost > 0 ? state.slotCost : GetSupportDroneTierSlots(state.tierKey);
                totalSlots += Mathf.Max(1, slotCost);
            }

            return Mathf.Max(0, totalSlots);
        }

        private void RegisterCobaltSupportDrone(CobaltSupportDroneState state)
        {
            if (state == null || state.droneNetId == 0U)
                return;

            cobaltSupportDrones[state.droneNetId] = state;
            if (state.turretNetId != 0U)
                cobaltSupportDroneLinkedEntities[state.turretNetId] = state;
            if (state.sphereNetId != 0U)
                cobaltSupportDroneLinkedEntities[state.sphereNetId] = state;
        }

        private void UnregisterCobaltSupportDrone(uint droneNetId)
        {
            if (droneNetId == 0U)
                return;

            CobaltSupportDroneState state;
            if (cobaltSupportDrones.TryGetValue(droneNetId, out state) && state != null)
            {
                if (state.turretNetId != 0U)
                    cobaltSupportDroneLinkedEntities.Remove(state.turretNetId);
                if (state.sphereNetId != 0U)
                    cobaltSupportDroneLinkedEntities.Remove(state.sphereNetId);
            }

            cobaltSupportDrones.Remove(droneNetId);
        }

        private void UpdateCobaltSupportDroneRuntimeState(uint droneNetId, Vector3 position, BaseCombatEntity target)
        {
            if (droneNetId == 0U)
                return;

            CobaltSupportDroneState state;
            if (!cobaltSupportDrones.TryGetValue(droneNetId, out state) || state == null)
                return;

            state.lastPosition = position;
            state.lastRuntimeUpdateAt = Time.time;
            state.currentTargetNetId = target != null && !target.IsDestroyed && target.net != null
                ? (uint)target.net.ID.Value
                : 0U;
        }

        private void DestroyCobaltSupportDrone(CobaltSupportDroneState state)
        {
            if (state == null)
                return;

            // Remove the drone state before killing linked entities so OnEntityKill
            // re-entry for the turret/sphere/drone does not recursively destroy it again.
            UnregisterCobaltSupportDrone(state.droneNetId);

            AutoTurret turret = BaseNetworkable.serverEntities.Find(new NetworkableId(state.turretNetId)) as AutoTurret;
            if (turret != null && !turret.IsDestroyed)
            {
                turret.inventory?.Clear();
                turret.Kill(BaseNetworkable.DestroyMode.None);
            }

            BaseEntity sphere = BaseNetworkable.serverEntities.Find(new NetworkableId(state.sphereNetId)) as BaseEntity;
            if (sphere != null && !sphere.IsDestroyed)
                sphere.Kill(BaseNetworkable.DestroyMode.None);

            Drone drone = BaseNetworkable.serverEntities.Find(new NetworkableId(state.droneNetId)) as Drone;
            if (drone != null && !drone.IsDestroyed)
                drone.Kill(BaseNetworkable.DestroyMode.None);
        }

        private void DestroyCobaltSupportDronesForWar(int warId)
        {
            foreach (CobaltSupportDroneState state in cobaltSupportDrones.Values.Where(x => x != null && x.warId == warId).ToList())
                DestroyCobaltSupportDrone(state);
        }

        private void AttachSupportDroneWeaponModules(Item weapon, SupportDroneWeaponConfig weaponConfig)
        {
            if (weapon == null || weapon.contents == null || weaponConfig?.shortnameModules == null)
                return;

            foreach (string moduleShortname in weaponConfig.shortnameModules.Where(x => !string.IsNullOrEmpty(x)))
            {
                Item moduleItem = ItemManager.CreateByName(moduleShortname, 1);
                if (moduleItem == null)
                    continue;

                if (!moduleItem.MoveToContainer(weapon.contents))
                    moduleItem.Remove();
            }
        }

        private void AddSupportDroneReserveAmmo(AutoTurret turret, SupportDroneTierConfig tier, SupportDroneWeaponConfig weaponConfig)
        {
            if (turret == null || turret.inventory == null || tier == null || weaponConfig == null || string.IsNullOrEmpty(weaponConfig.shortnameAmmo))
                return;

            int amount = Mathf.Max(1, tier.reserveAmmoPerSlot);
            int slotCount = Mathf.Clamp(tier.reserveAmmoSlots, 1, Mathf.Max(1, turret.inventory.capacity - 1));
            for (int slot = 1; slot <= slotCount; slot++)
            {
                if (slot >= turret.inventory.capacity)
                    break;

                Item ammo = ItemManager.CreateByName(weaponConfig.shortnameAmmo, amount);
                if (ammo == null)
                    continue;

                if (!ammo.MoveToContainer(turret.inventory, slot))
                    ammo.Remove();
                else
                    ammo.MarkDirty();
            }

            turret.UpdateTotalAmmo();
            turret.EnsureReloaded();
            turret.Reload();
        }

        private bool SetupSupportDroneTurretWeapon(AutoTurret turret, SupportDroneTierConfig tier, SupportDroneWeaponConfig weaponConfig)
        {
            if (turret == null || turret.inventory == null || tier == null || weaponConfig == null || string.IsNullOrEmpty(weaponConfig.shortnameWeapon))
                return false;

            Item weapon = ItemManager.CreateByName(weaponConfig.shortnameWeapon, 1);
            if (weapon == null)
                return false;

            AttachSupportDroneWeaponModules(weapon, weaponConfig);
            if (!weapon.MoveToContainer(turret.inventory, 0))
            {
                weapon.Remove();
                return false;
            }

            turret.CancelInvoke(turret.UpdateAttachedWeapon);
            turret.UpdateAttachedWeapon();

            timer.Once(0.2f, () =>
            {
                if (turret == null || turret.IsDestroyed)
                    return;

                AddSupportDroneReserveAmmo(turret, tier, weaponConfig);
            });

            return true;
        }

        private void AuthorizeCobaltSupportDroneTurret(AutoTurret turret, CobaltWarSession war)
        {
            if (turret == null || war == null)
                return;

            foreach (ulong userId in war.owners.Concat(war.GetAllRegisteredDefenders()).Concat(war.walkInDefenders).Distinct())
            {
                if (userId == 0UL || turret.authorizedPlayers.Contains(userId))
                    continue;

                turret.authorizedPlayers.Add(userId);
            }

            turret.SendNetworkUpdate();
        }

        private bool TryFindSupportDroneSpawn(CobaltWarSession war, SupportDroneTierConfig tier, int index, out Vector3 spawn)
        {
            spawn = Vector3.zero;
            if (war == null || tier == null || configData?.cobaltWar == null)
                return false;

            float minRadius = Mathf.Max(8f, configData.cobaltWar.supportDroneSpawnRadiusMin);
            float maxRadius = Mathf.Max(minRadius + 2f, configData.cobaltWar.supportDroneSpawnRadiusMax);
            LayerMask collisionMask = LayerMask.GetMask("World", "Construction", "Default", "Deployed", "Terrain");

            for (int attempt = 0; attempt < 24; attempt++)
            {
                float angle = ((360f / 6f) * (index % 6)) + (attempt * 17f) + UnityEngine.Random.Range(-12f, 12f);
                float radius = UnityEngine.Random.Range(minRadius, maxRadius);
                Vector3 flat = war.location + Quaternion.Euler(0f, angle, 0f) * (Vector3.forward * radius);
                float terrainHeight = TerrainMeta.HeightMap.GetHeight(flat);
                float waterHeight = TerrainMeta.WaterMap.GetHeight(flat) + 3f;
                float surfaceHeight = Mathf.Max(terrainHeight, waterHeight, war.location.y - 4f);

                RaycastHit hit;
                if (Physics.Raycast(flat + Vector3.up * 140f, Vector3.down, out hit, 280f, collisionMask))
                    surfaceHeight = Mathf.Max(surfaceHeight, hit.point.y + 1.5f);

                Vector3 candidate = new Vector3(flat.x, surfaceHeight + Mathf.Max(8f, tier.hoverHeight), flat.z);
                if (Physics.CheckSphere(candidate, 1.6f, collisionMask))
                    continue;

                spawn = candidate;
                return true;
            }

            spawn = new Vector3(war.location.x, Mathf.Max(war.location.y + Mathf.Max(10f, tier.hoverHeight), TerrainMeta.HeightMap.GetHeight(war.location) + Mathf.Max(10f, tier.hoverHeight)), war.location.z);
            return !Physics.CheckSphere(spawn, 1.6f, LayerMask.GetMask("World", "Construction", "Default", "Deployed"));
        }

        private bool SpawnCobaltSupportDrone(CobaltWarSession war, EventRandomManager manager, bool purchased, ulong requesterUserId = 0UL, string forcedTierKey = null, bool slotAlreadyReserved = false)
        {
            if (war == null || manager == null || configData?.cobaltWar == null || !configData.cobaltWar.enableSupportDrones)
                return false;

            CleanupCobaltSupportDroneRegistry();
            string tierKey = !string.IsNullOrEmpty(forcedTierKey) ? forcedTierKey : ChooseSupportDroneTierKey(war.raidType);
            SupportDroneTierConfig tier = GetSupportDroneTier(tierKey);
            if (tier == null)
            {
                tierKey = ChooseSupportDroneTierKey(war.raidType);
                tier = GetSupportDroneTier(tierKey);
            }
            if (tier == null || tier.weapons == null || tier.weapons.Count == 0)
                return false;

            int slotCost = Mathf.Max(1, GetSupportDroneTierSlots(tierKey));

            if (purchased && !slotAlreadyReserved && war.GetPurchasedSupportDroneSlotCap() > 0)
            {
                if (war.GetUsedPurchasedSupportDroneSlots() + slotCost > war.GetPurchasedSupportDroneSlotCap())
                    return false;
            }

            Vector3 spawn;
            if (!TryFindSupportDroneSpawn(war, tier, GetActiveSupportDroneCount(war.warId), out spawn))
                return false;

            Drone drone = GameManager.server.CreateEntity(CobaltSupportDronePrefab, spawn, Quaternion.identity, true) as Drone;
            if (drone == null)
                return false;

            drone.enableSaving = false;
            drone.OwnerID = war.targetUserId;
            drone.skinID = CobaltSupportDroneSkinId;
            drone.pickup.enabled = false;
            drone.EnableGlobalBroadcast(true);
            drone.Spawn();
            drone.SetFlag(BaseEntity.Flags.Reserved10, true);
            drone.enableGrounding = false;
            drone.keepAboveTerrain = false;
            drone.playerCheckRadius = 0f;
            drone.collisionDisableTime = 0f;
            drone.killInTerrain = false;
            drone.isGrounded = false;
            drone.lastCollision = -1000d;
            drone.lastGroundCheck = 0f;
            drone.lastPlayerCheck = 999f;
            drone._health = Mathf.Max(100f, tier.health);
            drone._maxHealth = drone._health;
            drone.startHealth = drone._health;
            drone.InitializeHealth(drone._health, drone._maxHealth);
            drone.health = drone._health;

            if (drone.body != null)
            {
                drone.body.isKinematic = false;
                drone.body.WakeUp();
                drone.body.velocity = Vector3.zero;
                drone.body.angularVelocity = Vector3.zero;
                drone.body.sleepThreshold = 0f;
            }

            SphereEntity sphere = GameManager.server.CreateEntity(CobaltSupportDroneSpherePrefab, Vector3.zero) as SphereEntity;
            if (sphere == null)
            {
                drone.Kill(BaseNetworkable.DestroyMode.None);
                return false;
            }

            sphere.currentRadius = 0.1f;
            sphere.lerpRadius = 0.1f;
            sphere.transform.localScale = new Vector3(0.1f, 0.1f, 0.1f);
            sphere.enableSaving = false;
            sphere.EnableGlobalBroadcast(true);
            sphere.SetParent(drone);
            sphere.Spawn();
            drone.SetSlot(BaseEntity.Slot.UpperModifier, sphere);

            AutoTurret turret = GameManager.server.CreateEntity(CobaltSupportDroneTurretPrefab, Vector3.zero, Quaternion.identity, true) as AutoTurret;
            if (turret == null)
            {
                sphere.Kill(BaseNetworkable.DestroyMode.None);
                drone.Kill(BaseNetworkable.DestroyMode.None);
                return false;
            }

            turret.baseProtection = null;
            turret.SetParent(sphere, 0);
            turret.enableSaving = false;
            turret.EnableGlobalBroadcast(true);
            turret.OwnerID = war.targetUserId;
            turret.skinID = CobaltSupportDroneSkinId;
            turret.pickup.enabled = false;
            turret.Spawn();
            turret.SetFlag(IOEntity.Flag_HasPower, true);
            turret.SetFlag(BaseEntity.Flags.Locked, true);
            turret.SetFlag(BaseEntity.Flags.Busy, true);
            turret.SetPeacekeepermode(false);
            turret.dropsLoot = false;
            turret.sightRange = Mathf.Max(15f, tier.sightRange);
            if (turret.targetTrigger != null)
            {
                SphereCollider sphereCollider = turret.targetTrigger.GetComponent<SphereCollider>();
                if (sphereCollider != null)
                    sphereCollider.radius = turret.sightRange;
            }
            turret.aimCone = Mathf.Max(0.1f, tier.aimCone);
            turret._health = Mathf.Max(100f, tier.health);
            turret._maxHealth = turret._health;
            turret.startHealth = turret._health;
            turret.InitializeHealth(turret._health, turret._maxHealth);
            AuthorizeCobaltSupportDroneTurret(turret, war);

            SupportDroneWeaponConfig weaponConfig = tier.weapons.GetRandom();
            if (!SetupSupportDroneTurretWeapon(turret, tier, weaponConfig))
            {
                turret.Kill(BaseNetworkable.DestroyMode.None);
                sphere.Kill(BaseNetworkable.DestroyMode.None);
                drone.Kill(BaseNetworkable.DestroyMode.None);
                return false;
            }

            EnsureSupportDroneTurretReady(turret, tier);

            timer.Once(0.35f, () =>
            {
                if (turret == null || turret.IsDestroyed)
                    return;

                EnsureSupportDroneTurretReady(turret, tier);
            });

            drone.SendNetworkUpdateImmediate();
            turret.SendNetworkUpdateImmediate();

            CobaltSupportDroneController controller = drone.gameObject.AddComponent<CobaltSupportDroneController>();
            controller.Initialize(this, war, manager, drone, turret, tierKey, tier);

            RegisterCobaltSupportDrone(new CobaltSupportDroneState
            {
                warId = war.warId,
                droneNetId = (uint)drone.net.ID.Value,
                turretNetId = (uint)turret.net.ID.Value,
                sphereNetId = (uint)sphere.net.ID.Value,
                tierKey = tierKey,
                slotCost = slotCost,
                purchased = purchased,
                requestedByUserId = requesterUserId
            });

            return true;
        }

        private float GetAimDelta(Vector3 previous, Vector3 current)
        {
            return Mathf.Abs(Mathf.DeltaAngle(previous.x, current.x)) + Mathf.Abs(Mathf.DeltaAngle(previous.y, current.y));
        }

        private bool HasMeaningfulRaidActivityInput(BasePlayer player, InputState input = null)
        {
            InputState state = input ?? player?.serverInput;
            if (state == null)
                return false;

            if (state.WasJustPressed(BUTTON.FIRE_PRIMARY)
                || state.WasJustPressed(BUTTON.FIRE_SECONDARY)
                || state.WasJustPressed(BUTTON.FIRE_THIRD)
                || state.WasJustPressed(BUTTON.USE))
                return true;

            if (player == null || player.serverInput == null)
                return false;

            return player.serverInput.IsDown(BUTTON.FIRE_PRIMARY)
                || player.serverInput.IsDown(BUTTON.FIRE_SECONDARY)
                || player.serverInput.IsDown(BUTTON.USE)
                || player.serverInput.IsDown(BUTTON.SPRINT)
                || player.serverInput.IsDown(BUTTON.DUCK);
        }

        private void TouchActivityTracker(Dictionary<ulong, DefenderActivityState> tracker, BasePlayer player, bool force = false, InputState input = null)
        {
            if (tracker == null || player == null)
                return;

            DefenderActivityState state;
            if (!tracker.TryGetValue(player.userID, out state) || state == null)
            {
                state = new DefenderActivityState();
                tracker[player.userID] = state;
            }

            Vector3 position = player.transform.position;
            Vector3 aimAngles = Vector3.zero;
            if (player.eyes != null)
                aimAngles = player.eyes.rotation.eulerAngles;
            if (player.serverInput?.current != null)
                aimAngles = player.serverInput.current.aimAngles;
            double now = GrabCurrentTime();

            if (force || !state.initialized)
            {
                state.lastActivityAt = now;
            }
            else
            {
                float moveThreshold = Mathf.Max(0.1f, configData?.cobaltWar?.afkMoveThreshold ?? 1.5f);
                bool moved = Vector3.Distance(state.lastPosition, position) >= moveThreshold;
                bool lookedAround = GetAimDelta(state.lastAimAngles, aimAngles) >= 6f;
                bool usedControls = HasMeaningfulRaidActivityInput(player, input);

                if (moved || lookedAround || usedControls)
                    state.lastActivityAt = now;
            }

            state.lastPosition = position;
            state.lastAimAngles = aimAngles;
            state.initialized = true;
        }

        private void TouchDefenderActivity(BasePlayer player, bool force = false, InputState input = null)
        {
            TouchActivityTracker(defenderActivity, player, force, input);
        }

        private void TouchRaidTargetActivity(BasePlayer player, bool force = false, InputState input = null)
        {
            TouchActivityTracker(raidTargetActivity, player, force, input);
        }

        private void ClearDefenderActivity(ulong userId)
        {
            defenderActivity.Remove(userId);
        }

        private void ClearRaidTargetActivity(ulong userId)
        {
