        private bool IsDefenderAfk(ulong userId)
        {
            if (configData?.cobaltWar == null || !configData.cobaltWar.removeAfkDefenders || configData.cobaltWar.afkDefenderSeconds <= 0f)
                return false;

            DefenderActivityState state;
            if (!defenderActivity.TryGetValue(userId, out state) || state == null || !state.initialized)
                return false;

            return GrabCurrentTime() - state.lastActivityAt >= configData.cobaltWar.afkDefenderSeconds;
        }

        private bool IsRaidTargetAfk(BasePlayer player)
        {
            if (player == null || !player.IsConnected || player.IsNpc)
                return false;

            if (configData?.cobaltWar == null || !configData.cobaltWar.protectAfkRaidTargets || configData.cobaltWar.afkRaidTargetSeconds <= 0f)
                return false;

            DefenderActivityState state;
            if (!raidTargetActivity.TryGetValue(player.userID, out state) || state == null || !state.initialized)
            {
                TouchRaidTargetActivity(player, true);
                return false;
            }

            return GrabCurrentTime() - state.lastActivityAt >= configData.cobaltWar.afkRaidTargetSeconds;
        }

        private bool ShouldCountHelperAsActive(ulong userId)
        {
            BasePlayer player = BasePlayer.FindByID(userId);
            if (player == null || !player.IsConnected)
                return false;

            string arenaMessageKey;
            if (IsArenaTournamentBlockingCobalt(player, true, out arenaMessageKey))
                return false;

            TouchDefenderActivity(player);
            return !IsDefenderAfk(userId);
        }

        private void PruneInactiveRegisteredDefenders(CobaltWarSession war)
        {
            if (war == null || war.IsEnded)
                return;

            foreach (ulong userId in war.GetAllRegisteredDefenders().ToList())
            {
                BasePlayer player = BasePlayer.FindByID(userId);

                if (player != null && player.IsConnected)
                    TouchDefenderActivity(player);

                if (player == null || !player.IsConnected)
                {
                    war.RemoveRegisteredDefender(userId, false);
                    continue;
                }

                string arenaMessageKey;
                if (IsArenaTournamentBlockingCobalt(player, true, out arenaMessageKey))
                {
                    war.RemoveRegisteredDefender(userId, true, "CobaltRemovedArenaTournament");
                    continue;
                }

                if (IsDefenderAfk(userId))
                    war.RemoveRegisteredDefender(userId, true, "CobaltRemovedAfk");
            }
        }

        private raidConfig CloneRaidConfig(raidConfig source)
