        private void TouchRaidCooldown(List<ulong> authPlayers)
        {
            if (authPlayers == null)
                return;

            foreach (var user in authPlayers)
            {
                if (!raidData.data.ContainsKey(user))
                    raidData.data.Add(user, new rData());
                raidData.data[user].LastRaided = DateTime.Now;
            }
            SaveRaidData();
        }

        private void TouchSuccessfulOwnerBuyoutAutoRaidCooldown(ulong userId)
        {
            if (userId == 0UL || raidData?.data == null || configData?.cobaltWar == null)
                return;

            rData playerRaidData;
            if (!raidData.data.TryGetValue(userId, out playerRaidData) || playerRaidData == null)
            {
                playerRaidData = new rData();
                raidData.data[userId] = playerRaidData;
            }

            playerRaidData.LastSuccessfulOwnerBuyoutAutoRaidBlockedUntil = DateTime.Now.AddMinutes(Mathf.Max(0, configData.cobaltWar.ownerBuyoutAutoRaidCooldownMinutes));
            SaveRaidData();
        }

        private bool IsGeneralRaidCooldownActive(ulong userId, out TimeSpan remaining)
        {
            remaining = TimeSpan.Zero;
            if (userId == 0UL || raidData?.data == null || configData?.settings == null)
                return false;

            rData data;
            if (!raidData.data.TryGetValue(userId, out data))
                return false;

            if (data.LastRaided == default(DateTime))
                return false;

            DateTime availableAt = data.LastRaided.AddMinutes(configData.settings.raidAgainCooldown);
            remaining = availableAt - DateTime.Now;
            return remaining > TimeSpan.Zero;
        }

        private bool IsAutomaticRaidTargetCooldownActive(ulong userId, int triggerCooldownMinutes, out TimeSpan remaining)
        {
            remaining = TimeSpan.Zero;
            if (userId == 0UL || raidData?.data == null)
                return false;

            rData data;
            if (!raidData.data.TryGetValue(userId, out data) || data == null)
                return false;

            DateTime availableAt = default(DateTime);
            if (data.LastRaided != default(DateTime) && triggerCooldownMinutes > 0)
                availableAt = data.LastRaided.AddMinutes(triggerCooldownMinutes);

            if (data.LastSuccessfulOwnerBuyoutAutoRaidBlockedUntil != default(DateTime)
                && data.LastSuccessfulOwnerBuyoutAutoRaidBlockedUntil > availableAt)
            {
                availableAt = data.LastSuccessfulOwnerBuyoutAutoRaidBlockedUntil;
            }

            if (availableAt == default(DateTime))
                return false;

            remaining = availableAt - DateTime.Now;
            return remaining > TimeSpan.Zero;
        }

        private void ShuffleListInPlace<T>(IList<T> list)
        {
            if (list == null)
                return;

            for (int i = list.Count - 1; i > 0; i--)
            {
                int j = UnityEngine.Random.Range(0, i + 1);
                if (i == j)
                    continue;

                T temp = list[i];
                list[i] = list[j];
                list[j] = temp;
            }
        }

