        private void NotifyPlayersWithOptionalTip(IEnumerable<ulong> userIds, string messageKey, params object[] args)
        {
            if (userIds == null)
                return;

            foreach (ulong userId in userIds.Distinct().Where(x => x != 0UL))
            {
                BasePlayer player = BasePlayer.FindByID(userId);
                if (player == null || !player.IsConnected)
                    continue;

                string template = lang.GetMessage(messageKey, this, player.UserIDString);
                if (string.IsNullOrEmpty(template))
                    continue;

                string message = args != null && args.Length > 0 ? string.Format(template, args) : template;
                SendReply(player, message);
                if (configData.settings.gameTip)
                    GameTipMessage(player, message);
            }
        }

        private void NotifyTriggeredRaidBusyRetry(IEnumerable<ulong> userIds, Vector3 location, float delaySeconds)
        {
            TimeSpan delay = TimeSpan.FromSeconds(delaySeconds);
            NotifyPlayersWithOptionalTip(userIds, "TriggeredRaidRetryBusy", GetGrid(location), FormatTime(delay), FormatTimeS(delay));

            if (!configData.settings.worldMarker)
                return;

            foreach (ulong userId in userIds.Distinct().Where(x => x != 0UL))
            {
                BasePlayer player = BasePlayer.FindByID(userId);
                if (player != null && player.IsConnected)
                    LocateBaseWithMarker(player, location, configData.settings.worldMarkerTime);
            }
        }

        private void NotifyTriggeredRaidCancelled(IEnumerable<ulong> userIds, string messageKey = "TriggeredRaidCancelled")
        {
            NotifyPlayersWithOptionalTip(userIds, string.IsNullOrEmpty(messageKey) ? "TriggeredRaidCancelled" : messageKey);
        }

        private void ScheduleTriggeredRaidAttempt(BuildingPrivlidge privilege, ulong targetUserId, string raidType, float delaySeconds, CobaltWarTrigger trigger, Action<List<ulong>, List<BuildingBlock>> onStarted, int retriesRemaining = 8, float retryDelaySeconds = 60f)
        {
            if (privilege == null)
                return;

            int scheduleGeneration = triggeredRaidScheduleGeneration;
            timer.Once(Mathf.Max(0.1f, delaySeconds), () =>
            {
                if (scheduleGeneration != triggeredRaidScheduleGeneration)
                    return;

                if (privilege == null || privilege.IsDestroyed)
                    return;

                List<ulong> currentOwners = privilege.authorizedPlayers != null ? privilege.authorizedPlayers.ToList() : new List<ulong>();

                if (HasAnyRaidEventInProgress())
                {
                    if (retriesRemaining > 0)
                    {
                        NotifyTriggeredRaidBusyRetry(currentOwners, privilege.transform.position, retryDelaySeconds);
                        ScheduleTriggeredRaidAttempt(privilege, targetUserId, raidType, retryDelaySeconds, trigger, onStarted, retriesRemaining - 1, retryDelaySeconds);
                    }
                    else
                    {
                        NotifyTriggeredRaidCancelled(currentOwners);
                    }
                    return;
                }

                List<BuildingBlock> blocks;
                List<ulong> authPlayers;
                string failReasonKey;
                if (!TryPrepareRaidBase(privilege, out blocks, out authPlayers, out failReasonKey))
                {
                    if (configData.settings.mustBeOnlinePlayer && !HasEligibleOnlineAuthorizedPlayer(privilege))
                    {
                        string availabilityMessageKey = GetAuthorizedRaidAvailabilityMessageKey(privilege, currentOwners);
                        NotifyTriggeredRaidCancelled(currentOwners, MapTriggeredRaidCancellationMessageKey(availabilityMessageKey));
                    }
                    else
                        NotifyTriggeredRaidCancelled(currentOwners);
                    return;
                }

                BasePlayer targetPlayer = ResolveCurrentRaidTargetPlayer(privilege, authPlayers, targetUserId);
                if (targetPlayer == null)
                {
                    string availabilityMessageKey = GetAuthorizedRaidAvailabilityMessageKey(privilege, authPlayers);
                    NotifyTriggeredRaidCancelled(authPlayers, MapTriggeredRaidCancellationMessageKey(availabilityMessageKey));
                    return;
                }

                bool started = configData.cobaltWar != null && configData.cobaltWar.enabled
                    ? TryScheduleCobaltWar(privilege, targetPlayer, raidType, blocks, authPlayers, trigger)
                    : startRandomRaid(privilege.transform.position, authPlayers, raidType, blocks) != null;

                if (!started)
                {
                    if (HasAnyRaidEventInProgress() && retriesRemaining > 0)
                    {
                        NotifyTriggeredRaidBusyRetry(authPlayers, privilege.transform.position, retryDelaySeconds);
                        ScheduleTriggeredRaidAttempt(privilege, targetUserId, raidType, retryDelaySeconds, trigger, onStarted, retriesRemaining - 1, retryDelaySeconds);
                    }
                    else
                    {
                        string startFailReason = GetRaidStartFailureMessageKey(authPlayers, raidType, null);
                        NotifyTriggeredRaidCancelled(authPlayers, MapTriggeredRaidCancellationMessageKey(startFailReason));
                    }
                    return;
                }

                onStarted?.Invoke(authPlayers, blocks);
            });
        }

        private void CachePlayerCupboard(BasePlayer player, BuildingPrivlidge privilege)
        {
            if (player == null || privilege == null)
                return;

            List<ulong> cupboards;
            if (!pcdData.tcData.TryGetValue(player.userID.Get(), out cupboards))
            {
                cupboards = new List<ulong>();
                pcdData.tcData[player.userID.Get()] = cupboards;
            }

            if (!cupboards.Contains(privilege.net.ID.Value))
            {
                cupboards.Add(privilege.net.ID.Value);
                QueuePlayerDataSave();
            }
        }

        private bool IsRaidTerrainBlocked(BuildingPrivlidge privilege, List<BuildingBlock> blocks, out RaidTerrainProfile terrainProfile)
        {
            terrainProfile = AnalyzeRaidTerrain(privilege, blocks);
            bool allowCliffs = terrainProfile != null && terrainProfile.isRockBase && configData?.cobaltWar?.adaptRockBases == true;
            return isBlockedTerain(privilege.transform.position, allowCliffs);
        }

        private float GetAutoRaidTurretScanRadius(BuildingPrivlidge privilege, List<BuildingBlock> blocks)
        {
            float radius = 20f;
            if (privilege == null)
                return radius;

            if (blocks != null)
            {
                foreach (BuildingBlock block in blocks)
                {
                    if (block == null)
                        continue;

                    radius = Mathf.Max(radius, Vector3.Distance(block.transform.position, privilege.transform.position) + 14f);
                }
            }

            return Mathf.Clamp(radius, 20f, Mathf.Max(40f, configData?.cobaltWar?.combatRadius ?? 160f));
        }

        private int CountAutomaticRaidTargetTurrets(BuildingPrivlidge privilege, List<BuildingBlock> blocks)
        {
            if (privilege == null)
                return 0;

            BuildingManager.Building baseBuilding = privilege.GetBuilding();
            if (baseBuilding == null)
                return 0;

            float radius = GetAutoRaidTurretScanRadius(privilege, blocks);
            List<AutoTurret> turrets = Pool.Get<List<AutoTurret>>();
            int count = 0;

            try
            {
                Vis.Entities(privilege.transform.position, radius, turrets);

                foreach (AutoTurret turret in turrets)
                {
                    if (turret == null || turret.IsDestroyed || IsValidCobaltSupportDroneTurret(turret))
                        continue;

                    BuildingManager.Building turretBuilding = turret.GetBuilding();
                    bool sameBuilding = turretBuilding != null && turretBuilding == baseBuilding;
                    bool sameOwnersNearby = privilege.authorizedPlayers != null
                        && privilege.authorizedPlayers.Contains(turret.OwnerID)
                        && Vector3.Distance(turret.transform.position, privilege.transform.position) <= radius;

                    if (!sameBuilding && !sameOwnersNearby)
                        continue;

                    count++;
                }
            }
            finally
            {
                Pool.FreeUnmanaged(ref turrets);
            }

            return count;
        }

        private bool HasRequiredAutomaticRaidTargetTurrets(BuildingPrivlidge privilege, List<BuildingBlock> blocks, out int turretCount)
        {
            turretCount = CountAutomaticRaidTargetTurrets(privilege, blocks);

            if (configData?.cobaltWar == null || !configData.cobaltWar.requireTurretsForAutomaticRaidTargets)
                return true;

            int requiredTurrets = Mathf.Max(0, configData.cobaltWar.minimumAutoRaidTargetTurrets);
            if (requiredTurrets <= 0)
                return true;

            return turretCount >= requiredTurrets;
        }

        private bool TryPrepareRaidBase(BuildingPrivlidge privFind, out List<BuildingBlock> blocks, out List<ulong> authPlayers, out string failReasonKey, bool ignoreRaidEligibility = false)
        {
            blocks = new List<BuildingBlock>();
            authPlayers = new List<ulong>();
            failReasonKey = null;

            if (privFind == null)
                return false;

            if (Convert.ToBoolean(RaidableBases?.CallHook("EventTerritory", privFind.transform.position)))
            {
                failReasonKey = "terrainBlocked";
                return false;
            }

            if (!ignoreRaidEligibility && !CanBeRaided(privFind))
                return false;

            BuildingManager.Building build = privFind.GetBuilding();
            if (build == null || !build.HasBuildingBlocks() || build.buildingBlocks.Count < 5)
            {
                failReasonKey = "BaseToSmallYet";
                return false;
            }

            blocks = GenerateTargets(privFind);
            if (blocks.Count < 5)
            {
                failReasonKey = "BaseToSmallYet";
                return false;
            }

            RaidTerrainProfile terrainProfile;
            if (IsRaidTerrainBlocked(privFind, blocks, out terrainProfile))
            {
                failReasonKey = "terrainBlocked";
                return false;
            }

            if (!ignoreRaidEligibility)
            {
                int turretCount;
                if (!HasRequiredAutomaticRaidTargetTurrets(privFind, blocks, out turretCount))
                {
                    failReasonKey = "BaseNeedsTurrets";
                    return false;
                }
            }

            foreach (var user in privFind.authorizedPlayers)
                if (!authPlayers.Contains(user))
                    authPlayers.Add(user);

            return true;
        }

        private bool TryGetPlayerBase(BasePlayer player, out BuildingPrivlidge privilege, out List<BuildingBlock> blocks, out List<ulong> authPlayers, bool allowLiveSearch = false, bool ignoreRaidEligibility = false)
        {
            EnsurePlayerDataStructures();

            privilege = null;
            blocks = new List<BuildingBlock>();
            authPlayers = new List<ulong>();

            if (player == null)
                return false;

            if (allowLiveSearch)
            {
                BuildingPrivlidge currentPriv = player.GetBuildingPrivilege();
                string currentReason;
                if (currentPriv != null && currentPriv.IsAuthed(player) && TryPrepareRaidBase(currentPriv, out blocks, out authPlayers, out currentReason, ignoreRaidEligibility))
                {
                    privilege = currentPriv;
                    CachePlayerCupboard(player, currentPriv);
                    return true;
                }
            }

            List<ulong> cupboardIds;
            if (pcdData.tcData.TryGetValue(player.userID.Get(), out cupboardIds))
            {
                bool removedInvalid = false;
                foreach (var key in cupboardIds.ToList())
                {
                    BuildingPrivlidge privFind = FindEntity(key) as BuildingPrivlidge;
                    if (privFind == null)
                    {
                        cupboardIds.Remove(key);
                        removedInvalid = true;
                        continue;
                    }

                    string reason;
                    if (!TryPrepareRaidBase(privFind, out blocks, out authPlayers, out reason, ignoreRaidEligibility))
                        continue;

                    privilege = privFind;
                    return true;
                }

                if (removedInvalid)
                    QueuePlayerDataSave();
            }

            if (!allowLiveSearch)
                return false;

            foreach (BuildingPrivlidge privFind in BaseNetworkable.serverEntities.OfType<BuildingPrivlidge>().OrderBy(x => Vector3.Distance(x.transform.position, player.transform.position)))
            {
                if (privFind == null || !privFind.IsAuthed(player))
                    continue;

                string reason;
                if (!TryPrepareRaidBase(privFind, out blocks, out authPlayers, out reason, ignoreRaidEligibility))
                    continue;

                privilege = privFind;
                CachePlayerCupboard(player, privFind);
                return true;
            }

            return false;
        }

        private BasePlayer FindPlayerByIdOrSleeping(ulong userId)
        {
            return BasePlayer.FindByID(userId) ?? BasePlayer.FindSleeping(userId);
        }

        private bool IsCurrentlyAuthorizedForPrivilege(BuildingPrivlidge privilege, ulong userId)
        {
            if (privilege == null || userId == 0UL || privilege.authorizedPlayers == null)
                return false;

            return privilege.authorizedPlayers.Contains(userId);
        }

        private BasePlayer ResolveCurrentRaidTargetPlayer(BuildingPrivlidge privilege, List<ulong> authPlayers, ulong preferredUserId)
        {
            List<ulong> currentAuthorized = new List<ulong>();
            bool requireOnlineTarget = configData != null && configData.settings.mustBeOnlinePlayer;

            if (authPlayers != null)
            {
                foreach (ulong userId in authPlayers)
                {
                    if (userId == 0UL || currentAuthorized.Contains(userId))
                        continue;

                    currentAuthorized.Add(userId);
                }
            }

            if (privilege != null && privilege.authorizedPlayers != null)
            {
                foreach (ulong userId in privilege.authorizedPlayers)
                {
                    if (userId == 0UL || currentAuthorized.Contains(userId))
                        continue;

                    currentAuthorized.Add(userId);
                }
            }

            if (currentAuthorized.Count <= 0)
                return null;

            if (preferredUserId != 0UL && currentAuthorized.Contains(preferredUserId))
            {
                BasePlayer preferredOnline = BasePlayer.FindByID(preferredUserId);
                if (preferredOnline != null
                    && preferredOnline.IsConnected
                    && !preferredOnline.IsNpc
                    && !IsBusyWithRaidableBases(preferredOnline)
                    && !IsRaidTargetAfk(preferredOnline))
                    return preferredOnline;

                BasePlayer preferredAny = FindPlayerByIdOrSleeping(preferredUserId);
                if (preferredAny != null
                    && !preferredAny.IsNpc
                    && (!requireOnlineTarget || preferredAny.IsConnected)
                    && (!preferredAny.IsConnected || !IsBusyWithRaidableBases(preferredAny))
                    && (!preferredAny.IsConnected || !IsRaidTargetAfk(preferredAny)))
                    return preferredAny;
            }

            foreach (ulong userId in currentAuthorized)
            {
                BasePlayer online = BasePlayer.FindByID(userId);
                if (online != null
                    && online.IsConnected
                    && !online.IsNpc
                    && !IsBusyWithRaidableBases(online)
                    && !IsRaidTargetAfk(online))
                    return online;
            }

            foreach (ulong userId in currentAuthorized)
            {
                BasePlayer any = FindPlayerByIdOrSleeping(userId);
                if (any != null
                    && !any.IsNpc
                    && (!requireOnlineTarget || any.IsConnected)
                    && (!any.IsConnected || !IsBusyWithRaidableBases(any))
                    && (!any.IsConnected || !IsRaidTargetAfk(any)))
                    return any;
            }

            return null;
        }

        private void ScanWealthTargets()
        {
            EnsurePlayerDataStructures();

            if (wealthScanInProgress)
            {
                CobaltDiagnosticLog("idle", "Wealth scan пропущен: предыдущий проход еще не завершен.");
                return;
            }

            if (ServerRewards == null || configData?.cobaltWar == null || !configData.cobaltWar.enabled || !configData.cobaltWar.enableWealthScanner)
            {
                CobaltDiagnosticLog("idle", "Wealth scan пропущен: сканер выключен или недоступен ServerRewards.");
                return;
            }

            if (pcdData?.tcData == null || pcdData.tcData.Count <= 0)
            {
                CobaltDiagnosticLog("idle", "Wealth scan пропущен: нет данных tcData.");
                return;
            }

            if (configData.cobaltWar.wealthTargetMustBeOnline && GetOnlineRaidPlayerCount() <= 0)
            {
                CobaltDiagnosticLog("idle", "Wealth scan пропущен: нет онлайн-игроков.");
                return;
            }

            if (QueryPauseAutomaticRaidsForPurchaseQueue())
            {
                CobaltDiagnosticLog("idle", "Wealth scan пропущен: есть очередь покупных рейдов.");
                return;
            }

            if (HasAnyRaidEventInProgress())
            {
                CobaltDiagnosticLog("idle", "Wealth scan пропущен: слот рейда уже занят.");
                return;
            }

            wealthScanInProgress = true;
            RefreshPlayerInputHookSubscription();
            try
            {
                int playerCount = configData.cobaltWar.wealthTargetMustBeOnline
                    ? Enumerable.Count(BasePlayer.activePlayerList)
                    : Enumerable.Count(BasePlayer.allPlayerList);
                CobaltDiagnosticLog("idle", $"Wealth scan начат: players={playerCount}, tcData={pcdData.tcData.Count}.");
                List<WealthTargetCandidate> candidates = new List<WealthTargetCandidate>();
                int skippedNullOrNpc = 0;
                int skippedMissingTcData = 0;
                int skippedPermission = 0;
                int skippedAlreadyInWar = 0;
                int skippedProtected = 0;
                int skippedAfk = 0;
                int skippedRaidableBases = 0;
                int skippedBalance = 0;
                int skippedTier = 0;
                int skippedCooldown = 0;
                int skippedBase = 0;

                IEnumerable<BasePlayer> players = configData.cobaltWar.wealthTargetMustBeOnline
                    ? BasePlayer.activePlayerList.Cast<BasePlayer>()
                    : BasePlayer.allPlayerList.Cast<BasePlayer>();
                foreach (var player in players)
                {
                    if (player == null || player.IsNpc)
                    {
                        skippedNullOrNpc++;
                        continue;
                    }
                    if (!pcdData.tcData.ContainsKey(player.userID.Get()))
                    {
                        skippedMissingTcData++;
                        continue;
                    }
                    if (configData.settings.musthavePerm && !HasAnyPermission(player.UserIDString, usePerm, legacyUsePerm))
                    {
                        skippedPermission++;
                        continue;
                    }
                    if (FindWarByParticipant(player.userID, player.transform.position) != null)
                    {
                        skippedAlreadyInWar++;
                        continue;
                    }

                    if (IsBusyWithRaidableBases(player))
                    {
                        skippedRaidableBases++;
                        continue;
                    }

                    TimeSpan protectionRemaining;
                    if (IsProtectedRaidTarget(player, out protectionRemaining))
                    {
                        skippedProtected++;
                        continue;
                    }
                    if (IsRaidTargetAfk(player))
                    {
                        skippedAfk++;
                        continue;
                    }

                    int balance;
                    if (!TryGetCachedWealthBalance(player.userID.Get(), out balance))
                    {
                        skippedBalance++;
                        continue;
                    }

                    var tier = GetBalanceTierFor(balance);
                    if (tier == null)
                    {
                        skippedTier++;
                        continue;
                    }

                    TimeSpan automaticCooldownRemaining;
                    if (IsAutomaticRaidTargetCooldownActive(player.userID.Get(), configData.cobaltWar.wealthCooldownMinutes, out automaticCooldownRemaining))
                    {
                        skippedCooldown++;
                        continue;
                    }

                    BuildingPrivlidge privilege;
                    List<BuildingBlock> blocks;
                    List<ulong> authPlayers;
                    if (!TryGetPlayerBase(player, out privilege, out blocks, out authPlayers))
                    {
                        skippedBase++;
                        continue;
                    }

                    candidates.Add(new WealthTargetCandidate
                    {
                        player = player,
                        tier = tier,
                        balance = balance,
                        privilege = privilege,
                        blocks = blocks,
                        authPlayers = authPlayers
                    });
                }

                if (candidates.Count <= 0)
                {
                    CobaltDiagnosticLog("idle", $"Wealth scan завершен: подходящих кандидатов не найдено. skipNullNpc={skippedNullOrNpc}, skipMissingTc={skippedMissingTcData}, skipPerm={skippedPermission}, skipInWar={skippedAlreadyInWar}, skipRaidableBases={skippedRaidableBases}, skipProtected={skippedProtected}, skipAfk={skippedAfk}, skipBalance={skippedBalance}, skipTier={skippedTier}, skipCooldown={skippedCooldown}, skipBase={skippedBase}.");
                    return;
                }

                CobaltDiagnosticLog("idle", $"Wealth scan собрал кандидатов: {candidates.Count}. skipNullNpc={skippedNullOrNpc}, skipMissingTc={skippedMissingTcData}, skipPerm={skippedPermission}, skipInWar={skippedAlreadyInWar}, skipProtected={skippedProtected}, skipAfk={skippedAfk}, skipBalance={skippedBalance}, skipTier={skippedTier}, skipCooldown={skippedCooldown}, skipBase={skippedBase}.");

                ShuffleListInPlace(candidates);
                foreach (WealthTargetCandidate candidate in candidates.OrderByDescending(x => x.tier != null ? x.tier.minBalance : 0).ThenByDescending(x => x.balance))
                {
                    if (candidate == null || candidate.player == null || candidate.tier == null || candidate.privilege == null)
                        continue;

                    if (HasAnyRaidEventInProgress())
                    {
                        CobaltDiagnosticLog("idle", "Wealth scan остановлен: слот рейда занялся во время прохода.");
                        return;
                    }

                    if (TryScheduleCobaltWar(candidate.privilege, candidate.player, candidate.tier.raidType, candidate.blocks, candidate.authPlayers, CobaltWarTrigger.Wealth, candidate.tier, candidate.balance))
                    {
                        CobaltDiagnosticLog("idle", $"Wealth scan запустил рейд: target={candidate.player.displayName}, raidType={candidate.tier.raidType}, balance={candidate.balance}, grid={GetGrid(candidate.privilege.transform.position)}.");
                        return;
                    }
                }

                CobaltDiagnosticLog("idle", "Wealth scan завершен: кандидаты были, но стартовать рейд не удалось.");
            }
            catch (Exception ex)
            {
                PrintError($"ScanWealthTargets failed: {ex}");
            }
            finally
            {
                wealthScanInProgress = false;
                RefreshPlayerInputHookSubscription();
            }
        }

        private bool TryScheduleCobaltWar(BuildingPrivlidge privilege, BasePlayer targetPlayer, string raidType, List<BuildingBlock> blocks, List<ulong> authPlayers, CobaltWarTrigger trigger, ConfigData.BalanceTierConfig balanceTier = null, int targetBalanceSnapshot = 0, bool bypassOnlineRequirement = false)
        {
            CobaltWarSession ignored;
            return TryScheduleCobaltWar(privilege, targetPlayer, raidType, blocks, authPlayers, trigger, out ignored, balanceTier, targetBalanceSnapshot, CobaltWarStartMode.Standard, 0UL, bypassOnlineRequirement);
        }

        private bool TryScheduleCobaltWar(BuildingPrivlidge privilege, BasePlayer targetPlayer, string raidType, List<BuildingBlock> blocks, List<ulong> authPlayers, CobaltWarTrigger trigger, out CobaltWarSession createdWar, ConfigData.BalanceTierConfig balanceTier = null, int targetBalanceSnapshot = 0, CobaltWarStartMode startMode = CobaltWarStartMode.Standard, ulong immediateOwnerDefenderUserId = 0UL, bool bypassOnlineRequirement = false)
        {
            createdWar = null;

            if ((authPlayers != null && authPlayers.Count > 0) || privilege != null)
            {
                ulong preferredUserId = targetPlayer != null ? targetPlayer.userID.Get() : 0UL;
                BasePlayer resolvedTargetPlayer = ResolveCurrentRaidTargetPlayer(privilege, authPlayers, preferredUserId);
                if (resolvedTargetPlayer != null)
                    targetPlayer = resolvedTargetPlayer;
            }

            if (privilege == null || targetPlayer == null || string.IsNullOrEmpty(raidType))
                return false;
            if (configData?.cobaltWar == null || !configData.cobaltWar.enabled)
                return false;
            if (!IsRaidTypeEnabled(raidType))
                return false;
            if (!configData.raidSettings.raidTypes.ContainsKey(raidType))
                return false;
            if (trigger != CobaltWarTrigger.Manual && !IsCurrentlyAuthorizedForPrivilege(privilege, targetPlayer.userID.Get()))
                return false;

            int currentOnline;
            int requiredOnline;
            if (!bypassOnlineRequirement && !MeetsRaidTypeOnlineRequirement(raidType, out currentOnline, out requiredOnline))
                return false;

            if (HasAnyRaidEventInProgress() || HasStagedWarNear(privilege.transform.position))
                return false;

            raidConfig profile = CloneRaidConfig(configData.raidSettings.raidTypes[raidType]);
            if (profile == null)
                return false;

            if (trigger != CobaltWarTrigger.Manual)
            {
                if (configData.settings.mustBeOnlinePlayer && !HasEligibleOnlineAuthorizedPlayer(privilege))
                    return false;

                TimeSpan protectionRemaining;
                if (IsProtectedRaidTarget(targetPlayer, out protectionRemaining))
                    return false;
                if (IsRaidTargetAfk(targetPlayer))
                    return false;
            }

            if (targetBalanceSnapshot <= 0 && ServerRewards != null)
            {
                try
                {
                    targetBalanceSnapshot = Convert.ToInt32(ServerRewards.Call("CheckPoints", targetPlayer.userID.Get()));
                }
                catch
                {
                    targetBalanceSnapshot = 0;
                }
            }

            if (balanceTier == null && targetBalanceSnapshot > 0)
                balanceTier = GetBalanceTierFor(targetBalanceSnapshot);

            GameObject warObject = null;
            CobaltWarSession war = null;

            try
            {
                CobaltDiagnosticLog(trigger == CobaltWarTrigger.Manual ? "purchase" : "raid", $"Попытка старта войны: trigger={trigger}, raidType={raidType}, target={targetPlayer?.displayName ?? "unknown"}, grid={GetGrid(privilege.transform.position)}, owners={(authPlayers != null ? authPlayers.Count : 0)}, bypassOnline={bypassOnlineRequirement}, startMode={startMode}.");
                warObject = new GameObject("CobaltWarSession");
                war = warObject.AddComponent<CobaltWarSession>();
                war.Setup(this, privilege, targetPlayer, raidType, profile, blocks, authPlayers, trigger, balanceTier, targetBalanceSnapshot, startMode, immediateOwnerDefenderUserId, bypassOnlineRequirement);
                createdWar = war;
                CobaltDiagnosticLog(trigger == CobaltWarTrigger.Manual ? "purchase" : "raid", $"Война создана успешно: warId={war.warId}, trigger={trigger}, raidType={raidType}, target={targetPlayer?.displayName ?? "unknown"}.");
                return true;
            }
            catch (Exception ex)
            {
                PrintError($"TryScheduleCobaltWar failed for raidType '{raidType}', trigger '{trigger}', startMode '{startMode}', target '{targetPlayer?.displayName ?? "unknown"}': {ex}");

                try
                {
                    if (war != null)
                        UnregisterWar(war);
                }
                catch
                {
                }

                try
                {
                    if (warObject != null)
                        UnityEngine.Object.DestroyImmediate(warObject);
                }
                catch
                {
                }

                createdWar = null;
                return false;
            }
        }

        private bool TryScheduleExternalRaidBaseWar(BuildingPrivlidge privilege, string raidType, string displayName, string externalSourceId, out CobaltWarSession createdWar, out string failureCode, out string failureMessage, bool immediateStart = false, bool bypassOnlineRequirement = false)
        {
            createdWar = null;
            failureCode = "start_failed";
            failureMessage = lang.GetMessage("CobaltExternalRaidStartFailed", this, null);

            if (privilege == null || string.IsNullOrEmpty(raidType))
            {
                failureCode = privilege == null ? "no_cupboard" : "invalid_type";
                failureMessage = privilege == null
                    ? lang.GetMessage("CobaltExternalRaidCupboardMissing", this, null)
                    : string.Format(lang.GetMessage("NoConfigType", this, null), raidType);
                return false;
            }
            if (configData?.cobaltWar == null || !configData.cobaltWar.enabled)
            {
                failureCode = "disabled";
                failureMessage = "CobaltWar disabled.";
                return false;
            }
            if (!IsRaidTypeEnabled(raidType))
            {
                failureCode = "disabled_type";
                failureMessage = lang.GetMessage("CobaltRaidTypeDisabled", this, null);
                return false;
            }
            if (!configData.raidSettings.raidTypes.ContainsKey(raidType))
            {
                failureCode = "invalid_type";
                failureMessage = string.Format(lang.GetMessage("NoConfigType", this, null), raidType);
                return false;
            }
            if (HasAnyRaidEventInProgress() || HasStagedWarNear(privilege.transform.position))
            {
                failureCode = "max_events";
                failureMessage = lang.GetMessage("CobaltWarCancelledAnotherRaidActive", this, null);
                return false;
            }

            List<BuildingBlock> blocks;
            List<ulong> authPlayers;
            string failReasonKey;
            if (!TryPrepareRaidBase(privilege, out blocks, out authPlayers, out failReasonKey, true))
            {
                failureCode = "invalid_base";
                failureMessage = lang.GetMessage(string.IsNullOrEmpty(failReasonKey) ? "terrainBlocked" : failReasonKey, this, null);
                return false;
            }

            if (!bypassOnlineRequirement)
            {
                int currentOnline;
                int requiredOnline;
                if (!MeetsRaidTypeOnlineRequirement(raidType, out currentOnline, out requiredOnline))
                {
                    failureCode = "min_online";
                    failureMessage = string.Format(lang.GetMessage("CobaltMinOnlineRequirement", this, null), raidType, requiredOnline, currentOnline);
                    return false;
                }
            }

            raidConfig profile = CloneRaidConfig(configData.raidSettings.raidTypes[raidType]);
            if (profile == null)
            {
                failureCode = "invalid_profile";
                failureMessage = lang.GetMessage("CobaltExternalRaidStartFailed", this, null);
                return false;
            }

            GameObject warObject = null;
            CobaltWarSession war = null;

            try
            {
                warObject = new GameObject("CobaltWarSession");
                war = warObject.AddComponent<CobaltWarSession>();
                war.SetupExternal(this, privilege, string.IsNullOrEmpty(displayName) ? "Рейдовая база Кобальт" : displayName, raidType, profile, blocks, authPlayers, externalSourceId, immediateStart ? CobaltWarStartMode.Immediate : CobaltWarStartMode.Standard, bypassOnlineRequirement);
                createdWar = war;
                return true;
            }
            catch (Exception ex)
            {
                PrintError($"TryScheduleExternalRaidBaseWar failed for raidType '{raidType}', source '{externalSourceId ?? "unknown"}', display '{displayName ?? "unknown"}': {ex}");
                failureCode = "exception";
                failureMessage = ex.Message;

                try
                {
                    if (war != null)
                        UnregisterWar(war);
                }
                catch
                {
                }

                try
                {
                    if (warObject != null)
                        UnityEngine.Object.Destroy(warObject);
                }
                catch
                {
                }

                return false;
            }
        }

        private bool TrySampleNavMesh(Vector3 position, float distance, out Vector3 result)
        {
            NavMeshHit hit;
            if (NavMesh.SamplePosition(position, out hit, distance, NavMesh.AllAreas))
            {
                result = hit.position;
                return true;
            }

            result = Vector3.zero;
            return false;
        }

        private float GetTerrainSlopeAngle(Vector3 position)
        {
            Vector3 normal = TerrainMeta.HeightMap.GetNormal(position);
            if (normal == Vector3.zero)
                return 0f;

            return Vector3.Angle(normal, Vector3.up);
        }

        private RaidTerrainProfile AnalyzeRaidTerrain(BuildingPrivlidge privilege, List<BuildingBlock> blocks)
        {
            RaidTerrainProfile profile = new RaidTerrainProfile();
            if (privilege == null)
                return profile;

            List<Vector3> samples = new List<Vector3>();
            Vector3 origin = privilege.transform.position;
            float baseY = origin.y;
            samples.Add(origin);

            if (blocks != null && blocks.Count > 0)
            {
                List<BuildingBlock> baseLevelBlocks = blocks
                    .Where(x => x != null && Mathf.Abs(x.transform.position.y - baseY) <= 6f)
                    .OrderBy(x => Vector3.Distance(x.transform.position, origin))
                    .ToList();

                int step = Mathf.Max(1, Mathf.CeilToInt(baseLevelBlocks.Count / 10f));
                for (int i = 0; i < baseLevelBlocks.Count; i += step)
                    samples.Add(baseLevelBlocks[i].transform.position);
            }

            for (float radius = 8f; radius <= 22f; radius += 7f)
            {
                for (int i = 0; i < 8; i++)
                {
                    float angle = (360f / 8f) * i;
                    Vector3 point = origin + Quaternion.Euler(0f, angle, 0f) * Vector3.forward * radius;
                    point.y = baseY;
                    samples.Add(point);
                }
            }

            float heightDelta = Mathf.Max(2f, configData?.cobaltWar?.rockBaseHeightDelta ?? 7.5f);
            float slopeAngle = Mathf.Clamp(configData?.cobaltWar?.rockBaseSlopeAngle ?? 40f, 0f, 89f);
            float totalDelta = 0f;

            foreach (Vector3 sample in samples)
            {
                float terrainHeight = TerrainMeta.HeightMap.GetHeight(sample);
                if (terrainHeight <= -10f)
                    continue;

                float delta = Mathf.Max(0f, sample.y - terrainHeight);
                float slope = GetTerrainSlopeAngle(sample);

                profile.sampleCount++;
                totalDelta += delta;
                profile.maxElevationDelta = Mathf.Max(profile.maxElevationDelta, delta);

                if (delta >= heightDelta)
                    profile.elevatedSamples++;
                if (slope >= slopeAngle)
                    profile.steepSamples++;
            }

            if (profile.sampleCount > 0)
            {
                profile.averageElevationDelta = totalDelta / profile.sampleCount;
                profile.steepSampleRatio = (float)profile.steepSamples / profile.sampleCount;
            }

            int minElevatedSamples = Mathf.Max(2, configData?.cobaltWar?.rockBaseMinElevatedSamples ?? 3);
            bool elevatedBase = profile.elevatedSamples >= minElevatedSamples;
            bool steepBase = profile.steepSamples >= Mathf.Max(2, Mathf.CeilToInt(minElevatedSamples * 0.5f));

            profile.isRockBase = (configData?.cobaltWar?.adaptRockBases ?? false)
                && profile.sampleCount > 0
                && (
                    profile.maxElevationDelta >= heightDelta * 1.6f ||
                    (elevatedBase && steepBase) ||
                    (profile.averageElevationDelta >= heightDelta && profile.steepSampleRatio >= 0.35f)
                );

            return profile;
        }

        private bool TryGetGroundHit(Vector3 position, out RaycastHit bestHit, float rayHeight = 30f, float rayDistance = 90f)
        {
            Vector3 origin = position + Vector3.up * rayHeight;
            RaycastHit[] hits = Physics.RaycastAll(origin, Vector3.down, rayDistance, groundLayer, QueryTriggerInteraction.Ignore);

            bestHit = default(RaycastHit);
            bool found = false;
            float bestScore = float.MaxValue;
            RaycastHit fallbackHit = default(RaycastHit);
            bool hasFallback = false;

            if (hits != null && hits.Length > 0)
            {
                foreach (RaycastHit hit in hits.OrderBy(x => x.distance))
                {
                    if (hit.collider == null)
                        continue;

                    if (hit.collider.gameObject.layer == LayerMask.NameToLayer("Construction"))
                        continue;

                    if (!hasFallback)
                    {
                        fallbackHit = hit;
                        hasFallback = true;
                    }

                    float slope = Vector3.Angle(hit.normal, Vector3.up);
                    if (slope >= 84f)
                        continue;

                    float score = slope;
                    if (hit.collider.gameObject.layer == LayerMask.NameToLayer("Terrain"))
                        score -= 6f;
                    else if (hit.collider.gameObject.layer == LayerMask.NameToLayer("World"))
                        score -= 2f;

                    score += hit.distance * 0.02f;

                    if (!found || score < bestScore)
                    {
                        bestScore = score;
                        bestHit = hit;
                        found = true;
                    }
                }
            }

            if (!found && hasFallback)
            {
                bestHit = fallbackHit;
                found = true;
            }

            return found;
        }

        private bool TryGetGroundPoint(Vector3 position, out Vector3 result, float rayHeight = 30f, float rayDistance = 90f)
        {
            RaycastHit hit;
            if (TryGetGroundHit(position, out hit, rayHeight, rayDistance))
            {
                Vector3 normalOffset = hit.normal.sqrMagnitude > 0.01f ? hit.normal.normalized * 0.3f : Vector3.zero;
                result = hit.point + normalOffset + Vector3.up * 0.05f;
                if (result.y < hit.point.y + 0.12f)
                    result.y = hit.point.y + 0.12f;
                if (IsBlockedByRockObstruction(result))
                {
                    result = Vector3.zero;
                    return false;
                }
                return true;
            }

            result = Vector3.zero;
            return false;
        }

        private static bool IsRockLikeColliderName(string colliderName)
        {
            if (string.IsNullOrEmpty(colliderName))
                return false;

            return colliderName.IndexOf("rock", StringComparison.OrdinalIgnoreCase) >= 0
                || colliderName.IndexOf("formation", StringComparison.OrdinalIgnoreCase) >= 0
                || colliderName.IndexOf("cliff", StringComparison.OrdinalIgnoreCase) >= 0
                || colliderName.IndexOf("prevent_movement", StringComparison.OrdinalIgnoreCase) >= 0
                || colliderName.IndexOf("invisible", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static bool IsBlockedByRockObstruction(Vector3 position, float probeRadius = 0.35f, float raycastHeight = 24f, float raycastDistance = 28f)
        {
            float terrainHeight = TerrainMeta.HeightMap.GetHeight(position);
            float surfaceHeight = Mathf.Max(position.y, terrainHeight);
            Vector3 probePoint = new Vector3(position.x, surfaceHeight + 0.2f, position.z);
            int worldMask = LayerMask.GetMask("World");

            if (worldMask != 0)
            {
                Collider[] overlaps = Physics.OverlapSphere(probePoint, Mathf.Clamp(probeRadius, 0.12f, 0.65f), worldMask, QueryTriggerInteraction.Ignore);
                if (overlaps != null)
                {
                    foreach (Collider collider in overlaps)
                    {
                        if (collider == null || !IsRockLikeColliderName(collider.name))
                            continue;

                        Vector3 closestPoint = collider.ClosestPoint(probePoint);
                        if ((closestPoint - probePoint).sqrMagnitude <= (probeRadius + 0.08f) * (probeRadius + 0.08f))
                            return true;
                    }
                }
            }

            int raycastMask = terrainLayer != 0 ? terrainLayer : LayerMask.GetMask("Terrain", "World", "Water");
            RaycastHit[] hits = Physics.RaycastAll(new Vector3(position.x, surfaceHeight + raycastHeight, position.z), Vector3.down, raycastDistance, raycastMask, QueryTriggerInteraction.Ignore);
            if (hits == null || hits.Length == 0)
                return false;

            foreach (RaycastHit hit in hits)
            {
                if (hit.collider == null || !IsRockLikeColliderName(hit.collider.name))
                    continue;

                if (hit.point.y > surfaceHeight + 0.25f)
                    return true;
            }

            return false;
        }

        private int GetPlayerSpawnObstacleMask()
        {
            return spawnObstacleLayer != 0
                ? spawnObstacleLayer
                : LayerMask.GetMask("Construction", "World", "Default", "Deployed", "Deployable", "Tree", "Resource", "Vehicle_Large", "Vehicle_Movement");
        }

        private bool HasHorizontalSpawnClearance(Vector3 position, float radius = 0.8f)
        {
            int obstacleMask = GetPlayerSpawnObstacleMask();
            if (obstacleMask == 0)
                return true;

            float[] heights = { 0.55f, 1.15f, 1.7f };
            foreach (float height in heights)
            {
                Vector3 origin = position + Vector3.up * height;
                for (int i = 0; i < 8; i++)
                {
                    Vector3 direction = Quaternion.Euler(0f, 45f * i, 0f) * Vector3.forward;
                    RaycastHit hit;
                    if (Physics.Raycast(origin, direction, out hit, radius, obstacleMask, QueryTriggerInteraction.Ignore))
                    {
                        if (hit.collider != null && !hit.collider.isTrigger)
                            return false;
                    }
                }
            }

            return true;
        }

        private float GetSpawnFreedomScore(Vector3 position, float probeDistance = 1.35f)
        {
            int obstacleMask = GetPlayerSpawnObstacleMask();
            if (obstacleMask == 0)
                return probeDistance;

            float total = 0f;
            int samples = 0;
            float[] heights = { 0.55f, 1.15f };
            foreach (float height in heights)
            {
                Vector3 origin = position + Vector3.up * height;
                for (int i = 0; i < 8; i++)
                {
                    Vector3 direction = Quaternion.Euler(0f, 45f * i, 0f) * Vector3.forward;
                    RaycastHit hit;
                    if (Physics.Raycast(origin, direction, out hit, probeDistance, obstacleMask, QueryTriggerInteraction.Ignore) && hit.collider != null && !hit.collider.isTrigger)
                        total += hit.distance;
                    else
                        total += probeDistance;

                    samples++;
                }
            }

            return samples > 0 ? total / samples : 0f;
        }

        private bool ShouldUseNavMeshSpawnPoint(Vector3 surfacePoint, Vector3 navPoint, bool allowCliffs)
        {
            if (navPoint == Vector3.zero)
                return false;

            float horizontalDelta = GetHorizontalDistance(surfacePoint, navPoint);
            float verticalDelta = Mathf.Abs(surfacePoint.y - navPoint.y);
            if (horizontalDelta > (allowCliffs ? 4.5f : 3f))
                return false;

            if (verticalDelta > (allowCliffs ? 2.4f : 1.35f))
                return false;

            int obstacleMask = GetPlayerSpawnObstacleMask();
            RaycastHit obstructionHit;
            if (Physics.Linecast(surfacePoint + Vector3.up * 0.9f, navPoint + Vector3.up * 0.9f, out obstructionHit, obstacleMask, QueryTriggerInteraction.Ignore))
            {
                if (obstructionHit.collider != null && !obstructionHit.collider.isTrigger)
                    return false;
            }

            if (!HasSpawnClearance(navPoint))
                return false;

            if (!HasStableSpawnSurface(navPoint, allowCliffs))
                return false;

            if (IsBlockedByRockObstruction(surfacePoint, allowCliffs ? 0.28f : 0.35f) || IsBlockedByRockObstruction(navPoint, allowCliffs ? 0.28f : 0.35f))
                return false;

            return GetSpawnFreedomScore(navPoint) >= GetSpawnFreedomScore(surfacePoint) - 0.05f;
        }

        private bool HasStableSpawnSurface(Vector3 position, bool allowCliffs = false)
        {
            float maxSlope = Mathf.Clamp(configData?.cobaltWar?.maxDefenderSpawnSlopeAngle ?? 42f, 5f, 89f);
            float allowedSlope = allowCliffs ? Mathf.Min(89f, maxSlope + 6f) : maxSlope;
            float maxVerticalOffset = allowCliffs ? 1.15f : 0.7f;
            float maxSurfaceVariance = allowCliffs ? 1.05f : 0.6f;

            Vector3[] offsets =
            {
                Vector3.zero,
                Vector3.forward * 0.45f,
                Vector3.back * 0.45f,
                Vector3.left * 0.45f,
                Vector3.right * 0.45f,
                (Vector3.forward + Vector3.left).normalized * 0.35f,
                (Vector3.forward + Vector3.right).normalized * 0.35f
            };

            bool centerFound = false;
            int supportHits = 0;
            float minY = float.MaxValue;
            float maxY = float.MinValue;

            foreach (Vector3 offset in offsets)
            {
                RaycastHit surfaceHit;
                if (!TryGetGroundHit(position + offset, out surfaceHit, 2.5f, 6f))
                    continue;

                float surfaceSlope = Vector3.Angle(surfaceHit.normal, Vector3.up);
                if (surfaceSlope > allowedSlope)
                    continue;

                float verticalOffset = Mathf.Abs(surfaceHit.point.y - position.y);
                if (verticalOffset > maxVerticalOffset)
                    continue;

                supportHits++;
                minY = Mathf.Min(minY, surfaceHit.point.y);
                maxY = Mathf.Max(maxY, surfaceHit.point.y);

                if (offset == Vector3.zero)
                    centerFound = true;
            }

            if (!centerFound)
                return false;

            if (supportHits < (allowCliffs ? 5 : 6))
                return false;

            if (minY == float.MaxValue || maxY == float.MinValue)
                return false;

            return (maxY - minY) <= maxSurfaceVariance;
        }

        private bool HasSpawnClearance(Vector3 position)
        {
            int obstacleMask = GetPlayerSpawnObstacleMask();
            Vector3 feet = position + Vector3.up * 0.45f;
            Vector3 head = position + Vector3.up * 1.55f;
            if (Physics.CheckCapsule(feet, head, 0.42f, obstacleMask, QueryTriggerInteraction.Ignore))
                return false;

            RaycastHit hit;
            if (Physics.Raycast(position + Vector3.up * 0.35f, Vector3.up, out hit, 1.65f, obstacleMask, QueryTriggerInteraction.Ignore))
            {
                if (hit.collider != null && hit.distance < 1.35f)
                    return false;
            }

            return HasHorizontalSpawnClearance(position);
        }

        private bool IsSpawnBlockingEntity(BaseEntity entity)
        {
            if (entity == null || entity.IsDestroyed)
                return false;

            if (entity is BasePlayer)
                return false;

            string typeName = entity.GetType().Name ?? string.Empty;
            if (typeName.IndexOf("Building", StringComparison.OrdinalIgnoreCase) >= 0
                || typeName.IndexOf("Door", StringComparison.OrdinalIgnoreCase) >= 0
                || typeName.IndexOf("Deploy", StringComparison.OrdinalIgnoreCase) >= 0
                || typeName.IndexOf("Resource", StringComparison.OrdinalIgnoreCase) >= 0
                || typeName.IndexOf("Tree", StringComparison.OrdinalIgnoreCase) >= 0
                || typeName.IndexOf("Turret", StringComparison.OrdinalIgnoreCase) >= 0)
                return true;

            string prefabName = entity.ShortPrefabName ?? string.Empty;
            return prefabName.IndexOf("foundation", StringComparison.OrdinalIgnoreCase) >= 0
                || prefabName.IndexOf("wall", StringComparison.OrdinalIgnoreCase) >= 0
                || prefabName.IndexOf("floor", StringComparison.OrdinalIgnoreCase) >= 0
                || prefabName.IndexOf("door", StringComparison.OrdinalIgnoreCase) >= 0
                || prefabName.IndexOf("cupboard", StringComparison.OrdinalIgnoreCase) >= 0
                || prefabName.IndexOf("deploy", StringComparison.OrdinalIgnoreCase) >= 0
                || prefabName.IndexOf("ore", StringComparison.OrdinalIgnoreCase) >= 0
                || prefabName.IndexOf("tree", StringComparison.OrdinalIgnoreCase) >= 0
                || prefabName.IndexOf("stone", StringComparison.OrdinalIgnoreCase) >= 0
                || prefabName.IndexOf("rock", StringComparison.OrdinalIgnoreCase) >= 0
                || prefabName.IndexOf("barricade", StringComparison.OrdinalIgnoreCase) >= 0
                || prefabName.IndexOf("turret", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private bool HasNearbySpawnEntityObstruction(Vector3 position, float radius = 0.7f)
        {
            List<BaseEntity> nearbyEntities = Pool.Get<List<BaseEntity>>();
            try
            {
                Vis.Entities(position + Vector3.up * 0.9f, radius, nearbyEntities);

                foreach (BaseEntity entity in nearbyEntities)
                {
                    if (IsSpawnBlockingEntity(entity))
                        return true;
                }
            }
            finally
            {
                Pool.FreeUnmanaged(ref nearbyEntities);
            }

            return false;
        }

        private bool HasStrictPlayerSpawnClearance(Vector3 position)
        {
            int obstacleMask = GetPlayerSpawnObstacleMask();
            if (obstacleMask == 0)
                return true;

            Vector3 feet = position + Vector3.up * 0.52f;
            Vector3 head = position + Vector3.up * 1.68f;

            if (Physics.CheckCapsule(feet, head, 0.48f, obstacleMask, QueryTriggerInteraction.Ignore))
                return false;

            if (HasNearbySpawnEntityObstruction(position))
                return false;

            RaycastHit upHit;
            if (Physics.Raycast(position + Vector3.up * 0.25f, Vector3.up, out upHit, 1.95f, obstacleMask, QueryTriggerInteraction.Ignore))
            {
                if (upHit.collider != null && !upHit.collider.isTrigger)
                    return false;
            }

            return HasHorizontalSpawnClearance(position, 1.25f);
        }

        private bool TryValidateFinalDefenderSpawnPoint(CobaltWarSession war, Vector3 spawnPoint, bool rockAware, bool requireNavigablePath, bool strictClearance, out string reason)
        {
            reason = null;

            if (!IsSpawnLocationSafe(spawnPoint, rockAware))
            {
                reason = "safe";
                return false;
            }

            if (strictClearance && !HasStrictPlayerSpawnClearance(spawnPoint))
            {
                reason = "clearance";
                return false;
            }

            if (GetHorizontalDistance(spawnPoint, war.location) < 10f)
            {
                reason = "base-distance";
                return false;
            }

            if (IsNearActiveRaidTank(war, spawnPoint))
            {
                reason = "tank";
                return false;
            }

            if (requireNavigablePath && !HasNavigableCombatPath(war, spawnPoint))
            {
                reason = "path";
                return false;
            }

            return true;
        }

        private bool TryResolveFinalDefenderSpawn(CobaltWarSession war, Vector3 candidate, out Vector3 resolved, out string reason, bool strictClearance = true)
        {
            resolved = Vector3.zero;
            reason = null;

            if (war == null)
            {
                reason = "war";
                return false;
            }

            if (!IsFinitePosition(candidate))
            {
                reason = "invalid";
                return false;
            }

            bool rockAware = war.IsRockBaseTerrain;
            Vector3 surfacePoint;
            if (!TryGetGroundPoint(candidate, out surfacePoint, rockAware ? 14f : 7f, rockAware ? 34f : 18f))
            {
                reason = "ground";
                return false;
            }

            Vector3 navPoint;
            bool hasNavMesh = TrySampleNavMesh(surfacePoint, rockAware ? 8f : 5f, out navPoint);
            bool useNavMesh = hasNavMesh && ShouldUseNavMeshSpawnPoint(surfacePoint, navPoint, rockAware);

            string navReason = null;
            if (useNavMesh && TryValidateFinalDefenderSpawnPoint(war, navPoint, rockAware, true, strictClearance, out navReason))
            {
                resolved = navPoint;
                return true;
            }

            string surfaceReason;
            if (TryValidateFinalDefenderSpawnPoint(war, surfacePoint, rockAware, false, strictClearance, out surfaceReason))
            {
                resolved = surfacePoint;
                return true;
            }

            reason = !string.IsNullOrEmpty(surfaceReason) ? surfaceReason : (!string.IsNullOrEmpty(navReason) ? navReason : "unknown");
            return false;
        }

        private float GetHorizontalDistance(Vector3 a, Vector3 b)
        {
            Vector2 a2 = new Vector2(a.x, a.z);
            Vector2 b2 = new Vector2(b.x, b.z);
            return Vector2.Distance(a2, b2);
        }

        private float GetWarBaseHorizontalRadius(CobaltWarSession war)
        {
            if (war == null)
                return 0f;

            float maxDistance = 0f;

            if (war.blocks != null)
            {
                foreach (BuildingBlock block in war.blocks)
                {
                    if (block == null)
                        continue;

                    maxDistance = Mathf.Max(maxDistance, GetHorizontalDistance(war.location, block.transform.position));
                }
            }

            if (war.privilege != null)
                maxDistance = Mathf.Max(maxDistance, GetHorizontalDistance(war.location, war.privilege.transform.position));

            return maxDistance;
        }

        private float GetWarBaseVerticalRange(CobaltWarSession war)
        {
            if (war == null)
                return 0f;

            float minY = war.location.y;
            float maxY = war.location.y;

            if (war.blocks != null)
            {
                foreach (BuildingBlock block in war.blocks)
                {
                    if (block == null)
                        continue;

                    float y = block.transform.position.y;
                    if (y < minY)
                        minY = y;
                    if (y > maxY)
                        maxY = y;
                }
            }

            return Mathf.Max(0f, maxY - minY);
        }

        private bool HasNavigableCombatPath(CobaltWarSession war, Vector3 start)
        {
            if (war == null)
                return true;

            NavMeshPath path = new NavMeshPath();
            List<Vector3> targets = new List<Vector3> { war.location };

            foreach (ulong ownerId in war.owners)
            {
                BasePlayer owner = BasePlayer.FindByID(ownerId);
                if (owner != null && owner.IsConnected)
                    targets.Add(owner.transform.position);
            }

            foreach (Vector3 target in targets)
            {
                Vector3 sampledTarget;
                if (!TrySampleNavMesh(target, 8f, out sampledTarget))
                    sampledTarget = target;

                if (NavMesh.CalculatePath(start, sampledTarget, NavMesh.AllAreas, path) && path.status == NavMeshPathStatus.PathComplete)
                    return true;

                float horizontalDistance = GetHorizontalDistance(start, sampledTarget);
                float heightDifference = Mathf.Abs(start.y - sampledTarget.y);

                if (war.IsRockBaseTerrain && horizontalDistance <= 48f && heightDifference <= 18f)
                    return true;

                if (horizontalDistance <= 30f && heightDifference <= 10f)
                    return true;
            }

            return false;
        }

        private bool TryGetNearestBaseToPlayer(BasePlayer player, out BuildingPrivlidge privilege, out List<BuildingBlock> blocks, out List<ulong> authPlayers, out string failReasonKey, bool ignoreRaidEligibility = true)
        {
            privilege = null;
            blocks = new List<BuildingBlock>();
            authPlayers = new List<ulong>();
            failReasonKey = null;

            if (player == null)
            {
                failReasonKey = "NoNearestBaseForRaid";
                return false;
            }

            string lastFailure = null;

            foreach (BuildingPrivlidge privFind in BaseNetworkable.serverEntities.OfType<BuildingPrivlidge>().OrderBy(x => Vector3.Distance(x.transform.position, player.transform.position)))
            {
                if (privFind == null || privFind.IsDestroyed)
                    continue;

                string reason;
                List<BuildingBlock> preparedBlocks;
                List<ulong> preparedAuth;
                if (!TryPrepareRaidBase(privFind, out preparedBlocks, out preparedAuth, out reason, ignoreRaidEligibility))
                {
                    if (string.IsNullOrEmpty(lastFailure) && !string.IsNullOrEmpty(reason))
                        lastFailure = reason;
                    continue;
                }

                privilege = privFind;
                blocks = preparedBlocks;
                authPlayers = preparedAuth;
                return true;
            }

            failReasonKey = string.IsNullOrEmpty(lastFailure) ? "NoNearestBaseForRaid" : lastFailure;
            return false;
        }

        private bool IsSpawnLocationSafe(Vector3 position, bool allowCliffs = false)
        {
            if (position == Vector3.zero)
                return false;

            Vector3 check = position;
            float terrainHeight = TerrainMeta.HeightMap.GetHeight(check);
            if (Mathf.Max(check.y, terrainHeight) <= -0.1f)
                return false;

            Vector3 waterCheck = check;
            waterCheck.y = Mathf.Max(check.y, terrainHeight);
            if (WaterLevel.GetWaterDepth(waterCheck, true, false) > 0.44f)
                return false;

            if (isBlockedTerain(check, allowCliffs))
                return false;

            if (IsBlockedByRockObstruction(check, allowCliffs ? 0.28f : 0.35f))
                return false;

            if (!HasSpawnClearance(check))
                return false;

            if (!HasStableSpawnSurface(check, allowCliffs))
                return false;

            int obstacleMask = GetPlayerSpawnObstacleMask();
            if (Physics.CheckCapsule(check + Vector3.up * 0.45f, check + Vector3.up * 1.8f, 0.45f, obstacleMask, QueryTriggerInteraction.Ignore))
                return false;

            return true;
        }

        private bool TryAddDefenderSpawnCandidate(CobaltWarSession war, Vector3 candidate, bool rockAware, float rayHeight, float rayDistance, float navSearchDistance, bool requireNavMesh, List<Vector3> candidates)
        {
            if (war == null)
                return false;

            Vector3 surfacePoint;
            if (!TryGetGroundPoint(candidate, out surfacePoint, rayHeight, rayDistance))
                return false;

            Vector3 spawnPoint = surfacePoint;
            Vector3 navPoint;
            bool hasNavMesh = TrySampleNavMesh(surfacePoint, navSearchDistance, out navPoint);
            bool useNavMesh = false;
            if (hasNavMesh && ShouldUseNavMeshSpawnPoint(surfacePoint, navPoint, rockAware))
            {
                spawnPoint = navPoint;
                useNavMesh = true;
            }
            else if (requireNavMesh)
                return false;

            if (!IsSpawnLocationSafe(spawnPoint, rockAware))
                return false;
            if (GetHorizontalDistance(spawnPoint, war.location) < 10f)
                return false;
            if (IsNearActiveRaidTank(war, spawnPoint))
                return false;
            if (useNavMesh && !HasNavigableCombatPath(war, spawnPoint))
                return false;
            if (candidates.Any(existing => Vector3.Distance(existing, spawnPoint) <= 2f))
                return false;

            candidates.Add(spawnPoint);
            return true;
        }

        private bool HasNearbyNavMesh(Vector3 position, float distance = 4f)
        {
            Vector3 navPoint;
            return TrySampleNavMesh(position, distance, out navPoint);
        }

        private bool TryFindDefenderSpawn(CobaltWarSession war, out Vector3 spawn)
        {
            spawn = Vector3.zero;
            if (war == null)
                return false;

            bool rockAware = war.IsRockBaseTerrain;
            float baseRadius = GetWarBaseHorizontalRadius(war);
            float verticalRange = GetWarBaseVerticalRange(war);
            float minRadius = Mathf.Max(10f, rockAware ? configData.cobaltWar.rockBaseDefenderSpawnRadiusMin : configData.cobaltWar.defenderSpawnRadiusMin);
            float maxRadius = Mathf.Max(minRadius + 5f, rockAware ? configData.cobaltWar.rockBaseDefenderSpawnRadiusMax : configData.cobaltWar.defenderSpawnRadiusMax);
            minRadius = Mathf.Max(minRadius, baseRadius + (rockAware ? 8f : 6f));
            maxRadius = Mathf.Max(maxRadius, baseRadius + (rockAware ? 26f : 18f));
            float extendedMaxRadius = Mathf.Max(maxRadius + 18f, baseRadius + (rockAware ? 46f : 32f));
            float hardMaxRadius = Mathf.Min(Mathf.Max(extendedMaxRadius, minRadius + 12f), Mathf.Max(minRadius + 12f, configData.cobaltWar.combatRadius - 10f));
            List<Vector3> candidates = new List<Vector3>();
            float angleOffset = UnityEngine.Random.Range(0f, 360f);
            int angleSteps = rockAware ? 36 : 28;
            float radiusStep = rockAware ? 4f : 4.5f;
            float navSearchDistance = rockAware ? 16f : 10f;
            float rayHeight = rockAware ? Mathf.Max(54f, 26f + verticalRange) : Mathf.Max(34f, 20f + (verticalRange * 0.65f));
            float rayDistance = rockAware ? Mathf.Max(180f, 120f + verticalRange) : Mathf.Max(130f, 95f + verticalRange);

            for (float radius = minRadius; radius <= maxRadius; radius += radiusStep)
            {
                for (int i = 0; i < angleSteps; i++)
                {
                    float angle = angleOffset + (360f / angleSteps) * i;
                    Vector3 candidate = war.location + Quaternion.Euler(0f, angle, 0f) * Vector3.forward * radius;
                    candidate.y = war.location.y;

                    TryAddDefenderSpawnCandidate(war, candidate, rockAware, rayHeight, rayDistance, navSearchDistance, false, candidates);
                }
            }

            if (candidates.Count <= 0)
            {
                for (float radius = maxRadius + 4f; radius <= hardMaxRadius; radius += rockAware ? 5f : 6f)
                {
                    for (int i = 0; i < angleSteps; i++)
                    {
                        float angle = angleOffset + (360f / angleSteps) * i;
                        Vector3 candidate = war.location + Quaternion.Euler(0f, angle, 0f) * Vector3.forward * radius;
                        candidate.y = war.location.y;
                        TryAddDefenderSpawnCandidate(war, candidate, rockAware, rayHeight + 12f, rayDistance + 20f, navSearchDistance + 4f, false, candidates);
                    }
                }
            }

            if (candidates.Count <= 0)
            {
                foreach (ulong ownerId in war.owners)
                {
                    BasePlayer owner = BasePlayer.FindByID(ownerId);
                    if (owner == null || !owner.IsConnected)
                        continue;

                    int ownerAngleSteps = rockAware ? 18 : 12;
                    float ownerRadiusMin = rockAware ? 8f : 6f;
                    float ownerRadiusMax = rockAware ? 20f : 12f;

                    for (float radius = ownerRadiusMin; radius <= ownerRadiusMax; radius += rockAware ? 3f : 2f)
                    {
                        for (int i = 0; i < ownerAngleSteps; i++)
                        {
                            float angle = angleOffset + (360f / ownerAngleSteps) * i;
                            Vector3 candidate = owner.transform.position + Quaternion.Euler(0f, angle, 0f) * Vector3.forward * radius;
                            candidate.y = owner.transform.position.y;

                            TryAddDefenderSpawnCandidate(war, candidate, rockAware, rayHeight, rayDistance, rockAware ? 16f : 10f, false, candidates);
                        }
                    }
                }
            }

            if (candidates.Count <= 0 && war.blocks != null && war.blocks.Count > 0)
            {
                List<BuildingBlock> edgeBlocks = war.blocks
                    .Where(x => x != null)
                    .OrderByDescending(x => GetHorizontalDistance(war.location, x.transform.position))
                    .Take(18)
                    .ToList();

                foreach (BuildingBlock block in edgeBlocks)
                {
                    float anchorRadius = rockAware ? 8f : 6f;
                    float anchorMaxRadius = rockAware ? 18f : 14f;
                    int anchorAngleSteps = rockAware ? 14 : 10;

                    for (float radius = anchorRadius; radius <= anchorMaxRadius; radius += 3f)
                    {
                        for (int i = 0; i < anchorAngleSteps; i++)
                        {
                            float angle = angleOffset + (360f / anchorAngleSteps) * i;
                            Vector3 candidate = block.transform.position + Quaternion.Euler(0f, angle, 0f) * Vector3.forward * radius;
                            candidate.y = block.transform.position.y;

                            TryAddDefenderSpawnCandidate(war, candidate, rockAware, rayHeight + 8f, rayDistance + 20f, navSearchDistance + 4f, false, candidates);
                        }
                    }
                }
            }

            if (candidates.Count <= 0)
            {
                CobaltDiagnosticLog("raid", $"Defender spawn generation failed: war={war.warId}, rock={rockAware}, baseRadius={baseRadius:0.##}, verticalRange={verticalRange:0.##}, minRadius={minRadius:0.##}, maxRadius={maxRadius:0.##}, hardMaxRadius={hardMaxRadius:0.##}.");
                return false;
            }

            List<Vector3> orderedCandidates = candidates
                .OrderByDescending(x => HasNearbyNavMesh(x))
                .ThenByDescending(x => GetSpawnFreedomScore(x))
                .ThenBy(x => Mathf.Abs(GetHorizontalDistance(x, war.location) - Mathf.Clamp(baseRadius + 12f, minRadius, hardMaxRadius)))
                .ThenBy(x => Mathf.Abs(x.y - war.location.y))
                .ToList();

            Dictionary<string, int> rejectReasons = new Dictionary<string, int>();
            foreach (Vector3 candidate in orderedCandidates)
            {
                Vector3 finalSpawn;
                string reason;
                if (TryResolveFinalDefenderSpawn(war, candidate, out finalSpawn, out reason))
                {
                    spawn = finalSpawn;
                    if (Vector3.Distance(candidate, finalSpawn) > 0.35f)
                        CobaltDiagnosticLog("raid", $"Defender spawn adjusted: war={war.warId}, from={candidate.x:0.##},{candidate.y:0.##},{candidate.z:0.##}, to={finalSpawn.x:0.##},{finalSpawn.y:0.##},{finalSpawn.z:0.##}, rock={rockAware}.");
                    return true;
                }

                reason = string.IsNullOrEmpty(reason) ? "unknown" : reason;
                rejectReasons[reason] = rejectReasons.ContainsKey(reason) ? rejectReasons[reason] + 1 : 1;
            }

            if (rejectReasons.Count == 1 && rejectReasons.ContainsKey("clearance"))
            {
                foreach (Vector3 candidate in orderedCandidates)
                {
                    Vector3 finalSpawn;
                    string reason;
                    if (TryResolveFinalDefenderSpawn(war, candidate, out finalSpawn, out reason, false))
                    {
                        spawn = finalSpawn;
                        CobaltDiagnosticLog("raid", $"Defender spawn accepted by relaxed clearance: war={war.warId}, pos={finalSpawn.x:0.##},{finalSpawn.y:0.##},{finalSpawn.z:0.##}, total={orderedCandidates.Count}, rock={rockAware}.");
                        return true;
                    }
                }
            }

            CobaltDiagnosticLog("raid", $"Defender spawn rejected all candidates: war={war.warId}, total={orderedCandidates.Count}, rock={rockAware}, reasons={string.Join(",", rejectReasons.Select(x => x.Key + ":" + x.Value).ToArray())}.");
            return false;
        }

        private bool IsNearActiveRaidTank(CobaltWarSession war, Vector3 position, float minDistance = 22f)
        {
            if (war?.raidManager?.tanks == null || war.raidManager.tanks.Count == 0)
                return false;

            float sqrDistance = minDistance * minDistance;
            foreach (BradleyAPC tank in war.raidManager.tanks)
            {
                if (tank == null || tank.IsDestroyed)
                    continue;

                if ((tank.transform.position - position).sqrMagnitude <= sqrDistance)
                    return true;
            }

            return false;
        }

        private Vector3 GetTankTargetPosition(EventRandomManager manager)
        {
            if (manager == null)
                return Vector3.zero;

            manager.RefreshRaidAnchors();
            BaseCombatEntity tc = manager.tc;
            if (tc != null && !tc.IsDestroyed)
                return tc.transform.position + new Vector3(0f, 0.8f, 0f);

            return manager.location + new Vector3(0f, 1.2f, 0f);
        }

        private Vector3 GetTankObjectivePoint(BaseCombatEntity entity)
        {
            if (entity == null || entity.IsDestroyed)
                return Vector3.zero;

            BuildingBlock block = entity as BuildingBlock;
            if (block != null)
                return block.CenterPoint();

            return entity.transform.position + (entity is BuildingPrivlidge ? new Vector3(0f, 0.8f, 0f) : new Vector3(0f, 0.5f, 0f));
        }

        private bool HasTankFireSolution(Vector3 origin, Vector3 target, bool allowIndirect)
        {
            float maxDistance = Mathf.Max(40f, configData?.cobaltWar?.tankAttackDistance ?? 160f);
            if (Vector3.Distance(origin, target) > maxDistance)
                return false;

            Vector3 fireOrigin = origin + new Vector3(0f, 2.4f, 0f);
            Vector3 fireTarget = target + new Vector3(0f, 1.2f, 0f);

            RaycastHit hit;
            if (!Physics.Linecast(fireOrigin, fireTarget, out hit, obstructionMask, QueryTriggerInteraction.Ignore))
                return true;

            if (hit.collider == null)
                return allowIndirect;

            BaseEntity hitEntity = hit.GetEntity();
            if (hitEntity is BuildingBlock || hitEntity is BuildingPrivlidge)
                return true;

            if (hitEntity != null && Vector3.Distance(hit.point, fireTarget) <= 4f)
                return true;

            if (Vector3.Distance(hit.point, fireTarget) <= 6f)
                return true;

            return allowIndirect;
        }

        private bool IsTankSpawnLocationSafe(Vector3 position)
        {
            if (position == Vector3.zero)
                return false;

            float terrainHeight = TerrainMeta.HeightMap.GetHeight(position);
            if (Mathf.Max(position.y, terrainHeight) <= -0.1f)
                return false;

            Vector3 waterCheck = position;
            waterCheck.y = Mathf.Max(position.y, terrainHeight);
            if (WaterLevel.GetWaterDepth(waterCheck, true, false) > 0.2f)
                return false;

            if (isBlockedTerain(position, false))
                return false;

            if (IsBlockedByRockObstruction(position, 0.55f))
                return false;

            if (GetTerrainSlopeAngle(position) > Mathf.Clamp(configData?.cobaltWar?.maxTankSpawnSlopeAngle ?? 18f, 5f, 45f))
                return false;

            if (Physics.CheckSphere(position + Vector3.up, 3.75f, BuildingLayer, QueryTriggerInteraction.Ignore))
                return false;

            if (Physics.CheckCapsule(position + Vector3.up * 0.5f, position + Vector3.up * 3f, 2.25f, LayerMask.GetMask("World", "Construction"), QueryTriggerInteraction.Ignore))
                return false;

            return true;
        }

        private bool TryFindTankSpawn(EventRandomManager manager, int tankIndex, out Vector3 spawn, out bool indirectFireOnly)
        {
            spawn = Vector3.zero;
            indirectFireOnly = false;

            if (manager == null || configData?.cobaltWar == null || !configData.cobaltWar.enableTanks)
                return false;

            bool rockAware = manager.warSession != null && manager.warSession.IsRockBaseTerrain;
            float minRadius = Mathf.Max(30f, rockAware ? configData.cobaltWar.rockBaseTankSpawnRadiusMin : configData.cobaltWar.tankSpawnRadiusMin);
            float maxRadius = Mathf.Max(minRadius + 10f, rockAware ? configData.cobaltWar.rockBaseTankSpawnRadiusMax : configData.cobaltWar.tankSpawnRadiusMax);
            Vector3 target = GetTankTargetPosition(manager);
            float angleOffset = UnityEngine.Random.Range(0f, 360f) + (tankIndex * (rockAware ? 29f : 41f));
            int angleSteps = rockAware ? 36 : 28;
            float radiusStep = rockAware ? 6f : 5f;
            float occupiedTankDistanceSqr = 18f * 18f;

            List<Vector3> occupiedTankPositions = manager.tanks
                .Where(x => x != null && !x.IsDestroyed)
                .Select(x => x.transform.position)
                .ToList();

            BaseCombatEntity preferredObjective = manager.GetTankObjective(target, null);
            Vector3 preferredObjectivePoint = preferredObjective != null && !preferredObjective.IsDestroyed
                ? GetTankObjectivePoint(preferredObjective)
                : target;
            if (preferredObjectivePoint == Vector3.zero)
                preferredObjectivePoint = target;

            Vector3 bestDirect = Vector3.zero;
            Vector3 bestIndirect = Vector3.zero;
            float bestDirectScore = float.MaxValue;
            float bestIndirectScore = float.MaxValue;

            for (float radius = minRadius; radius <= maxRadius; radius += radiusStep)
            {
                for (int i = 0; i < angleSteps; i++)
                {
                    float angle = angleOffset + (360f / angleSteps) * i;
                    Vector3 candidate = manager.location + Quaternion.Euler(0f, angle, 0f) * Vector3.forward * radius;
                    candidate.y = manager.location.y;

                    Vector3 surfacePoint;
                    if (!TryGetGroundPoint(candidate, out surfacePoint, rockAware ? 42f : 30f, rockAware ? 140f : 100f))
                        continue;

                    if (!IsTankSpawnLocationSafe(surfacePoint))
                        continue;
                    if (occupiedTankPositions.Any(x => (x - surfacePoint).sqrMagnitude < occupiedTankDistanceSqr))
                        continue;

                    bool directFire = HasTankFireSolution(surfacePoint, preferredObjectivePoint, false);
                    bool indirectFire = rockAware && HasTankFireSolution(surfacePoint, preferredObjectivePoint, true);
                    if (!directFire && !indirectFire)
                        continue;

                    float slopePenalty = GetTerrainSlopeAngle(surfacePoint) * 2f;
                    float score = Mathf.Abs(Vector3.Distance(surfacePoint, manager.location) - ((minRadius + maxRadius) * 0.5f))
                        + (Mathf.Abs(surfacePoint.y - manager.location.y) * 0.35f)
                        + slopePenalty;

                    if (directFire)
                    {
                        if (score < bestDirectScore)
                        {
                            bestDirectScore = score;
                            bestDirect = surfacePoint;
                        }
                    }
                    else if (score < bestIndirectScore)
                    {
                        bestIndirectScore = score;
                        bestIndirect = surfacePoint;
                    }
                }
            }

            if (bestDirect != Vector3.zero)
            {
                spawn = bestDirect;
                indirectFireOnly = false;
                return true;
            }

            if (bestIndirect != Vector3.zero)
            {
                spawn = bestIndirect;
                indirectFireOnly = true;
                return true;
            }

            return false;
        }

        private BradleyAPC SpawnCobaltTank(EventRandomManager manager, int tankIndex)
        {
            if (manager == null || configData?.cobaltWar == null || !configData.cobaltWar.enableTanks)
                return null;

            Vector3 spawn;
            bool indirectFireOnly;
            if (!TryFindTankSpawn(manager, tankIndex, out spawn, out indirectFireOnly))
                return null;

            BradleyAPC tank = GameManager.server.CreateEntity("assets/prefabs/npc/m2bradley/bradleyapc.prefab", spawn) as BradleyAPC;
            if (tank == null)
                return null;

            tank.enableSaving = false;
            tank.OwnerID = 0;
            tank.Spawn();

            tank.maxCratesToSpawn = 0;
            tank.ScientistSpawnCount = 0;
            tank.searchRange = Mathf.Max(80f, configData.cobaltWar.tankAttackDistance + 25f);
            tank.viewDistance = Mathf.Max(80f, configData.cobaltWar.tankAttackDistance + 25f);
            tank.coaxBurstLength = 12;
            tank.coaxFireRate = 0.07f;
            tank.coaxAimCone = 2.6f;
            tank.bulletDamage = Mathf.Max(8f, configData.cobaltWar.tankCoaxDamage);
            tank._health = Mathf.Max(1000f, configData.cobaltWar.tankHealth);
            tank._maxHealth = tank._health;
            tank.globalBroadcast = true;
            tank.InitializeHealth(tank._health, tank._maxHealth);
            tank.health = tank._health;
            tank.SendNetworkUpdateImmediate();
            RegisterCobaltTank(tank);

            CobaltTankController controller = tank.gameObject.AddComponent<CobaltTankController>();
            controller.Initialize(this, manager, tank, spawn, indirectFireOnly, tankIndex);

            return tank;
        }

        private SaveMetabolism CaptureMetabolism(BasePlayer player)
        {
            PlayerMetabolism metabolism = player.metabolism;
            return new SaveMetabolism
            {
                bleeding = metabolism.bleeding.value,
                calories = metabolism.calories.value,
                caloriesMin = metabolism.calories.min,
                dirtyness = metabolism.dirtyness.value,
                health = player.health,
                heartrate = metabolism.heartrate.value,
                hydration = metabolism.hydration.value,
                hydrationMin = metabolism.hydration.min,
                oxygen = metabolism.oxygen.value,
                poison = metabolism.poison.value,
                radiationLevel = metabolism.radiation_level.value,
                radiationPoison = metabolism.radiation_poison.value,
                temperatureMin = metabolism.temperature.min,
                temperatureMax = metabolism.temperature.max,
                temperatureValue = metabolism.temperature.value,
                wetness = metabolism.wetness.value
            };
        }

        private void ApplyMetabolism(BasePlayer player, SaveMetabolism metabolism)
        {
            if (player == null || metabolism == null)
                return;

            player.SetHealth(metabolism.health);
            player.metabolism.bleeding.SetValue(metabolism.bleeding);
            player.metabolism.calories.SetValue(metabolism.calories);
            player.metabolism.calories.min = metabolism.caloriesMin;
            player.metabolism.dirtyness.SetValue(metabolism.dirtyness);
            player.metabolism.heartrate.SetValue(metabolism.heartrate);
            player.metabolism.hydration.min = metabolism.hydrationMin;
            player.metabolism.hydration.SetValue(metabolism.hydration);
            player.metabolism.oxygen.SetValue(metabolism.oxygen);
            player.metabolism.poison.SetValue(metabolism.poison);
            player.metabolism.radiation_level.SetValue(metabolism.radiationLevel);
            player.metabolism.radiation_poison.SetValue(metabolism.radiationPoison);
            player.metabolism.temperature.min = metabolism.temperatureMin;
            player.metabolism.temperature.max = metabolism.temperatureMax;
            player.metabolism.temperature.value = metabolism.temperatureValue;
            player.metabolism.wetness.SetValue(metabolism.wetness);
            player.SendNetworkUpdateImmediate();
        }

        private void CleanupSavedDefenderState(ulong userId)
        {
            ClearDefenderRespawnProtection(userId);
            ClearProtectedDefenderItems(userId);
            DefenderSnapshot snapshot;
            if (!defenderSnapshots.TryGetValue(userId, out snapshot) || snapshot == null || snapshot.saveman == 0UL)
                return;

            BasePlayer saveman = FindStoredSaveman(snapshot);
            if (saveman != null && !saveman.IsDestroyed)
            {
                snapshotSavemen.Remove(saveman.userID.Get());
                saveman.Kill();
            }
        }

        private BasePlayer FindStoredSaveman(ulong userId)
        {
            BasePlayer player = BasePlayer.FindByID(userId);
            if (player != null)
                return player;

            player = BasePlayer.sleepingPlayerList.FirstOrDefault(x => x != null && x.userID == userId);
            if (player != null)
                return player;

            return BasePlayer.FindBot(userId);
        }

        private BasePlayer FindStoredSaveman(DefenderSnapshot snapshot)
        {
            if (snapshot == null)
                return null;

            if (snapshot.savemanNetId != 0UL)
            {
                BasePlayer byNetId = FindEntity(snapshot.savemanNetId) as BasePlayer;
                if (byNetId != null && !byNetId.IsDestroyed)
                    return byNetId;
            }

            if (snapshot.saveman == 0UL)
                return null;

            return FindStoredSaveman(snapshot.saveman);
        }

        private List<SavedItemData> CaptureItemContainerSnapshot(ItemContainer container)
        {
            List<SavedItemData> snapshot = new List<SavedItemData>();
            if (container?.itemList == null)
                return snapshot;

            foreach (Item item in container.itemList.OrderBy(x => x.position).ToList())
            {
                SavedItemData itemData = CaptureItemSnapshot(item);
                if (itemData != null)
                    snapshot.Add(itemData);
            }

            return snapshot;
        }

        private SavedItemData CaptureItemSnapshot(Item item)
        {
            if (item?.info == null)
                return null;

            SavedItemData snapshot = new SavedItemData
            {
                shortname = item.info.shortname,
                amount = Mathf.Max(1, item.amount),
                position = item.position,
                skin = item.skin,
                condition = item.condition,
                text = item.text
            };

            if (item.instanceData != null)
            {
                snapshot.hasInstanceData = true;
                snapshot.instanceDataInt = item.instanceData.dataInt;
            }

            BaseProjectile projectile = item.GetHeldEntity() as BaseProjectile;
            if (projectile?.primaryMagazine != null)
            {
                snapshot.ammoCount = Mathf.Max(0, projectile.primaryMagazine.contents);
                snapshot.ammoShortname = projectile.primaryMagazine.ammoType?.shortname;
            }

            if (item.contents?.itemList != null && item.contents.itemList.Count > 0)
            {
                foreach (Item child in item.contents.itemList.OrderBy(x => x.position).ToList())
                {
                    SavedItemData childSnapshot = CaptureItemSnapshot(child);
                    if (childSnapshot != null)
                        snapshot.contents.Add(childSnapshot);
                }
            }

            return snapshot;
        }

        private bool HasSerializedSnapshotInventory(DefenderSnapshot snapshot)
        {
            return snapshot != null
                && snapshot.beltItems != null
                && snapshot.mainItems != null
                && snapshot.wearItems != null;
        }

        private void RestoreSerializedWeaponMagazine(Item item, SavedItemData snapshot)
        {
            if (item == null || snapshot == null || snapshot.ammoCount < 0)
                return;

            if (item.instanceData == null)
            {
                item.instanceData = new ProtoBuf.Item.InstanceData();
                item.instanceData.ShouldPool = false;
            }

            item.instanceData.dataInt = snapshot.ammoCount;

            BaseProjectile projectile = item.GetHeldEntity() as BaseProjectile;
            if (projectile?.primaryMagazine != null)
            {
                if (!string.IsNullOrEmpty(snapshot.ammoShortname))
                {
                    ItemDefinition ammoDef = ItemManager.FindItemDefinition(snapshot.ammoShortname);
                    if (ammoDef != null)
                        projectile.primaryMagazine.ammoType = ammoDef;
                }

                projectile.primaryMagazine.contents = Mathf.Max(0, snapshot.ammoCount);
                projectile.SendNetworkUpdateImmediate();
            }

            item.MarkDirty();
        }

        private bool RestoreSerializedItemContents(Item parent, List<SavedItemData> contents)
        {
            if (parent == null || contents == null || contents.Count <= 0)
                return true;

            if (parent.contents == null)
            {
                parent.contents = new ItemContainer();
                parent.contents.ServerInitialize(null, Mathf.Max(1, contents.Count));
                parent.contents.GiveUID();
                parent.contents.parent = parent;
            }

            bool restoredAll = true;
            foreach (SavedItemData child in contents.OrderBy(x => x.position))
                restoredAll &= RestoreSerializedItemToContainer(parent.contents, child);

            parent.MarkDirty();
            return restoredAll;
        }

        private bool RestoreSerializedItemToContainer(ItemContainer container, SavedItemData snapshot)
        {
            if (container == null || snapshot == null || string.IsNullOrEmpty(snapshot.shortname) || snapshot.amount <= 0)
                return false;

            Item item = ItemManager.CreateByName(snapshot.shortname, Mathf.Max(1, snapshot.amount), snapshot.skin);
            if (item == null)
                return false;

            if (snapshot.hasInstanceData || snapshot.ammoCount >= 0)
            {
                if (item.instanceData == null)
                {
                    item.instanceData = new ProtoBuf.Item.InstanceData();
                    item.instanceData.ShouldPool = false;
                }

                if (snapshot.hasInstanceData)
                    item.instanceData.dataInt = snapshot.instanceDataInt;
            }

            if (!string.IsNullOrEmpty(snapshot.text))
                item.text = snapshot.text;

            if (item.hasCondition)
                item.condition = Mathf.Clamp(snapshot.condition, 0f, item.maxCondition);

            bool moved = snapshot.position >= 0
                ? item.MoveToContainer(container, snapshot.position, true)
                : item.MoveToContainer(container, -1, true);

            if (!moved)
                moved = item.MoveToContainer(container, allowStack: false, ignoreStackLimit: true);

            if (!moved)
            {
                item.Remove();
                return false;
            }

            if (!RestoreSerializedItemContents(item, snapshot.contents))
            {
                item.Remove();
                return false;
            }

            RestoreSerializedWeaponMagazine(item, snapshot);
            item.MarkDirty();
            return true;
        }

        private bool RestoreSerializedContainerSnapshot(ItemContainer container, List<SavedItemData> items)
        {
            if (container == null)
                return false;

            if (items == null || items.Count <= 0)
                return true;

            bool restoredAll = true;
            foreach (SavedItemData item in items.OrderBy(x => x.position))
                restoredAll &= RestoreSerializedItemToContainer(container, item);

            container.OnChanged();
            return restoredAll;
        }

        private bool RestoreSerializedInventorySnapshot(BasePlayer player, DefenderSnapshot snapshot)
        {
            if (player?.inventory == null || snapshot == null || !HasSerializedSnapshotInventory(snapshot))
                return false;

            ForceClearRestoreInventory(player);

            bool wearRestored = RestoreSerializedContainerSnapshot(player.inventory.containerWear, snapshot.wearItems);
            bool beltRestored = RestoreSerializedContainerSnapshot(player.inventory.containerBelt, snapshot.beltItems);
            bool mainRestored = RestoreSerializedContainerSnapshot(player.inventory.containerMain, snapshot.mainItems);

            player.inventory.containerWear?.OnChanged();
            player.inventory.containerBelt?.OnChanged();
            player.inventory.containerMain?.OnChanged();
            player.SendNetworkUpdateImmediate();
            return wearRestored && beltRestored && mainRestored;
        }

        private void StripInventory(BasePlayer player)
        {
            if (player == null || player.inventory == null)
                return;

            List<Item> allItems = Pool.Get<List<Item>>();
            player.inventory.GetAllItems(allItems);
            for (int i = allItems.Count - 1; i >= 0; i--)
            {
                Item item = allItems[i];
                item.RemoveFromContainer();
                item.Remove();
            }
            Pool.FreeUnmanaged(ref allItems);
        }

        private void ForceClearRestoreInventory(BasePlayer player)
        {
            if (player == null || player.inventory == null)
                return;

            ClearProtectedDefenderItems(player.userID);
            StripInventory(player);

            player.inventory.containerWear?.OnChanged();
            player.inventory.containerBelt?.OnChanged();
            player.inventory.containerMain?.OnChanged();
            player.SendNetworkUpdateImmediate();
        }

        private bool TryMoveRestoredItemToContainer(Item item, ItemContainer container)
        {
            if (item == null || container == null)
                return false;

            int targetPosition = item.position;
            if (targetPosition >= 0 && item.MoveToContainer(container, targetPosition, false, true))
                return true;

            if (item.MoveToContainer(container, -1, false, true))
                return true;

            return item.MoveToContainer(container, allowStack: false, ignoreStackLimit: true);
        }

        private bool RestoreInventoryFromSaveman(BasePlayer player, BasePlayer saveman)
        {
            if (player?.inventory == null || saveman?.inventory == null)
                return false;

            ForceClearRestoreInventory(player);

            bool restoredAll = true;

            foreach (Item item in saveman.inventory.containerWear.itemList.ToList())
                restoredAll &= TryMoveRestoredItemToContainer(item, player.inventory.containerWear);

            foreach (Item item in saveman.inventory.containerBelt.itemList.ToList())
                restoredAll &= TryMoveRestoredItemToContainer(item, player.inventory.containerBelt);

            foreach (Item item in saveman.inventory.containerMain.itemList.ToList())
                restoredAll &= TryMoveRestoredItemToContainer(item, player.inventory.containerMain);

            bool savemanDrained = saveman.inventory.containerWear.itemList.Count == 0
                && saveman.inventory.containerBelt.itemList.Count == 0
                && saveman.inventory.containerMain.itemList.Count == 0;

            player.inventory.containerWear?.OnChanged();
            player.inventory.containerBelt?.OnChanged();
            player.inventory.containerMain?.OnChanged();
            player.SendNetworkUpdateImmediate();

            return restoredAll && savemanDrained;
        }

        private void StartSleeping(BasePlayer player)
        {
            if (player == null || player.IsSleeping())
                return;

            player.SetPlayerFlag(BasePlayer.PlayerFlags.Sleeping, true);
            if (!BasePlayer.sleepingPlayerList.Contains(player))
                BasePlayer.sleepingPlayerList.Add(player);
            player.CancelInvoke("InventoryUpdate");
        }

        private bool IsFinitePosition(Vector3 position)
        {
            return !float.IsNaN(position.x) && !float.IsNaN(position.y) && !float.IsNaN(position.z)
                && !float.IsInfinity(position.x) && !float.IsInfinity(position.y) && !float.IsInfinity(position.z);
        }

        private void FinishTeleportLoading(BasePlayer player, Vector3 position, string reason)
        {
            if (player == null || !player.IsConnected)
                return;

            try
            {
                if (player.HasPlayerFlag(BasePlayer.PlayerFlags.ReceivingSnapshot))
                    player.SetPlayerFlag(BasePlayer.PlayerFlags.ReceivingSnapshot, false);
            }
            catch { }

            try
            {
                if (player.IsSleeping())
                    player.EndSleeping();
            }
            catch
            {
                try
                {
                    player.SetPlayerFlag(BasePlayer.PlayerFlags.Sleeping, false);
                    BasePlayer.sleepingPlayerList.Remove(player);
                }
                catch { }
            }

            try
            {
                player.UpdateNetworkGroup();
                player.SendNetworkUpdateImmediate();
            }
            catch { }

            CobaltDiagnosticLog("raid", $"Teleport finish: player={player.displayName}({player.userID}), reason={reason}, pos={position.x:0.##},{position.y:0.##},{position.z:0.##}.");
        }

        private void ScheduleTeleportFinishSafety(BasePlayer player, Vector3 position, string reason)
        {
            if (player == null)
                return;

            timer.Once(0.35f, () => FinishTeleportLoading(player, position, reason));
            timer.Once(1.25f, () => FinishTeleportLoading(player, position, reason));
            timer.Once(3.0f, () => FinishTeleportLoading(player, position, reason));
        }

        private void TeleportPlayer(BasePlayer player, Vector3 position)
        {
            if (player == null)
                return;

            if (!IsFinitePosition(position))
            {
                CobaltDiagnosticLog("raid", $"Teleport skipped: invalid position for player={player.displayName}({player.userID}), pos={position}.");
                return;
            }

            Vector3 safePosition = position + Vector3.up * 0.12f;

            StopPlayerSpectating(player);
            CobaltDiagnosticLog("raid", $"Teleport begin: player={player.displayName}({player.userID}), from={player.transform.position.x:0.##},{player.transform.position.y:0.##},{player.transform.position.z:0.##}, to={safePosition.x:0.##},{safePosition.y:0.##},{safePosition.z:0.##}.");

            try
            {
                player.Teleport(safePosition);
            }
            catch
            {
                try
                {
                    player.MovePosition(safePosition);
                    if (player.net?.connection != null)
                        player.ClientRPCPlayer(null, player, "ForcePositionTo", safePosition);
                    player.UpdateNetworkGroup();
                    player.SendNetworkUpdateImmediate();
                }
                catch
                {
                    CobaltDiagnosticLog("raid", $"Teleport failed: player={player.displayName}({player.userID}), pos={safePosition.x:0.##},{safePosition.y:0.##},{safePosition.z:0.##}.");
                    return;
                }
            }

            if (player.net?.connection != null)
                ScheduleTeleportFinishSafety(player, safePosition, "cobalt");
        }

        private bool CaptureDefenderSnapshot(BasePlayer player, int warId)
        {
            if (player == null)
                return false;

            EnsurePlayerDataStructures();
            CleanupSavedDefenderState(player.userID);

            List<SavedItemData> beltSnapshot = CaptureItemContainerSnapshot(player.inventory?.containerBelt);
            List<SavedItemData> mainSnapshot = CaptureItemContainerSnapshot(player.inventory?.containerMain);
            List<SavedItemData> wearSnapshot = CaptureItemContainerSnapshot(player.inventory?.containerWear);

            ulong savemanUserId = 0UL;
            BasePlayer saveman = GameManager.server.CreateEntity("assets/prefabs/player/player.prefab", new Vector3(1999f, 400f, 1999f)) as BasePlayer;
            if (saveman == null)
            {
                PrintWarning($"[CobaltWar] Не удалось создать snapshot carrier для {player.displayName} ({player.userID}). Выдача защитного набора отменена.");
                return false;
            }

            saveman.enableSaving = true;
            saveman.Spawn();
            StartSleeping(saveman);
            snapshotSavemen.Add(saveman.userID.Get());
            savemanUserId = saveman.userID;
            StripInventory(saveman);
            foreach (Item item in player.inventory.containerBelt.itemList.ToList())
                item.MoveToContainer(saveman.inventory.containerBelt, item.position, false, true);
            foreach (Item item in player.inventory.containerMain.itemList.ToList())
                item.MoveToContainer(saveman.inventory.containerMain, item.position, false, true);
            foreach (Item item in player.inventory.containerWear.itemList.ToList())
                item.MoveToContainer(saveman.inventory.containerWear, item.position, false, true);
            saveman.SendNetworkUpdateImmediate();

            defenderSnapshots[player.userID] = new DefenderSnapshot
            {
                saveman = savemanUserId,
                savemanNetId = saveman != null && saveman.net != null ? saveman.net.ID.Value : 0UL,
                position = player.transform.position,
                metabolism = CaptureMetabolism(player),
                buffsDisabled = configData.cobaltWar.disableSkillTreeBuffs && SkillTree != null,
                warId = warId,
                beltItems = beltSnapshot,
                mainItems = mainSnapshot,
                wearItems = wearSnapshot
            };
            pcdData.defenderSnapshots[player.userID] = defenderSnapshots[player.userID];
            SaveData();

            if (configData.cobaltWar.disableSkillTreeBuffs && SkillTree != null)
            {
                CobaltDiagnosticLog("idle", $"SkillTree DisableBuffs: player={player.displayName}({player.userID}), warId={warId}.");
                TraceExternalPluginCall("external", SkillTree, "DisableBuffs", player.userID.Get());
            }

            return true;
        }

        private IEnumerable<ulong> GetSnapshotUsersForWar(int warId)
        {
            EnsurePlayerDataStructures();

            foreach (var entry in defenderSnapshots)
            {
                if (entry.Value != null && entry.Value.warId == warId)
                    yield return entry.Key;
            }

            if (pcdData == null || pcdData.defenderSnapshots == null)
                yield break;

            foreach (var entry in pcdData.defenderSnapshots)
            {
                if (entry.Value != null && entry.Value.warId == warId)
                    yield return entry.Key;
            }
        }

        private bool TryGetDefenderSnapshot(ulong userId, out DefenderSnapshot snapshot)
        {
            EnsurePlayerDataStructures();

            if (defenderSnapshots.TryGetValue(userId, out snapshot) && snapshot != null)
                return true;

            if (pcdData != null && pcdData.defenderSnapshots != null && pcdData.defenderSnapshots.TryGetValue(userId, out snapshot) && snapshot != null)
            {
                defenderSnapshots[userId] = snapshot;
                return true;
            }

            snapshot = null;
            return false;
        }

        private bool TryGetDisconnectedRaidBackup(ulong userId, out DisconnectedRaidBackup backup)
        {
            EnsurePlayerDataStructures();

            if (pcdData != null && pcdData.disconnectRaidBackups != null && pcdData.disconnectRaidBackups.TryGetValue(userId, out backup) && backup != null)
                return true;

            backup = null;
            return false;
        }

        private void RemoveDisconnectedRaidBackup(ulong userId, bool saveData = true)
        {
            EnsurePlayerDataStructures();

            if (pcdData?.disconnectRaidBackups == null)
                return;

            if (!pcdData.disconnectRaidBackups.Remove(userId))
                return;

            if (saveData)
                SaveData();
        }

        private bool HasSerializedSnapshotInventory(DisconnectedRaidBackup backup)
        {
            return backup != null
                && backup.beltItems != null
                && backup.mainItems != null
                && backup.wearItems != null;
        }

        private bool RestoreSerializedInventorySnapshot(BasePlayer player, DisconnectedRaidBackup backup)
        {
            if (player?.inventory == null || backup == null || !HasSerializedSnapshotInventory(backup))
                return false;

            ForceClearRestoreInventory(player);

            bool wearRestored = RestoreSerializedContainerSnapshot(player.inventory.containerWear, backup.wearItems);
            bool beltRestored = RestoreSerializedContainerSnapshot(player.inventory.containerBelt, backup.beltItems);
            bool mainRestored = RestoreSerializedContainerSnapshot(player.inventory.containerMain, backup.mainItems);

            player.inventory.containerWear?.OnChanged();
            player.inventory.containerBelt?.OnChanged();
            player.inventory.containerMain?.OnChanged();
            player.SendNetworkUpdateImmediate();
            return wearRestored && beltRestored && mainRestored;
        }

        private bool CaptureDisconnectedRaidBackup(BasePlayer player, int warId, bool buffsDisabled)
        {
            if (player == null)
                return false;

            EnsurePlayerDataStructures();

            pcdData.disconnectRaidBackups[player.userID.Get()] = new DisconnectedRaidBackup
            {
                position = player.transform.position,
                metabolism = CaptureMetabolism(player),
                buffsDisabled = buffsDisabled,
                warId = warId,
                capturedAt = DateTime.UtcNow,
                beltItems = CaptureItemContainerSnapshot(player.inventory?.containerBelt),
                mainItems = CaptureItemContainerSnapshot(player.inventory?.containerMain),
                wearItems = CaptureItemContainerSnapshot(player.inventory?.containerWear)
            };

            SaveData();
            return true;
        }

        private bool TryResolveDisconnectedRaidReturnPosition(CobaltWarSession war, Vector3 requestedPosition, out Vector3 resolvedPosition)
        {
            resolvedPosition = Vector3.zero;

            bool rockAware = war != null && war.IsRockBaseTerrain;
            float rayHeight = rockAware ? 54f : 34f;
            float rayDistance = rockAware ? 180f : 130f;
            float navSearchDistance = rockAware ? 16f : 10f;

            Vector3 surfacePoint;
            if (TryGetGroundPoint(requestedPosition, out surfacePoint, rayHeight, rayDistance))
            {
                Vector3 candidate = surfacePoint;
                Vector3 navPoint;
                if (TrySampleNavMesh(surfacePoint, navSearchDistance, out navPoint) && ShouldUseNavMeshSpawnPoint(surfacePoint, navPoint, rockAware))
                    candidate = navPoint;

                if (IsSpawnLocationSafe(candidate, rockAware) && (war == null || war.IsInsideCombatArea(candidate)))
                {
                    resolvedPosition = candidate;
                    return true;
                }

                if (candidate != surfacePoint && IsSpawnLocationSafe(surfacePoint, rockAware) && (war == null || war.IsInsideCombatArea(surfacePoint)))
                {
                    resolvedPosition = surfacePoint;
                    return true;
                }
            }

            if (war != null)
            {
                Vector3 fallbackSpawn;
                if (TryFindDefenderSpawn(war, out fallbackSpawn))
                {
                    resolvedPosition = fallbackSpawn;
                    return true;
                }
            }

            return false;
        }

        private bool TryPreparePlayerForDisconnectedRaidBackupRestore(BasePlayer player, DisconnectedRaidBackup backup, bool respawnIfDead)
        {
            return TryPreparePlayerForDisconnectedRaidBackupRestore(player, backup, respawnIfDead, backup != null ? backup.position : Vector3.zero);
        }

        private bool TryPreparePlayerForDisconnectedRaidBackupRestore(BasePlayer player, DisconnectedRaidBackup backup, bool respawnIfDead, Vector3 restorePosition)
        {
            if (player == null || !player.IsConnected || backup == null)
                return false;

            if (player.IsWounded())
                player.StopWounded();

            if (player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
                StopPlayerSpectating(player);

            if (respawnIfDead && player.IsDead())
            {
                try
                {
                    player.RespawnAt(restorePosition, Quaternion.identity);
                }
                catch
                {
                    return false;
                }

                return false;
            }

            if (player.IsDead() || player.IsWounded() || player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating) || player.IsSleeping())
                return false;

            return true;
        }

        private IEnumerator RestoreDisconnectedRaidBackup(BasePlayer player)
        {
            if (player == null)
                yield break;

            EnsurePlayerDataStructures();

            for (int i = 0; i < 25; i++)
            {
                if (player == null || !player.IsConnected)
                    yield break;

                DisconnectedRaidBackup waitBackup;
                if (!TryGetDisconnectedRaidBackup(player.userID.Get(), out waitBackup) || waitBackup == null)
                    yield break;

                if (TryPreparePlayerForDisconnectedRaidBackupRestore(player, waitBackup, true))
                    break;

                yield return CoroutineEx.waitForSeconds(0.2f);
            }

            if (player == null || !player.IsConnected)
                yield break;

            RestoreDisconnectedRaidBackupNow(player);
        }

        private bool RestoreDisconnectedRaidBackupNow(BasePlayer player)
        {
            if (player == null)
                return false;

            EnsurePlayerDataStructures();

            DisconnectedRaidBackup backup;
            if (!TryGetDisconnectedRaidBackup(player.userID.Get(), out backup) || backup == null)
                return false;

            Vector3 restorePosition;
            if (!TryResolveDisconnectedRaidReturnPosition(null, backup.position, out restorePosition))
            {
                CobaltDiagnosticLog("idle", $"Disconnect backup restore failed: safe restore position not found, player={player.displayName}({player.userID}), warId={backup.warId}.");
                return false;
            }

            if (!TryPreparePlayerForDisconnectedRaidBackupRestore(player, backup, false, restorePosition))
                return false;

            TeleportPlayer(player, restorePosition);

            if (!RestoreSerializedInventorySnapshot(player, backup))
            {
                PrintWarning($"[CobaltWar] Disconnect backup restore failed for {player.displayName} ({player.userID}).");
                return false;
            }

            ApplyMetabolism(player, backup.metabolism);
            if (backup.buffsDisabled && SkillTree != null)
            {
                CobaltDiagnosticLog("idle", $"SkillTree EnableBuffs: player={player.displayName}({player.userID}), warId={backup.warId}, source=disconnectBackup.");
                TraceExternalPluginCall("external", SkillTree, "EnableBuffs", player.userID.Get());
            }

            CleanupSavedDefenderState(player.userID.Get());
            pendingRedeploys.Remove(player.userID.Get());
            defenderSnapshots.Remove(player.userID.Get());
            if (pcdData?.defenderSnapshots != null)
                pcdData.defenderSnapshots.Remove(player.userID.Get());
            RemoveDisconnectedRaidBackup(player.userID.Get(), false);
            SaveData();
            ClearDefenderActivity(player.userID);
            ClearDefenderRespawnProtection(player.userID);
            CuiHelper.DestroyUi(player, JoinUiName);
            return true;
        }

        private bool TryRestoreDisconnectedRaidRecovery(BasePlayer player)
        {
            if (player == null)
                return false;

            CobaltWarSession returnableWar = FindWarByUiRegisteredPlayer(player.userID.Get());
            if (returnableWar != null && returnableWar.CanReturnDefender(player.userID.Get()))
                return false;

            DisconnectedRaidBackup backup;
            if (!TryGetDisconnectedRaidBackup(player.userID.Get(), out backup) || backup == null)
                return false;

            DefenderSnapshot snapshot;
            bool hasSnapshot = TryGetDefenderSnapshot(player.userID.Get(), out snapshot) && snapshot != null;

            if (hasSnapshot && HasActiveWarForSnapshot(snapshot))
                return false;

            if (hasSnapshot)
            {
                defenderSnapshots[player.userID.Get()] = snapshot;
                ServerMgr.Instance.StartCoroutine(RestoreDefenderSnapshot(player));
                return true;
            }

            ServerMgr.Instance.StartCoroutine(RestoreDisconnectedRaidBackup(player));
            return true;
        }

        private IEnumerator RestoreDisconnectedRaidLoadoutForReturn(CobaltWarSession war, BasePlayer player)
        {
            if (war == null || player == null)
                yield break;

            ulong userId = player.userID.Get();
            DisconnectedRaidBackup backup;
            if (!TryGetDisconnectedRaidBackup(userId, out backup) || backup == null || backup.warId != war.warId)
                yield break;

            bool prepared = false;
            Vector3 preparedReturnPosition = Vector3.zero;
            for (int i = 0; i < 25; i++)
            {
                if (war == null || war.IsEnded || player == null || !player.IsConnected)
                    yield break;

                if (!TryGetDisconnectedRaidBackup(userId, out backup) || backup == null || backup.warId != war.warId)
                    yield break;

                Vector3 safeReturnPosition;
                if (!TryResolveDisconnectedRaidReturnPosition(war, backup.position, out safeReturnPosition))
                {
                    yield return CoroutineEx.waitForSeconds(0.15f);
                    continue;
                }

                if (TryPreparePlayerForDisconnectedRaidBackupRestore(player, backup, true, safeReturnPosition))
                {
                    prepared = true;
                    preparedReturnPosition = safeReturnPosition;
                    break;
                }

                yield return CoroutineEx.waitForSeconds(0.15f);
            }

            if (war == null || war.IsEnded || player == null || !player.IsConnected)
                yield break;

            if (!TryGetDisconnectedRaidBackup(userId, out backup) || backup == null || backup.warId != war.warId)
            {
                if (war.IsRegisteredDefender(userId))
                    PrepareRegisteredDefender(war, player, false);
                yield break;
            }

            if (!prepared || !RestoreDisconnectedRaidLoadoutForReturnNow(war, player, backup, preparedReturnPosition))
            {
                if (war.IsRegisteredDefender(userId))
                    PrepareRegisteredDefender(war, player, false);
            }
        }

        private bool RestoreDisconnectedRaidLoadoutForReturnNow(CobaltWarSession war, BasePlayer player, DisconnectedRaidBackup backup, Vector3 preparedReturnPosition = default(Vector3))
        {
            if (war == null || war.IsEnded || player == null || !player.IsConnected || backup == null)
                return false;

            Vector3 restorePosition = preparedReturnPosition;
            if (restorePosition == Vector3.zero && !TryResolveDisconnectedRaidReturnPosition(war, backup.position, out restorePosition))
            {
                CobaltDiagnosticLog("idle", $"Return defender failed: safe return position not found, player={player.displayName}({player.userID}), warId={war.warId}.");
                return false;
            }

            if (!TryPreparePlayerForDisconnectedRaidBackupRestore(player, backup, false, restorePosition))
                return false;

            TeleportPlayer(player, restorePosition);

            if (!RestoreSerializedInventorySnapshot(player, backup))
            {
                PrintWarning($"[CobaltWar] Return restore from disconnect backup failed for {player.displayName} ({player.userID}) in war {war.warId}.");
                return false;
            }

            ApplyMetabolism(player, backup.metabolism);
            if (backup.buffsDisabled && SkillTree != null)
            {
                CobaltDiagnosticLog("idle", $"SkillTree DisableBuffs: player={player.displayName}({player.userID}), warId={war.warId}, source=disconnectReturn.");
                TraceExternalPluginCall("external", SkillTree, "DisableBuffs", player.userID.Get());
            }
            if (war.IsRegisteredDefender(player.userID.Get()))
                TrackProtectedDefenderInventory(player, war.warId);
            ScheduleDefenderHotbarNormalization(player);
            pendingRedeploys.Remove(player.userID.Get());
            RemoveDisconnectedRaidBackup(player.userID.Get(), false);
            SaveData();
            ClearDefenderRespawnProtection(player.userID);
            TouchDefenderActivity(player, true);
            QueueCombatRespawnLocationAudit(player);
            SendReply(player, lang.GetMessage("CobaltReturnSuccess", this, player.UserIDString), war.targetName, GetGrid(war.location));
            return true;
        }

        private bool TryRestoreDisconnectedRaidLoadoutForReturn(CobaltWarSession war, BasePlayer player)
        {
            if (war == null || player == null)
                return false;

            DisconnectedRaidBackup backup;
            if (!TryGetDisconnectedRaidBackup(player.userID.Get(), out backup) || backup == null || backup.warId != war.warId)
                return false;

            ServerMgr.Instance.StartCoroutine(RestoreDisconnectedRaidLoadoutForReturn(war, player));
            return true;
        }

        private bool TryPreparePlayerForDefenderRestore(BasePlayer player, bool respawnIfDead)
        {
            if (player == null || !player.IsConnected)
                return false;

            DefenderSnapshot snapshot;
            TryGetDefenderSnapshot(player.userID, out snapshot);

            if (player.IsWounded())
                player.StopWounded();

            if (player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
                StopPlayerSpectating(player);

            if (respawnIfDead && player.IsDead() && snapshot != null)
            {
                try
                {
                    player.RespawnAt(snapshot.position, Quaternion.identity);
                }
                catch
                {
                    return false;
                }

                return false;
            }

            if (player.IsDead() || player.IsWounded() || player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating) || player.IsSleeping())
                return false;

            return true;
        }

        private IEnumerator RestoreDefenderSnapshot(BasePlayer player)
        {
            if (player == null)
                yield break;

            EnsurePlayerDataStructures();

            for (int i = 0; i < 25; i++)
            {
                if (player == null || !player.IsConnected)
                    yield break;

                if (TryPreparePlayerForDefenderRestore(player, true))
                    break;

                yield return CoroutineEx.waitForSeconds(0.15f);
            }

            if (player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
            {
                StopPlayerSpectating(player);

                for (int i = 0; i < 30; i++)
                {
                    if (player == null || !player.IsConnected)
                        yield break;

                    if (!player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
                        break;

                    if (i == 10 || i == 20)
                    {
                        try
                        {
                            player.StopSpectating();
                        }
                        catch { }
                    }

                    yield return CoroutineEx.waitForSeconds(0.1f);
                }

                if (player != null && player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
                {
                    try
                    {
                        player.SetPlayerFlag(BasePlayer.PlayerFlags.Spectating, false);
                        player.UpdateNetworkGroup();
                        player.SendNetworkUpdateImmediate();
                    }
                    catch { }

                    yield return CoroutineEx.waitForSeconds(0.15f);
                }
            }

            for (int i = 0; i < 20; i++)
            {
                if (player == null || !player.IsConnected)
                    yield break;

                if (player.IsWounded())
                    player.StopWounded();

                if (player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
                {
                    StopPlayerSpectating(player);
                    yield return CoroutineEx.waitForSeconds(0.1f);
                    continue;
                }

                if (!player.IsSleeping())
                    break;

                yield return CoroutineEx.waitForSeconds(0.25f);
            }

            if (player == null || !player.IsConnected)
                yield break;

            if (!TryPreparePlayerForDefenderRestore(player, false))
            {
                timer.Once(0.5f, () =>
                {
                    if (_ == null || player == null || !player.IsConnected)
                        return;

                    if (!defenderSnapshots.ContainsKey(player.userID) && (pcdData == null || pcdData.defenderSnapshots == null || !pcdData.defenderSnapshots.ContainsKey(player.userID)))
                        return;

                    ServerMgr.Instance.StartCoroutine(RestoreDefenderSnapshot(player));
                });
                yield break;
            }

            if (player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
            {
                timer.Once(0.5f, () =>
                {
                    if (_ == null || player == null || !player.IsConnected)
                        return;

                    if (!defenderSnapshots.ContainsKey(player.userID))
                        return;

                    ServerMgr.Instance.StartCoroutine(RestoreDefenderSnapshot(player));
                });
                yield break;
            }

            RestoreDefenderSnapshotNow(player);
        }

        private bool RestoreDefenderSnapshotNow(BasePlayer player)
        {
            if (player == null)
                return false;

            EnsurePlayerDataStructures();

            DefenderSnapshot snapshot;
            if (!defenderSnapshots.TryGetValue(player.userID, out snapshot) || snapshot == null)
                return false;

            BasePlayer saveman = FindStoredSaveman(snapshot);
            bool canUseSerializedRestore = HasSerializedSnapshotInventory(snapshot);
            if (snapshot.saveman != 0UL && saveman == null && !canUseSerializedRestore)
            {
                PrintWarning($"[CobaltWar] Snapshot carrier missing for {player.displayName} ({player.userID}). Original inventory restore was postponed to avoid silent loss.");
                return false;
            }

            if (player.IsWounded())
                player.StopWounded();

            if (player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
            {
                StopPlayerSpectating(player);

                if (player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
                {
                    try
                    {
                        player.StopSpectating();
                    }
                    catch { }
                }

                if (player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
                {
                    try
                    {
                        player.SetPlayerFlag(BasePlayer.PlayerFlags.Spectating, false);
                        player.UpdateNetworkGroup();
                        player.SendNetworkUpdateImmediate();
                    }
                    catch { }
                }
            }

            if (player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
                return false;

            StopPlayerSpectating(player);
            TeleportPlayer(player, snapshot.position);

            if (saveman != null)
            {
                bool restoredFromSaveman = RestoreInventoryFromSaveman(player, saveman);
                snapshotSavemen.Remove(saveman.userID.Get());
                saveman.Kill();

                if (!restoredFromSaveman)
                {
                    PrintWarning($"[CobaltWar] Direct snapshot carrier restore was incomplete for {player.displayName} ({player.userID}). Falling back to serialized snapshot.");

                    if (!RestoreSerializedInventorySnapshot(player, snapshot))
                    {
                        PrintWarning($"[CobaltWar] Serialized fallback restore failed for {player.displayName} ({player.userID}). Trying disconnect backup.");
                        if (!RestoreDisconnectedRaidBackupNow(player))
                            return false;
                        return true;
                    }
                }
            }
            else
            {
                if (!RestoreSerializedInventorySnapshot(player, snapshot))
                {
                    PrintWarning($"[CobaltWar] Serialized snapshot restore failed for {player.displayName} ({player.userID}). Trying disconnect backup.");
                    if (!RestoreDisconnectedRaidBackupNow(player))
                        return false;
                    return true;
                }
            }

            ApplyMetabolism(player, snapshot.metabolism);
            if (snapshot.buffsDisabled && SkillTree != null)
            {
                CobaltDiagnosticLog("idle", $"SkillTree EnableBuffs: player={player.displayName}({player.userID}), warId={snapshot.warId}.");
                TraceExternalPluginCall("external", SkillTree, "EnableBuffs", player.userID.Get());
            }

            ReplayPendingRouletteItemRewards(player);

            pendingRedeploys.Remove(player.userID);
            defenderSnapshots.Remove(player.userID);
            pcdData.defenderSnapshots.Remove(player.userID);
            RemoveDisconnectedRaidBackup(player.userID.Get(), false);
            SaveData();
            ClearDefenderActivity(player.userID);
            ClearDefenderRespawnProtection(player.userID);
            CuiHelper.DestroyUi(player, JoinUiName);
            return true;
        }

        private void OnServerSave()
        {
            bool hasPersistentCombatState = activeCobaltWars.Count > 0
                || pendingRedeploys.Count > 0
                || defenderSnapshots.Count > 0
                || (pcdData?.deferredXpDamage != null && pcdData.deferredXpDamage.Count > 0)
                || (pcdData?.deferredXpRewards != null && pcdData.deferredXpRewards.Count > 0)
                || (pcdData?.defenderSnapshots != null && pcdData.defenderSnapshots.Count > 0);
            double now = GrabCurrentTime();
            double idleSaveIntervalSeconds = 300d;

            if (!hasPersistentCombatState && lastIdleFullSaveAt > 0d && now - lastIdleFullSaveAt < idleSaveIntervalSeconds)
            {
                if (now - lastIdleSaveSkipLogAt >= 60d)
                {
                    lastIdleSaveSkipLogAt = now;
                    CobaltDiagnosticLog("idle", $"OnServerSave skipped: no combat state, nextFullSaveIn={Math.Ceiling(idleSaveIntervalSeconds - (now - lastIdleFullSaveAt))}s.");
                }
                return;
            }

            lastIdleFullSaveAt = now;
            double saveStartedAt = GrabCurrentTime();
            CobaltDiagnosticLog("idle", $"OnServerSave begin: activeWars={activeCobaltWars.Count}, pendingRedeploys={pendingRedeploys.Count}, defenderSnapshots={defenderSnapshots.Count}, tcData={pcdData?.tcData?.Count ?? 0}, persistentCombatState={hasPersistentCombatState}.");
            SaveData();
            SaveRaidData();
            SaveLogData();
            SaveRBLogData();
            CobaltDiagnosticLog("idle", $"OnServerSave end: elapsed={(GrabCurrentTime() - saveStartedAt):0.###}s.");
        }

        private void TryRestoreDeferredPlayer(BasePlayer player)
        {
            if (player == null || FindWarByRegisteredPlayer(player.userID) != null)
                return;

            DefenderSnapshot persistedSnapshot;
            if (!TryGetDefenderSnapshot(player.userID, out persistedSnapshot) || persistedSnapshot == null)
                return;

            if (!HasActiveWarForSnapshot(persistedSnapshot))
                return;

            defenderSnapshots[player.userID] = persistedSnapshot;
            ServerMgr.Instance.StartCoroutine(RestoreDefenderSnapshot(player));
        }

        private bool TryRestoreDisconnectedDefenderSnapshot(ulong userId)
        {
            if (userId == 0UL)
                return false;

            EnsurePlayerDataStructures();

            DefenderSnapshot snapshot;
            if (!TryGetDefenderSnapshot(userId, out snapshot) || snapshot == null)
                return false;

            BasePlayer player = BasePlayer.FindSleeping(userId);
            if (player == null || player.IsConnected)
                return false;

            if (player.IsWounded())
                player.StopWounded();

            if (player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
            {
                StopPlayerSpectating(player);

                if (player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
                {
                    try
                    {
                        player.StopSpectating();
                    }
                    catch { }
                }
            }

            if (player.IsDead())
            {
                try
                {
                    player.RespawnAt(snapshot.position, Quaternion.identity);
                }
                catch
                {
                    return false;
                }

                if (player.IsDead())
                    return false;
            }

            return RestoreDefenderSnapshotNow(player);
        }

        private void HandleRegisteredDefenderDisconnect(BasePlayer player)
        {
            if (player == null)
                return;

            ulong userId = player.userID.Get();
            CobaltWarSession registeredWar = FindWarByRegisteredPlayer(userId);
            DefenderSnapshot snapshot;
            bool hasSnapshot = TryGetDefenderSnapshot(userId, out snapshot) && snapshot != null;
            int disconnectWarId = registeredWar != null ? registeredWar.warId : (snapshot != null ? snapshot.warId : 0);

            if (hasSnapshot)
            {
                bool captured = CaptureDisconnectedRaidBackup(player, disconnectWarId, snapshot.buffsDisabled);
                CobaltDiagnosticLog("idle", $"OnPlayerDisconnected: disconnect backup {(captured ? "saved" : "skipped")} for player={player.displayName}({userId}), warId={disconnectWarId}, hasSnapshot={hasSnapshot}.");
            }

            if (registeredWar != null)
            {
                registeredWar.MarkDefenderDisconnected(userId);
                ClearWarUiDismiss(player.userID, registeredWar.warId);
                ClearRenderedWarUiState(player.userID, registeredWar.warId);
            }

            if (!hasSnapshot)
                return;

            string displayName = player.displayName;
            timer.Once(0.5f, () =>
            {
                if (_ == null)
                    return;

                CobaltWarSession returnWar = FindWarByUiRegisteredPlayer(userId);
                if (returnWar != null && returnWar.CanReturnDefender(userId))
                    return;

                if (!TryGetDefenderSnapshot(userId, out snapshot) || snapshot == null)
                    return;

                BasePlayer onlinePlayer = BasePlayer.FindByID(userId);
                if (onlinePlayer != null && onlinePlayer.IsConnected)
                    return;

                if (!TryRestoreDisconnectedDefenderSnapshot(userId))
                    PrintWarning($"[CobaltWar] Не удалось сразу вернуть сохраненный лут отключившемуся защитнику {displayName} ({userId}). Snapshot сохранен и будет восстановлен при следующем входе.");
            });
        }

        private void SetEventVitals(BasePlayer player)
        {
            if (player == null)
                return;

            player.SetHealth(100f);
            player.metabolism.bleeding.value = 0f;
            player.metabolism.calories.min = 0f;
            player.metabolism.calories.value = 500f;
            player.metabolism.hydration.min = 0f;
            player.metabolism.hydration.value = 250f;
            player.metabolism.oxygen.value = 1f;
            player.metabolism.poison.value = 0f;
            player.metabolism.radiation_level.value = 0f;
            player.metabolism.radiation_poison.value = 0f;
            player.metabolism.wetness.value = 0f;
            player.metabolism.temperature.min = 32f;
            player.metabolism.temperature.max = 32f;
            player.metabolism.temperature.value = 32f;
            player.SendNetworkUpdateImmediate();
        }

        private Item GivePlayerItemToPosition(ItemContainer container, string shortname, int amount = 1, int position = -1, ulong skin = 0UL)
        {
            if (container == null || string.IsNullOrEmpty(shortname) || amount <= 0)
                return null;

            Item item = ItemManager.CreateByName(shortname, amount, skin);
            if (item != null)
            {
                if (position >= 0)
                    item.MoveToContainer(container, position, true);
                else
                    item.MoveToContainer(container, allowStack: false, ignoreStackLimit: true);
            }

            return item;
        }

        private void GivePlayerItem(ItemContainer container, string shortname, int amount = 1, ulong skin = 0UL)
        {
            GivePlayerItemToPosition(container, shortname, amount, -1, skin);
        }

        private int GetItemStackLimit(string shortname)
        {
            if (string.IsNullOrEmpty(shortname))
                return 1;

            ItemDefinition definition = ItemManager.FindItemDefinition(shortname);
            return Mathf.Max(1, definition?.stackable ?? 1);
        }

        private void GivePlayerStackedItems(ItemContainer container, string shortname, int amount, ulong skin = 0UL)
        {
            if (container == null || string.IsNullOrEmpty(shortname) || amount <= 0)
                return;

            int stackLimit = GetItemStackLimit(shortname);
            int remaining = amount;
            while (remaining > 0)
            {
                int giveAmount = Mathf.Min(remaining, stackLimit);
                GivePlayerItemToPosition(container, shortname, giveAmount, -1, skin);
                remaining -= giveAmount;
            }
        }

        private int CountAndRemovePlayerItems(BasePlayer player, string shortname)
        {
            if (player == null || string.IsNullOrEmpty(shortname))
                return 0;

            int total = 0;
            foreach (Item item in EnumerateInventoryItems(player).ToList())
            {
                if (item?.info == null || item.info.shortname != shortname)
                    continue;

                total += item.amount;
                item.Remove();
            }

            return total;
        }

        private void MoveBeltOccupantToMain(BasePlayer player, int slot)
        {
            if (player?.inventory?.containerBelt == null || player.inventory.containerMain == null || slot < 0)
                return;

            Item occupying = player.inventory.containerBelt.GetSlot(slot);
            if (occupying == null)
                return;

            if (!occupying.MoveToContainer(player.inventory.containerMain, -1, true))
                occupying.Drop(player.GetDropPosition(), player.GetDropVelocity());
        }

        private int PlaceSupportStackInBelt(BasePlayer player, string shortname, int amount, int slot)
        {
            if (player?.inventory?.containerBelt == null || amount <= 0 || string.IsNullOrEmpty(shortname))
                return amount;

            MoveBeltOccupantToMain(player, slot);

            int placedAmount = Mathf.Min(amount, GetItemStackLimit(shortname));
            Item created = GivePlayerItemToPosition(player.inventory.containerBelt, shortname, placedAmount, slot);
            if (created == null || created.parent != player.inventory.containerBelt)
                return amount;

            return amount - placedAmount;
        }

        private void RebuildDefenderSupportItems(BasePlayer player)
        {
            if (player?.inventory?.containerBelt == null || player.inventory.containerMain == null)
                return;

            int syringeCount = CountAndRemovePlayerItems(player, "syringe.medical");
            int medkitCount = CountAndRemovePlayerItems(player, "largemedkit");
            int bandageCount = CountAndRemovePlayerItems(player, "bandage");
            int f1Count = CountAndRemovePlayerItems(player, "grenade.f1");
            f1Count += CountAndRemovePlayerItems(player, "grenade.beancan");

            syringeCount = PlaceSupportStackInBelt(player, "syringe.medical", syringeCount, 1);
            medkitCount = PlaceSupportStackInBelt(player, "largemedkit", medkitCount, 2);
            f1Count = PlaceSupportStackInBelt(player, "grenade.f1", f1Count, 3);
            bandageCount = PlaceSupportStackInBelt(player, "bandage", bandageCount, 4);

            if (syringeCount > 0)
                syringeCount = PlaceSupportStackInBelt(player, "syringe.medical", syringeCount, 5);
            else if (f1Count > 0)
                f1Count = PlaceSupportStackInBelt(player, "grenade.f1", f1Count, 5);
            else if (medkitCount > 0)
                medkitCount = PlaceSupportStackInBelt(player, "largemedkit", medkitCount, 5);
            else if (bandageCount > 0)
                bandageCount = PlaceSupportStackInBelt(player, "bandage", bandageCount, 5);

            GivePlayerStackedItems(player.inventory.containerMain, "syringe.medical", syringeCount);
            GivePlayerStackedItems(player.inventory.containerMain, "largemedkit", medkitCount);
            GivePlayerStackedItems(player.inventory.containerMain, "grenade.f1", f1Count);
            GivePlayerStackedItems(player.inventory.containerMain, "bandage", bandageCount);
        }

        private string GetWeaponAmmoShortname(string weaponShortname)
        {
            switch (weaponShortname)
            {
                case "rifle.semiauto":
                case "rifle.ak":
                case "rifle.lr300":
                case "lmg.m249":
                case "hmlmg":
                case "minigun":
                    return "ammo.rifle";
                case "smg.thompson":
                case "smg.mp5":
                    return "ammo.pistol";
                case "rocket.launcher":
                    return "ammo.rocket.hv";
                default:
                    return string.Empty;
            }
        }

        private int GetDesiredReserveAmmo(string ammoShortname, int magazineCapacity = 0)
        {
            switch (ammoShortname)
            {
                case "ammo.rocket.hv":
                    return 4 * DefenderAmmoMultiplier;
                case "ammo.rifle":
                    return 320 * DefenderAmmoMultiplier;
                default:
                    return magazineCapacity > 0 ? magazineCapacity * 6 * DefenderAmmoMultiplier : 0;
            }
        }

        private IEnumerable<string> GetKnownBuyoutItemShortnames()
        {
            HashSet<string> result = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
            {
                "keycard_green",
                "keycard_blue",
                "keycard_red"
            };

            if (configData?.raidSettings?.raidTypes != null)
            {
                foreach (string raidType in configData.raidSettings.raidTypes.Keys)
                {
                    string shortname = GetBuyoutItemShortname(raidType);
                    if (!string.IsNullOrEmpty(shortname))
                        result.Add(shortname);
                }
            }

            return result;
        }

        private void QueueBuyoutCardImages(bool force = false)
        {
            if (ImageLibrary == null || !ImageLibrary.IsLoaded)
                return;

            if (buyoutImagesQueued && !force)
                return;

            List<KeyValuePair<string, ulong>> imageList = new List<KeyValuePair<string, ulong>>();
            foreach (string shortname in GetKnownBuyoutItemShortnames())
            {
                if (!string.IsNullOrEmpty(shortname))
                    imageList.Add(new KeyValuePair<string, ulong>(shortname, 0UL));
            }

            if (imageList.Count <= 0)
                return;

            buyoutImagesQueued = true;
            TraceExternalPluginCall("external", ImageLibrary, "LoadImageList", Name, imageList, new Action(OnBuyoutCardImagesLoaded));
        }

        private void OnBuyoutCardImagesLoaded()
        {
            foreach (var war in activeCobaltWars.Values.ToList())
            {
                if (war != null && !war.IsEnded && war.phase == CobaltWarPhase.Buyout)
                    UpdateWarJoinUi(war);
            }
        }

        private string GetBuyoutCardImagePng(string raidType)
        {
            if (ImageLibrary == null || !ImageLibrary.IsLoaded)
                return null;

            if (!buyoutImagesQueued)
                QueueBuyoutCardImages();

            string shortname = GetBuyoutItemShortname(raidType);
            if (string.IsNullOrEmpty(shortname))
                return null;

            try
            {
                return TraceExternalPluginCall("external", ImageLibrary, "GetImage", shortname, 0UL, false) as string;
            }
            catch
            {
                return null;
            }
        }

        private int GetBuyoutCardItemId(string raidType)
        {
            string shortname = GetBuyoutItemShortname(raidType);
            if (string.IsNullOrEmpty(shortname))
                return 0;

            ItemDefinition itemDefinition = ItemManager.FindItemDefinition(shortname);
            return itemDefinition?.itemid ?? 0;
        }

        private string GetBuyoutItemShortname(string raidType)
        {
            if (IsEasyRaidType(raidType) || IsMediumRaidType(raidType))
                return "keycard_green";

            if (string.Equals(raidType, "hard", StringComparison.OrdinalIgnoreCase))
                return "keycard_blue";

            return "keycard_red";
        }

        private string GetBuyoutItemDisplayName(string raidType, string userId = null)
        {
            string shortname = GetBuyoutItemShortname(raidType);
            if (string.IsNullOrEmpty(shortname))
                return lang.GetMessage("CobaltBuyoutUnknownItem", this, userId);

            switch (shortname)
            {
                case "keycard_green":
                    return lang.GetMessage("CobaltBuyoutItemGreen", this, userId);
                case "keycard_blue":
                    return lang.GetMessage("CobaltBuyoutItemBlue", this, userId);
                case "keycard_red":
                    return lang.GetMessage("CobaltBuyoutItemRed", this, userId);
                default:
                    ItemDefinition definition = ItemManager.FindItemDefinition(shortname);
                    return definition?.displayName?.english ?? shortname;
            }
        }

        private int CountPlayerItem(BasePlayer player, string shortname)
        {
            if (player == null || string.IsNullOrEmpty(shortname))
                return 0;

            return EnumeratePlayerInventoryItemsRecursive(player)
                .Where(item => item?.info != null && item.info.shortname == shortname)
                .Sum(item => item.amount);
        }

        private int GetSuccessfulOwnerBuyoutCount(ulong userId)
        {
            if (userId == 0UL)
                return 0;

            EnsurePlayerDataStructures();

            int count;
            if (!pcdData.successfulOwnerBuyouts.TryGetValue(userId, out count))
                return 0;

            return Mathf.Max(0, count);
        }

        private bool CanOfferOwnerBuyout(ulong userId)
        {
            return GetSuccessfulOwnerBuyoutCount(userId) < MaxOwnerBuyoutCount;
        }

        private int GetBuyoutRequiredAmount(ulong userId)
        {
            return Mathf.Clamp(GetSuccessfulOwnerBuyoutCount(userId) + 1, 1, MaxOwnerBuyoutCount);
        }

        private int GetRemainingOwnerBuyouts(ulong userId)
        {
            return Mathf.Max(0, MaxOwnerBuyoutCount - GetSuccessfulOwnerBuyoutCount(userId));
        }

        private void RegisterSuccessfulOwnerBuyout(ulong userId)
        {
            if (userId == 0UL)
                return;

            EnsurePlayerDataStructures();
            pcdData.successfulOwnerBuyouts[userId] = Mathf.Min(MaxOwnerBuyoutCount, GetSuccessfulOwnerBuyoutCount(userId) + 1);
            SaveData();
        }

        private void ResetSuccessfulOwnerBuyoutCount(ulong userId)
        {
            if (userId == 0UL)
                return;

            EnsurePlayerDataStructures();

            int currentCount;
            if (!pcdData.successfulOwnerBuyouts.TryGetValue(userId, out currentCount) || currentCount <= 0)
                return;

            pcdData.successfulOwnerBuyouts.Remove(userId);
            SaveData();
        }

        private string GetBuyoutRequirementText(string raidType, ulong userId, string languageUserId = null)
        {
            return string.Format(lang.GetMessage("CobaltBuyoutRequirement", this, languageUserId), GetBuyoutRequiredAmount(userId), GetBuyoutItemDisplayName(raidType, languageUserId));
        }

        private string GetBuyoutProgressText(ulong userId, string languageUserId = null)
        {
            int nextAttempt = Mathf.Min(GetSuccessfulOwnerBuyoutCount(userId) + 1, MaxOwnerBuyoutCount);
            return string.Format(lang.GetMessage("CobaltUiBuyoutAttemptValue", this, languageUserId), nextAttempt, MaxOwnerBuyoutCount);
        }

        private bool PlayerHasRequiredBuyoutItem(BasePlayer player, string raidType)
        {
            return PlayerHasRequiredBuyoutItem(player, raidType, 1);
        }

        private bool PlayerHasRequiredBuyoutItem(BasePlayer player, string raidType, int requiredAmount)
        {
            return CountPlayerItem(player, GetBuyoutItemShortname(raidType)) >= Mathf.Max(1, requiredAmount);
        }

        private void BroadcastLocalizedChat(string messageKey, params object[] args)
        {
            foreach (BasePlayer player in BasePlayer.activePlayerList)
            {
                if (player == null || !player.IsConnected)
                    continue;

                SendLocalizedReply(player, messageKey, args);
            }
        }

        private string FormatLocalizedMessage(string template, object[] args, string messageKey = null)
        {
            if (string.IsNullOrEmpty(template) || args == null || args.Length == 0)
                return template ?? string.Empty;

            try
            {
                return string.Format(template, args);
            }
            catch (FormatException)
            {
                int requiredArgs = 0;
                foreach (Match match in FormatPlaceholderRegex.Matches(template))
                {
                    int index;
                    if (int.TryParse(match.Groups[1].Value, out index))
                        requiredArgs = Mathf.Max(requiredArgs, index + 1);
                }

                if (requiredArgs > args.Length)
                {
                    object[] paddedArgs = new object[requiredArgs];
                    Array.Copy(args, paddedArgs, args.Length);
                    for (int i = args.Length; i < paddedArgs.Length; i++)
                        paddedArgs[i] = string.Empty;

                    try
                    {
                        return string.Format(template, paddedArgs);
                    }
                    catch
                    {
                    }
                }

                PrintWarning($"Не удалось форматировать локализованное сообщение '{messageKey ?? "unknown"}'. Шаблон: {template}. Аргументов: {args.Length}.");
                return template;
            }
        }

        private void SendLocalizedReply(BasePlayer player, string messageKey, params object[] args)
        {
            if (player == null)
                return;

            string template = lang.GetMessage(messageKey, this, player.UserIDString);
            string formattedMessage = FormatLocalizedMessage(template, args, messageKey);
            SendReply(player, formattedMessage);
        }

