        private bool TryConsumePlayerItem(BasePlayer player, string shortname, int amount)
        {
            if (player == null || string.IsNullOrEmpty(shortname) || amount <= 0)
                return false;

            int remaining = amount;
            var containers = new List<ItemContainer>();
            if (player.inventory != null)
            {
                containers.Add(player.inventory.containerMain);
                containers.Add(player.inventory.containerBelt);
                containers.Add(player.inventory.containerWear);
            }

            foreach (ItemContainer container in containers)
            {
                if (container == null)
                    continue;

                foreach (Item item in container.itemList.ToList())
                {
                    if (item?.info == null || item.info.shortname != shortname)
                        continue;

                    int toUse = Mathf.Min(item.amount, remaining);
                    if (toUse <= 0)
                        continue;

                    item.UseItem(toUse);
                    remaining -= toUse;

                    if (remaining <= 0)
                    {
                        player.SendNetworkUpdateImmediate();
                        return true;
                    }
                }
            }

            player.SendNetworkUpdateImmediate();
            return false;
        }

