        private IEnumerable<Item> EnumerateInventoryItems(BasePlayer player)
        {
            if (player?.inventory == null)
                yield break;

            foreach (Item item in player.inventory.containerBelt.itemList)
                if (item != null)
                    yield return item;

            foreach (Item item in player.inventory.containerMain.itemList)
                if (item != null)
                    yield return item;
        }

        private bool IsDefenderCombatWeapon(Item item)
        {
            if (item?.info == null)
                return false;

            switch (item.info.shortname)
            {
                case "rifle.semiauto":
                case "rifle.ak":
                case "rifle.lr300":
                case "lmg.m249":
                case "hmlmg":
                case "minigun":
                case "smg.thompson":
                case "smg.mp5":
                case "rocket.launcher":
                    return true;
                default:
                    return false;
            }
        }

        private int GetDefenderWeaponHotbarPriority(Item item)
        {
            if (item?.info == null)
                return int.MaxValue;

            switch (item.info.shortname)
            {
                case "minigun":
                    return -1;
                case "lmg.m249":
                case "hmlmg":
                    return 0;
                case "rifle.ak":
                case "rifle.lr300":
                    return 1;
                case "smg.mp5":
                case "smg.thompson":
                case "rifle.semiauto":
                    return 2;
                case "rocket.launcher":
                    return 20;
                default:
                    return 50;
            }
        }

        private bool TryMoveItemToBeltSlot(BasePlayer player, Item item, int slot)
        {
            if (player?.inventory?.containerBelt == null || item == null || slot < 0)
                return false;

            ItemContainer belt = player.inventory.containerBelt;
            if (item.parent == belt && item.position == slot)
                return true;

            Item occupying = belt.GetSlot(slot);
            if (occupying != null && occupying != item)
            {
                if (!occupying.MoveToContainer(player.inventory.containerMain, -1, true))
                    return false;
            }

            return item.MoveToContainer(belt, slot, true);
        }

        private Item FindBestDefenderInventoryItem(BasePlayer player, Func<Item, bool> predicate, HashSet<uint> usedItems)
        {
            if (player == null || predicate == null)
                return null;

            return EnumerateInventoryItems(player)
                .Where(item => item != null && !usedItems.Contains(GetItemUid(item)) && predicate(item))
                .OrderBy(item => item.parent == player.inventory.containerBelt ? 0 : 1)
                .ThenBy(item => item.position)
                .FirstOrDefault();
        }

        private void ArrangeDefenderHotbar(BasePlayer player)
        {
            if (player?.inventory?.containerBelt == null || player.inventory.containerMain == null)
                return;

            HashSet<uint> usedItems = new HashSet<uint>();
            List<int> freeSlots = new List<int> { 1, 2, 3, 4, 5 };

            Action<Func<Item, bool>, int> assignToExactSlot = (predicate, slot) =>
            {
                Item candidate = FindBestDefenderInventoryItem(player, predicate, usedItems);
                if (candidate == null)
                    return;

                if (TryMoveItemToBeltSlot(player, candidate, slot))
                {
                    usedItems.Add(GetItemUid(candidate));
                    freeSlots.Remove(slot);
                }
            };

            Item primaryWeapon = EnumerateInventoryItems(player)
                .Where(IsDefenderCombatWeapon)
                .Where(item => item.info.shortname != "rocket.launcher")
                .OrderBy(item => GetDefenderWeaponHotbarPriority(item))
                .ThenBy(item => item.parent == player.inventory.containerBelt ? 0 : 1)
                .ThenBy(item => item.position)
                .FirstOrDefault();

            if (primaryWeapon != null && TryMoveItemToBeltSlot(player, primaryWeapon, 0))
                usedItems.Add(GetItemUid(primaryWeapon));

            assignToExactSlot(item => item.info != null && item.info.shortname == "syringe.medical", 1);
            assignToExactSlot(item => item.info != null && item.info.shortname == "largemedkit", 2);
            assignToExactSlot(item => item.info != null && item.info.shortname == "grenade.f1", 3);
            assignToExactSlot(item => item.info != null && item.info.shortname == "bandage", 4);
            assignToExactSlot(item => item.info != null && item.info.shortname == "rocket.launcher", 5);

            string[] utilityFallback =
            {
                "grenade.f1",
                "syringe.medical",
                "largemedkit",
                "bandage"
            };

            foreach (string shortname in utilityFallback)
            {
                if (freeSlots.Count <= 0)
                    break;

                int slot = freeSlots[0];
                assignToExactSlot(item => item.info != null && item.info.shortname == shortname, slot);
            }
        }

        private void ScheduleDefenderHotbarNormalization(BasePlayer player, int attempt = 0)
        {
            if (player == null)
                return;

            float delay;
            switch (attempt)
            {
                case 0:
                    delay = 0.05f;
                    break;
                case 1:
                    delay = 0.2f;
                    break;
                default:
                    delay = 0.45f;
                    break;
            }

            timer.Once(delay, () =>
            {
                if (player == null || !player.IsConnected || player.inventory?.containerBelt == null || player.inventory.containerMain == null)
                    return;

                ArrangeDefenderHotbar(player);
                player.inventory.containerBelt.OnChanged();
                player.inventory.containerMain.OnChanged();
                player.SendNetworkUpdateImmediate();

                if (attempt < 2)
                    ScheduleDefenderHotbarNormalization(player, attempt + 1);
            });
        }

        private bool HasDefenderUtilityItemsInBelt(BasePlayer player)
        {
            if (player?.inventory?.containerBelt?.itemList == null)
                return false;

            return player.inventory.containerBelt.itemList.Any(item => item?.info != null && (
                item.info.shortname == "syringe.medical"
                || item.info.shortname == "largemedkit"
                || item.info.shortname == "bandage"
                || item.info.shortname == "grenade.f1"));
        }

        private int CountPlayerItems(BasePlayer player, string shortname)
        {
            if (player == null || string.IsNullOrEmpty(shortname))
                return 0;

            int total = 0;
            foreach (Item item in EnumerateInventoryItems(player))
            {
                if (item.info != null && item.info.shortname == shortname)
                    total += item.amount;
            }

            return total;
        }

        private void EnsureReserveAmmo(BasePlayer player, string ammoShortname, int desiredAmount)
        {
            if (player == null || string.IsNullOrEmpty(ammoShortname) || desiredAmount <= 0)
                return;

            int currentAmount = CountPlayerItems(player, ammoShortname);
            if (currentAmount >= desiredAmount)
                return;

            GivePlayerItem(player.inventory.containerMain, ammoShortname, desiredAmount - currentAmount);
        }

        private void LoadWeaponMagazine(Item weaponItem, string ammoShortname = null)
        {
            if (weaponItem == null)
                return;

            BaseProjectile projectile = weaponItem.GetHeldEntity() as BaseProjectile;
            int desiredContents = GetWeaponMagazineCapacity(weaponItem.info?.shortname);

            if (projectile?.primaryMagazine != null)
            {
                if (string.IsNullOrEmpty(ammoShortname))
                    ammoShortname = projectile.primaryMagazine.ammoType?.shortname;

                if (!string.IsNullOrEmpty(ammoShortname))
                {
                    ItemDefinition ammoDef = ItemManager.FindItemDefinition(ammoShortname);
                    if (ammoDef != null)
                        projectile.primaryMagazine.ammoType = ammoDef;
                }

                if (projectile.primaryMagazine.capacity > 0)
                    desiredContents = projectile.primaryMagazine.capacity;

                if (desiredContents > 0)
                    projectile.primaryMagazine.contents = desiredContents;

                projectile.SendNetworkUpdateImmediate();
            }

            if (desiredContents > 0)
                SetWeaponMagazineInstanceData(weaponItem, desiredContents);

            weaponItem.MarkDirty();
        }

        private List<string> GetDefenderWeaponMods(string weaponShortname)
        {
            switch (weaponShortname)
            {
                case "rifle.semiauto":
                    return new List<string> { "weapon.mod.simplesight", "weapon.mod.flashhider", "weapon.mod.flashlight" };
                case "smg.thompson":
                    return new List<string> { "weapon.mod.simplesight", "weapon.mod.flashlight" };
                case "smg.mp5":
                    return new List<string> { "weapon.mod.holosight", "weapon.mod.flashhider", "weapon.mod.flashlight" };
                case "rifle.ak":
                    return new List<string> { "weapon.mod.holosight", "weapon.mod.flashhider", "weapon.mod.flashlight" };
                case "rifle.lr300":
                    return new List<string> { "weapon.mod.holosight", "weapon.mod.flashhider", "weapon.mod.flashlight" };
                case "lmg.m249":
                    return new List<string> { "weapon.mod.simplesight", "weapon.mod.flashhider", "weapon.mod.flashlight" };
                case "hmlmg":
                    return new List<string> { "weapon.mod.holosight", "weapon.mod.flashhider", "weapon.mod.flashlight" };
                default:
                    return null;
            }
        }

        private bool IsMagnifiedDefenderScope(string shortname)
        {
            if (string.IsNullOrEmpty(shortname))
                return false;

            return shortname == "weapon.mod.8x.scope" || shortname == "weapon.mod.16x.scope";
        }

        private void RemoveMagnifiedDefenderScopes(Item weaponItem)
        {
            if (weaponItem?.contents == null || weaponItem.contents.itemList == null)
                return;

            foreach (Item modItem in weaponItem.contents.itemList.ToList())
            {
                if (modItem?.info == null)
                    continue;

                if (IsMagnifiedDefenderScope(modItem.info.shortname))
                    modItem.Remove();
            }

            weaponItem.MarkDirty();
            BaseEntity heldEntity = weaponItem.GetHeldEntity();
            heldEntity?.SendNetworkUpdateImmediate();
        }

        private void ApplyDefenderWeaponMods(Item weaponItem, string weaponShortname)
        {
            if (weaponItem == null || string.IsNullOrEmpty(weaponShortname))
                return;

            List<string> modShortnames = GetDefenderWeaponMods(weaponShortname);
            if (modShortnames == null || modShortnames.Count <= 0)
                return;

            if (weaponItem.contents == null)
            {
                weaponItem.contents = new ItemContainer();
                weaponItem.contents.ServerInitialize(null, modShortnames.Count);
                weaponItem.contents.GiveUID();
                weaponItem.contents.parent = weaponItem;
            }

            foreach (Item modItem in weaponItem.contents.itemList.ToList())
                modItem?.Remove();

            foreach (string modShortname in modShortnames)
            {
                Item modItem = ItemManager.CreateByName(modShortname, 1);
                if (modItem == null)
                    continue;

                if (!modItem.MoveToContainer(weaponItem.contents, -1, true))
                    modItem.Remove();
            }

            weaponItem.MarkDirty();
            BaseEntity heldEntity = weaponItem.GetHeldEntity();
            heldEntity?.SendNetworkUpdateImmediate();
        }

        private Item GiveLoadedWeapon(BasePlayer player, int beltSlot, string weaponShortname, int reserveAmmoAmount)
        {
            if (player == null || string.IsNullOrEmpty(weaponShortname))
                return null;

            Item weaponItem = GivePlayerItemToPosition(player.inventory.containerBelt, weaponShortname, 1, beltSlot);
            if (weaponItem == null)
                return null;

            string ammoShortname = GetWeaponAmmoShortname(weaponShortname);
            if (!string.IsNullOrEmpty(ammoShortname) && reserveAmmoAmount > 0)
                EnsureReserveAmmo(player, ammoShortname, reserveAmmoAmount);

            ApplyDefenderWeaponMods(weaponItem, weaponShortname);
            LoadWeaponMagazine(weaponItem, ammoShortname);
            return weaponItem;
        }

        private void EnsureDefenderRocketLauncher(BasePlayer player, string raidType)
        {
            if (player == null || !ShouldDefenderHaveRocketLauncher(raidType))
                return;

            Item rocketLauncher = EnumerateInventoryItems(player)
                .FirstOrDefault(item => item?.info != null && item.info.shortname == "rocket.launcher");

            if (rocketLauncher == null)
                rocketLauncher = GiveLoadedWeapon(player, 5, "rocket.launcher", 4 * DefenderAmmoMultiplier);
            else
            {
                EnsureReserveAmmo(player, "ammo.rocket.hv", 4 * DefenderAmmoMultiplier);
                LoadWeaponMagazine(rocketLauncher, "ammo.rocket.hv");
            }

            if (rocketLauncher != null)
                TryMoveItemToBeltSlot(player, rocketLauncher, 5);
        }

        private void NormalizeDefenderSupportItems(BasePlayer player)
        {
            if (player == null)
                return;

            RebuildDefenderSupportItems(player);
        }

        private Item SelectPrimaryDefenderWeapon(BasePlayer player)
        {
            if (player == null)
                return null;

            Item preferred = EnumerateInventoryItems(player)
                .Where(IsDefenderCombatWeapon)
                .Where(item => item.info.shortname == "minigun")
                .OrderBy(item => item.parent == player.inventory.containerBelt ? 0 : 1)
                .ThenBy(item => item.position)
                .FirstOrDefault();

            if (preferred != null)
                return preferred;

            preferred = EnumerateInventoryItems(player)
                .Where(IsDefenderCombatWeapon)
                .Where(item => item.info.shortname != "rocket.launcher")
                .OrderBy(item => GetDefenderWeaponHotbarPriority(item))
                .ThenBy(item => item.parent == player.inventory.containerBelt ? 0 : 1)
                .ThenBy(item => item.position)
                .FirstOrDefault();

            if (preferred != null)
                return preferred;

            return EnumerateInventoryItems(player)
                .Where(IsDefenderCombatWeapon)
                .OrderBy(item => GetDefenderWeaponHotbarPriority(item))
                .ThenBy(item => item.parent == player.inventory.containerBelt ? 0 : 1)
                .ThenBy(item => item.position)
                .FirstOrDefault();
        }

        private void EnforceSingleDefenderWeapon(BasePlayer player, bool keepRocketLauncher)
        {
            if (player == null)
                return;

            Item keepWeapon = SelectPrimaryDefenderWeapon(player);
            if (keepWeapon == null)
                return;

            ulong keepUid = keepWeapon.uid.Value;
            bool keptRocketLauncher = false;
            foreach (Item item in EnumerateInventoryItems(player).ToList())
            {
                if (!IsDefenderCombatWeapon(item))
                    continue;

                if (item.uid.Value == keepUid)
                    continue;

                if (keepRocketLauncher && item.info?.shortname == "rocket.launcher")
                {
                    if (keptRocketLauncher)
                    {
                        item.Remove();
                        continue;
                    }

                    keptRocketLauncher = true;
                    continue;
                }

                item.Remove();
            }
        }

        private void MultiplyExistingAmmoStacks(BasePlayer player, int multiplier)
        {
            if (player == null || multiplier <= 1)
                return;

            foreach (Item item in EnumerateInventoryItems(player))
            {
                if (item?.info == null || string.IsNullOrEmpty(item.info.shortname) || !item.info.shortname.StartsWith("ammo.", StringComparison.Ordinal))
                    continue;

                item.amount *= multiplier;
                item.MarkDirty();
            }
        }

        private void FinalizeDefenderLoadout(BasePlayer player, string raidType, bool multiplyExistingAmmo, bool preserveExistingHotbarLayout = false)
        {
            if (player == null)
                return;

            if (multiplyExistingAmmo)
                MultiplyExistingAmmoStacks(player, DefenderAmmoMultiplier);

            NormalizeDefenderSupportItems(player);
            EnforceSingleDefenderWeapon(player, ShouldDefenderHaveRocketLauncher(raidType));
            EnsureDefenderRocketLauncher(player, raidType);

            foreach (Item item in EnumerateInventoryItems(player).ToList())
            {
                if (item?.info == null)
                    continue;

                if (!IsDefenderCombatWeapon(item))
                    continue;

                string ammoShortname = GetWeaponAmmoShortname(item.info.shortname);
                BaseProjectile projectile = item.GetHeldEntity() as BaseProjectile;
                int magazineCapacity = projectile?.primaryMagazine?.capacity ?? GetWeaponMagazineCapacity(item.info.shortname);

                EnsureReserveAmmo(player, ammoShortname, GetDesiredReserveAmmo(ammoShortname, magazineCapacity));
                RemoveMagnifiedDefenderScopes(item);
                ApplyDefenderWeaponMods(item, item.info.shortname);
                LoadWeaponMagazine(item, ammoShortname);
            }

            ArrangeDefenderHotbar(player);
            ScheduleDefenderHotbarNormalization(player);

            Item firstWeapon = player.inventory.containerBelt.itemList
                .Where(item => item != null && IsDefenderCombatWeapon(item) && item.info.shortname != "rocket.launcher")
                .OrderBy(item => item.position)
                .FirstOrDefault();

            if (firstWeapon == null)
            {
                firstWeapon = player.inventory.containerBelt.itemList
                    .Where(item => item != null && IsDefenderCombatWeapon(item))
                    .OrderBy(item => item.position)
                    .FirstOrDefault();
            }

            if (firstWeapon == null)
            {
                firstWeapon = EnumerateInventoryItems(player)
                    .Where(item => item != null && IsDefenderCombatWeapon(item) && item.info.shortname != "rocket.launcher")
                    .OrderBy(item => item.parent == player.inventory.containerBelt ? 0 : 1)
                    .ThenBy(item => item.position)
                    .FirstOrDefault();
            }

            if (firstWeapon == null)
            {
                firstWeapon = EnumerateInventoryItems(player)
                    .Where(item => item != null && IsDefenderCombatWeapon(item))
                    .OrderBy(item => item.position)
                    .FirstOrDefault();
            }

            if (firstWeapon != null)
                player.UpdateActiveItem(firstWeapon.uid);

            player.SendNetworkUpdateImmediate();

            if (firstWeapon != null)
            {
                ulong firstWeaponUid = firstWeapon.uid.Value;
                timer.Once(0.1f, () =>
                {
                    if (player == null || !player.IsConnected || player.inventory?.containerBelt == null)
                        return;

                    Item refreshedFirstWeapon = player.inventory.containerBelt.itemList.FirstOrDefault(item => item != null && item.uid.Value == firstWeaponUid);
                    if (refreshedFirstWeapon == null)
                        return;

                    player.UpdateActiveItem(refreshedFirstWeapon.uid);
                    LoadWeaponMagazine(refreshedFirstWeapon, GetWeaponAmmoShortname(refreshedFirstWeapon.info?.shortname));
                    ArrangeDefenderHotbar(player);
                    player.inventory.containerBelt?.OnChanged();
                    player.inventory.containerMain?.OnChanged();
                    player.SendNetworkUpdateImmediate();
                    ScheduleDefenderHotbarNormalization(player);
                });
            }
        }

        private bool ApplyKitFromPlugin(BasePlayer player, string raidType, string kitName)
        {
            if (player == null || string.IsNullOrEmpty(kitName) || Kits == null || !Kits.IsLoaded)
                return false;

            StripInventory(player);

            object kitResult = Kits.Call("GiveKit", player, kitName, false);
            bool applied = kitResult is bool success && success;
            if (!applied)
            {
                kitResult = Kits.Call("GiveKit", player, kitName);
                applied = kitResult is bool fallbackSuccess && fallbackSuccess;
            }

            if (!applied)
                return false;

            FinalizeDefenderLoadout(player, raidType, true, false);
            player.SendNetworkUpdateImmediate();
            return true;
        }

        private void GiveCombatConsumables(BasePlayer player, int syringeCount, int bandageCount, int medkitCount, int f1Count, int beanCanCount)
        {
            if (player == null)
                return;

            int totalF1Count = Mathf.Max(0, f1Count) + Mathf.Max(0, beanCanCount);

            GivePlayerStackedItems(player.inventory.containerMain, "syringe.medical", syringeCount);
            GivePlayerStackedItems(player.inventory.containerMain, "bandage", bandageCount);
            GivePlayerStackedItems(player.inventory.containerMain, "largemedkit", medkitCount);
            if (totalF1Count > 0)
                GivePlayerStackedItems(player.inventory.containerMain, "grenade.f1", totalF1Count);
        }

