        private bool IsEasyRaidType(string raidType) => string.Equals(raidType, "easy", StringComparison.OrdinalIgnoreCase);

        private bool IsMediumRaidType(string raidType) => string.Equals(raidType, "medium", StringComparison.OrdinalIgnoreCase);

        private bool ShouldDefenderHaveRocketLauncher(string raidType)
        {
            return string.Equals(raidType, "hard", StringComparison.OrdinalIgnoreCase)
                || string.Equals(raidType, "expert", StringComparison.OrdinalIgnoreCase)
                || string.Equals(raidType, "nightmare", StringComparison.OrdinalIgnoreCase);
        }

        private List<ConfigData.DefenderKitConfig> GetDefenderKitPool(string raidType)
        {
            if (configData?.cobaltWar == null)
                return null;

            if (IsEasyRaidType(raidType) && configData.cobaltWar.easyDefenderKits != null && configData.cobaltWar.easyDefenderKits.Count > 0)
                return configData.cobaltWar.easyDefenderKits;

            if (IsMediumRaidType(raidType) && configData.cobaltWar.mediumDefenderKits != null && configData.cobaltWar.mediumDefenderKits.Count > 0)
                return configData.cobaltWar.mediumDefenderKits;

            return configData.cobaltWar.defenderKits;
        }

        private int GetDefenderFallbackVariantMax(string raidType)
        {
            if (IsEasyRaidType(raidType) || IsMediumRaidType(raidType))
                return 2;

            return 4;
        }

        private string GetDefaultFallbackDefenderKitName(string raidType)
        {
            if (IsEasyRaidType(raidType))
                return "Легкий резервный набор";

            if (IsMediumRaidType(raidType))
                return "Средний резервный набор";

            return "Резервный набор";
        }

        private void GiveFallbackDefenderKit(BasePlayer player, string raidType, int variant)
        {
            if (player == null)
                return;

            StripInventory(player);

            if (IsEasyRaidType(raidType))
            {
                switch (Mathf.Clamp(variant, 0, 2))
                {
                    case 1:
                        GiveHazmatCombatSet(player);
                        GiveLoadedWeapon(player, 0, "smg.thompson", 180 * DefenderAmmoMultiplier);
                        GiveCombatConsumables(player, 10, 6, 1, 3, 0);
                        break;
                    case 2:
                        GiveLightCombatSet(player);
                        GiveLoadedWeapon(player, 0, "rifle.semiauto", 150 * DefenderAmmoMultiplier);
                        GiveCombatConsumables(player, 10, 7, 1, 3, 0);
                        break;
                    default:
                        GiveBanditCombatSet(player);
                        GiveLoadedWeapon(player, 0, "rifle.semiauto", 150 * DefenderAmmoMultiplier);
                        GiveCombatConsumables(player, 11, 6, 1, 3, 0);
                        break;
                }

                FinalizeDefenderLoadout(player, raidType, false);
                return;
            }

            if (IsMediumRaidType(raidType))
            {
                switch (Mathf.Clamp(variant, 0, 2))
                {
                    case 1:
                        GiveRoadsignCombatSet(player);
                        GiveLoadedWeapon(player, 0, "smg.mp5", 240 * DefenderAmmoMultiplier);
                        GiveCombatConsumables(player, 12, 7, 2, 4, 0);
                        break;
                    case 2:
                        GiveMetalCombatSet(player);
                        GiveLoadedWeapon(player, 0, "rifle.ak", 240 * DefenderAmmoMultiplier);
                        GiveCombatConsumables(player, 12, 7, 2, 4, 0);
                        break;
                    default:
                        GiveBanditCombatSet(player);
                        GiveLoadedWeapon(player, 0, "rifle.semiauto", 200 * DefenderAmmoMultiplier);
                        GiveCombatConsumables(player, 12, 8, 2, 4, 0);
                        break;
                }

                FinalizeDefenderLoadout(player, raidType, false);
                return;
            }

            switch (variant)
            {
                case 1:
                    GiveMetalCombatSet(player);
                    GiveLoadedWeapon(player, 0, "rifle.ak", 320 * DefenderAmmoMultiplier);
                    GiveLoadedWeapon(player, 5, "rocket.launcher", 4 * DefenderAmmoMultiplier);
                    GiveCombatConsumables(player, 15, 9, 3, 6, 0);
                    break;
                case 2:
                    GiveBanditCombatSet(player);
                    GiveLoadedWeapon(player, 0, "rifle.lr300", 320 * DefenderAmmoMultiplier);
                    GiveLoadedWeapon(player, 5, "rocket.launcher", 4 * DefenderAmmoMultiplier);
                    GiveCombatConsumables(player, 15, 9, 3, 6, 0);
                    break;
                case 3:
                    GiveHeavyCombatSet(player);
                    GiveLoadedWeapon(player, 0, "minigun", 480 * DefenderAmmoMultiplier);
                    GiveLoadedWeapon(player, 5, "rocket.launcher", 4 * DefenderAmmoMultiplier);
                    GiveCombatConsumables(player, 16, 10, 3, 6, 0);
                    break;
                case 4:
                    GiveMetalCombatSet(player);
                    GiveLoadedWeapon(player, 0, "hmlmg", 360 * DefenderAmmoMultiplier);
                    GiveLoadedWeapon(player, 5, "rocket.launcher", 4 * DefenderAmmoMultiplier);
                    GiveCombatConsumables(player, 15, 9, 3, 6, 0);
                    break;
                default:
                    GiveBanditCombatSet(player);
                    GiveLoadedWeapon(player, 0, "rifle.ak", 320 * DefenderAmmoMultiplier);
                    GiveLoadedWeapon(player, 5, "rocket.launcher", 4 * DefenderAmmoMultiplier);
                    GiveCombatConsumables(player, 15, 9, 3, 6, 0);
                    break;
            }

            FinalizeDefenderLoadout(player, raidType, false);
        }

        private string GiveRandomDefenderKit(BasePlayer player, string raidType)
        {
            if (player == null)
                return string.Empty;

            ConfigData.DefenderKitConfig selected = null;
            List<ConfigData.DefenderKitConfig> pool = GetDefenderKitPool(raidType);
            if (pool != null && pool.Count > 0)
                selected = pool.GetRandom();

            if (selected == null)
            {
                GiveFallbackDefenderKit(player, raidType, 0);
                return GetDefaultFallbackDefenderKitName(raidType);
            }

            if (!string.IsNullOrEmpty(selected.kitName) && ApplyKitFromPlugin(player, raidType, selected.kitName))
                return selected.name ?? selected.kitName;

            int clampedVariant = Mathf.Clamp(selected.fallbackVariant, 0, GetDefenderFallbackVariantMax(raidType));
            GiveFallbackDefenderKit(player, raidType, clampedVariant);
            return selected.name ?? $"{GetDefaultFallbackDefenderKitName(raidType)} {clampedVariant + 1}";
        }

        private string GetRandomAdminKitRaidType()
        {
            if (configData?.raidSettings?.raidTypes != null && configData.raidSettings.raidTypes.Count > 0)
            {
                List<string> availableTypes = configData.raidSettings.raidTypes.Keys
                    .Where(x => !string.IsNullOrEmpty(x) && IsRaidTypeEnabled(x))
                    .ToList();

                if (availableTypes.Count > 0)
                    return availableTypes.GetRandom();
            }

            return "hard";
        }

        private void GiveAdminRandomDefenderKit(BasePlayer player, string raidType = null)
        {
            if (player == null)
                return;

            if (configData?.cobaltWar == null)
            {
                SendReply(player, lang.GetMessage("CobaltNoOpenWar", this, player.UserIDString));
                return;
            }

            string selectedRaidType = string.IsNullOrWhiteSpace(raidType) ? GetRandomAdminKitRaidType() : raidType.Trim().ToLower();
            if (configData?.raidSettings?.raidTypes == null || !configData.raidSettings.raidTypes.ContainsKey(selectedRaidType))
            {
                SendReply(player, lang.GetMessage("NoConfigType", this, player.UserIDString), selectedRaidType);
                SendReply(player, lang.GetMessage("usageRandomKit", this, player.UserIDString));
                return;
            }

            if (!IsRaidTypeEnabled(selectedRaidType))
            {
                SendReply(player, lang.GetMessage("CobaltRaidTypeDisabled", this, player.UserIDString));
                SendReply(player, lang.GetMessage("usageRandomKit", this, player.UserIDString));
                return;
            }

            string kitName = GiveRandomDefenderKit(player, selectedRaidType);
            SetEventVitals(player);
            ScheduleDefenderHotbarNormalization(player);
            SendReply(player, lang.GetMessage("AdminRandomKitGranted", this, player.UserIDString), selectedRaidType, kitName);
        }

        private void StopPlayerSpectating(BasePlayer player)
        {
            if (player == null || !player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
                return;

            try
            {
                player.StopSpectating();
            }
            catch { }
        }

        private void QueueRegisteredDefenderRedeploy(CobaltWarSession war, BasePlayer player, DefenderRedeployState redeployState, bool sendMessage)
        {
            if (war == null || player == null || redeployState == null)
                return;

            float remainingSeconds = Mathf.Max(0f, (float)(redeployState.redeployAt - GrabCurrentTime()));
            if (remainingSeconds <= 0f)
            {
                pendingRedeploys.Remove(player.userID);
                if (redeployState.useDefenderLoadout)
                    PrepareRegisteredDefender(war, player, true);
                else if (!PrepareNaturalFriendlyDefender(war, player, true))
                {
                    redeployState.redeployAt = GrabCurrentTime() + 2f;
                    redeployState.redeployTimerScheduled = false;
                    pendingRedeploys[player.userID.Get()] = redeployState;
                    QueueRegisteredDefenderRedeploy(war, player, redeployState, false);
                }
                return;
            }

            if (player.IsWounded())
                player.StopWounded();

            StopPlayerSpectating(player);
            if (player.HasPlayerFlag(BasePlayer.PlayerFlags.Spectating))
            {
                try
                {
                    player.StopSpectating();
                }
                catch { }

                try
                {
                    player.SetPlayerFlag(BasePlayer.PlayerFlags.Spectating, false);
                    player.UpdateNetworkGroup();
                    player.SendNetworkUpdateImmediate();
                }
                catch { }
            }

            if (sendMessage)
                SendReply(player, lang.GetMessage("CobaltRespawnQueued", this, player.UserIDString), Mathf.CeilToInt(remainingSeconds));

            if (redeployState.redeployTimerScheduled)
                return;

            redeployState.redeployTimerScheduled = true;
            timer.Once(remainingSeconds, () =>
            {
                if (_ == null || player == null)
                    return;

                DefenderRedeployState currentRedeploy;
                if (!pendingRedeploys.TryGetValue(player.userID.Get(), out currentRedeploy) || currentRedeploy.warId != war.warId)
                    return;

                currentRedeploy.redeployTimerScheduled = false;

                if (war == null || !war.IsCombatRespawnWindowOpen())
                    return;

                if (!player.IsConnected)
                    return;

                if (player.IsDead())
                {
                    if (currentRedeploy.useDefenderLoadout)
                        TryForceRegisteredDefenderRespawn(war, player, currentRedeploy);
                    else
                        TryForceNaturalFriendlyRespawn(war, player, currentRedeploy);
                    return;
                }

                if (currentRedeploy.useDefenderLoadout)
                {
                    if (!war.IsRegisteredDefender(player.userID.Get()))
                    {
                        pendingRedeploys.Remove(player.userID.Get());
                        return;
                    }

                    pendingRedeploys.Remove(player.userID);
                    PrepareRegisteredDefender(war, player, true);
                    return;
                }

                if (!war.IsNaturalCombatRespawnEligible(player.userID.Get(), true))
                {
                    pendingRedeploys.Remove(player.userID.Get());
                    return;
                }

                pendingRedeploys.Remove(player.userID);
                if (!PrepareNaturalFriendlyDefender(war, player, true))
                {
                    currentRedeploy.redeployAt = GrabCurrentTime() + 2f;
                    currentRedeploy.redeployTimerScheduled = false;
                    pendingRedeploys[player.userID.Get()] = currentRedeploy;
                    QueueRegisteredDefenderRedeploy(war, player, currentRedeploy, false);
                }
            });
        }

        private void TryForceRegisteredDefenderRespawn(CobaltWarSession war, BasePlayer player, DefenderRedeployState redeployState)
        {
            if (war == null || player == null || redeployState == null)
                return;

            if (!war.IsCombatRespawnWindowOpen() || !player.IsConnected)
                return;

            if (!war.IsRegisteredDefender(player.userID.Get()))
            {
                pendingRedeploys.Remove(player.userID.Get());
                return;
            }

            if (!player.IsDead())
            {
                pendingRedeploys.Remove(player.userID.Get());
                PrepareRegisteredDefender(war, player, true);
                return;
            }

            Vector3 spawn;
            if (!TryFindDefenderSpawn(war, out spawn))
            {
                redeployState.redeployTimerScheduled = false;
                redeployState.redeployAt = GrabCurrentTime() + 2f;
                QueueRegisteredDefenderRedeploy(war, player, redeployState, false);
                return;
            }

            try
            {
                ArmPendingDefenderRespawnProtection(player.userID);
                player.RespawnAt(spawn, Quaternion.identity);
            }
            catch
            {
                redeployState.redeployTimerScheduled = false;
                redeployState.redeployAt = GrabCurrentTime() + 1f;
                QueueRegisteredDefenderRedeploy(war, player, redeployState, false);
            }
        }

        private void TryForceNaturalFriendlyRespawn(CobaltWarSession war, BasePlayer player, DefenderRedeployState redeployState)
        {
            if (war == null || player == null || redeployState == null)
                return;

            if (!war.IsCombatRespawnWindowOpen() || !player.IsConnected)
                return;

            if (!war.IsNaturalCombatRespawnEligible(player.userID.Get(), true))
            {
                pendingRedeploys.Remove(player.userID.Get());
                return;
            }

            if (!player.IsDead())
            {
                pendingRedeploys.Remove(player.userID.Get());
                if (!PrepareNaturalFriendlyDefender(war, player, true))
                {
                    redeployState.redeployTimerScheduled = false;
                    redeployState.redeployAt = GrabCurrentTime() + 2f;
                    pendingRedeploys[player.userID.Get()] = redeployState;
                    QueueRegisteredDefenderRedeploy(war, player, redeployState, false);
                }
                return;
            }

            Vector3 spawn;
            if (!TryFindDefenderSpawn(war, out spawn))
            {
                redeployState.redeployTimerScheduled = false;
                redeployState.redeployAt = GrabCurrentTime() + 2f;
                pendingRedeploys[player.userID.Get()] = redeployState;
                QueueRegisteredDefenderRedeploy(war, player, redeployState, false);
                return;
            }

            try
            {
                ArmPendingDefenderRespawnProtection(player.userID);
                player.RespawnAt(spawn, Quaternion.identity);
            }
            catch
            {
                redeployState.redeployTimerScheduled = false;
                redeployState.redeployAt = GrabCurrentTime() + 1f;
                pendingRedeploys[player.userID.Get()] = redeployState;
                QueueRegisteredDefenderRedeploy(war, player, redeployState, false);
            }
        }

        private void PrepareRegisteredDefender(CobaltWarSession war, BasePlayer player, bool isRedeploy)
        {
            if (war == null || player == null)
                return;

            if (!isRedeploy && !defenderSnapshots.ContainsKey(player.userID))
            {
                if (!CaptureDefenderSnapshot(player, war.warId))
                {
                    war.RemoveRegisteredDefender(player.userID, false);
                    SendReply(player, lang.GetMessage("CobaltSnapshotCaptureFailed", this, player.UserIDString));
                    return;
                }
            }

            Vector3 spawn;
            if (!TryFindDefenderSpawn(war, out spawn))
            {
                war.RemoveRegisteredDefender(player.userID, true, "CobaltDefenderSpawnFailed");
                return;
            }

            if (player.IsWounded())
                player.StopWounded();

            if (isRedeploy)
                SetDefenderRespawnProtection(player.userID, Mathf.Max(0f, configData.cobaltWar.respawnProtectionSeconds));
            else
                ClearDefenderRespawnProtection(player.userID);

            StopPlayerSpectating(player);
            string kitName = GiveRandomDefenderKit(player, war.raidType);
            if (war.IsRegisteredDefender(player.userID))
                TrackProtectedDefenderInventory(player, war.warId);
            TeleportPlayer(player, spawn);
            SetEventVitals(player);
            ScheduleDefenderHotbarNormalization(player);
            if (isRedeploy)
            {
                RefreshDefenderRespawnProtection(player.userID, Mathf.Max(0f, configData.cobaltWar.respawnProtectionSeconds));
                if (configData.cobaltWar.respawnProtectionSeconds > 0f)
                    SendReply(player, lang.GetMessage("CobaltRespawnProtection", this, player.UserIDString), Mathf.CeilToInt(configData.cobaltWar.respawnProtectionSeconds));
            }
            TouchDefenderActivity(player, true);
            SendReply(player, lang.GetMessage("CobaltDefenderTeleported", this, player.UserIDString), kitName);
            QueueCombatRespawnLocationAudit(player);
        }

        private bool PrepareNaturalFriendlyDefender(CobaltWarSession war, BasePlayer player, bool isRedeploy)
        {
            if (war == null || player == null)
                return false;

            Vector3 spawn;
            if (!TryFindDefenderSpawn(war, out spawn))
                return false;

            if (player.IsWounded())
                player.StopWounded();

            if (isRedeploy)
                SetDefenderRespawnProtection(player.userID, Mathf.Max(0f, configData.cobaltWar.respawnProtectionSeconds));
            else
                ClearDefenderRespawnProtection(player.userID);

            StopPlayerSpectating(player);
            TeleportPlayer(player, spawn);
            SetEventVitals(player);

            ulong userId = player.userID.Get();
            if (!war.owners.Contains(userId) && !war.IsRegisteredDefender(userId))
                war.PreserveWalkInNaturalRespawnEligibility(userId);

            if (isRedeploy)
            {
                RefreshDefenderRespawnProtection(player.userID, Mathf.Max(0f, configData.cobaltWar.respawnProtectionSeconds));
                if (configData.cobaltWar.respawnProtectionSeconds > 0f)
                    SendReply(player, lang.GetMessage("CobaltRespawnProtection", this, player.UserIDString), Mathf.CeilToInt(configData.cobaltWar.respawnProtectionSeconds));
            }

            TouchDefenderActivity(player, true);
            SendReply(player, lang.GetMessage("CobaltNaturalDefenderTeleported", this, player.UserIDString), war.targetName, GetGrid(war.location));
            QueueCombatRespawnLocationAudit(player);
            return true;
        }

        private bool AwardDamageXp(BasePlayer player, float damage, out double awardedXp)
        {
            awardedXp = 0d;

            if (player == null || damage <= 0f || SkillTree == null || configData?.cobaltWar == null)
                return false;

            double xp = GetCobaltDamageXp(damage);
            if (xp <= 0d)
                return false;

            if (!TryAwardSkillTreeXp(player.userID, xp))
                return false;

            awardedXp = xp;
            return true;
        }

