        private string BuildCobaltUiBody(CobaltWarSession war, BasePlayer player, string phaseLabel, string helpersLabel, int ownerCount, int registeredCount, int walkInCount, int helperCount, int defenseProgress, string countdownLabel, int remainingSeconds)
        {
            string userId = player?.UserIDString;

            var lines = new List<string>
            {
                string.Format(lang.GetMessage("CobaltUiLineTarget", this, userId), war.targetName),
                string.Format(lang.GetMessage("CobaltUiLineGrid", this, userId), GetGrid(war.location)),
                string.Format(lang.GetMessage("CobaltUiLinePhase", this, userId), phaseLabel),
                string.Format(lang.GetMessage("CobaltUiLineOwners", this, userId), ownerCount),
                string.Format(lang.GetMessage("CobaltUiLineRegistered", this, userId), registeredCount),
                string.Format(lang.GetMessage("CobaltUiLineWalkIns", this, userId), walkInCount),
                string.Format(lang.GetMessage("CobaltUiLineHelpers", this, userId), helpersLabel, helperCount),
                string.Format(lang.GetMessage("CobaltUiLineProgress", this, userId), defenseProgress),
            };

            if (war != null
                && player != null
                && war.owners.Contains(player.userID)
                && configData?.cobaltWar != null
                && configData.cobaltWar.enableSupportDrones)
            {
                int permanentSupportDrones = war.GetPermanentSupportDroneCount();
                int activePurchasedSupportDrones = war.GetActivePurchasedSupportDroneCount();
                int usedPurchasedSlots = war.GetUsedPurchasedSupportDroneSlots();
                int supportDroneCap = war.GetPurchasedSupportDroneSlotCap();

                if (permanentSupportDrones > 0)
                    lines.Add(string.Format(lang.GetMessage("CobaltUiLinePermanentSupportDrones", this, userId), permanentSupportDrones));

                if (supportDroneCap > 0 || activePurchasedSupportDrones > 0 || usedPurchasedSlots > 0)
                {
                    lines.Add(string.Format(lang.GetMessage("CobaltUiLineSupportDrones", this, userId), activePurchasedSupportDrones, usedPurchasedSlots, supportDroneCap));

                    if (supportDroneCap > 0 && (war.phase == CobaltWarPhase.Registration || war.phase == CobaltWarPhase.Preparation || war.phase == CobaltWarPhase.Active))
                    {
                        foreach (var tierEntry in GetOrderedSupportDroneTiers())
                        {
                            string tierKey = tierEntry.Key;
                            lines.Add(string.Format(
                                lang.GetMessage("CobaltUiLineSupportDroneTier", this, userId),
                                GetSupportDroneTierUiName(tierKey),
                                GetSupportDroneTierSlots(tierKey),
                                war.GetSupportDroneCostLabel(tierKey, userId)));
                        }

                        lines.Add(lang.GetMessage("CobaltUiLineSupportDroneHint", this, userId));
                    }
                }
            }

            if (!string.IsNullOrEmpty(countdownLabel))
                lines.Add(string.Format(lang.GetMessage("CobaltUiLineCountdown", this, userId), countdownLabel, remainingSeconds));

            return string.Join("\n", lines);
        }

        private string BuildCobaltUiRenderDigest(CobaltWarSession war, BasePlayer player, string phaseLabel, string helpersLabel, int ownerCount, int registeredCount, int walkInCount, int helperCount, int defenseProgress, string countdownLabel, int remainingSeconds)
        {
            string userId = player?.UserIDString;
            string digest = string.Concat(
                war?.targetName ?? string.Empty, "|",
                GetGrid(war.location), "|",
                phaseLabel ?? string.Empty, "|",
                helpersLabel ?? string.Empty, "|",
                ownerCount.ToString(), "|",
                registeredCount.ToString(), "|",
                walkInCount.ToString(), "|",
                helperCount.ToString(), "|",
                defenseProgress.ToString(), "|",
                countdownLabel ?? string.Empty, "|",
                remainingSeconds.ToString(), "|",
                war != null ? war.GetCurrentWaveNumber().ToString() : "0", "|",
                war != null ? war.GetTotalWaveCount().ToString() : "0", "|",
                war != null ? war.GetAliveNpcCount().ToString() : "0");

            if (war != null && war.IsExternalRaidBase)
            {
                digest = string.Concat(
                    digest, "|",
                    war.GetExternalRaidCurrentParticipantCount().ToString(), "|",
                    GetExternalRaidBaseMinimumParticipantCount(war.raidType).ToString());
            }

            if (war != null
                && player != null
                && war.owners.Contains(player.userID)
                && configData?.cobaltWar != null
                && configData.cobaltWar.enableSupportDrones)
            {
                digest = string.Concat(
                    digest, "|",
                    war.GetPermanentSupportDroneCount().ToString(), "|",
                    war.GetActivePurchasedSupportDroneCount().ToString(), "|",
                    war.GetUsedPurchasedSupportDroneSlots().ToString(), "|",
                    war.GetPurchasedSupportDroneSlotCap().ToString(), "|",
                    GetSupportDronePurchaseAvailability(war, "lite").ToString(), "|",
                    GetSupportDronePurchaseAvailability(war, "middle").ToString(), "|",
                    GetSupportDronePurchaseAvailability(war, "hard").ToString(), "|",
                    GetSupportDroneTierPlainCostText(war.raidType, "lite", userId, !war.IsNextSupportDroneFree()), "|",
                    GetSupportDroneTierPlainCostText(war.raidType, "middle", userId, !war.IsNextSupportDroneFree()), "|",
                    GetSupportDroneTierPlainCostText(war.raidType, "hard", userId, !war.IsNextSupportDroneFree()));
            }

            return digest;
        }

        private string BuildCobaltBuyoutUiBody(CobaltWarSession war, BasePlayer player, string phaseLabel, string countdownLabel, int remainingSeconds)
        {
            string userId = player?.UserIDString;
            int requiredAmount = GetBuyoutRequiredAmount(war.targetUserId);
            string requirementText = GetBuyoutRequirementText(war.raidType, war.targetUserId, userId);
            int buyoutItemCount = player == null ? 0 : CountPlayerItem(player, GetBuyoutItemShortname(war.raidType));
            string availability = string.Format(lang.GetMessage("CobaltUiBuyoutOwnedCount", this, userId), buyoutItemCount, requiredAmount);

            var lines = new List<string>
            {
                string.Format(lang.GetMessage("CobaltUiLineTarget", this, userId), war.targetName),
                string.Format(lang.GetMessage("CobaltUiLineGrid", this, userId), GetGrid(war.location)),
                string.Format(lang.GetMessage("CobaltUiLinePhase", this, userId), phaseLabel),
                string.Format(lang.GetMessage("CobaltUiLineBuyoutItem", this, userId), requirementText),
                string.Format(lang.GetMessage("CobaltUiLineBuyoutStatus", this, userId), availability),
                string.Format(lang.GetMessage("CobaltUiLineBuyoutAttempt", this, userId), GetBuyoutProgressText(war.targetUserId, userId)),
                string.Format(lang.GetMessage("CobaltUiLineCountdown", this, userId), countdownLabel, remainingSeconds)
            };

            return string.Join("\n", lines);
        }

