        private void RenderCobaltWarStatusLayout(CuiElementContainer container, string infoPanel, CobaltWarSession war, BasePlayer player, string phaseLabel, string helpersLabel, int ownerCount, int registeredCount, int walkInCount, int helperCount, int defenseProgress, string countdownLabel, int remainingSeconds, bool canRequestDroneButton, bool canJoin)
        {
            string userId = player?.UserIDString;
            string timerTitle = !string.IsNullOrEmpty(countdownLabel)
                ? countdownLabel
                : lang.GetMessage("CobaltUiCountdownEnd", this, userId);
            string timerValue = $"{Mathf.Max(0, remainingSeconds)}с";
            string compactPhaseLabel = GetCompactCobaltPhaseLabel(war.phase, userId);
            int reinforcementCount = registeredCount + walkInCount;
            bool showDroneSection = canRequestDroneButton;

            if (!showDroneSection)
            {
                RenderParticipantWarStatusLayout(container, infoPanel, war, player, userId, timerTitle, timerValue, compactPhaseLabel, ownerCount, reinforcementCount, helperCount, canJoin);
                return;
            }

            AddWarUiMetricCard(container, infoPanel, "0.03 0.78", "0.40 0.96", lang.GetMessage("CobaltUiLineTarget", this, userId).Split(':')[0], war.targetName, "0.94 0.56 0.22 0.95", 12);
            AddWarUiMetricCard(container, infoPanel, "0.42 0.78", "0.58 0.96", lang.GetMessage("CobaltUiLineGrid", this, userId).Split(':')[0], GetGrid(war.location), "0.32 0.54 0.82 0.95", 12);
            AddWarUiMetricCard(container, infoPanel, "0.60 0.78", "0.77 0.96", lang.GetMessage("CobaltUiLinePhase", this, userId).Split(':')[0], compactPhaseLabel, "0.57 0.43 0.88 0.95", 11);
            AddWarUiMetricCard(container, infoPanel, "0.79 0.78", "0.97 0.96", timerTitle, timerValue, "0.26 0.69 0.58 0.95", 12);

            string leftSection = AddWarUiPanel(container, infoPanel, "0.03 0.08", showDroneSection ? "0.48 0.72" : "0.97 0.72", "0.07 0.09 0.13 0.92");
            container.Add(new CuiPanel
            {
                Image = { Color = "0.95 0.57 0.20 0.08" },
                RectTransform = { AnchorMin = "0 0.982", AnchorMax = "1 1" }
            }, leftSection);
            AddWarUiSectionTitle(container, leftSection, "Оборона");
            AddWarUiInfoRow(container, leftSection, "0.05 0.34", "0.95 0.54", "Подкрепление", reinforcementCount.ToString());
            AddWarUiInfoRow(container, leftSection, "0.05 0.12", "0.95 0.32", "В бою", helperCount.ToString());

            string rightSection = AddWarUiPanel(container, infoPanel, "0.51 0.08", "0.97 0.72", "0.07 0.09 0.13 0.92");
            container.Add(new CuiPanel
            {
                Image = { Color = "0.84 0.57 0.18 0.10" },
                RectTransform = { AnchorMin = "0 0.982", AnchorMax = "1 1" }
            }, rightSection);
            string droneBody = AddWarUiPanel(container, rightSection, "0.05 0.08", "0.95 0.95", "0.09 0.12 0.16 0.88");
            AddWarUiSectionTitle(container, droneBody, "Дроны");
            AddWarUiLabel(container, droneBody, "0.06 0.10", "0.94 0.80", BuildSupportDroneOverviewText(war), 10, TextAnchor.UpperLeft, "0.94 0.95 0.97 1");
        }

        private string BuildWarUiRenderSignature(CobaltWarSession war, BasePlayer player, string titleText, string bodyText, bool canSurrender, bool canReturn, bool canJoin, bool canLeave, bool canRequestDroneButton, bool expandedLayout, string panelAnchorMin, string panelAnchorMax, string layoutKey, string buyoutVisualSignature = null)
        {
            string footerMode = canSurrender
                ? "surrender"
                : canReturn
                    ? "return"
                    : canJoin
                    ? "join"
                    : canLeave
                        ? "leave"
                        : canRequestDroneButton
                            ? "drone"
                            : "label";

            return string.Concat(
                war?.warId.ToString() ?? "0", "|",
                player != null ? player.userID.Get().ToString() : "0", "|",
                ((int)(war?.phase ?? CobaltWarPhase.Completed)).ToString(), "|",
                footerMode, "|",
                expandedLayout ? "1" : "0", "|",
                layoutKey ?? string.Empty, "|",
                panelAnchorMin, "|",
                panelAnchorMax, "|",
                titleText ?? string.Empty, "|",
                bodyText ?? string.Empty, "|",
                buyoutVisualSignature ?? string.Empty, "|",
                war != null ? war.GetCurrentWaveNumber().ToString() : "0", "|",
                war != null ? war.GetTotalWaveCount().ToString() : "0", "|",
                war != null ? war.GetAliveNpcCount().ToString() : "0");
        }

        private void UpdateWarJoinUi(CobaltWarSession war)
        {
            if (war == null || war.IsEnded)
                return;

            foreach (var player in BasePlayer.activePlayerList)
            {
                try
                {
                    UpdateWarJoinUi(war, player);
                }
                catch (Exception ex)
                {
                    PrintError($"UpdateWarJoinUi failed for war {war.warId} and player '{player?.displayName ?? "unknown"}': {ex}");
                }
            }
        }

        private void UpdateWarJoinUi(CobaltWarSession war, BasePlayer player)
        {
            UpdateWarJoinUi(war, player, false);
        }

        private void UpdateWarJoinUi(CobaltWarSession war, BasePlayer player, bool forceDisplay)
        {
            if (war == null || player == null || !player.IsConnected)
                return;

            int minimizedWarId;
            bool isMinimizedForWar = minimizedWarUi.TryGetValue(player.userID, out minimizedWarId) && minimizedWarId == war.warId;

            int displayedWarId;
            displayedWarUi.TryGetValue(player.userID, out displayedWarId);

            if (!forceDisplay && !ShouldDisplayWarUi(war, player))
            {
                if (displayedWarId == war.warId || (displayedWarId != 0 && FindPreferredWarForPlayer(player) == null))
                {
                    CuiHelper.DestroyUi(player, JoinUiName);
                    displayedWarUi.Remove(player.userID);
                    ClearRenderedWarUiState(player.userID, war.warId);
                }

                if (isMinimizedForWar)
                {
                    CuiHelper.DestroyUi(player, MinimizedJoinUiName);
                    minimizedWarUi.Remove(player.userID);
                    ClearMinimizedWarUiRenderState(player.userID, war.warId);
                    RefreshMinimizedUiTimerState();
                }
                return;
            }

            if (!forceDisplay && isMinimizedForWar)
            {
                CuiHelper.DestroyUi(player, JoinUiName);
                displayedWarUi.Remove(player.userID);
                ClearRenderedWarUiState(player.userID, war.warId);
                RenderMinimizedWarUi(player, war);
                RefreshMinimizedUiTimerState();
                return;
            }

            float remaining = Mathf.Max(0f, war.phaseEndTime - Time.realtimeSinceStartup);
            string phaseLabel = GetCobaltPhaseLabel(war.phase, player.UserIDString);
            string countdownLabel = war.phase == CobaltWarPhase.Active ? null : GetCobaltCountdownLabel(war.phase, player.UserIDString);
            string helpersLabel = GetCobaltHelpersLabel(war.phase, player.UserIDString);
            int ownerCount = war.GetOwnerCount();
            int registeredCount = war.GetRegisteredDefenderCount();
            int walkInCount = war.GetWalkInDefenderCount();
            int helperCount = war.phase == CobaltWarPhase.Registration ? war.GetRegisteredDefenderCount() : war.GetConnectedHelperCount();
            int defenseProgress = war.GetDefenseProgressPercent();
            bool isOwner = war.owners.Contains(player.userID);
            bool isRegisteredDefender = war.IsUiRegisteredDefender(player.userID);
            bool isDisconnectedDefender = war.IsDisconnectedDefender(player.userID);
            bool canJoin = war.CanJoinDefender(player.userID);
            bool canLeave = war.CanLeaveDefender(player.userID);
            bool canReturn = war.CanReturnDefender(player.userID);
            int remainingSeconds = Mathf.CeilToInt(remaining);
            bool canSurrender = war.CanSurrender(player);
            bool canRequestDroneButton = isOwner
                && war.phase != CobaltWarPhase.Buyout
                && war.phase != CobaltWarPhase.Cleanup
                && configData?.cobaltWar != null
                && configData.cobaltWar.enableSupportDrones;
            bool buyoutLayout = war.phase == CobaltWarPhase.Buyout;
            string titleText = lang.GetMessage("CobaltUiTitle", this, player.UserIDString);
            if (!string.IsNullOrEmpty(titleText) && titleText.Contains("{0}"))
                titleText = string.Format(titleText, configData?.cobaltWar?.factionName ?? "Кобальт");
            string bodyText = buyoutLayout
                ? BuildCobaltBuyoutUiBody(war, player, phaseLabel, countdownLabel, remainingSeconds)
                : BuildCobaltUiRenderDigest(war, player, phaseLabel, helpersLabel, ownerCount, registeredCount, walkInCount, helperCount, defenseProgress, countdownLabel, remainingSeconds);
            int bodyLineCount = buyoutLayout && !string.IsNullOrEmpty(bodyText) ? bodyText.Count(c => c == '\n') + 1 : 0;
            bool denseLayout = buyoutLayout && bodyLineCount >= 10;
            bool veryDenseLayout = buyoutLayout && bodyLineCount >= 14;
            bool expandedLayout = buyoutLayout || canRequestDroneButton;

            string panelAnchorMin;
            string panelAnchorMax;
            string titleAnchorMin = "0.03 0.14";
            string titleAnchorMax;
            string closeAnchorMin;
            string closeAnchorMax;
            string minimizeAnchorMin;
            string minimizeAnchorMax;
            string infoSectionAnchorMin;
            string infoSectionAnchorMax;
            string actionSectionAnchorMin;
            string actionSectionAnchorMax;
            string bodyAnchorMin;
            string bodyAnchorMax;
            string primaryActionAnchorMin = "0.02 0.15";
            string primaryActionAnchorMax = "0.98 0.85";
            int bodyFontSize;
            string layoutKey;

            if (buyoutLayout)
            {
                panelAnchorMin = "0.015 0.55";
                panelAnchorMax = "0.385 0.92";
                titleAnchorMax = "0.62 0.94";
                minimizeAnchorMin = "0.69 0.18";
                minimizeAnchorMax = "0.84 0.86";
                closeAnchorMin = "0.86 0.18";
                closeAnchorMax = "0.97 0.86";
                infoSectionAnchorMin = "0.03 0.22";
                infoSectionAnchorMax = "0.97 0.80";
                actionSectionAnchorMin = "0.03 0.04";
                actionSectionAnchorMax = "0.97 0.18";
                bodyAnchorMin = "0.36 0.06";
                bodyAnchorMax = "0.96 0.94";
                bodyFontSize = 10;
                layoutKey = "buyout-wide";
            }
            else if (canRequestDroneButton || veryDenseLayout)
            {
                panelAnchorMin = "0.015 0.50";
                panelAnchorMax = "0.385 0.87";
                titleAnchorMax = "0.58 0.94";
                minimizeAnchorMin = "0.67 0.18";
                minimizeAnchorMax = "0.82 0.86";
                closeAnchorMin = "0.84 0.18";
                closeAnchorMax = "0.97 0.86";
                infoSectionAnchorMin = "0.02 0.23";
                infoSectionAnchorMax = "0.98 0.79";
                actionSectionAnchorMin = "0.02 0.04";
                actionSectionAnchorMax = "0.98 0.17";
                bodyAnchorMin = "0.04 0.06";
                bodyAnchorMax = "0.96 0.94";
                bodyFontSize = veryDenseLayout ? 9 : 10;
                layoutKey = bodyFontSize <= 9 ? "modern-support-tight" : "modern-support";
            }
            else if (expandedLayout)
            {
                panelAnchorMin = "0.015 0.54";
                panelAnchorMax = "0.360 0.85";
                titleAnchorMax = "0.58 0.94";
                minimizeAnchorMin = "0.67 0.18";
                minimizeAnchorMax = "0.82 0.86";
                closeAnchorMin = "0.84 0.18";
                closeAnchorMax = "0.97 0.86";
                infoSectionAnchorMin = "0.02 0.22";
                infoSectionAnchorMax = "0.98 0.79";
                actionSectionAnchorMin = "0.02 0.04";
                actionSectionAnchorMax = "0.98 0.16";
                bodyAnchorMin = "0.04 0.06";
                bodyAnchorMax = "0.96 0.94";
                bodyFontSize = 10;
                layoutKey = "modern-expanded";
            }
            else
            {
                panelAnchorMin = "0.015 0.56";
                panelAnchorMax = "0.355 0.85";
                titleAnchorMax = "0.58 0.94";
                minimizeAnchorMin = "0.67 0.18";
                minimizeAnchorMax = "0.82 0.86";
                closeAnchorMin = "0.84 0.18";
                closeAnchorMax = "0.97 0.86";
                infoSectionAnchorMin = "0.02 0.20";
                infoSectionAnchorMax = "0.98 0.79";
                actionSectionAnchorMin = "0.02 0.03";
                actionSectionAnchorMax = "0.98 0.16";
                bodyAnchorMin = "0.04 0.06";
                bodyAnchorMax = "0.96 0.94";
                primaryActionAnchorMin = "0.03 0.10";
                primaryActionAnchorMax = "0.97 0.90";
                bodyFontSize = 10;
                layoutKey = "modern-join";
            }

            string buyoutVisualSignature = string.Empty;
            if (buyoutLayout)
            {
                string buyoutPngSignature = GetBuyoutCardImagePng(war.raidType);
                if (!string.IsNullOrEmpty(buyoutPngSignature))
                    buyoutVisualSignature = "png:" + buyoutPngSignature.Length.ToString();
                else
                    buyoutVisualSignature = "item:" + GetBuyoutCardItemId(war.raidType).ToString();
            }

            string renderSignature = BuildWarUiRenderSignature(war, player, titleText, bodyText, canSurrender, canReturn, canJoin, canLeave, canRequestDroneButton, expandedLayout, panelAnchorMin, panelAnchorMax, layoutKey, buyoutVisualSignature);

            if (!forceDisplay && IsWarUiDismissed(player.userID, war.warId, war.phase, canJoin || canReturn || canSurrender, canLeave))
            {
                CuiHelper.DestroyUi(player, JoinUiName);
                CuiHelper.DestroyUi(player, MinimizedJoinUiName);
                displayedWarUi.Remove(player.userID);
                minimizedWarUi.Remove(player.userID);
                ClearRenderedWarUiState(player.userID, war.warId);
                ClearMinimizedWarUiRenderState(player.userID, war.warId);
                RefreshMinimizedUiTimerState();
                return;
            }

            if (!forceDisplay
                && displayedWarId != war.warId
                && ShouldDefaultToMinimizedWarUi(war, player))
            {
                minimizedWarUi[player.userID] = war.warId;
                CuiHelper.DestroyUi(player, JoinUiName);
                displayedWarUi.Remove(player.userID);
                ClearRenderedWarUiState(player.userID, war.warId);
                ClearMinimizedWarUiRenderState(player.userID, war.warId);
                RenderMinimizedWarUi(player, war);
                RefreshMinimizedUiTimerState();
                return;
            }

            WarUiRenderState renderedState;
            if (!forceDisplay
                && displayedWarId == war.warId
                && renderedWarUiState.TryGetValue(player.userID, out renderedState)
                && renderedState != null
                && renderedState.warId == war.warId
                && renderedState.signature == renderSignature)
                return;

            CuiHelper.DestroyUi(player, JoinUiName);

            CuiElementContainer container = new CuiElementContainer();
            string panel = container.Add(new CuiPanel
            {
                Image = { Color = "0.04 0.06 0.09 0.94" },
                RectTransform = { AnchorMin = panelAnchorMin, AnchorMax = panelAnchorMax },
                CursorEnabled = false
            }, "Overlay", JoinUiName);

            string headerPanel = container.Add(new CuiPanel
            {
                Image = { Color = "0.10 0.13 0.18 0.96" },
                RectTransform = { AnchorMin = "0.015 0.84", AnchorMax = "0.985 0.985" }
            }, panel);

            string infoPanel = container.Add(new CuiPanel
            {
                Image = { Color = "0.07 0.09 0.13 0.94" },
                RectTransform = { AnchorMin = infoSectionAnchorMin, AnchorMax = infoSectionAnchorMax }
            }, panel);

            container.Add(new CuiPanel
            {
                Image = { Color = "0.94 0.56 0.22 0.10" },
                RectTransform = { AnchorMin = "0 0.965", AnchorMax = "1 1" }
            }, infoPanel);

            string footerPanel = container.Add(new CuiPanel
            {
                Image = { Color = "0.07 0.09 0.12 0.98" },
                RectTransform = { AnchorMin = actionSectionAnchorMin, AnchorMax = actionSectionAnchorMax }
            }, panel);

            container.Add(new CuiPanel
            {
                Image = { Color = "0.95 0.57 0.20 0.10" },
                RectTransform = { AnchorMin = "0 0.94", AnchorMax = "1 1" }
            }, footerPanel);

            container.Add(new CuiLabel
            {
                RectTransform = { AnchorMin = titleAnchorMin, AnchorMax = titleAnchorMax },
                Text = { Text = titleText, FontSize = 13, Align = TextAnchor.MiddleLeft, Color = "1 0.7 0.35 1" }
            }, headerPanel);

            if (war.phase == CobaltWarPhase.Buyout)
            {
                string imagePanel = container.Add(new CuiPanel
                {
                    Image = { Color = "0.07 0.09 0.11 0.98" },
                    RectTransform = { AnchorMin = "0.03 0.06", AnchorMax = "0.31 0.94" }
                }, infoPanel);

                string buyoutPng = GetBuyoutCardImagePng(war.raidType);
                if (!string.IsNullOrEmpty(buyoutPng))
                {
                    container.Add(new CuiElement
                    {
                        Parent = imagePanel,
                        Components =
                        {
                            new CuiRawImageComponent { Png = buyoutPng, Color = "1 1 1 1" },
                            new CuiRectTransformComponent { AnchorMin = "0.08 0.08", AnchorMax = "0.92 0.92" }
                        }
                    });
                }
                else
                {
                    int buyoutItemId = GetBuyoutCardItemId(war.raidType);
                    container.Add(new CuiPanel
                    {
                        Image = { Color = "1 1 1 1", ItemId = buyoutItemId },
                        RectTransform = { AnchorMin = "0.08 0.08", AnchorMax = "0.92 0.92" }
                    }, imagePanel);
                }
            }

            if (war.phase == CobaltWarPhase.Buyout)
            {
                container.Add(new CuiLabel
                {
                    RectTransform = { AnchorMin = bodyAnchorMin, AnchorMax = bodyAnchorMax },
                    Text = { Text = bodyText, FontSize = bodyFontSize, Align = TextAnchor.UpperLeft, Color = "0.92 0.92 0.92 1" }
                }, infoPanel);
            }
            else
            {
                RenderCobaltWarStatusLayout(container, infoPanel, war, player, phaseLabel, helpersLabel, ownerCount, registeredCount, walkInCount, helperCount, defenseProgress, countdownLabel, remainingSeconds, canRequestDroneButton, canJoin);
            }

            container.Add(new CuiButton
            {
                Button = { Color = "0.16 0.18 0.22 0.95", Command = $"rr.cobalt.close {war.warId}" },
                RectTransform = { AnchorMin = closeAnchorMin, AnchorMax = closeAnchorMax },
                Text = { Text = "X", FontSize = 12, Align = TextAnchor.MiddleCenter }
            }, headerPanel);
             
            container.Add(new CuiButton
            {
                Button = { Color = "0.24 0.42 0.26 0.95", Command = $"rr.cobalt.minimize {war.warId}" },
                RectTransform = { AnchorMin = minimizeAnchorMin, AnchorMax = minimizeAnchorMax },
                Text = { Text = "Свернуть", FontSize = 10, Align = TextAnchor.MiddleCenter }
            }, headerPanel);

            string surrenderActionText = GetCompactWarActionTitle(lang.GetMessage("CobaltUiSurrender", this, player.UserIDString), "Сдаться");
            string joinActionText = GetCompactWarActionTitle(lang.GetMessage("CobaltUiJoin", this, player.UserIDString), "Помочь");
            string leaveActionText = GetCompactWarActionTitle(lang.GetMessage("CobaltUiLeave", this, player.UserIDString), "Покинуть");
            string returnActionText = GetCompactWarActionTitle(lang.GetMessage("CobaltUiReturn", this, player.UserIDString), "Вернуться");

            if (canSurrender)
            {
                AddWarUiPrimaryActionButton(container, footerPanel, primaryActionAnchorMin, primaryActionAnchorMax, $"rr.cobalt.surrender {war.warId}", surrenderActionText, "0.63 0.20 0.14 0.98");
            }
            else if (canReturn)
            {
                AddWarUiPrimaryActionButton(container, footerPanel, primaryActionAnchorMin, primaryActionAnchorMax, $"rr.cobalt.return {war.warId}", returnActionText, "0.22 0.51 0.29 0.98");
            }
            else if (canJoin)
            {
                AddWarUiPrimaryActionButton(container, footerPanel, primaryActionAnchorMin, primaryActionAnchorMax, $"rr.cobalt.join {war.warId}", joinActionText, "0.67 0.21 0.13 0.98");
            }
            else if (canLeave)
            {
                AddWarUiPrimaryActionButton(container, footerPanel, primaryActionAnchorMin, primaryActionAnchorMax, $"rr.cobalt.leave {war.warId}", leaveActionText, "0.58 0.21 0.13 0.98");
            }
            else if (canRequestDroneButton)
            {
                string[] tierKeys = GetOrderedSupportDroneTiers().Select(x => x.Key).Take(3).ToArray();
                string[] buttonColors = { "0.28 0.67 0.31 0.98", "0.86 0.58 0.16 0.98", "0.82 0.30 0.24 0.98" };
                string[] anchorsMin = { "0.02 0.12", "0.345 0.12", "0.67 0.12" };
                string[] anchorsMax = { "0.33 0.88", "0.655 0.88", "0.98 0.88" };

                for (int tierIndex = 0; tierIndex < tierKeys.Length && tierIndex < 3; tierIndex++)
                {
                    string tierKey = tierKeys[tierIndex];
                    int slotCost = GetSupportDroneTierSlots(tierKey);
                    AddWarUiDroneActionButton(
                        container,
                        footerPanel,
                        anchorsMin[tierIndex],
                        anchorsMax[tierIndex],
                        $"rr.cobalt.drone {war.warId} {tierKey}",
                        GetSupportDroneTierUiName(tierKey),
                        $"{slotCost} сл.",
                        GetSupportDroneTierPlainCostText(war.raidType, tierKey, player.UserIDString, !war.IsNextSupportDroneFree()),
                        buttonColors[tierIndex]);
                }
            }
            else
            {
                string footerMessage;
                if (war.phase == CobaltWarPhase.Buyout)
                    footerMessage = lang.GetMessage("CobaltUiBuyoutOwnerHint", this, player.UserIDString);
                else if (isDisconnectedDefender)
                    footerMessage = lang.GetMessage("CobaltUiReturnHint", this, player.UserIDString);
                else if (isRegisteredDefender)
                    footerMessage = lang.GetMessage("CobaltUiJoined", this, player.UserIDString);
                else if (isOwner)
                    footerMessage = lang.GetMessage("CobaltUiOwner", this, player.UserIDString);
                else
                    footerMessage = lang.GetMessage("CobaltUiLocked", this, player.UserIDString);

                string infoNotice = AddWarUiPanel(container, footerPanel, primaryActionAnchorMin, primaryActionAnchorMax, "0.10 0.13 0.17 0.90");
                container.Add(new CuiPanel
                {
                    Image = { Color = "0.34 0.61 0.42 0.95" },
                    RectTransform = { AnchorMin = "0 0.92", AnchorMax = "1 1" }
                }, infoNotice);
                AddWarUiLabel(container, infoNotice, "0.04 0.18", "0.96 0.82", footerMessage, 10, TextAnchor.MiddleLeft, "0.78 0.90 0.80 1");
            }

            CuiHelper.AddUi(player, container);
            displayedWarUi[player.userID] = war.warId;
            renderedWarUiState[player.userID] = new WarUiRenderState
            {
                warId = war.warId,
                signature = renderSignature
            };
        }

        public class CobaltWarSession : FacepunchBehaviour
        {
            public CobaltWar plugin;
            public int warId;
            public CobaltWarTrigger trigger;
            public CobaltWarPhase phase;
            public BuildingPrivlidge privilege;
            public BasePlayer targetPlayer;
            public ulong targetUserId;
            public string targetName;
            public Vector3 location;
            public string raidType;
            public raidConfig raidProfile;
            public List<BuildingBlock> blocks = new List<BuildingBlock>();
            public List<ulong> owners = new List<ulong>();
            public bool IsExternalRaidBase { get; private set; }
            public string ExternalSourceId { get; private set; }
            public ConfigData.BalanceTierConfig balanceTier;
            public int targetBalanceSnapshot;
            public int failurePenaltyAmount;
            public float phaseEndTime;
            public EventRandomManager raidManager;
            private CobaltWarStartMode startMode;
            private RaidTerrainProfile terrainProfile;
            public readonly HashSet<ulong> registeredDefenders = new HashSet<ulong>();
            public readonly HashSet<ulong> ownerTestDefenders = new HashSet<ulong>();
            public readonly HashSet<ulong> disconnectedRegisteredDefenders = new HashSet<ulong>();
            public readonly HashSet<ulong> disconnectedOwnerTestDefenders = new HashSet<ulong>();
            public readonly HashSet<ulong> walkInDefenders = new HashSet<ulong>();
            private readonly Dictionary<ulong, double> walkInPresenceSince = new Dictionary<ulong, double>();
            public readonly Dictionary<ulong, float> totalDamage = new Dictionary<ulong, float>();
            public readonly Dictionary<ulong, float> pendingDamage = new Dictionary<ulong, float>();
            private readonly Queue<PendingSupportDroneRequest> pendingSupportDroneRequests = new Queue<PendingSupportDroneRequest>();
            private readonly List<PendingSupportDroneRespawn> pendingSupportDroneRespawns = new List<PendingSupportDroneRespawn>();
            private float nextUiUpdate;
            private float nextWalkInRefresh;
            private float nextSupportDroneRespawnCheck;
            private float nextAfkCheck;
            private bool cleanupStarted;
            private bool cancelledBeforeRaid;
            private bool buyoutSkippedByLimit;
            private bool bypassStartOnlineRequirement;
            private bool raidCooldownApplied;
            private bool notifyOwnersOnCleanup;
            private bool postRaidCombatGraceActive;
            private bool automaticSupportDronesScheduled;
            private bool automaticSupportDronesResolved;
            private bool victoryCompletionRewardsAwarded;
            private int cleanupFinalizeRetryCount;
            private int frozenAutomaticSupportDroneCap;
            private int frozenSupportDroneCountCap;
            private int acceptedSupportDroneRequests;
            private float nextOwnerSyncAt;
            private float forcedCleanupGraceSeconds = -1f;
            private string cleanupOwnerMessageKey;
            private readonly List<ulong> victoryRouletteRewardPlayers = new List<ulong>();
            public bool CompletedSuccessfully { get; private set; }
            public bool IsEnded { get; private set; }
            public bool IsRockBaseTerrain => terrainProfile != null && terrainProfile.isRockBase;

            private float GetFailurePenaltyPercent()
            {
                if (balanceTier != null && balanceTier.penaltyPercent > 0f)
                    return balanceTier.penaltyPercent;

                if (plugin?.configData?.cobaltWar?.balanceTiers == null)
                    return 0f;

                return plugin.configData.cobaltWar.balanceTiers
                    .Where(x => x != null && x.penaltyPercent > 0f)
                    .OrderBy(x => x.minBalance)
                    .Select(x => x.penaltyPercent)
                    .FirstOrDefault();
            }

            public void Setup(CobaltWar plugin, BuildingPrivlidge privilege, BasePlayer targetPlayer, string raidType, raidConfig raidProfile, List<BuildingBlock> blocks, List<ulong> owners, CobaltWarTrigger trigger, ConfigData.BalanceTierConfig balanceTier, int targetBalanceSnapshot, CobaltWarStartMode startMode = CobaltWarStartMode.Standard, ulong immediateOwnerDefenderUserId = 0UL, bool bypassOnlineRequirement = false)
            {
                this.plugin = plugin;
                this.warId = plugin.GetNextWarId();
                this.privilege = privilege;
                this.targetPlayer = targetPlayer;
                this.targetUserId = targetPlayer.userID.Get();
                this.targetName = targetPlayer.displayName;
                this.location = privilege.transform.position;
                this.raidType = raidType;
                this.raidProfile = raidProfile;
                this.blocks = new List<BuildingBlock>(blocks ?? new List<BuildingBlock>());
                this.owners = new List<ulong>(owners ?? new List<ulong>());
                this.trigger = trigger;
                this.balanceTier = balanceTier;
                this.targetBalanceSnapshot = targetBalanceSnapshot;
                this.startMode = startMode;
                float failurePenaltyPercent = GetFailurePenaltyPercent();
                this.failurePenaltyAmount = targetBalanceSnapshot > 0 && failurePenaltyPercent > 0f
                    ? Mathf.RoundToInt(targetBalanceSnapshot * (failurePenaltyPercent / 100f))
                    : 0;
                this.terrainProfile = plugin.AnalyzeRaidTerrain(privilege, this.blocks);
                this.nextUiUpdate = 0f;
                this.nextWalkInRefresh = 0f;
                this.nextAfkCheck = 0f;
                this.cancelledBeforeRaid = false;
                this.buyoutSkippedByLimit = false;
                this.bypassStartOnlineRequirement = bypassOnlineRequirement;
                this.raidCooldownApplied = false;
                this.notifyOwnersOnCleanup = true;
                this.postRaidCombatGraceActive = false;
                this.automaticSupportDronesScheduled = false;
                this.automaticSupportDronesResolved = false;
                this.victoryCompletionRewardsAwarded = false;
                this.cleanupFinalizeRetryCount = 0;
                this.frozenAutomaticSupportDroneCap = -1;
                this.frozenSupportDroneCountCap = -1;
                this.acceptedSupportDroneRequests = 0;
                this.nextOwnerSyncAt = 0f;
                this.cleanupOwnerMessageKey = null;
                this.victoryRouletteRewardPlayers.Clear();
                this.walkInPresenceSince.Clear();
                plugin.RegisterWar(this);

                if (!RefreshPreStartState(true))
                    return;

                if (this.startMode == CobaltWarStartMode.Immediate)
                {
                    BeginImmediate(immediateOwnerDefenderUserId);
                }
                else if (!IsExternalRaidBase && plugin.configData.cobaltWar.enableOwnerBuyout && plugin.CanOfferOwnerBuyout(this.targetUserId))
                {
                    this.phase = CobaltWarPhase.Buyout;
                    this.phaseEndTime = Time.realtimeSinceStartup + plugin.configData.cobaltWar.ownerBuyoutSeconds;
                    AnnounceBuyoutStart();
                }
                else
                {
                    this.buyoutSkippedByLimit = !IsExternalRaidBase && plugin.configData.cobaltWar.enableOwnerBuyout && !plugin.CanOfferOwnerBuyout(this.targetUserId);
                    BeginRegistration();
                }
            }

            public void SetupExternal(CobaltWar plugin, BuildingPrivlidge privilege, string displayName, string raidType, raidConfig raidProfile, List<BuildingBlock> blocks, List<ulong> authPlayers, string externalSourceId, CobaltWarStartMode startMode = CobaltWarStartMode.Standard, bool bypassOnlineRequirement = false)
            {
                this.plugin = plugin;
                this.warId = plugin.GetNextWarId();
                this.privilege = privilege;
                this.targetPlayer = null;
                this.targetUserId = 0UL;
                this.targetName = string.IsNullOrEmpty(displayName) ? "Рейдовая база Кобальт" : displayName;
                this.location = privilege != null ? privilege.transform.position : Vector3.zero;
                this.raidType = raidType;
                this.raidProfile = raidProfile;
                this.blocks = new List<BuildingBlock>(blocks ?? new List<BuildingBlock>());
                this.owners = new List<ulong>();
                this.IsExternalRaidBase = true;
                this.ExternalSourceId = externalSourceId ?? string.Empty;
                this.trigger = CobaltWarTrigger.Manual;
                this.balanceTier = null;
                this.targetBalanceSnapshot = 0;
                this.failurePenaltyAmount = 0;
                this.startMode = startMode;
                this.terrainProfile = plugin.AnalyzeRaidTerrain(privilege, this.blocks);
                this.nextUiUpdate = 0f;
                this.nextWalkInRefresh = 0f;
                this.nextAfkCheck = 0f;
                this.cancelledBeforeRaid = false;
                this.buyoutSkippedByLimit = false;
                this.bypassStartOnlineRequirement = bypassOnlineRequirement;
                this.raidCooldownApplied = false;
                this.notifyOwnersOnCleanup = false;
                this.postRaidCombatGraceActive = false;
                this.automaticSupportDronesScheduled = false;
                this.automaticSupportDronesResolved = false;
                this.victoryCompletionRewardsAwarded = false;
                this.cleanupFinalizeRetryCount = 0;
                this.frozenAutomaticSupportDroneCap = -1;
                this.frozenSupportDroneCountCap = -1;
                this.acceptedSupportDroneRequests = 0;
                this.nextOwnerSyncAt = 0f;
                this.cleanupOwnerMessageKey = null;
                this.victoryRouletteRewardPlayers.Clear();
                this.walkInPresenceSince.Clear();
                plugin.RegisterWar(this);

                if (!RefreshPreStartState(false))
                    return;

                if (this.startMode == CobaltWarStartMode.Immediate)
                    BeginImmediate(0UL);
                else
                    BeginRegistration();
            }

            private void BeginImmediate(ulong immediateOwnerDefenderUserId)
            {
                if (cleanupStarted || IsEnded)
                    return;

                if (!IsExternalRaidBase && immediateOwnerDefenderUserId != 0UL && owners.Contains(immediateOwnerDefenderUserId))
                {
                    ownerTestDefenders.Add(immediateOwnerDefenderUserId);

                    BasePlayer ownerPlayer = BasePlayer.FindByID(immediateOwnerDefenderUserId);
                    if (ownerPlayer != null && ownerPlayer.IsConnected)
                    {
                        plugin.ClearWarUiDismiss(ownerPlayer.userID, warId);
                        plugin.TouchDefenderActivity(ownerPlayer, true);
                        plugin.SendReply(ownerPlayer, plugin.lang.GetMessage("CobaltOwnerTestJoinSuccess", plugin, ownerPlayer.UserIDString), targetName, plugin.GetGrid(location));
                    }
                }

                BeginRegistration();
            }

            public void ApplyRaidCooldownNow()
            {
                if (raidCooldownApplied || plugin == null || owners == null || owners.Count == 0)
                    return;

                plugin.TouchRaidCooldown(new List<ulong>(owners));
                raidCooldownApplied = true;
            }

            private void RefreshFailurePenaltyAmount(bool clearSnapshotWhenUnavailable = false)
            {
                int updatedBalanceSnapshot = targetBalanceSnapshot;
                if (targetUserId == 0UL)
                {
                    updatedBalanceSnapshot = 0;
                }
                else if (plugin.ServerRewards != null)
                {
                    try
                    {
                        updatedBalanceSnapshot = Convert.ToInt32(plugin.ServerRewards.Call("CheckPoints", targetUserId));
                    }
                    catch
                    {
                        if (clearSnapshotWhenUnavailable)
                            updatedBalanceSnapshot = 0;
                    }
                }
                else if (clearSnapshotWhenUnavailable)
                {
                    updatedBalanceSnapshot = 0;
                }

                targetBalanceSnapshot = Mathf.Max(0, updatedBalanceSnapshot);
                float failurePenaltyPercent = GetFailurePenaltyPercent();
                failurePenaltyAmount = targetBalanceSnapshot > 0 && failurePenaltyPercent > 0f
                    ? Mathf.RoundToInt(targetBalanceSnapshot * (failurePenaltyPercent / 100f))
                    : 0;
            }

            private bool RefreshPreparedBaseSnapshot()
            {
                if (privilege == null || privilege.IsDestroyed)
                    return false;

                List<BuildingBlock> preparedBlocks;
                List<ulong> preparedOwners;
                string failReasonKey;
                if (!plugin.TryPrepareRaidBase(privilege, out preparedBlocks, out preparedOwners, out failReasonKey, true))
                    return false;

                blocks = preparedBlocks ?? new List<BuildingBlock>();
                terrainProfile = plugin.AnalyzeRaidTerrain(privilege, blocks);
                if (!IsExternalRaidBase)
                {
                    owners = preparedOwners != null
                        ? preparedOwners.Where(userId => userId != 0UL).Distinct().ToList()
                        : new List<ulong>();
                }
                return true;
            }

            private bool RefreshCurrentTargetState(bool refreshBalanceSnapshot = false)
            {
                ulong previousTargetUserId = targetUserId;
                BasePlayer resolvedTarget = plugin.ResolveCurrentRaidTargetPlayer(privilege, owners, previousTargetUserId);
                if (resolvedTarget == null && trigger == CobaltWarTrigger.Manual)
                    resolvedTarget = targetPlayer ?? (previousTargetUserId != 0UL ? plugin.FindPlayerByIdOrSleeping(previousTargetUserId) : null);
                if (resolvedTarget == null)
                {
                    targetPlayer = null;
                    targetUserId = 0UL;
                    if (refreshBalanceSnapshot || previousTargetUserId != 0UL)
                        RefreshFailurePenaltyAmount(true);
                    return false;
                }

                targetPlayer = resolvedTarget;
                targetUserId = resolvedTarget.userID.Get();
                if (!string.IsNullOrEmpty(resolvedTarget.displayName))
                    targetName = resolvedTarget.displayName;

                if (refreshBalanceSnapshot || previousTargetUserId != targetUserId)
                    RefreshFailurePenaltyAmount(previousTargetUserId != targetUserId);

                return true;
            }

            private void CancelBeforeRaid(string messageKey)
            {
                cleanupOwnerMessageKey = string.IsNullOrEmpty(messageKey) ? "CobaltWarCancelledStartFailed" : messageKey;
                cancelledBeforeRaid = true;
                CompletedSuccessfully = false;
                BeginCleanup();
            }

            private bool RefreshPreStartState(bool refreshBalanceSnapshot = false)
            {
                RefreshOwnersFromPrivilege();
                if (CancelWarIfTargetCupboardLost())
                    return false;

                if (!RefreshPreparedBaseSnapshot())
                {
                    CancelBeforeRaid("CobaltWarCancelledStartFailed");
                    return false;
                }

                if (IsExternalRaidBase)
                    return true;

                if (!RefreshCurrentTargetState(refreshBalanceSnapshot))
                {
                    string availabilityMessageKey = plugin.GetAuthorizedRaidAvailabilityMessageKey(privilege, owners);
                    CancelBeforeRaid(string.IsNullOrEmpty(availabilityMessageKey) ? "CobaltWarCancelledStartFailed" : availabilityMessageKey);
                    return false;
                }

                return true;
            }

            private void AnnounceBuyoutStart()
            {
                RefreshOwnersFromPrivilege();
                int buyoutSeconds = Mathf.CeilToInt(plugin.configData.cobaltWar.ownerBuyoutSeconds);
                string grid = plugin.GetGrid(location);
                string requirementText = plugin.GetBuyoutRequirementText(raidType, targetUserId);

                foreach (var ownerId in owners)
                {
                    BasePlayer owner = BasePlayer.FindByID(ownerId);
                    if (owner == null || !owner.IsConnected)
                        continue;

                    plugin.SendReply(owner, plugin.lang.GetMessage("CobaltWarBuyoutOwner", plugin, owner.UserIDString), plugin.configData.cobaltWar.factionName, grid, plugin.GetBuyoutRequirementText(raidType, targetUserId, owner.UserIDString), buyoutSeconds, plugin.GetBuyoutProgressText(targetUserId, owner.UserIDString));
                    if (plugin.configData.settings.worldMarker)
                        plugin.LocateBaseWithMarker(owner, location, plugin.configData.settings.worldMarkerTime);
                }

                plugin.BroadcastLocalizedChat("CobaltWarBuyoutGlobal", plugin.configData.cobaltWar.factionName, targetName, grid, buyoutSeconds, requirementText);
                plugin.UpdateWarJoinUi(this);
            }

            private void AnnounceRegistrationStart(bool fromBuyout)
            {
                RefreshOwnersFromPrivilege();
                int registrationSeconds = Mathf.CeilToInt(plugin.configData.cobaltWar.registrationSeconds);
                int preparationSeconds = Mathf.CeilToInt(plugin.configData.cobaltWar.preparationSeconds);
                int assaultSeconds = registrationSeconds + preparationSeconds;
                string grid = plugin.GetGrid(location);

                string globalMessageKey = fromBuyout
                    ? "CobaltWarBuyoutExpiredGlobal"
                    : buyoutSkippedByLimit
                        ? "CobaltWarIncomingGlobalNoBuyout"
                        : "CobaltWarIncomingGlobal";

                plugin.BroadcastLocalizedChat(globalMessageKey, plugin.configData.cobaltWar.factionName, targetName, grid, registrationSeconds, preparationSeconds, assaultSeconds);

                foreach (var ownerId in owners)
                {
                    BasePlayer owner = BasePlayer.FindByID(ownerId);
                    if (owner == null || !owner.IsConnected)
                        continue;

                    plugin.SendReply(owner, plugin.lang.GetMessage("CobaltWarIncomingOwner", plugin, owner.UserIDString), plugin.configData.cobaltWar.factionName, grid, registrationSeconds, preparationSeconds);
                    if (plugin.configData.settings.worldMarker)
                        plugin.LocateBaseWithMarker(owner, location, plugin.configData.settings.worldMarkerTime);
                }
            }

            private void BeginRegistration()
            {
                if (cleanupStarted || IsEnded)
                    return;

                if (!RefreshPreStartState(true))
                    return;

                if (trigger != CobaltWarTrigger.Manual)
                    plugin.ResetSuccessfulOwnerBuyoutCount(targetUserId);

                if (trigger != CobaltWarTrigger.Manual && plugin.configData.settings.mustBeOnlinePlayer && !plugin.HasEligibleOnlineAuthorizedPlayer(privilege))
                {
                    cleanupOwnerMessageKey = plugin.GetAuthorizedRaidAvailabilityMessageKey(privilege, owners);
                    cancelledBeforeRaid = true;
                    CompletedSuccessfully = false;
                    BeginCleanup();
                    return;
                }

                bool fromBuyout = phase == CobaltWarPhase.Buyout;
                phase = CobaltWarPhase.Registration;
                phaseEndTime = Time.realtimeSinceStartup + plugin.configData.cobaltWar.registrationSeconds;
                plugin.CobaltDiagnosticLog("raid", $"Война #{warId}: этап Registration, raidType={raidType}, owners={owners.Count}, defenders={registeredDefenders.Count}, walkIns={walkInDefenders.Count}, external={IsExternalRaidBase}.");
                AnnounceRegistrationStart(fromBuyout);
                plugin.UpdateWarJoinUi(this);
            }

            public bool RegisterDefender(BasePlayer player)
            {
                if (player == null || (phase != CobaltWarPhase.Registration && phase != CobaltWarPhase.Preparation && phase != CobaltWarPhase.Active))
                    return false;
                string arenaMessageKey;
                if (plugin.IsArenaTournamentBlockingCobalt(player, true, out arenaMessageKey))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage(arenaMessageKey, plugin, player.UserIDString));
                    return false;
                }
                if (owners.Contains(player.userID.Get()))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltOwnerAlreadyDefending", plugin, player.UserIDString));
                    return false;
                }
                if (registeredDefenders.Contains(player.userID.Get()))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltAlreadyRegistered", plugin, player.UserIDString));
                    return false;
                }
                if (plugin.configData.cobaltWar.requireJoinPermission && !plugin.HasAnyPermission(player.UserIDString, joinPerm, legacyJoinPerm))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltJoinNoPermission", plugin, player.UserIDString));
                    return false;
                }
                if (registeredDefenders.Count >= plugin.configData.cobaltWar.maxRegisteredDefenders)
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltJoinFull", plugin, player.UserIDString));
                    return false;
                }
                if (plugin.FindWarByRegisteredPlayer(player.userID) != null || plugin.defenderSnapshots.ContainsKey(player.userID))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltJoinBusy", plugin, player.UserIDString));
                    return false;
                }

                registeredDefenders.Add(player.userID.Get());
                plugin.ClearWarUiDismiss(player.userID, warId);
                plugin.TouchDefenderActivity(player, true);
                plugin.SendReply(player, plugin.lang.GetMessage("CobaltJoinSuccess", plugin, player.UserIDString), targetName, plugin.GetGrid(location));

                if (phase == CobaltWarPhase.Preparation || phase == CobaltWarPhase.Active)
                    plugin.PrepareRegisteredDefender(this, player, false);

                plugin.UpdateWarJoinUi(this);
                return true;
            }

            public bool CanJoinDefender(ulong userId)
            {
                if (phase != CobaltWarPhase.Registration && phase != CobaltWarPhase.Preparation && phase != CobaltWarPhase.Active)
                    return false;

                return !IsFriendlyParticipant(userId) && !IsUiRegisteredDefender(userId);
            }

            public bool CanSurrender(BasePlayer player)
            {
                if (IsExternalRaidBase)
                    return false;

                RefreshOwnersFromPrivilege();
                return player != null && phase == CobaltWarPhase.Buyout && owners.Contains(player.userID.Get());
            }

            public bool TrySurrender(BasePlayer player)
            {
                if (player == null)
                    return false;

                if (!CanSurrender(player))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltBuyoutUnavailable", plugin, player.UserIDString));
                    return false;
                }

                string requiredItem = plugin.GetBuyoutItemShortname(raidType);
                int requiredAmount = plugin.GetBuyoutRequiredAmount(targetUserId);
                string requirementText = plugin.GetBuyoutRequirementText(raidType, targetUserId, player.UserIDString);
                if (string.IsNullOrEmpty(requiredItem))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltBuyoutUnavailable", plugin, player.UserIDString));
                    return false;
                }

                if (!plugin.PlayerHasRequiredBuyoutItem(player, raidType, requiredAmount))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltBuyoutNeedItem", plugin, player.UserIDString), requirementText);
                    return false;
                }

                if (!plugin.TryConsumePlayerItem(player, requiredItem, requiredAmount))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltBuyoutConsumeFailed", plugin, player.UserIDString));
                    return false;
                }

                if (trigger != CobaltWarTrigger.Manual)
                {
                    plugin.TouchRaidCooldown(new List<ulong>(owners));
                    plugin.TouchRaidLocationCooldown(location);
                    plugin.TouchSuccessfulOwnerBuyoutAutoRaidCooldown(targetUserId);
                }

                plugin.RegisterSuccessfulOwnerBuyout(targetUserId);

                foreach (ulong ownerId in owners)
                {
                    BasePlayer owner = BasePlayer.FindByID(ownerId);
                    if (owner != null && owner.IsConnected)
                        plugin.SendReply(owner, plugin.lang.GetMessage("CobaltBuyoutAccepted", plugin, owner.UserIDString), player.displayName, plugin.GetBuyoutRequirementText(raidType, targetUserId, owner.UserIDString));
                }

                plugin.BroadcastLocalizedChat("CobaltBuyoutAcceptedGlobal", player.displayName, targetName, plugin.GetGrid(location), plugin.GetBuyoutRequirementText(raidType, targetUserId), plugin.GetSuccessfulOwnerBuyoutCount(targetUserId), CobaltWar.MaxOwnerBuyoutCount);
                CancelWar("CobaltBuyoutAcceptedCleanup", true);
                return true;
            }

            public bool RegisterOwnerTestDefender(BasePlayer player)
            {
                if (player == null)
                    return false;

                if (IsExternalRaidBase)
                    return false;

                RefreshOwnersFromPrivilege();

                string arenaMessageKey;
                if (plugin.IsArenaTournamentBlockingCobalt(player, true, out arenaMessageKey))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage(arenaMessageKey, plugin, player.UserIDString));
                    return false;
                }

                if (phase != CobaltWarPhase.Registration && phase != CobaltWarPhase.Preparation && phase != CobaltWarPhase.Active)
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltOwnerTestJoinUnavailable", plugin, player.UserIDString));
                    return false;
                }

                if (!owners.Contains(player.userID.Get()))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltOwnerTestJoinOnlyOwner", plugin, player.UserIDString));
                    return false;
                }

                if (ownerTestDefenders.Contains(player.userID.Get()))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltOwnerTestAlreadyEnabled", plugin, player.UserIDString));
                    return false;
                }

                if (registeredDefenders.Contains(player.userID.Get()))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltAlreadyRegistered", plugin, player.UserIDString));
                    return false;
                }

                if (plugin.FindWarByRegisteredPlayer(player.userID) != null || plugin.defenderSnapshots.ContainsKey(player.userID))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltJoinBusy", plugin, player.UserIDString));
                    return false;
                }

                ownerTestDefenders.Add(player.userID.Get());
                plugin.ClearWarUiDismiss(player.userID, warId);
                plugin.TouchDefenderActivity(player, true);
                plugin.SendReply(player, plugin.lang.GetMessage("CobaltOwnerTestJoinSuccess", plugin, player.UserIDString), targetName, plugin.GetGrid(location));

                if (phase == CobaltWarPhase.Preparation || phase == CobaltWarPhase.Active)
                    plugin.PrepareRegisteredDefender(this, player, false);

                plugin.UpdateWarJoinUi(this);
                return true;
            }

            public bool CanLeaveDefender(ulong userId)
            {
                if (phase != CobaltWarPhase.Registration && phase != CobaltWarPhase.Preparation && phase != CobaltWarPhase.Cleanup)
                    return false;

                return IsUiRegisteredDefender(userId);
            }

            public List<ulong> GetAllRegisteredDefenders()
            {
                return registeredDefenders.Concat(ownerTestDefenders).Distinct().ToList();
            }

            public List<ulong> GetAllUiRegisteredDefenders()
            {
                return registeredDefenders
                    .Concat(ownerTestDefenders)
                    .Concat(disconnectedRegisteredDefenders)
                    .Concat(disconnectedOwnerTestDefenders)
                    .Distinct()
                    .ToList();
            }

            public int GetActiveSupportDroneCount()
            {
                return plugin != null ? plugin.GetActiveSupportDroneCount(warId) : 0;
            }

            public int GetActivePurchasedSupportDroneCount()
            {
                return plugin != null ? plugin.GetActivePurchasedSupportDroneCount(warId) : 0;
            }

            public int GetPendingSupportDroneCount()
            {
                if (plugin?.configData?.cobaltWar == null || !plugin.configData.cobaltWar.enableSupportDrones)
                    return 0;

                return GetQueuedSupportDroneRequestCount() + GetPendingSupportDroneRespawnCount() + GetPlannedAutomaticSupportDroneCount();
            }

            private int GetQueuedSupportDroneRequestCount()
            {
                return pendingSupportDroneRequests.Count;
            }

            private int GetPendingSupportDroneRespawnCount()
            {
                return pendingSupportDroneRespawns.Count;
            }

            public int GetMaxPurchasableSupportDroneRequests()
            {
                return plugin != null ? plugin.GetMaxPurchasedSupportDrones(raidType) : 0;
            }

            private int GetConsumedPaidSupportDroneRequests()
            {
                int freeRequests = Mathf.Max(0, plugin?.configData?.cobaltWar?.freePurchasedSupportDronesPerWar ?? 0);
                return Mathf.Max(0, acceptedSupportDroneRequests - freeRequests);
            }

            public bool IsNextSupportDroneFree()
            {
                int freeRequests = Mathf.Max(0, plugin?.configData?.cobaltWar?.freePurchasedSupportDronesPerWar ?? 0);
                return acceptedSupportDroneRequests < freeRequests;
            }

            public int GetNextSupportDroneCost(string tierKey = null)
            {
                if (IsNextSupportDroneFree())
                    return 0;

                string resolvedTierKey = plugin != null ? plugin.NormalizeSupportDroneTierKey(tierKey) : null;
                if (string.IsNullOrEmpty(resolvedTierKey))
                    resolvedTierKey = plugin != null ? plugin.GetDefaultPurchasableSupportDroneTierKey() : null;

                return plugin != null ? plugin.GetSupportDroneTierCost(raidType, resolvedTierKey) : 0;
            }

            public string GetSupportDroneCostLabel(string tierKey = null, string userId = null)
            {
                string resolvedTierKey = plugin != null ? plugin.NormalizeSupportDroneTierKey(tierKey) : null;
                if (string.IsNullOrEmpty(resolvedTierKey))
                    resolvedTierKey = plugin != null ? plugin.GetDefaultPurchasableSupportDroneTierKey() : null;

                if (plugin == null)
                    return string.Empty;

                return plugin.GetSupportDroneTierCostLabel(raidType, resolvedTierKey, userId, !IsNextSupportDroneFree());
            }

            public bool HasHumanHelpers()
            {
                return GetConnectedHelperCount() > 0;
            }

            private int GetExternalRaidPresentPlayerCount(bool includePendingRedeploys = true)
            {
                if (!IsExternalRaidBase || plugin == null)
                    return 0;

                HashSet<ulong> participantIds = new HashSet<ulong>();

                foreach (BasePlayer activePlayer in BasePlayer.activePlayerList)
                {
                    if (activePlayer == null || !activePlayer.IsConnected || activePlayer.IsNpc || activePlayer.IsDead())
                        continue;

                    string arenaMessageKey;
                    if (plugin.IsArenaTournamentBlockingCobalt(activePlayer, true, out arenaMessageKey))
                        continue;

                    ulong userId = activePlayer.userID.Get();
                    if ((registeredDefenders.Contains(userId) || ownerTestDefenders.Contains(userId)) && plugin.ShouldCountHelperAsActive(userId))
                    {
                        participantIds.Add(userId);
                        continue;
                    }

                    if (owners.Contains(userId))
                        continue;

                    if (IsInsideCombatArea(activePlayer.transform.position))
                        participantIds.Add(userId);
                }

                if (!includePendingRedeploys)
                    return participantIds.Count;

                Func<ulong, bool> hasPendingRedeploy = userId =>
                {
                    DefenderRedeployState pendingState;
                    return plugin.pendingRedeploys.TryGetValue(userId, out pendingState)
                        && pendingState != null
                        && pendingState.warId == warId;
                };

                foreach (ulong userId in registeredDefenders)
                {
                    if (hasPendingRedeploy(userId))
                        participantIds.Add(userId);
                }

                foreach (ulong userId in ownerTestDefenders)
                {
                    if (hasPendingRedeploy(userId))
                        participantIds.Add(userId);
                }

                foreach (ulong userId in walkInDefenders)
                {
                    if (hasPendingRedeploy(userId))
                        participantIds.Add(userId);
                }

                return participantIds.Count;
            }

            private int GetExternalRaidMinimumParticipantCount()
            {
                return plugin != null ? plugin.GetExternalRaidBaseMinimumParticipantCount(raidType) : 1;
            }

            public int GetExternalRaidCurrentParticipantCount()
            {
                return GetExternalRaidPresentPlayerCount();
            }

            private bool HasAnyExternalRaidPlayersPresent(bool includePendingRedeploys = true)
            {
                if (!IsExternalRaidBase || plugin == null)
                    return true;

                return GetExternalRaidPresentPlayerCount(includePendingRedeploys) > 0;
            }

            private int GetManualSupportDroneRequestCap()
            {
                int freeRequests = Mathf.Max(0, plugin?.configData?.cobaltWar?.freePurchasedSupportDronesPerWar ?? 0);
                return Mathf.Max(0, freeRequests + GetMaxPurchasableSupportDroneRequests());
            }

            public int GetRemainingPurchasableSupportDroneRequests()
            {
                return Mathf.Max(0, GetManualSupportDroneRequestCap() - acceptedSupportDroneRequests);
            }

            public int GetPermanentSupportDroneCount()
            {
                return Mathf.Max(0, GetAutomaticSupportDroneWaveCap());
            }

            private bool ShouldMaintainAutomaticSupportDrones()
            {
                if (plugin?.configData?.cobaltWar == null || !plugin.configData.cobaltWar.enableSupportDrones)
                    return false;

                if (IsExternalRaidBase)
                    return plugin.GetAutoSupportDroneCountForWar(this) > 0;

                return plugin.configData.cobaltWar.autoSpawnSupportDronesWithoutHelpers
                    && !HasHumanHelpers()
                    && plugin.GetAutoSupportDroneCountForWar(this) > 0;
            }

            private int GetPendingPurchasedSupportDroneSlotCount()
            {
                int slots = 0;

                foreach (PendingSupportDroneRequest request in pendingSupportDroneRequests)
                {
                    if (request == null)
                        continue;

                    int requestSlots = request.slotCost > 0
                        ? request.slotCost
                        : (plugin != null ? plugin.GetSupportDroneTierSlots(request.tierKey) : 1);
                    slots += Mathf.Max(1, requestSlots);
                }

                foreach (PendingSupportDroneRespawn respawn in pendingSupportDroneRespawns)
                {
                    if (respawn == null || !respawn.purchased)
                        continue;

                    int respawnSlots = respawn.slotCost > 0
                        ? respawn.slotCost
                        : (plugin != null ? plugin.GetSupportDroneTierSlots(respawn.tierKey) : 1);
                    slots += Mathf.Max(1, respawnSlots);
                }

                return Mathf.Max(0, slots);
            }

            public int GetUsedPurchasedSupportDroneSlots()
            {
                int activeSlots = plugin != null ? plugin.GetActivePurchasedSupportDroneSlots(warId) : 0;
                return Mathf.Max(0, activeSlots + GetPendingPurchasedSupportDroneSlotCount());
            }

            public int GetPurchasedSupportDroneSlotCap()
            {
                if (plugin?.configData?.cobaltWar == null || !plugin.configData.cobaltWar.enableSupportDrones)
                    return 0;

                return Mathf.Max(0, plugin.configData.cobaltWar.maxTotalSupportDronesPerWar);
            }

            private int GetAutomaticSupportDroneWaveCap()
            {
                if (frozenAutomaticSupportDroneCap >= 0)
                    return Mathf.Max(0, frozenAutomaticSupportDroneCap);

                if (!ShouldMaintainAutomaticSupportDrones())
                    return 0;

                return plugin.GetAutoSupportDroneCountForWar(this);
            }

            private int GetPlannedAutomaticSupportDroneCount()
            {
                if (automaticSupportDronesResolved)
                    return 0;

                int automaticCap = GetAutomaticSupportDroneWaveCap();
                if (automaticCap <= 0)
                    return 0;

                return automaticCap;
            }

            internal void ScheduleSupportDroneRespawn(CobaltSupportDroneState state)
            {
                if (state == null || plugin == null || cleanupStarted || IsEnded || phase != CobaltWarPhase.Active)
                    return;

                pendingSupportDroneRespawns.Add(new PendingSupportDroneRespawn
                {
                    tierKey = state.tierKey,
                    slotCost = state.slotCost,
                    purchased = state.purchased,
                    requesterUserId = state.requestedByUserId,
                    respawnAt = Time.realtimeSinceStartup + CobaltSupportDroneRespawnDelaySeconds
                });

                if (nextSupportDroneRespawnCheck <= 0f)
                    nextSupportDroneRespawnCheck = Time.realtimeSinceStartup + CobaltSupportDroneRespawnDelaySeconds;
                else
                    nextSupportDroneRespawnCheck = Mathf.Min(nextSupportDroneRespawnCheck, Time.realtimeSinceStartup + CobaltSupportDroneRespawnDelaySeconds);

                plugin.UpdateWarJoinUi(this);
            }

            private void FreezeSupportDroneCaps()
            {
                if (frozenSupportDroneCountCap >= 0)
                    return;

                if (plugin?.configData?.cobaltWar == null || !plugin.configData.cobaltWar.enableSupportDrones)
                {
                    frozenAutomaticSupportDroneCap = 0;
                    frozenSupportDroneCountCap = 0;
                    return;
                }

                int automaticCap = 0;

                if (ShouldMaintainAutomaticSupportDrones())
                {
                    automaticCap = plugin.GetAutoSupportDroneCountForWar(this);
                }

                frozenAutomaticSupportDroneCap = Mathf.Max(0, automaticCap);
                frozenSupportDroneCountCap = Mathf.Max(0, plugin?.configData?.cobaltWar?.maxTotalSupportDronesPerWar ?? 0);
            }

            public void NotifySupportDroneParticipants(string messageKey, params object[] args)
            {
                foreach (ulong userId in owners.Concat(GetAllRegisteredDefenders()).Concat(walkInDefenders).Distinct())
                {
                    BasePlayer player = BasePlayer.FindByID(userId);
                    if (player == null || !player.IsConnected)
                        continue;

                    plugin.SendLocalizedReply(player, messageKey, args);
                }
            }

            public bool CanRequestSupportDrone(BasePlayer player, out string messageKey)
            {
                string ignoredTierKey;
                int ignoredSlotCost;
                int ignoredCost;
                return CanRequestSupportDrone(player, null, out ignoredTierKey, out ignoredSlotCost, out ignoredCost, out messageKey);
            }

            public bool CanRequestSupportDrone(BasePlayer player, string requestedTierKey, out string resolvedTierKey, out int slotCost, out int cost, out string messageKey)
            {
                resolvedTierKey = null;
                slotCost = 0;
                cost = 0;
                messageKey = null;

                if (player == null || plugin == null || plugin.configData?.cobaltWar == null || !plugin.configData.cobaltWar.enableSupportDrones)
                {
                    messageKey = "CobaltSupportDroneUnavailable";
                    return false;
                }

                if (cleanupStarted || IsEnded || phase == CobaltWarPhase.Buyout || phase == CobaltWarPhase.Cleanup)
                {
                    messageKey = "CobaltSupportDroneUnavailable";
                    return false;
                }

                if (!owners.Contains(player.userID.Get()))
                {
                    messageKey = "CobaltSupportDroneOwnerOnly";
                    return false;
                }

                resolvedTierKey = plugin.NormalizeSupportDroneTierKey(requestedTierKey);
                if (string.IsNullOrEmpty(resolvedTierKey))
                    resolvedTierKey = plugin.GetDefaultPurchasableSupportDroneTierKey();

                SupportDroneTierConfig tier = plugin.GetSupportDroneTier(resolvedTierKey);
                if (tier == null)
                {
                    messageKey = "CobaltSupportDroneUnavailable";
                    return false;
                }

                bool isFreeRequest = IsNextSupportDroneFree();
                if (!isFreeRequest && GetConsumedPaidSupportDroneRequests() >= GetMaxPurchasableSupportDroneRequests())
                {
                    messageKey = "CobaltSupportDroneMaxReached";
                    return false;
                }

                slotCost = plugin.GetSupportDroneTierSlots(resolvedTierKey);
                int slotLimit = GetPurchasedSupportDroneSlotCap();
                if (slotLimit > 0 && GetUsedPurchasedSupportDroneSlots() + slotCost > slotLimit)
                {
                    messageKey = "CobaltSupportDroneSlotLimitReached";
                    return false;
                }

                cost = isFreeRequest ? 0 : GetNextSupportDroneCost(resolvedTierKey);
                if (cost > 0)
                {
                    if (plugin.ServerRewards == null)
                    {
                        messageKey = "CobaltSupportDroneNoServerRewards";
                        return false;
                    }

                    if (plugin.GetServerRewardsBalance(player.userID.Get()) < cost)
                    {
                        messageKey = "CobaltSupportDroneNotEnoughCurrency";
                        return false;
                    }
                }

                return true;
            }

            public bool TryRequestSupportDrone(BasePlayer player, string requestedTierKey = null)
            {
                string resolvedTierKey;
                int slotCost;
                int nextCost;
                string messageKey;
                if (!CanRequestSupportDrone(player, requestedTierKey, out resolvedTierKey, out slotCost, out nextCost, out messageKey))
                {
                    if (!string.IsNullOrEmpty(messageKey))
                    {
                        if (messageKey == "CobaltSupportDroneNotEnoughCurrency")
                            plugin.SendReply(player, plugin.lang.GetMessage(messageKey, plugin, player.UserIDString), nextCost);
                        else
                            plugin.SendReply(player, plugin.lang.GetMessage(messageKey, plugin, player.UserIDString));
                    }
                    return false;
                }

                bool chargeNow = phase != CobaltWarPhase.Active || raidManager == null || raidManager.isDestroyed;
                if (chargeNow && nextCost > 0 && !plugin.TryTakeServerRewardsPoints(player.userID.Get(), nextCost))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltSupportDroneNotEnoughCurrency", plugin, player.UserIDString), nextCost);
                    return false;
                }

                if (!chargeNow)
                {
                    if (nextCost > 0 && !plugin.TryTakeServerRewardsPoints(player.userID.Get(), nextCost))
                    {
                        plugin.SendReply(player, plugin.lang.GetMessage("CobaltSupportDroneNotEnoughCurrency", plugin, player.UserIDString), nextCost);
                        return false;
                    }

                    if (!plugin.SpawnCobaltSupportDrone(this, raidManager, true, player.userID.Get(), resolvedTierKey))
                    {
                        if (nextCost > 0)
                            plugin.TryAddServerRewardsPoints(player.userID.Get(), nextCost);
                        plugin.SendReply(player, plugin.lang.GetMessage("CobaltSupportDroneUnavailable", plugin, player.UserIDString));
                        return false;
                    }

                    acceptedSupportDroneRequests++;
                    NotifySupportDroneParticipants(
                        nextCost > 0 ? "CobaltSupportDronePurchased" : "CobaltSupportDroneFreeGranted",
                        player.displayName,
                        plugin.GetGrid(location),
                        GetActivePurchasedSupportDroneCount(),
                        GetPurchasedSupportDroneSlotCap(),
                        nextCost,
                        plugin.GetSupportDroneTierDisplayName(resolvedTierKey),
                        slotCost,
                        GetUsedPurchasedSupportDroneSlots());
                    plugin.UpdateWarJoinUi(this);
                    return true;
                }

                acceptedSupportDroneRequests++;
                pendingSupportDroneRequests.Enqueue(new PendingSupportDroneRequest
                {
                    requesterUserId = player.userID.Get(),
                    cost = nextCost,
                    tierKey = resolvedTierKey,
                    slotCost = slotCost
                });

                NotifySupportDroneParticipants(
                    nextCost > 0 ? "CobaltSupportDroneQueuedPaid" : "CobaltSupportDroneQueuedFree",
                    player.displayName,
                    plugin.GetGrid(location),
                    nextCost,
                    plugin.GetSupportDroneTierDisplayName(resolvedTierKey),
                    slotCost);
                plugin.UpdateWarJoinUi(this);
                return true;
            }

            public int GetSupportDroneCountCap()
            {
                return GetPurchasedSupportDroneSlotCap();
            }

            private void RefundPendingSupportDroneRequests()
            {
                while (pendingSupportDroneRequests.Count > 0)
                {
                    PendingSupportDroneRequest request = pendingSupportDroneRequests.Dequeue();
                    if (request == null || request.cost <= 0)
                        continue;

                    if (!plugin.TryAddServerRewardsPoints(request.requesterUserId, request.cost))
                        continue;

                    BasePlayer requester = BasePlayer.FindByID(request.requesterUserId);
                    if (requester != null && requester.IsConnected)
                        plugin.SendReply(requester, plugin.lang.GetMessage("CobaltSupportDroneRefunded", plugin, requester.UserIDString), request.cost);
                }
            }

            private void SpawnPendingSupportDroneRequests()
            {
                if (raidManager == null || raidManager.isDestroyed || cleanupStarted || IsEnded)
                    return;

                int safety = 0;
                while (pendingSupportDroneRequests.Count > 0 && safety++ < 32)
                {
                    PendingSupportDroneRequest request = pendingSupportDroneRequests.Peek();
                    if (request == null)
                    {
                        pendingSupportDroneRequests.Dequeue();
                        continue;
                    }

                    if (GetPurchasedSupportDroneSlotCap() > 0 && GetUsedPurchasedSupportDroneSlots() > GetPurchasedSupportDroneSlotCap())
                        break;

                    if (!plugin.SpawnCobaltSupportDrone(this, raidManager, true, request.requesterUserId, request.tierKey, true))
                    {
                        pendingSupportDroneRequests.Dequeue();
                        request.attempts++;

                        if (request.attempts >= 5)
                        {
                            acceptedSupportDroneRequests = Mathf.Max(0, acceptedSupportDroneRequests - 1);

                            if (request.cost > 0 && plugin.TryAddServerRewardsPoints(request.requesterUserId, request.cost))
                            {
                                BasePlayer requester = BasePlayer.FindByID(request.requesterUserId);
                                if (requester != null && requester.IsConnected)
                                    plugin.SendReply(requester, plugin.lang.GetMessage("CobaltSupportDroneRefunded", plugin, requester.UserIDString), request.cost);
                            }
                            else
                            {
                                BasePlayer requester = BasePlayer.FindByID(request.requesterUserId);
                                if (requester != null && requester.IsConnected)
                                    plugin.SendReply(requester, plugin.lang.GetMessage("CobaltSupportDroneUnavailable", plugin, requester.UserIDString));
                            }

                            plugin.UpdateWarJoinUi(this);
                            continue;
                        }

                        pendingSupportDroneRequests.Enqueue(request);
                        break;
                    }

                    pendingSupportDroneRequests.Dequeue();
                }
            }

            private void SpawnPendingSupportDroneRespawns()
            {
                if (raidManager == null || raidManager.isDestroyed || cleanupStarted || IsEnded || phase != CobaltWarPhase.Active)
                    return;

                float now = Time.realtimeSinceStartup;
                bool changed = false;
                float nextDueAt = 0f;

                for (int index = pendingSupportDroneRespawns.Count - 1; index >= 0; index--)
                {
                    PendingSupportDroneRespawn request = pendingSupportDroneRespawns[index];
                    if (request == null)
                    {
                        pendingSupportDroneRespawns.RemoveAt(index);
                        changed = true;
                        continue;
                    }

                    if (request.respawnAt > now)
                    {
                        nextDueAt = nextDueAt <= 0f ? request.respawnAt : Mathf.Min(nextDueAt, request.respawnAt);
                        continue;
                    }

                    if (request.purchased && GetPurchasedSupportDroneSlotCap() > 0 && GetUsedPurchasedSupportDroneSlots() > GetPurchasedSupportDroneSlotCap())
                    {
                        nextDueAt = now + 1f;
                        continue;
                    }

                    if (!plugin.SpawnCobaltSupportDrone(this, raidManager, request.purchased, request.requesterUserId, request.tierKey, request.purchased))
                    {
                        request.attempts++;
                        request.respawnAt = now + Mathf.Min(5f * Mathf.Max(1, request.attempts), 15f);
                        nextDueAt = nextDueAt <= 0f ? request.respawnAt : Mathf.Min(nextDueAt, request.respawnAt);
                        continue;
                    }

                    pendingSupportDroneRespawns.RemoveAt(index);
                    changed = true;
                }

                nextSupportDroneRespawnCheck = pendingSupportDroneRespawns.Count > 0
                    ? (nextDueAt > 0f ? nextDueAt : now + 1f)
                    : 0f;

                if (changed)
                    plugin.UpdateWarJoinUi(this);
            }

            private void SpawnAutomaticSupportDrones()
            {
                if (cleanupStarted || IsEnded || raidManager == null || raidManager.isDestroyed || plugin.configData?.cobaltWar == null)
                    return;

                automaticSupportDronesResolved = true;
                int count = GetAutomaticSupportDroneWaveCap();
                if (!ShouldMaintainAutomaticSupportDrones() || count <= 0)
                    return;

                int spawned = 0;
                for (int i = 0; i < count; i++)
                {
                    if (plugin.SpawnCobaltSupportDrone(this, raidManager, false))
                        spawned++;
                }

                if (spawned > 0)
                {
                    NotifySupportDroneParticipants("CobaltSupportDroneAutoIncoming", spawned, plugin.GetGrid(location));
                    plugin.UpdateWarJoinUi(this);
                }
            }

            private void ScheduleAutomaticSupportDrones()
            {
                if (automaticSupportDronesScheduled || cleanupStarted || IsEnded || plugin?.configData?.cobaltWar == null)
                    return;

                if (!ShouldMaintainAutomaticSupportDrones() || GetAutomaticSupportDroneWaveCap() <= 0)
                    return;

                automaticSupportDronesScheduled = true;
                float delay = Mathf.Max(0f, plugin.configData.cobaltWar.autoSupportDroneDelaySeconds);
                plugin.timer.Once(delay, () =>
                {
                    if (this == null || cleanupStarted || IsEnded || phase != CobaltWarPhase.Active)
                        return;

                    SpawnAutomaticSupportDrones();
                });
            }

            public bool RemoveRegisteredDefender(ulong userId, bool restoreSnapshot, string messageKey = null)
            {
                bool removed = registeredDefenders.Remove(userId);
                removed = ownerTestDefenders.Remove(userId) || removed;
                removed = disconnectedRegisteredDefenders.Remove(userId) || removed;
                removed = disconnectedOwnerTestDefenders.Remove(userId) || removed;

                if (!removed)
                    return false;

                plugin.pendingRedeploys.Remove(userId);
                plugin.ClearDefenderActivity(userId);
                plugin.ClearDefenderRespawnProtection(userId);

                BasePlayer player = BasePlayer.FindByID(userId);
                if (player != null && !string.IsNullOrEmpty(messageKey))
                    plugin.SendReply(player, plugin.lang.GetMessage(messageKey, plugin, player.UserIDString));

                DefenderSnapshot snapshot;
                if (restoreSnapshot && plugin.TryGetDefenderSnapshot(userId, out snapshot) && snapshot != null)
                {
                    if (player != null && player.IsConnected)
                        ServerMgr.Instance.StartCoroutine(plugin.RestoreDefenderSnapshot(player));
                }
                else if (restoreSnapshot && player != null && player.IsConnected)
                {
                    plugin.TryRestoreDisconnectedRaidRecovery(player);
                }

                plugin.UpdateWarJoinUi(this);
                return true;
            }

            public bool LeaveDefender(BasePlayer player)
            {
                if (player == null)
                    return false;

                if (phase != CobaltWarPhase.Registration && phase != CobaltWarPhase.Preparation && phase != CobaltWarPhase.Cleanup)
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltLeaveUnavailable", plugin, player.UserIDString));
                    return false;
                }

                if (!RemoveRegisteredDefender(player.userID.Get(), true))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltLeaveUnavailable", plugin, player.UserIDString));
                    return false;
                }

                plugin.ClearWarUiDismiss(player.userID, warId);
                plugin.SendReply(player, plugin.lang.GetMessage("CobaltLeaveSuccess", plugin, player.UserIDString), targetName, plugin.GetGrid(location));
                return true;
            }

            public bool IsFriendlyParticipant(ulong userId)
            {
                return owners.Contains(userId) || registeredDefenders.Contains(userId) || ownerTestDefenders.Contains(userId) || walkInDefenders.Contains(userId);
            }

            public bool IsDisconnectedDefender(ulong userId)
            {
                return disconnectedRegisteredDefenders.Contains(userId) || disconnectedOwnerTestDefenders.Contains(userId);
            }

            public bool CanReturnDefender(ulong userId)
            {
                if (!IsDisconnectedDefender(userId))
                    return false;

                if (phase == CobaltWarPhase.Registration || phase == CobaltWarPhase.Preparation)
                    return true;

                return IsCombatRespawnWindowOpen();
            }

            public bool IsNaturalCombatRespawnEligible(ulong userId, bool includePending = false)
            {
                if (IsRegisteredDefender(userId))
                    return false;

                if (owners.Contains(userId))
                    return plugin.configData.cobaltWar.enableOwnerNaturalCombatRespawn;

                if (walkInDefenders.Contains(userId))
                    return plugin.configData.cobaltWar.enableWalkInNaturalCombatRespawn
                        && HasUnlockedWalkInNaturalRespawn(userId)
                        && IsWalkInDefenderCurrentlyActive(userId);

                if (includePending)
                {
                    DefenderRedeployState pendingState;
                    if (plugin.pendingRedeploys.TryGetValue(userId, out pendingState) && pendingState != null && pendingState.warId == warId && !pendingState.useDefenderLoadout)
                        return owners.Contains(userId)
                            ? plugin.configData.cobaltWar.enableOwnerNaturalCombatRespawn
                            : plugin.configData.cobaltWar.enableWalkInNaturalCombatRespawn;
                }

                return false;
            }

            public bool CanUseNaturalCombatRespawn(BasePlayer player, bool allowDeadInZone = false)
            {
                if (player == null || !IsCombatRespawnWindowOpen())
                    return false;

                ulong userId = player.userID.Get();
                if (IsRegisteredDefender(userId))
                    return false;

                if (owners.Contains(userId))
                    return plugin.configData.cobaltWar.enableOwnerNaturalCombatRespawn;

                return plugin.configData.cobaltWar.enableWalkInNaturalCombatRespawn
                    && IsWalkInDefenderCurrentlyActive(userId, allowDeadInZone)
                    && HasUnlockedWalkInNaturalRespawn(userId);
            }

            internal bool IsCombatRespawnWindowOpen()
            {
                if (IsEnded)
                    return false;

                if (phase == CobaltWarPhase.Active)
                    return true;

                return phase == CobaltWarPhase.Cleanup
                    && postRaidCombatGraceActive
                    && Time.realtimeSinceStartup < phaseEndTime;
            }

            public int GetHelperCount()
            {
                int total = 0;

                foreach (var userId in registeredDefenders.Concat(disconnectedRegisteredDefenders))
                {
                    if (!owners.Contains(userId))
                        total++;
                }

                foreach (var userId in ownerTestDefenders.Concat(disconnectedOwnerTestDefenders))
                {
                    if (!registeredDefenders.Contains(userId) && !disconnectedRegisteredDefenders.Contains(userId))
                        total++;
                }

                foreach (var userId in walkInDefenders)
                {
                    if (!owners.Contains(userId) && !registeredDefenders.Contains(userId) && !ownerTestDefenders.Contains(userId))
                        total++;
                }

                return total;
            }

            private int GetScaledDefenderCount()
            {
                int total = 0;

                foreach (var userId in registeredDefenders)
                {
                    if (!owners.Contains(userId) && plugin.ShouldCountHelperAsActive(userId))
                        total++;
                }

                foreach (var userId in walkInDefenders)
                {
                    if (!registeredDefenders.Contains(userId) && !ownerTestDefenders.Contains(userId) && !owners.Contains(userId) && IsWalkInDefenderCurrentlyActive(userId) && plugin.ShouldCountHelperAsActive(userId))
                        total++;
                }

                return total;
            }

            public int GetOwnerCount()
            {
                return owners.Distinct().Count();
            }

            public int GetCurrentWaveNumber()
            {
                if (phase != CobaltWarPhase.Active || raidManager == null)
                    return 0;

                return Mathf.Clamp(raidManager.currentWave, 0, GetTotalWaveCount());
            }

            public int GetTotalWaveCount()
            {
                if (raidManager != null && raidManager.config != null)
                    return Mathf.Max(1, raidManager.config.TotalNpcWaves + 1);

                int defenders = GetScaledDefenderCount();
                int totalAdditionalWaves = raidProfile != null ? raidProfile.TotalNpcWaves : 0;

                if (balanceTier != null)
                    totalAdditionalWaves += balanceTier.extraWaves;

                totalAdditionalWaves += GetExtraWavesFromHelpers(defenders);
                return Mathf.Max(1, totalAdditionalWaves + 1);
            }

            public int GetAliveNpcCount()
            {
                if (phase != CobaltWarPhase.Active || raidManager == null || raidManager.members == null)
                    return 0;

                return raidManager.members.Count;
            }

            public int GetDefenseProgressPercent()
            {
                if (phase == CobaltWarPhase.Cleanup)
                    return CompletedSuccessfully ? 100 : 0;

                int totalWaves = GetTotalWaveCount();
                if (totalWaves <= 0)
                    return 0;

                int npcPerWave;
                if (raidManager != null && raidManager.config != null)
                    npcPerWave = Mathf.Max(1, raidManager.config.TotalNpcs);
                else
                {
                    int defenders = GetScaledDefenderCount();
                    npcPerWave = Mathf.Max(1, (raidProfile != null ? raidProfile.TotalNpcs : 0) + (balanceTier != null ? balanceTier.extraNpcPerWave : 0) + GetExtraNpcPerWaveFromHelpers(defenders));
                }

                if (phase != CobaltWarPhase.Active || raidManager == null)
                    return 0;

                int currentWave = Mathf.Clamp(raidManager.currentWave, 1, totalWaves);
                int completedWaves = Mathf.Clamp(currentWave - 1, 0, totalWaves);
                int aliveNpc = Mathf.Clamp(GetAliveNpcCount(), 0, npcPerWave);
                int defeatedInCurrentWave = Mathf.Clamp(npcPerWave - aliveNpc, 0, npcPerWave);
                float completedUnits = (completedWaves * npcPerWave) + defeatedInCurrentWave;
                float totalUnits = totalWaves * npcPerWave;

                if (totalUnits <= 0f)
                    return 0;

                return Mathf.Clamp(Mathf.RoundToInt((completedUnits / totalUnits) * 100f), 0, 100);
            }

            public int GetRegisteredDefenderCount()
            {
                return GetAllUiRegisteredDefenders().Count;
            }

            public int GetWalkInDefenderCount()
            {
                return walkInDefenders.Count(userId => IsWalkInDefenderCurrentlyActive(userId));
            }

            private bool HasUnlockedWalkInNaturalRespawn(ulong userId)
            {
                if (!plugin.configData.cobaltWar.enableWalkInNaturalCombatRespawn)
                    return false;

                double enteredAt;
                if (!walkInPresenceSince.TryGetValue(userId, out enteredAt))
                    return false;

                float activationSeconds = Mathf.Max(0f, plugin.configData.cobaltWar.walkInNaturalRespawnActivationSeconds);
                return GrabCurrentTime() - enteredAt >= activationSeconds;
            }

            private bool IsWalkInDefenderCurrentlyActive(ulong userId, bool allowDeadInZone = false)
            {
                if (!walkInDefenders.Contains(userId))
                    return false;

                BasePlayer player = BasePlayer.FindByID(userId);
                if (player != null && player.IsConnected && IsInsideCombatArea(player.transform.position) && (!player.IsDead() || allowDeadInZone))
                    return true;

                DefenderRedeployState pendingState;
                return plugin.pendingRedeploys.TryGetValue(userId, out pendingState)
                    && pendingState != null
                    && pendingState.warId == warId
                    && !pendingState.useDefenderLoadout;
            }

            internal void PreserveWalkInNaturalRespawnEligibility(ulong userId)
            {
                if (owners.Contains(userId))
                    return;

                walkInDefenders.Add(userId);
                walkInPresenceSince[userId] = GrabCurrentTime() - Mathf.Max(0f, plugin.configData.cobaltWar.walkInNaturalRespawnActivationSeconds);
            }

            public int GetConnectedHelperCount()
            {
                int total = 0;

                Action<ulong> addIfConnected = userId =>
                {
                    if (owners.Contains(userId))
                        return;

                    if (plugin.ShouldCountHelperAsActive(userId))
                        total++;
                };

                foreach (var userId in registeredDefenders)
                    addIfConnected(userId);
                foreach (var userId in ownerTestDefenders)
                    addIfConnected(userId);
                foreach (var userId in walkInDefenders)
                {
                    if (!registeredDefenders.Contains(userId) && !ownerTestDefenders.Contains(userId) && IsWalkInDefenderCurrentlyActive(userId))
                        addIfConnected(userId);
                }

                return total;
            }

            public bool MarkDefenderDisconnected(ulong userId)
            {
                bool moved = false;

                if (registeredDefenders.Remove(userId))
                {
                    disconnectedRegisteredDefenders.Add(userId);
                    moved = true;
                }

                if (ownerTestDefenders.Remove(userId))
                {
                    disconnectedOwnerTestDefenders.Add(userId);
                    moved = true;
                }

                if (moved)
                    plugin.UpdateWarJoinUi(this);

                return moved;
            }

            private bool RestoreDisconnectedDefenderMembership(ulong userId)
            {
                bool restored = false;

                if (disconnectedRegisteredDefenders.Remove(userId))
                {
                    registeredDefenders.Add(userId);
                    restored = true;
                }

                if (disconnectedOwnerTestDefenders.Remove(userId))
                {
                    ownerTestDefenders.Add(userId);
                    restored = true;
                }

                return restored;
            }

            public bool ReturnDisconnectedDefender(BasePlayer player)
            {
                if (player == null)
                    return false;

                ulong userId = player.userID.Get();
                if (!CanReturnDefender(userId))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltReturnUnavailable", plugin, player.UserIDString));
                    return false;
                }

                if (!RestoreDisconnectedDefenderMembership(userId))
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltReturnUnavailable", plugin, player.UserIDString));
                    return false;
                }

                plugin.ClearWarUiDismiss(player.userID, warId);
                plugin.TouchDefenderActivity(player, true);

                DefenderRedeployState redeploy;
                if (plugin.pendingRedeploys.TryGetValue(userId, out redeploy) && redeploy != null && redeploy.warId == warId && redeploy.useDefenderLoadout)
                {
                    HandleRegisteredDefenderRespawn(player);
                }
                else if (phase == CobaltWarPhase.Preparation || phase == CobaltWarPhase.Active || (phase == CobaltWarPhase.Cleanup && postRaidCombatGraceActive))
                {
                    if (!plugin.TryRestoreDisconnectedRaidLoadoutForReturn(this, player))
                        plugin.PrepareRegisteredDefender(this, player, false);
                }
                else
                {
                    plugin.SendReply(player, plugin.lang.GetMessage("CobaltReturnSuccess", plugin, player.UserIDString), targetName, plugin.GetGrid(location));
                }

                plugin.UpdateWarJoinUi(this);
                return true;
            }

            public bool IsRegisteredDefender(ulong userId) => registeredDefenders.Contains(userId) || ownerTestDefenders.Contains(userId);

            public bool IsUiRegisteredDefender(ulong userId) => IsRegisteredDefender(userId) || IsDisconnectedDefender(userId);

            public bool IsInsideCombatArea(Vector3 position) => Vector3.Distance(location, position) <= plugin.configData.cobaltWar.combatRadius;

            private int GetExtraNpcPerWaveFromHelpers(int defenders)
            {
                if (defenders <= 0)
                    return 0;

                int perHelper = Mathf.Max(0, plugin.configData.cobaltWar.extraNpcPerActiveHelper);
                int maxExtra = Mathf.Max(0, plugin.configData.cobaltWar.maxExtraNpcPerWaveFromHelpers);
                return Mathf.Clamp(defenders * perHelper, 0, maxExtra);
            }

            private int GetExtraWavesFromHelpers(int defenders)
            {
                if (defenders <= 0)
                    return 0;

                int helpersPerWave = Mathf.Max(1, plugin.configData.cobaltWar.activeHelpersPerExtraWave);
                int maxExtra = Mathf.Max(0, plugin.configData.cobaltWar.maxExtraWavesFromHelpers);
                return Mathf.Clamp(defenders / helpersPerWave, 0, maxExtra);
            }

            private int GetExtraSecondsFromHelpers(int defenders)
            {
                if (defenders <= 0)
                    return 0;

                int perHelper = Mathf.Max(0, plugin.configData.cobaltWar.extraSecondsPerActiveHelper);
                int maxExtra = Mathf.Max(0, plugin.configData.cobaltWar.maxExtraSecondsFromHelpers);
                return Mathf.Clamp(defenders * perHelper, 0, maxExtra);
            }

            public List<ulong> GetRewardEligiblePlayers()
            {
                HashSet<ulong> eligible = new HashSet<ulong>();

                foreach (var userId in owners)
                    eligible.Add(userId);
                foreach (var userId in registeredDefenders)
                    eligible.Add(userId);
                foreach (var userId in disconnectedRegisteredDefenders)
                    eligible.Add(userId);
                foreach (var userId in disconnectedOwnerTestDefenders)
                    eligible.Add(userId);
                foreach (var userId in walkInDefenders)
                    eligible.Add(userId);
                foreach (var userId in totalDamage.Keys)
                    eligible.Add(userId);

                if (targetUserId != 0UL)
                    eligible.Add(targetUserId);

                return eligible.ToList();
            }

            private bool IsVictoryRoulettePresentPlayer(ulong userId)
            {
                if (userId == 0UL)
                    return false;

                BasePlayer player = BasePlayer.FindByID(userId);
                if (player == null || !player.IsConnected || player.IsNpc)
                    return false;

                DefenderRedeployState pendingState;
                if (plugin.pendingRedeploys.TryGetValue(userId, out pendingState) && pendingState != null && pendingState.warId == warId)
                    return true;

                if (player.IsDead())
                    return false;

                return IsInsideCombatArea(player.transform.position);
            }

            private List<ulong> GetVictoryRouletteEligiblePlayers()
            {
                HashSet<ulong> candidates = new HashSet<ulong>();

                foreach (var userId in owners)
                    candidates.Add(userId);
                foreach (var userId in registeredDefenders)
                    candidates.Add(userId);
                foreach (var userId in ownerTestDefenders)
                    candidates.Add(userId);
                foreach (var userId in walkInDefenders)
                    candidates.Add(userId);

                return candidates
                    .Where(IsVictoryRoulettePresentPlayer)
                    .ToList();
            }

            private void BeginPreparation()
            {
                if (!RefreshPreStartState(true))
                    return;

                plugin.PruneInactiveRegisteredDefenders(this);

                if (!IsExternalRaidBase && trigger != CobaltWarTrigger.Manual && plugin.configData.settings.mustBeOnlinePlayer && !plugin.HasEligibleOnlineAuthorizedPlayer(privilege))
                {
                    string ownerAvailabilityMessageKey = plugin.GetAuthorizedRaidAvailabilityMessageKey(privilege, owners);
                    foreach (ulong userId in GetAllRegisteredDefenders())
                    {
                        BasePlayer player = BasePlayer.FindByID(userId);
                        if (player != null && player.IsConnected)
                            plugin.SendReply(player, plugin.lang.GetMessage(ownerAvailabilityMessageKey, plugin, player.UserIDString));
                    }

                    cleanupOwnerMessageKey = ownerAvailabilityMessageKey;
                    cancelledBeforeRaid = true;
                    CompletedSuccessfully = false;
                    BeginCleanup();
                    return;
                }

                phase = CobaltWarPhase.Preparation;
                phaseEndTime = Time.realtimeSinceStartup + plugin.configData.cobaltWar.preparationSeconds;
                plugin.CobaltDiagnosticLog("raid", $"Война #{warId}: этап Preparation, registered={registeredDefenders.Count}, walkIns={walkInDefenders.Count}, external={IsExternalRaidBase}.");

                foreach (var userId in GetAllRegisteredDefenders())
                {
                    BasePlayer player = BasePlayer.FindByID(userId);
                    if (player == null || !player.IsConnected)
                        continue;
                    plugin.PrepareRegisteredDefender(this, player, false);
                }

                plugin.UpdateWarJoinUi(this);
            }

            private raidConfig BuildScaledProfile()
            {
                raidConfig scaled = plugin.CloneRaidConfig(raidProfile);
                int defenders = GetScaledDefenderCount();

                if (balanceTier != null)
                {
                    scaled.TotalNpcWaves += balanceTier.extraWaves;
                    scaled.TotalNpcs += balanceTier.extraNpcPerWave;
                }

                scaled.TotalNpcWaves += GetExtraWavesFromHelpers(defenders);
                scaled.TotalNpcs += GetExtraNpcPerWaveFromHelpers(defenders);
                scaled.RunTimeSeconds += GetExtraSecondsFromHelpers(defenders);
                scaled.notifyOwners = !IsExternalRaidBase;

                if (!plugin.configData.cobaltWar.enableTanks)
                {
                    scaled.spawnTanks = false;
                    scaled.tankCount = 0;
                }
                else if (scaled.spawnTanks)
                {
                    if (IsRockBaseTerrain)
                        scaled.tankCount += Mathf.Max(0, plugin.configData.cobaltWar.rockBaseExtraTanks);

                    scaled.tankCount = Mathf.Clamp(scaled.tankCount, 0, 4);
                }

                if (IsRockBaseTerrain)
                {
                    List<string> rockCopterProfiles = new List<string>();

                    if (scaled.spawnCopter != null && scaled.spawnCopter.Count > 0)
                        rockCopterProfiles.AddRange(scaled.spawnCopter.Where(x => !string.IsNullOrEmpty(x) && plugin.configData.copterSettings.copterProfile.ContainsKey(x)));

                    if (rockCopterProfiles.Count == 0 && plugin.configData.cobaltWar.rockBaseFallbackCopterProfiles != null)
                        rockCopterProfiles.AddRange(plugin.configData.cobaltWar.rockBaseFallbackCopterProfiles.Where(x => !string.IsNullOrEmpty(x) && plugin.configData.copterSettings.copterProfile.ContainsKey(x)));

                    if (rockCopterProfiles.Count == 0)
                    {
                        string fallbackProfile = plugin.configData.copterSettings.copterProfile.Keys.FirstOrDefault();
                        if (!string.IsNullOrEmpty(fallbackProfile))
                            rockCopterProfiles.Add(fallbackProfile);
                    }

                    if (rockCopterProfiles.Count > 0)
                    {
                        int targetHeliCount = Mathf.Clamp(rockCopterProfiles.Count + Mathf.Max(0, plugin.configData.cobaltWar.rockBaseExtraCopters), 2, 5);
                        string repeatProfile = rockCopterProfiles.Last();
                        while (rockCopterProfiles.Count < targetHeliCount)
                            rockCopterProfiles.Add(repeatProfile);

                        scaled.attackCopter = true;
                        scaled.spawnCopter = rockCopterProfiles;
                    }
                }

                return scaled;
            }

            private void BeginActive()
            {
                if (!RefreshPreStartState(true))
                    return;

                plugin.PruneInactiveRegisteredDefenders(this);
                phase = CobaltWarPhase.Active;
                RefreshWalkIns();

                if (IsExternalRaidBase)
                {
                    int participantCount = GetExternalRaidPresentPlayerCount();
                    int requiredParticipantCount = GetExternalRaidMinimumParticipantCount();

                    if (participantCount <= 0)
                    {
                        CancelBeforeRaid("CobaltWarCancelledExternalNoPlayers");
                        return;
                    }

                    if (participantCount < requiredParticipantCount)
                    {
                        plugin.BroadcastLocalizedChat("CobaltWarCancelledExternalNotEnoughPlayersBroadcast", requiredParticipantCount, participantCount);
                        CancelBeforeRaid("CobaltWarCancelledExternalNotEnoughPlayers");
                        return;
                    }
                }

                if (!IsExternalRaidBase && trigger != CobaltWarTrigger.Manual && plugin.configData.settings.mustBeOnlinePlayer && !plugin.HasEligibleOnlineAuthorizedPlayer(privilege))
                {
                    string ownerAvailabilityMessageKey = plugin.GetAuthorizedRaidAvailabilityMessageKey(privilege, owners);
                    foreach (ulong userId in GetAllRegisteredDefenders())
                    {
                        BasePlayer player = BasePlayer.FindByID(userId);
                        if (player != null && player.IsConnected)
                            plugin.SendReply(player, plugin.lang.GetMessage(ownerAvailabilityMessageKey, plugin, player.UserIDString));
                    }

                    cleanupOwnerMessageKey = ownerAvailabilityMessageKey;
                    cancelledBeforeRaid = true;
                    CompletedSuccessfully = false;
                    BeginCleanup();
                    return;
                }

                FreezeSupportDroneCaps();
                raidConfig scaled = BuildScaledProfile();
                phaseEndTime = Time.realtimeSinceStartup + scaled.RunTimeSeconds;
                plugin.CobaltDiagnosticLog("raid", $"Война #{warId}: этап Active, raidType={raidType}, totalWaves={scaled.TotalNpcWaves}, totalNpcs={scaled.TotalNpcs}, tanks={scaled.tankCount}, copters={(scaled.spawnCopter != null ? scaled.spawnCopter.Count : 0)}, external={IsExternalRaidBase}.");
                string startFailReason = plugin.GetRaidStartFailureMessageKey(new List<ulong>(owners), raidType, scaled, this, bypassStartOnlineRequirement);
                if (!string.IsNullOrEmpty(startFailReason))
                {
                    cleanupOwnerMessageKey = startFailReason;
                    cancelledBeforeRaid = true;
                    CompletedSuccessfully = false;
                    BeginCleanup();
                    return;
                }

                raidManager = CobaltWar.startRandomRaid(location, new List<ulong>(owners), raidType, blocks, 0.1f, scaled, this, bypassStartOnlineRequirement);
                if (raidManager == null)
                {
                    cleanupOwnerMessageKey = "CobaltWarCancelledStartFailed";
                    cancelledBeforeRaid = true;
                    CompletedSuccessfully = false;
                    BeginCleanup();
                    return;
                }

                ApplyRaidCooldownNow();
                if (trigger == CobaltWarTrigger.Random)
                    plugin.TouchRaidLocationCooldown(location);

                foreach (var ownerId in owners)
                {
                    BasePlayer owner = BasePlayer.FindByID(ownerId);
                    if (owner != null && owner.IsConnected)
                        plugin.SendReply(owner, plugin.lang.GetMessage("CobaltWarStartedOwner", plugin, owner.UserIDString), plugin.configData.cobaltWar.factionName, plugin.GetGrid(location));
                }

                SpawnPendingSupportDroneRequests();
                ScheduleAutomaticSupportDrones();
                plugin.UpdateWarJoinUi(this);
            }

            public void Update()
            {
                if (plugin == null || IsEnded)
                    return;

                if (nextOwnerSyncAt <= Time.realtimeSinceStartup)
                {
                    nextOwnerSyncAt = Time.realtimeSinceStartup + 1f;
                    RefreshOwnersFromPrivilege();
                }

                if (nextUiUpdate <= Time.realtimeSinceStartup)
                {
                    nextUiUpdate = Time.realtimeSinceStartup + (phase == CobaltWarPhase.Active ? 2f : 2.5f);
                    plugin.UpdateWarJoinUi(this);
                }

                if (phase == CobaltWarPhase.Buyout && nextAfkCheck <= Time.realtimeSinceStartup)
                {
                    nextAfkCheck = Time.realtimeSinceStartup + 5f;
                    if (!RefreshPreStartState(true))
                        return;
                }

                if ((phase == CobaltWarPhase.Registration || phase == CobaltWarPhase.Preparation) && nextAfkCheck <= Time.realtimeSinceStartup)
                {
                    nextAfkCheck = Time.realtimeSinceStartup + 5f;
                    plugin.PruneInactiveRegisteredDefenders(this);
                }

                if (phase == CobaltWarPhase.Active && nextSupportDroneRespawnCheck > 0f && nextSupportDroneRespawnCheck <= Time.realtimeSinceStartup)
                    SpawnPendingSupportDroneRespawns();

                if (phase == CobaltWarPhase.Buyout && Time.realtimeSinceStartup >= phaseEndTime)
                    BeginRegistration();
                else if (phase == CobaltWarPhase.Registration && Time.realtimeSinceStartup >= phaseEndTime)
                    BeginPreparation();
                else if (phase == CobaltWarPhase.Preparation && Time.realtimeSinceStartup >= phaseEndTime)
                    BeginActive();
                else if (phase == CobaltWarPhase.Active && nextWalkInRefresh <= Time.realtimeSinceStartup)
                {
                    nextWalkInRefresh = Time.realtimeSinceStartup + 5f;
                    RefreshWalkIns();
                    SpawnPendingSupportDroneRequests();
                }
                else if (phase == CobaltWarPhase.Cleanup && Time.realtimeSinceStartup >= phaseEndTime)
                {
                    FinalizeCleanup();
                }
            }

            private void RefreshWalkIns()
            {
                HashSet<ulong> playersInsideZone = new HashSet<ulong>();
                foreach (var player in BasePlayer.activePlayerList)
                {
                    if (player == null || player.IsNpc || player.IsDead() || !player.IsConnected)
                        continue;
                    string arenaMessageKey;
                    if (plugin.IsArenaTournamentBlockingCobalt(player, true, out arenaMessageKey))
                        continue;
                    if (registeredDefenders.Contains(player.userID.Get()) || owners.Contains(player.userID.Get()))
                        continue;
                    if (IsInsideCombatArea(player.transform.position))
                    {
                        ulong userId = player.userID.Get();
                        playersInsideZone.Add(userId);
                        if (!walkInPresenceSince.ContainsKey(userId))
                            walkInPresenceSince[userId] = GrabCurrentTime();
                        if (HasUnlockedWalkInNaturalRespawn(userId))
                            walkInDefenders.Add(userId);
                        plugin.TouchDefenderActivity(player);
                    }
                }

                List<ulong> staleWalkIns = new List<ulong>();
                foreach (var entry in walkInPresenceSince)
                {
                    DefenderRedeployState pendingState;
                    bool hasPendingNaturalRedeploy = plugin.pendingRedeploys.TryGetValue(entry.Key, out pendingState)
                        && pendingState != null
                        && pendingState.warId == warId
                        && !pendingState.useDefenderLoadout;
                    if (!playersInsideZone.Contains(entry.Key) && !hasPendingNaturalRedeploy)
                        staleWalkIns.Add(entry.Key);
                }

                foreach (var userId in staleWalkIns)
                {
                    walkInPresenceSince.Remove(userId);
                    walkInDefenders.Remove(userId);
                }
            }

            public void RecordDamage(BasePlayer player, float damage)
            {
                if (player == null || damage <= 0f)
                    return;

                if (!totalDamage.ContainsKey(player.userID.Get()))
                    totalDamage[player.userID.Get()] = 0f;
                if (!pendingDamage.ContainsKey(player.userID.Get()))
                    pendingDamage[player.userID.Get()] = 0f;

                totalDamage[player.userID.Get()] += damage;
                pendingDamage[player.userID.Get()] += damage;

                if (pendingDamage[player.userID.Get()] >= plugin.configData.cobaltWar.xpChunkDamage)
                {
                    double awardedXp;
                    if (plugin.AwardDamageXp(player, pendingDamage[player.userID.Get()], out awardedXp))
                        pendingDamage[player.userID.Get()] = 0f;
                }
            }

            public void HandleRegisteredDefenderDeath(BasePlayer player)
            {
                if (player == null || !IsRegisteredDefender(player.userID.Get()) || !IsCombatRespawnWindowOpen())
                    return;

                float redeploySeconds = Mathf.Max(0f, plugin.configData.cobaltWar.redeploySeconds);
                if (redeploySeconds <= 0f)
                {
                    plugin.pendingRedeploys.Remove(player.userID.Get());
                    plugin.ClearDefenderRespawnProtection(player.userID);
                    RemoveRegisteredDefender(player.userID.Get(), false);
                    return;
                }

                plugin.ClearDefenderRespawnProtection(player.userID);
                plugin.pendingRedeploys[player.userID.Get()] = new DefenderRedeployState
                {
                    warId = warId,
                    redeployAt = GrabCurrentTime() + redeploySeconds,
                    redeployTimerScheduled = false,
                    useDefenderLoadout = true
                };

                plugin.QueueRegisteredDefenderRedeploy(this, player, plugin.pendingRedeploys[player.userID.Get()], true);
            }

            public bool HandleRegisteredDefenderWound(BasePlayer player)
            {
                if (player == null || !IsRegisteredDefender(player.userID.Get()) || !IsCombatRespawnWindowOpen())
                    return false;

                float redeploySeconds = Mathf.Max(0f, plugin.configData.cobaltWar.redeploySeconds);
                if (redeploySeconds <= 0f)
                    return false;

                DefenderRedeployState existingRedeploy;
                if (plugin.pendingRedeploys.TryGetValue(player.userID.Get(), out existingRedeploy) && existingRedeploy.warId == warId)
                    return true;

                plugin.ClearDefenderRespawnProtection(player.userID);
                plugin.pendingRedeploys[player.userID.Get()] = new DefenderRedeployState
                {
                    warId = warId,
                    redeployAt = GrabCurrentTime(),
                    redeployTimerScheduled = true,
                    useDefenderLoadout = true
                };

                plugin.timer.Once(0.1f, () =>
                {
                    if (_ == null || player == null)
                        return;

                    DefenderRedeployState currentRedeploy;
                    if (!plugin.pendingRedeploys.TryGetValue(player.userID.Get(), out currentRedeploy) || currentRedeploy.warId != warId)
                        return;

                    currentRedeploy.redeployTimerScheduled = false;

                    if (!IsCombatRespawnWindowOpen() || !player.IsConnected)
                        return;

                    if (player.IsDead())
                        return;

                    if (player.IsWounded())
                        player.StopWounded();

                    plugin.pendingRedeploys.Remove(player.userID.Get());
                    plugin.PrepareRegisteredDefender(this, player, true);
                });

                return true;
            }

            public void HandleNaturalDefenderDeath(BasePlayer player)
            {
                if (player == null || !CanUseNaturalCombatRespawn(player, true))
                    return;

                ulong userId = player.userID.Get();
                if (!owners.Contains(userId))
                    PreserveWalkInNaturalRespawnEligibility(userId);

                float redeploySeconds = Mathf.Max(0f, plugin.configData.cobaltWar.redeploySeconds);
                if (redeploySeconds <= 0f)
                    return;

                plugin.ClearDefenderRespawnProtection(player.userID);
                plugin.pendingRedeploys[userId] = new DefenderRedeployState
                {
                    warId = warId,
                    redeployAt = GrabCurrentTime() + redeploySeconds,
                    redeployTimerScheduled = false,
                    useDefenderLoadout = false
                };

                plugin.QueueRegisteredDefenderRedeploy(this, player, plugin.pendingRedeploys[userId], true);
            }

            public bool HandleNaturalDefenderWound(BasePlayer player)
            {
                if (player == null || !CanUseNaturalCombatRespawn(player, true))
                    return false;

                ulong userId = player.userID.Get();
                if (!owners.Contains(userId))
                    PreserveWalkInNaturalRespawnEligibility(userId);

                float redeploySeconds = Mathf.Max(0f, plugin.configData.cobaltWar.redeploySeconds);
                if (redeploySeconds <= 0f)
                    return false;

                DefenderRedeployState existingRedeploy;
                if (plugin.pendingRedeploys.TryGetValue(userId, out existingRedeploy) && existingRedeploy.warId == warId)
                    return true;

                plugin.ClearDefenderRespawnProtection(player.userID);
                plugin.pendingRedeploys[userId] = new DefenderRedeployState
                {
                    warId = warId,
                    redeployAt = GrabCurrentTime(),
                    redeployTimerScheduled = true,
                    useDefenderLoadout = false
                };

                plugin.timer.Once(0.1f, () =>
                {
                    if (_ == null || player == null)
                        return;

                    DefenderRedeployState currentRedeploy;
                    if (!plugin.pendingRedeploys.TryGetValue(player.userID.Get(), out currentRedeploy) || currentRedeploy.warId != warId || currentRedeploy.useDefenderLoadout)
                        return;

                    currentRedeploy.redeployTimerScheduled = false;

                    if (!IsCombatRespawnWindowOpen() || !player.IsConnected || player.IsDead())
                        return;

                    if (player.IsWounded())
                        player.StopWounded();

                    plugin.pendingRedeploys.Remove(player.userID.Get());
                    if (!plugin.PrepareNaturalFriendlyDefender(this, player, true))
                    {
                        currentRedeploy.redeployAt = GrabCurrentTime() + 2f;
                        currentRedeploy.redeployTimerScheduled = false;
                        plugin.pendingRedeploys[player.userID.Get()] = currentRedeploy;
                        plugin.QueueRegisteredDefenderRedeploy(this, player, currentRedeploy, false);
                    }
                });

                return true;
            }

            public void HandleNaturalDefenderRespawn(BasePlayer player)
            {
                if (player == null || player.IsDead() || !IsCombatRespawnWindowOpen())
                    return;

                DefenderRedeployState redeploy;
                if (!plugin.pendingRedeploys.TryGetValue(player.userID.Get(), out redeploy) || redeploy.warId != warId || redeploy.useDefenderLoadout)
                    return;

                float remaining = Mathf.Max(0f, (float)(redeploy.redeployAt - GrabCurrentTime()));
                if (remaining <= 0f)
                {
                    if (plugin.PrepareNaturalFriendlyDefender(this, player, true))
                        plugin.pendingRedeploys.Remove(player.userID);
                    else
                        plugin.QueueRegisteredDefenderRedeploy(this, player, redeploy, false);
                    return;
                }

                plugin.QueueRegisteredDefenderRedeploy(this, player, redeploy, true);
            }

            public void HandleRegisteredDefenderRespawn(BasePlayer player)
            {
                if (player == null || !IsCombatRespawnWindowOpen())
                    return;

                if (player.IsDead())
                    return;

                DefenderRedeployState redeploy;
                if (!plugin.pendingRedeploys.TryGetValue(player.userID.Get(), out redeploy) || redeploy.warId != warId)
                    return;

                float remaining = Mathf.Max(0f, (float)(redeploy.redeployAt - GrabCurrentTime()));
                if (remaining <= 0f)
                {
                    plugin.PrepareRegisteredDefender(this, player, true);
                    plugin.pendingRedeploys.Remove(player.userID);
                    return;
                }

                plugin.QueueRegisteredDefenderRedeploy(this, player, redeploy, true);
            }

            private void RefreshOwnersFromPrivilege()
            {
                if (IsExternalRaidBase)
                {
                    if (owners.Count > 0)
                        owners = new List<ulong>();
                    return;
                }

                if (privilege == null || privilege.IsDestroyed || privilege.authorizedPlayers == null)
                {
                    if (owners.Count > 0)
                        owners = new List<ulong>();
                    return;
                }

                List<ulong> currentOwners = privilege.authorizedPlayers
                    .Where(userId => userId != 0UL)
                    .Distinct()
                    .ToList();

                if (owners.Count == currentOwners.Count && !owners.Except(currentOwners).Any())
                    return;

                owners = currentOwners;
            }

            private bool CancelWarIfTargetCupboardLost()
            {
                if (privilege != null && !privilege.IsDestroyed)
                    return false;

                cleanupOwnerMessageKey = "CobaltWarCancelledTargetLost";
                cancelledBeforeRaid = true;
                CompletedSuccessfully = false;
                BeginCleanup();
                return true;
            }

            public void OnRaidManagerEnded(bool win)
            {
                if (cleanupStarted || IsEnded)
                    return;

                CompletedSuccessfully = win;
                BeginCleanup();
            }

            public void FailWarBecauseCupboardDestroyed()
            {
                if (cleanupStarted || IsEnded)
                    return;

                CompletedSuccessfully = false;

                if (raidManager != null && !raidManager.isDestroyed)
                {
                    raidManager.Destroy(false);
                    return;
                }

                BeginCleanup();
            }

            public void CancelWar(string ownerMessageKey = null, bool notifyOwners = true)
            {
                CancelWarForAdmin(ownerMessageKey, notifyOwners, 0f);
            }

            public void CancelWarForAdmin(string ownerMessageKey = null, bool notifyOwners = true, float cleanupGraceSeconds = 0f)
            {
                if (cleanupStarted || IsEnded)
                    return;

                cancelledBeforeRaid = true;
                CompletedSuccessfully = false;
                notifyOwnersOnCleanup = notifyOwners;
                cleanupOwnerMessageKey = ownerMessageKey;
                forcedCleanupGraceSeconds = phase == CobaltWarPhase.Active ? Mathf.Max(0f, cleanupGraceSeconds) : 0f;

                EventRandomManager activeRaidManager = raidManager;
                raidManager = null;

                if (activeRaidManager != null && !activeRaidManager.isDestroyed)
                {
                    activeRaidManager.warSession = null;
                    activeRaidManager.Destroy(false);
                }

                if (forcedCleanupGraceSeconds > 0f)
                    NotifyGracefulAdminCancellation(Mathf.CeilToInt(forcedCleanupGraceSeconds));

                BeginCleanup();
            }

            private void NotifyGracefulAdminCancellation(int graceSeconds)
            {
                foreach (ulong userId in owners.Concat(walkInDefenders).Distinct())
                {
                    BasePlayer participant = BasePlayer.FindByID(userId);
                    if (participant == null || !participant.IsConnected)
                        continue;

                    plugin.SendReply(participant, plugin.lang.GetMessage("CobaltAdminGracefulStopNotice", plugin, participant.UserIDString), graceSeconds);
                }
            }

            private void FinalizeCleanup()
            {
                List<ulong> usersToRestore = GetAllRegisteredDefenders()
                    .Concat(plugin.GetSnapshotUsersForWar(warId))
                    .Distinct()
                    .ToList();
                List<ulong> readyUsersToRestore = new List<ulong>();
                List<ulong> usersToClearPending = owners
                    .Concat(walkInDefenders)
                    .Concat(plugin.pendingRedeploys.Where(x => x.Value != null && x.Value.warId == warId).Select(x => x.Key))
                    .Concat(usersToRestore)
                    .Distinct()
                    .ToList();
                foreach (var userId in usersToRestore)
                {
                    // Once final cleanup starts returning original inventories, do not allow the
                    // respawn hooks to route these defenders back into the combat redeploy branch.
                    plugin.pendingRedeploys.Remove(userId);
                }

                bool awaitingLivePlayers = false;
                foreach (var userId in usersToRestore)
                {
                    BasePlayer player = BasePlayer.FindByID(userId);
                    if (player == null || !player.IsConnected)
                        continue;

                    DefenderSnapshot snapshot;
                    if (!plugin.TryGetDefenderSnapshot(userId, out snapshot) || snapshot == null)
                        continue;

                    if (!plugin.TryPreparePlayerForDefenderRestore(player, true))
                        awaitingLivePlayers = true;
                    else
                        readyUsersToRestore.Add(userId);
                }

                int maxRetryCount = Mathf.Max(0, plugin.configData.cobaltWar.cleanupFinalizeMaxRetries);
                float retrySeconds = Mathf.Max(0.1f, plugin.configData.cobaltWar.cleanupFinalizeRetrySeconds);
                if (awaitingLivePlayers && cleanupFinalizeRetryCount < maxRetryCount)
                {
                    cleanupFinalizeRetryCount++;
                    phaseEndTime = Time.realtimeSinceStartup + retrySeconds;
                    plugin.UpdateWarJoinUi(this);
                    return;
                }

                cleanupFinalizeRetryCount = 0;

                foreach (var userId in usersToClearPending)
                    plugin.pendingRedeploys.Remove(userId);

                foreach (var userId in readyUsersToRestore)
                {
                    BasePlayer player = BasePlayer.FindByID(userId);
                    if (player != null && player.IsConnected)
                        ServerMgr.Instance.StartCoroutine(plugin.RestoreDefenderSnapshot(player));
                }

                foreach (var player in BasePlayer.activePlayerList)
                {
                    CuiHelper.DestroyUi(player, JoinUiName);
                    plugin.displayedWarUi.Remove(player.userID);
                    plugin.ClearWarUiDismiss(player.userID, warId);
                    plugin.ClearRenderedWarUiState(player.userID, warId);
                }

                postRaidCombatGraceActive = false;
                IsEnded = true;
                if (IsExternalRaidBase)
                    Interface.Oxide.CallHook("OnCobaltWarExternalRaidEnded", warId, ExternalSourceId ?? string.Empty, CompletedSuccessfully, location, raidType, targetName);
                plugin.UnregisterWar(this);
                Destroy(gameObject);
            }

            private void AwardVictoryCompletionRewards(List<ulong> victoryRoulettePlayers)
            {
                if (victoryCompletionRewardsAwarded)
                    return;

                victoryCompletionRewardsAwarded = true;

                double successDefenseXpReward = plugin.GetSuccessDefenseXpForRaidType(raidType);
                if (!CompletedSuccessfully || cancelledBeforeRaid || successDefenseXpReward <= 0d)
                {
                    victoryRouletteRewardPlayers.Clear();
                    return;
                }

                HashSet<ulong> rouletteEligible = new HashSet<ulong>();
                if (victoryRoulettePlayers != null)
                {
                    foreach (ulong userId in victoryRoulettePlayers)
                    {
                        if (userId != 0UL)
                            rouletteEligible.Add(userId);
                    }
                }

                List<ulong> rouletteAwardPlayers = new List<ulong>();
                foreach (var userId in GetRewardEligiblePlayers().Distinct())
                {
                    BasePlayer rewardPlayer = BasePlayer.FindByID(userId);
                    if (plugin.TryAwardSkillTreeXp(userId, successDefenseXpReward))
                    {
                        if (rewardPlayer != null && rewardPlayer.IsConnected)
                            plugin.SendCobaltXpSummary(rewardPlayer, plugin.GetCobaltDamageXp(totalDamage.ContainsKey(userId) ? totalDamage[userId] : 0f), successDefenseXpReward);

                        if (rouletteEligible.Contains(userId))
                            rouletteAwardPlayers.Add(userId);
                    }
                    else
                    {
                        plugin.QueueDeferredCobaltRewardXp(userId, successDefenseXpReward, false);
                    }
                }

                if (rouletteAwardPlayers.Count > 0)
                {
                    plugin.CobaltDiagnosticLog("raid", $"Война #{warId}: рулетка победы запускается вместе с наградой XP, players={rouletteAwardPlayers.Distinct().Count()}, difficulty={plugin.NormalizeRouletteDifficulty(raidType)}.");
                    plugin.QueueVictoryLootRouletteRewards(warId, raidType, IsExternalRaidBase, ExternalSourceId, rouletteAwardPlayers);
                }

                victoryRouletteRewardPlayers.Clear();
                plugin.timer.Once(0.1f, () => plugin.SaveData());
            }

            private void BeginCleanup()
            {
                cleanupStarted = true;
                pendingSupportDroneRespawns.Clear();
                nextSupportDroneRespawnCheck = 0f;
                cleanupFinalizeRetryCount = 0;
                plugin.CobaltDiagnosticLog("raid", $"Война #{warId}: этап Cleanup, completed={CompletedSuccessfully}, cancelledBeforeRaid={cancelledBeforeRaid}, phaseBeforeCleanup={phase}, owners={owners.Count}, defenders={registeredDefenders.Count}, walkIns={walkInDefenders.Count}, totalDamagePlayers={totalDamage.Count}.");
                plugin.DestroyCobaltSupportDronesForWar(warId);
                RefundPendingSupportDroneRequests();
                float cleanupGraceSeconds = forcedCleanupGraceSeconds;
                forcedCleanupGraceSeconds = -1f;
                bool finishedFromActiveRaid = phase == CobaltWarPhase.Active && (!cancelledBeforeRaid || cleanupGraceSeconds > 0f);
                victoryRouletteRewardPlayers.Clear();
                if (CompletedSuccessfully && !cancelledBeforeRaid && finishedFromActiveRaid)
                {
                    victoryRouletteRewardPlayers.AddRange(GetVictoryRouletteEligiblePlayers());
                    plugin.CobaltDiagnosticLog("raid", $"Война #{warId}: зафиксированы участники для рулетки победы: {victoryRouletteRewardPlayers.Count}.");
                }
                phase = CobaltWarPhase.Cleanup;
                postRaidCombatGraceActive = finishedFromActiveRaid;
                float cleanupDelay = cleanupGraceSeconds > 0f ? cleanupGraceSeconds : CobaltPostRaidReturnDelaySeconds;
                phaseEndTime = Time.realtimeSinceStartup + (finishedFromActiveRaid ? cleanupDelay : 0f);

                foreach (var userId in pendingDamage.Keys.ToList())
                {
                    if (pendingDamage[userId] <= 0f)
                        continue;
                    BasePlayer player = BasePlayer.FindByID(userId);
                    if (player != null && player.IsConnected)
                    {
                        double awardedXp;
                        if (!plugin.AwardDamageXp(player, pendingDamage[userId], out awardedXp))
                            plugin.QueueDeferredCobaltXp(userId, pendingDamage[userId], false);
                    }
                    else
                        plugin.QueueDeferredCobaltXp(userId, pendingDamage[userId], false);
                }
                plugin.timer.Once(0.1f, () => plugin.SaveData());

                double successDefenseXpReward = plugin.GetSuccessDefenseXpForRaidType(raidType);
                if (CompletedSuccessfully && !cancelledBeforeRaid && successDefenseXpReward > 0d)
                {
                    plugin.CobaltDiagnosticLog("raid", $"Война #{warId}: награда XP за победу выдается при старте отсчета возврата вместе с рулеткой, xp={Math.Round(successDefenseXpReward, 2)}.");
                    List<ulong> victoryRoulettePlayers = victoryRouletteRewardPlayers.Count > 0
                        ? victoryRouletteRewardPlayers.Distinct().ToList()
                        : null;
                    AwardVictoryCompletionRewards(victoryRoulettePlayers);
                }

                if ((!CompletedSuccessfully || successDefenseXpReward <= 0d) && finishedFromActiveRaid)
                {
                    foreach (var userId in totalDamage.Keys.ToList())
                    {
                        BasePlayer xpPlayer = BasePlayer.FindByID(userId);
                        if (xpPlayer != null && xpPlayer.IsConnected)
                            plugin.SendCobaltXpSummary(xpPlayer, plugin.GetCobaltDamageXp(totalDamage[userId]), 0d);
                    }
                }

                if (!CompletedSuccessfully && !cancelledBeforeRaid && failurePenaltyAmount > 0 && plugin.ServerRewards != null)
                {
                    try
                    {
                        int currentBalance = Convert.ToInt32(plugin.ServerRewards.Call("CheckPoints", targetUserId));
                        int amount = Mathf.Min(currentBalance, failurePenaltyAmount);
                        if (amount > 0)
                            plugin.ServerRewards.Call("TakePoints", targetUserId, amount, "cobalt_war_failure");
                    }
                    catch { }
                }

                if (!finishedFromActiveRaid)
                {
                    foreach (var userId in owners.Concat(walkInDefenders).Concat(GetAllRegisteredDefenders()).Concat(plugin.GetSnapshotUsersForWar(warId)).Concat(plugin.pendingRedeploys.Where(x => x.Value != null && x.Value.warId == warId).Select(x => x.Key)).Distinct())
                        plugin.pendingRedeploys.Remove(userId);
                }

                foreach (var ownerId in owners)
                {
                    BasePlayer owner = BasePlayer.FindByID(ownerId);
                    if (owner == null || !owner.IsConnected)
                        continue;

                    if (!notifyOwnersOnCleanup)
                        continue;

                    if (cancelledBeforeRaid)
                    {
                        string messageKey = string.IsNullOrEmpty(cleanupOwnerMessageKey) ? "CobaltWarCancelledOwnersOffline" : cleanupOwnerMessageKey;
                        plugin.SendReply(owner, plugin.lang.GetMessage(messageKey, plugin, owner.UserIDString));
                    }
                    else
                        plugin.SendReply(owner, CompletedSuccessfully ? plugin.lang.GetMessage("CobaltWarWon", plugin, owner.UserIDString) : plugin.lang.GetMessage("CobaltWarLost", plugin, owner.UserIDString), plugin.configData.cobaltWar.factionName, failurePenaltyAmount);
                }

                if (finishedFromActiveRaid)
                {
                    foreach (var userId in GetAllRegisteredDefenders())
                    {
                        BasePlayer player = BasePlayer.FindByID(userId);
                        if (player != null && player.IsConnected)
                            plugin.SendReply(player, plugin.lang.GetMessage("CobaltCleanupGraceNotice", plugin, player.UserIDString), Mathf.CeilToInt(cleanupDelay));
                    }

                    plugin.UpdateWarJoinUi(this);
                    return;
                }

                FinalizeCleanup();
            }
        }
        #endregion

        #region EventRandomManager
        public static float ProjectileDistToGravity(float x, float y, float Оё, float v)
        {
            float f1 = Оё * ((float)Math.PI / 180f);
            float f2 = (float)(((double)v * (double)v * (double)x * (double)Mathf.Sin(2f * f1) - 2.0 * (double)v * (double)v * (double)y * (double)Mathf.Cos(f1) * (double)Mathf.Cos(f1)) / ((double)x * (double)x));
            if (float.IsNaN(f2) || (double)f2 < 0.00999999977648258)
                f2 = -Physics.gravity.y;
            return f2;
        }

