            public static EventRandomManager Create(Vector3 l, raidConfig c, string t, List<ulong> authedPlayers, GameObject gobj, List<BuildingBlock> blocks, float useDelay = 0.1f)
            {
                GameObject gobjBew = new GameObject();
                EventRandomManager manager = gobjBew.AddComponent<EventRandomManager>();
                manager.members = Facepunch.Pool.Get<List<RandomRaider>>();
                manager.newWave = true;
                manager.config = c;
                manager.waveType = t;
                manager.location = l;
                manager._authedPlayers = authedPlayers;
                manager._AllFoundations = blocks;
                manager.building = HasCupboard(l);
                manager.tc = manager.building;
                manager.targetCupboardId = manager.building?.net?.ID.Value ?? 0UL;
                manager.useDelay = useDelay;

                _AllRaids.Add(manager);

                if (c != null && c.juggernaut != null && c.juggernaut.Count > 0)
                {
                    foreach (var jconfigs in c.juggernaut)
                    {
                        if (_.configData.juggernautProfile.ContainsKey(jconfigs))
                        {
                            manager.jconfig.Add(_.configData.juggernautProfile[jconfigs]);
                        }
                    }
                }
                manager.sendGUI = _.configData.settings.useGUI;
                return manager;
            }

            public void BindTargetCupboard(BuildingPrivlidge privilege = null)
            {
                if (privilege != null && !privilege.IsDestroyed)
                {
                    building = privilege;
                    tc = privilege;
                    targetCupboardId = privilege.net?.ID.Value ?? 0UL;
                    return;
                }

                if (targetCupboardId == 0UL)
                {
                    BuildingPrivlidge liveCupboard = building != null && !building.IsDestroyed
                        ? building
                        : tc as BuildingPrivlidge;

                    if (liveCupboard == null || liveCupboard.IsDestroyed)
                        liveCupboard = HasCupboard(location);

                    if (liveCupboard != null && !liveCupboard.IsDestroyed)
                    {
                        building = liveCupboard;
                        tc = liveCupboard;
                        targetCupboardId = liveCupboard.net?.ID.Value ?? 0UL;
                    }
                }
            }

            public void RegisterTemporaryExplosive(BaseEntity entity)
            {
                if (entity == null || entity.IsDestroyed || entity.net == null)
                    return;

                spawnedRaidExplosiveIds.Add(entity.net.ID.Value);
            }

            public void UnregisterTemporaryExplosive(BaseNetworkable entity)
            {
                if (entity == null || entity.net == null)
                    return;

                spawnedRaidExplosiveIds.Remove(entity.net.ID.Value);
            }

            private void CleanupTrackedRaidExplosives()
            {
                if (spawnedRaidExplosiveIds.Count <= 0)
                    return;

                foreach (ulong explosiveId in spawnedRaidExplosiveIds.ToList())
                {
                    BaseEntity explosiveEntity = BaseNetworkable.serverEntities.Find(new NetworkableId(explosiveId)) as BaseEntity;
                    if (explosiveEntity == null || explosiveEntity.IsDestroyed)
                        continue;

                    try
                    {
                        explosiveEntity.CancelInvoke();
                        explosiveEntity.Kill();
                    }
                    catch
                    {
                    }
                }

                spawnedRaidExplosiveIds.Clear();
            }

            private BuildingPrivlidge ResolveTargetCupboard()
            {
                if (targetCupboardId == 0UL)
                {
                    BindTargetCupboard();
                    if (targetCupboardId == 0UL)
                        return null;
                }

                if (building != null && !building.IsDestroyed && building.net != null && building.net.ID.Value == targetCupboardId)
                    return building;

                BuildingPrivlidge currentTc = tc as BuildingPrivlidge;
                if (currentTc != null && !currentTc.IsDestroyed && currentTc.net != null && currentTc.net.ID.Value == targetCupboardId)
                    return currentTc;

                BuildingPrivlidge resolved = _?.FindEntity(targetCupboardId) as BuildingPrivlidge;
                if (resolved != null && !resolved.IsDestroyed)
                    return resolved;

                return null;
            }

            public bool IsTrackingCupboard(ulong cupboardId)
            {
                return cupboardId != 0UL && targetCupboardId == cupboardId;
            }

            public bool HasLostTargetCupboard()
            {
                BuildingPrivlidge resolved = ResolveTargetCupboard();
                return targetCupboardId != 0UL && (resolved == null || resolved.IsDestroyed || resolved.Health() <= 0f);
            }

            public void RefreshRaidAnchors()
            {
                BuildingPrivlidge resolved = ResolveTargetCupboard();
                if (resolved != null)
                {
                    building = resolved;
                    tc = resolved;
                    return;
                }

                building = null;
                tc = null;
            }

            private IEnumerable<BuildingBlock> EnumerateRaidBlocks()
            {
                RefreshRaidAnchors();

                BuildingManager.Building liveBuilding = building?.GetBuilding();
                if (liveBuilding != null && liveBuilding.buildingBlocks != null)
                {
                    foreach (BuildingBlock block in liveBuilding.buildingBlocks)
                    {
                        if (block == null || block.IsDestroyed || block.Health() <= 0f)
                            continue;

                        yield return block;
                    }
                }

                if (_AllFoundations == null)
                    yield break;

                for (int i = _AllFoundations.Count - 1; i >= 0; i--)
                {
                    BuildingBlock block = _AllFoundations[i];
                    if (block == null || block.IsDestroyed || block.Health() <= 0f)
                    {
                        _AllFoundations.RemoveAt(i);
                        continue;
                    }

                    yield return block;
                }
            }

            private static float DistanceToRaidSegment(Vector3 attackerPosition, Vector3 raidCore, Vector3 point)
            {
                Vector2 from = new Vector2(attackerPosition.x, attackerPosition.z);
                Vector2 to = new Vector2(raidCore.x, raidCore.z);
                Vector2 sample = new Vector2(point.x, point.z);
                Vector2 direction = to - from;

                if (direction.sqrMagnitude <= 0.01f)
                    return Vector2.Distance(from, sample);

                float projection = Mathf.Clamp01(Vector2.Dot(sample - from, direction) / direction.sqrMagnitude);
                Vector2 closest = from + direction * projection;
                return Vector2.Distance(sample, closest);
            }

            private static bool IsWeakRaidBlock(BuildingBlock block)
            {
                if (block == null)
                    return false;

                return block.grade == BuildingGrade.Enum.Twigs || block.grade == BuildingGrade.Enum.Wood;
            }

            private static RaidBlockPriority GetRaidBlockPriority(BuildingBlock block)
            {
                if (block == null)
                    return RaidBlockPriority.Structure;

                string shortName = (block.ShortPrefabName ?? string.Empty).ToLowerInvariant();
                string entityName = (block.name ?? string.Empty).ToLowerInvariant();

                if (shortName.Contains("foundation") || entityName.Contains("foundation"))
                    return RaidBlockPriority.Foundation;

                if (shortName.Contains("wall")
                    || shortName.Contains("doorway")
                    || shortName.Contains("window")
                    || shortName.Contains("floor.frame")
                    || shortName.Contains("wall.frame")
                    || entityName.Contains("wall")
                    || entityName.Contains("doorway")
                    || entityName.Contains("window"))
                    return RaidBlockPriority.Wall;

                return RaidBlockPriority.Structure;
            }

            private void EvaluateRaidBlockTargets(
                Vector3 attackerPosition,
                Vector3 raidCore,
                BuildingBlock block,
                float routeLength,
                ref BuildingBlock bestBreachTarget,
                ref float bestBreachScore,
                ref RaidBlockPriority bestBreachPriority,
                ref BuildingBlock bestFallbackTarget,
                ref float bestFallbackDistance,
                ref RaidBlockPriority bestFallbackPriority)
            {
                if (block == null || block.IsDestroyed || block.Health() <= 0f)
                    return;

                Vector3 blockPosition = block.CenterPoint();
                RaidBlockPriority blockPriority = GetRaidBlockPriority(block);
                float distanceFromAttacker = Vector3.Distance(attackerPosition, blockPosition);

                if (bestFallbackTarget == null || blockPriority > bestFallbackPriority || (blockPriority == bestFallbackPriority && distanceFromAttacker < bestFallbackDistance))
                {
                    bestFallbackTarget = block;
                    bestFallbackDistance = distanceFromAttacker;
                    bestFallbackPriority = blockPriority;
                }

                float lineDistance = DistanceToRaidSegment(attackerPosition, raidCore, blockPosition);
                if (lineDistance > 12f)
                    return;

                Vector3 routeVector = raidCore - attackerPosition;
                float routeProgress = 0f;
                if (routeVector.sqrMagnitude > 0.01f)
                    routeProgress = Mathf.Clamp01(Vector3.Dot(blockPosition - attackerPosition, routeVector.normalized) / Mathf.Max(routeLength, 1f));

                if (routeProgress > 1.05f)
                    return;

                float durabilityFactor = Mathf.Clamp01(block.Health() / Mathf.Max(1f, block.MaxHealth()));
                float score = (lineDistance * 3f) + (routeProgress * 18f) + (distanceFromAttacker * 0.35f) + (durabilityFactor * 8f);

                if (IsWeakRaidBlock(block))
                    score -= 4f;

                if (blockPriority == RaidBlockPriority.Wall)
                    score -= 9f;
                else if (blockPriority == RaidBlockPriority.Foundation)
                    score += 16f;

                if (bestBreachTarget == null || blockPriority > bestBreachPriority || (blockPriority == bestBreachPriority && score < bestBreachScore))
                {
                    bestBreachPriority = blockPriority;
                    bestBreachScore = score;
                    bestBreachTarget = block;
                }
            }

            public BaseCombatEntity GetRaidObjective(Vector3 attackerPosition, BaseCombatEntity currentObjective = null)
            {
                RefreshRaidAnchors();

                if (building != null && !building.IsDestroyed && building.Health() > 0f && Vector3.Distance(attackerPosition, building.transform.position) <= 12f)
                    return building;

                if (currentObjective != null && !currentObjective.IsDestroyed && currentObjective.Health() > 0f)
                {
                    float keepDistance = Vector3.Distance(attackerPosition, currentObjective.transform.position);
                    if (keepDistance <= 18f)
                        return currentObjective;
                }

                if (cachedRaiderObjective != null
                    && !cachedRaiderObjective.IsDestroyed
                    && cachedRaiderObjective.Health() > 0f
                    && Time.realtimeSinceStartup < cachedRaiderObjectiveRefreshAt)
                    return cachedRaiderObjective;

                Vector3 raidCore = building != null && !building.IsDestroyed ? building.transform.position : location;
                float routeLength = Vector3.Distance(attackerPosition, raidCore);
                BuildingBlock breachTarget = null;
                float bestBreachScore = float.MaxValue;
                RaidBlockPriority bestBreachPriority = RaidBlockPriority.Foundation;
                BuildingBlock closestStructure = null;
                float closestStructureDistance = float.MaxValue;
                RaidBlockPriority closestStructurePriority = RaidBlockPriority.Foundation;

                foreach (BuildingBlock block in EnumerateRaidBlocks())
                {
                    EvaluateRaidBlockTargets(
                        attackerPosition,
                        raidCore,
                        block,
                        routeLength,
                        ref breachTarget,
                        ref bestBreachScore,
                        ref bestBreachPriority,
                        ref closestStructure,
                        ref closestStructureDistance,
                        ref closestStructurePriority);
                }

                float objectiveRefreshInterval = GetRaiderObjectiveRefreshInterval();

                if (breachTarget != null)
                {
                    cachedRaiderObjective = breachTarget;
                    cachedRaiderObjectiveRefreshAt = Time.realtimeSinceStartup + objectiveRefreshInterval;
                    return breachTarget;
                }

                if (building != null && !building.IsDestroyed && building.Health() > 0f)
                {
                    cachedRaiderObjective = building;
                    cachedRaiderObjectiveRefreshAt = Time.realtimeSinceStartup + objectiveRefreshInterval;
                    return building;
                }

                cachedRaiderObjective = closestStructure;
                cachedRaiderObjectiveRefreshAt = closestStructure != null
                    ? Time.realtimeSinceStartup + objectiveRefreshInterval
                    : 0f;
                return closestStructure;
            }

            public BaseCombatEntity GetTankObjective(Vector3 attackerPosition, BaseCombatEntity currentObjective = null)
            {
                RefreshRaidAnchors();

                if (currentObjective != null && !currentObjective.IsDestroyed && currentObjective.Health() > 0f)
                {
                    float keepDistance = Vector3.Distance(attackerPosition, currentObjective.transform.position);
                    if (keepDistance <= 40f)
                        return currentObjective;
                }

                if (cachedTankObjective != null
                    && !cachedTankObjective.IsDestroyed
                    && cachedTankObjective.Health() > 0f
                    && Time.realtimeSinceStartup < cachedTankObjectiveRefreshAt)
                    return cachedTankObjective;

                Vector3 raidCore = building != null && !building.IsDestroyed ? building.transform.position : location;
                float routeLength = Vector3.Distance(attackerPosition, raidCore);
                BuildingBlock breachTarget = null;
                float bestBreachScore = float.MaxValue;
                RaidBlockPriority bestBreachPriority = RaidBlockPriority.Foundation;
                BuildingBlock closestStructure = null;
                float closestStructureDistance = float.MaxValue;
                RaidBlockPriority closestStructurePriority = RaidBlockPriority.Foundation;

                foreach (BuildingBlock block in EnumerateRaidBlocks())
                {
                    EvaluateRaidBlockTargets(
                        attackerPosition,
                        raidCore,
                        block,
                        routeLength,
                        ref breachTarget,
                        ref bestBreachScore,
                        ref bestBreachPriority,
                        ref closestStructure,
                        ref closestStructureDistance,
                        ref closestStructurePriority);
                }

                if (breachTarget != null)
                {
                    cachedTankObjective = breachTarget;
                    cachedTankObjectiveRefreshAt = Time.realtimeSinceStartup + 0.9f;
                    return breachTarget;
                }

                if (building != null && !building.IsDestroyed && building.Health() > 0f)
                {
                    cachedTankObjective = building;
                    cachedTankObjectiveRefreshAt = Time.realtimeSinceStartup + 0.9f;
                    return building;
                }

                if (closestStructure != null)
                {
                    cachedTankObjective = closestStructure;
                    cachedTankObjectiveRefreshAt = Time.realtimeSinceStartup + 0.9f;
                    return closestStructure;
                }

                cachedTankObjective = null;
                cachedTankObjectiveRefreshAt = 0f;
                return null;
            }

            public Vector3 GetMlrsStrikePoint(int shotIndex)
            {
                RefreshRaidAnchors();

                List<Vector3> candidates = new List<Vector3>();
                if (tc != null && !tc.IsDestroyed)
                    candidates.Add(tc.transform.position + new Vector3(0f, 0.8f, 0f));

                foreach (BuildingBlock block in EnumerateRaidBlocks()
                    .OrderBy(x => tc != null && !tc.IsDestroyed ? Vector3.Distance(x.transform.position, tc.transform.position) : Vector3.Distance(x.transform.position, location))
                    .Take(18))
                {
                    candidates.Add(block.CenterPoint());
                }

                Vector3 basePoint = candidates.Count > 0
                    ? candidates[Mathf.Abs(shotIndex) % candidates.Count]
                    : location + new Vector3(0f, 1f, 0f);

                float spread = Mathf.Max(2f, _.configData?.cobaltWar?.mlrsSpreadRadius ?? 13f);
                Vector2 jitter = UnityEngine.Random.insideUnitCircle * spread;
                basePoint += new Vector3(jitter.x, 0f, jitter.y);
                basePoint.y = Mathf.Max(basePoint.y, TerrainMeta.HeightMap.GetHeight(basePoint));
                return basePoint;
            }

            public void StartEvent()
            {
                if (config.kitsSame && config.kits != null && config.kits.Count > 0)
                {
                    sameKit = config.kits.GetRandom();
                }
                _.timer.Once(useDelay, () =>
                {
                    if (_ == null || config == null)
                        return;
                    bool requireOnlineAuthorized = _.configData.settings.mustBeOnlinePlayer && (warSession == null || !warSession.IsExternalRaidBase);
                    if (requireOnlineAuthorized && (_authedPlayers == null || !_authedPlayers.Any(userId =>
                    {
                        BasePlayer player = BasePlayer.FindByID(userId);
                        return player != null && player.IsConnected;
                    })))
                    {
                        Destroy(gameObject);
                        return;
                    }

                    Interface.Oxide.CallHook("OnRandomRaidStart", waveType, location);
                    Interface.Oxide.CallHook("OnCobaltWarRaidStart", waveType, location);
                    MlrsEventTime = 0f;
                    mlrsCallsRemainingForWave = 0;
                    EndEventTime = Time.time + config.RunTimeSeconds;
                    nextWaveTime = Time.time + 3800;

                    QueuedRoutine = StartCoroutine(GenerateEventMembers());

                    if (_.configData.settings.useMarker)
                        marker = SpawnRaidMarker(location, EndEventTime);
                    if (_.configData.settings.useChat)
                        _.notifyChat(location);

                    if (config.TotalNpcWaves <= 0)
                        Duration = config.RunTimeSeconds;
                    else if (_.configData.settings.pauseWave)
                    {
                        Duration = 10;
                    }
                    else
                        Duration = config.NextWaveSeconds;
                    nextWaveTime = Time.time + config.NextWaveSeconds;
                });
            }

            private void CleanupSupportEntities()
            {
                helis.RemoveAll(x => x == null || x.IsDestroyed);
                tanks.RemoveAll(x => x == null || x.IsDestroyed);

                if (heli == null || heli.IsDestroyed)
                    heli = helis.FirstOrDefault(x => x != null && !x.IsDestroyed);
            }

            private bool ShouldSpawnSupportWave(int waveNumber, int repeatInterval)
            {
                if (waveNumber <= 1)
                    return true;

                if (repeatInterval <= 0)
                    return false;

                return ((waveNumber - 1) % repeatInterval) == 0;
            }

            private List<string> GetWaveCopterProfiles()
            {
                List<string> copterProfiles = new List<string>();

                if (config?.spawnCopter != null && config.spawnCopter.Count > 0)
                    copterProfiles.AddRange(config.spawnCopter.Where(x => !string.IsNullOrEmpty(x) && _.configData.copterSettings.copterProfile.ContainsKey(x)));

                if ((warSession != null && warSession.IsRockBaseTerrain) && copterProfiles.Count == 0 && _.configData.cobaltWar.rockBaseFallbackCopterProfiles != null)
                    copterProfiles.AddRange(_.configData.cobaltWar.rockBaseFallbackCopterProfiles.Where(x => !string.IsNullOrEmpty(x) && _.configData.copterSettings.copterProfile.ContainsKey(x)));

                if (copterProfiles.Count == 0)
                {
                    string fallbackProfile = _.configData.copterSettings.copterProfile.Keys.FirstOrDefault();
                    if (!string.IsNullOrEmpty(fallbackProfile))
                        copterProfiles.Add(fallbackProfile);
                }

                return copterProfiles;
            }

            private void SpawnWaveHelicopters(int waveNumber)
            {
                if (_ == null || _.configData?.cobaltWar == null || config == null || !config.attackCopter)
                    return;

                CleanupSupportEntities();

                int maxActiveCopters = Mathf.Clamp(_.configData.cobaltWar.maxActiveCopters, 1, 8);
                int aliveCopters = helis.Count;
                int availableSlots = Mathf.Max(0, maxActiveCopters - aliveCopters);
                if (availableSlots <= 0)
                    return;

                List<string> copterProfiles = GetWaveCopterProfiles();
                if (copterProfiles.Count == 0)
                    return;

                bool initialWave = waveNumber <= 1;
                List<string> profilesToSpawn = new List<string>();
                if (initialWave)
                {
                    bool spawnAllConfiguredCopters = copterProfiles.Count > 1 || (warSession != null && warSession.IsRockBaseTerrain);
                    if (spawnAllConfiguredCopters)
                        profilesToSpawn.AddRange(copterProfiles);
                    else
                        profilesToSpawn.Add(copterProfiles.GetRandom());
                }
                else
                {
                    string selectedProfile = copterProfiles[(waveNumber - 2) % copterProfiles.Count];
                    profilesToSpawn.Add(selectedProfile);
                }

                int spawnCount = Mathf.Min(profilesToSpawn.Count, availableSlots);
                int formationStartIndex = helis.Count;
                for (int i = 0; i < spawnCount; i++)
                {
                    copterConfig currentConfig;
                    if (!_.configData.copterSettings.copterProfile.TryGetValue(profilesToSpawn[i], out currentConfig))
                        continue;

                    PatrolHelicopter spawnedHeli = spawnHeli(this, location, currentConfig, formationStartIndex + i);
                    if (spawnedHeli == null)
                        continue;

                    if (heli == null || heli.IsDestroyed)
                        heli = spawnedHeli;

                    helis.Add(spawnedHeli);
                }
            }

            private void SpawnWaveTanks(int waveNumber)
            {
                if (_ == null || _.configData?.cobaltWar == null || config == null || !_.configData.cobaltWar.enableTanks || !config.spawnTanks || config.tankCount <= 0)
                    return;

                CleanupSupportEntities();

                int maxActiveTanks = Mathf.Clamp(_.configData.cobaltWar.maxActiveTanks, 1, 8);
                int aliveTanks = tanks.Count;
                int availableSlots = Mathf.Max(0, maxActiveTanks - aliveTanks);
                if (availableSlots <= 0)
                    return;

                int targetSpawnCount = waveNumber <= 1 ? Mathf.Clamp(config.tankCount, 1, 4) : 1;
                targetSpawnCount = Mathf.Min(targetSpawnCount, availableSlots);

                int startIndex = tanks.Count;
                for (int i = 0; i < targetSpawnCount; i++)
                {
                    BradleyAPC tank = _.SpawnCobaltTank(this, startIndex + i);
                    if (tank != null)
                        tanks.Add(tank);
                }
            }

            private void SpawnWaveSupport(int waveNumber)
            {
                if (_ == null || _.configData?.cobaltWar == null || config == null)
                    return;

                if (ShouldSpawnSupportWave(waveNumber, _.configData.cobaltWar.copterWaveInterval))
                    SpawnWaveHelicopters(waveNumber);

                if (ShouldSpawnSupportWave(waveNumber, _.configData.cobaltWar.tankWaveInterval))
                    SpawnWaveTanks(waveNumber);
            }

            private static MapMarkerExplosion SpawnRaidMarker(Vector3 vector, float timeLimit)
            {
                MapMarkerExplosion explosionMarker = null;

                explosionMarker = GameManager.server.CreateEntity(StringPool.Get(4060989661), vector) as MapMarkerExplosion;
                if (explosionMarker != null)
                {
                    explosionMarker.enableSaving = false;
                    explosionMarker.Spawn();
                    explosionMarker.SetDuration(timeLimit);
                }

                return explosionMarker;
            }

        public static void SendEffect(string effect, Vector3 position, BaseEntity entity)
        {
            if (_ == null || entity == null || string.IsNullOrEmpty(effect))
                return;

            // Voice/radio callouts are intentionally disabled for raid NPCs.
            if (IsNpcRadioEffect(effect))
                return;

            if (_.configData.settings.disableChatter)
                return;

            Effect infoEffect = new Effect(effect, entity, 0, new Vector3(), new Vector3());
            infoEffect.broadcast = true;
            EffectNetwork.Send(infoEffect);
            }

            private void ArmMlrsForCurrentWave(bool initialWave = false)
            {
                if (_ == null || config == null || !config.FireMlrs)
                {
                    MlrsEventTime = 0f;
                    mlrsCallsRemainingForWave = 0;
                    return;
                }

                int callCount = Mathf.Clamp(_.configData?.cobaltWar?.mlrsCallsPerWave ?? 1, 1, 6);
                mlrsCallsRemainingForWave = callCount;

                float baseDelay;
                if (initialWave)
                    baseDelay = Mathf.Clamp(config.NextWaveSeconds * 0.18f, 10f, 22f);
                else
                    baseDelay = Mathf.Clamp(config.NextWaveSeconds * 0.16f, 7f, 18f);

                MlrsEventTime = Time.time + baseDelay + UnityEngine.Random.Range(0.75f, 3.25f);
            }

            private void ConsumeMlrsCallForWave()
            {
                if (_ == null || config == null || !config.FireMlrs)
                {
                    MlrsEventTime = 0f;
                    mlrsCallsRemainingForWave = 0;
                    return;
                }

                mlrsCallsRemainingForWave = Mathf.Max(0, mlrsCallsRemainingForWave - 1);
                if (mlrsCallsRemainingForWave <= 0)
                {
                    MlrsEventTime = 0f;
                    return;
                }

                float repeatInterval = Mathf.Clamp(_.configData?.cobaltWar?.mlrsCallIntervalSeconds ?? 18f, 3f, 120f);
                MlrsEventTime = Time.time + repeatInterval;
            }

            public static void setupMlrs(EventRandomManager man)
            {
                if (isFireingMlrs || man == null || _ == null) return;
                isFireingMlrs = true;

                int bursts = Mathf.Clamp(_.configData?.cobaltWar?.mlrsBurstCount ?? 3, 1, 6);
                int rocketsPerBurst = Mathf.Clamp(_.configData?.cobaltWar?.mlrsRocketsPerBurst ?? 6, 2, 18);
                float rocketInterval = Mathf.Clamp(_.configData?.cobaltWar?.mlrsRocketIntervalSeconds ?? 0.45f, 0.1f, 3f);
                float burstInterval = Mathf.Clamp(_.configData?.cobaltWar?.mlrsBurstIntervalSeconds ?? 2.8f, 0.5f, 10f);
                int totalShots = bursts * rocketsPerBurst;
                int firedShots = 0;

                Action fireNext = null;
                fireNext = () =>
                {
                    if (_ == null || man == null || man.isDestroyed || !man.active || man.location == Vector3.zero)
                    {
                        isFireingMlrs = false;
                        return;
                    }

                    float baseGravity;
                    Vector3 posFire = man.GetMlrsStrikePoint(firedShots);
                    Vector3 posUP = posFire + new Vector3(UnityEngine.Random.Range(-12f, 12f), 240f + (Mathf.FloorToInt(firedShots / rocketsPerBurst) * 8f), UnityEngine.Random.Range(-12f, 12f));

                    Vector3 aimToTarget = GetAimToTarget(posUP, posFire, out baseGravity);

                    var startPoint = posUP;
                    startPoint.y += 30f;

                    ServerProjectile projectile;
                    if (CreateAndSpawnRocket(startPoint, aimToTarget, out projectile))
                    {
                        TimedExplosive component = projectile != null ? projectile.GetComponent<TimedExplosive>() : null;
                        if (component != null && _AllMembers.Count > 0)
                            component.creatorEntity = _AllMembers.GetRandom();

                        if (projectile != null)
                            projectile.gravityModifier = 1.5f;
                    }

                    firedShots++;
                    if (firedShots >= totalShots)
                    {
                        _.timer.Once(1.2f, () => { isFireingMlrs = false; });
                        return;
                    }

                    bool endOfBurst = firedShots % rocketsPerBurst == 0;
                    _.timer.Once(endOfBurst ? burstInterval : rocketInterval, fireNext);
                };

                fireNext();
            }

            public static Vector3 GetAimToTarget(Vector3 startPosition, Vector3 targetPos, out float baseGravity)
            {
                Vector3 vector = targetPos - startPosition;
                float num = 90f;
                float num2 = vector.Magnitude2D();
                float y = vector.y;
                float num5 = 40f;

                baseGravity = ProjectileDistToGravity(Mathf.Max(num2, 50f), y, num5, num);

                vector.Normalize();
                vector.y = 0f;

                Vector3 axis = Vector3.Cross(vector, Vector3.up);

                vector = Quaternion.AngleAxis(num5, axis) * vector;

                return vector;
            }

            public static bool CreateAndSpawnRocket(Vector3 firingPos, Vector3 firingDir, out ServerProjectile mlrsRocketProjectile)
            {
                RaycastHit hitInfo;

                float launchOffset = 0f;

                if (Physics.Raycast(firingPos, firingDir, out hitInfo, launchOffset, 1236478737))
                    launchOffset = hitInfo.distance - 0.1f;

                var mlrsRocketEntity = GameManager.server.CreateEntity("assets/content/vehicles/mlrs/rocket_mlrs.prefab", firingPos + firingDir * launchOffset);

                if (mlrsRocketEntity == null)
                {
                    mlrsRocketProjectile = null;
                    return false;
                }

                var mlrsRocket = mlrsRocketEntity as MLRSRocket;
                if (mlrsRocket == null)
                {
                    mlrsRocketProjectile = null;
                    return false;
                }

                mlrsRocketProjectile = mlrsRocket.GetComponent<ServerProjectile>();
                if (mlrsRocketProjectile == null)
                {
                    mlrsRocketProjectile = null;
                    return false;
                }

                var velocityVector = mlrsRocketProjectile.initialVelocity + firingDir * mlrsRocketProjectile.speed;
                mlrsRocketProjectile.InitializeVelocity(velocityVector);

                mlrsRocket.OwnerID = 0;
                mlrsRocket.Spawn();

                return true;
            }

            public void Update()
            {
                ulong id = 0UL;
                if (_ == null)
                {
                    UnityEngine.GameObject.Destroy(this.gameObject);
                    return;
                }

                if (isDestroyed || !active)
                    return;

                if (nextMemberCleanupAt <= Time.time)
                {
                    CleanupInvalidMembers();
                    nextMemberCleanupAt = Time.time + 1f;
                }

                if (EndEventTime < Time.time)
                {
                    _.PrintWarning($"Завершаю рейд в точке {location}");
                    Destroy();
                    return;
                }

                RefreshRaidAnchors();
                if (HasLostTargetCupboard())
                {
                    _.PrintWarning($"Целевой шкаф рейда уничтожен в точке {location}, завершаю рейд как поражение владельцев.");
                    Destroy(false);
                    return;
                }

                if (sendGUI && Time.realtimeSinceStartup >= nextGuiUpdateAt)
                {
                    nextGuiUpdateAt = Time.realtimeSinceStartup + GetGuiRefreshInterval();
                    lastUINotification = DateTime.Now;
                    updatePlayers();
                    foreach (BasePlayer onPlayers in _onlinePlayers)
                        if (onPlayers != null && onPlayers.IsConnected)
                            SendClockGUI(onPlayers);
                }

                if (config.FireMlrs && MlrsEventTime < Time.time && !EventRandomManager.isFireingMlrs && MlrsEventTime != 0)
                {
                    setupMlrs(this);
                    ConsumeMlrsCallForWave();
                }

                int configuredWaveCount = Mathf.Max(1, config.TotalNpcWaves + 1);
                bool hasPendingWaveSpawn = currentWave < configuredWaveCount;

                if (!_.configData.settings.pauseWave)
                {
                    if (hasPendingWaveSpawn && nextWaveTime < Time.time)
                    {
                        nextWaveTime = Time.time + config.NextWaveSeconds;

                        if ((currentWave + 1) >= configuredWaveCount)
                        {
                            time = DateTime.Now;

                            int totalMinus = config.NextWaveSeconds * currentWave;
                            Duration = config.RunTimeSeconds - totalMinus;
                            TimeSpan timeOffset = new TimeSpan();
                            lastBlock = DateTime.Now;
                            lastNotification = DateTime.MinValue;
                            lastUINotification = DateTime.MinValue;
                            nextGuiUpdateAt = 0f;
                        }
                        else
                        {
                            Duration = config.NextWaveSeconds;
                            TimeSpan timeOffset = new TimeSpan();
                            lastBlock = DateTime.Now;
                            lastNotification = DateTime.MinValue;
                            lastUINotification = DateTime.MinValue;
                            nextGuiUpdateAt = 0f;
                        }
                        if (QueuedRoutine != null)
                            stopSpawning();
                        QueuedRoutine = StartCoroutine(GenerateEventMembers());
                        return;
                    }
                }
                else
                {
                    if (!newWave && hasPendingWaveSpawn && members.Count <= 0 && !curentlySawning)
                    {
                        curentlySawning = true;
                        nextWaveTime = Time.time + config.NextWaveSeconds;

                        if ((currentWave + 1) >= configuredWaveCount)
                        {
                            time = DateTime.Now;

                            Duration = config.NextWaveSeconds;
                            TimeSpan timeOffset = new TimeSpan();
                            lastBlock = DateTime.Now;
                            lastNotification = DateTime.MinValue;
                            lastUINotification = DateTime.MinValue;
                            nextGuiUpdateAt = 0f;
                        }
                        else
                        {
                            Duration = config.NextWaveSeconds;
                            TimeSpan timeOffset = new TimeSpan();
                            lastBlock = DateTime.Now;
                            lastNotification = DateTime.MinValue;
                            lastUINotification = DateTime.MinValue;
                            nextGuiUpdateAt = 0f;
                        }

                        return;
                    }
                    else if (curentlySawning && members.Count <= 0 && lastBlock.AddSeconds(Duration) - DateTime.Now <= TimeSpan.Zero)
                    {
                        Duration = 30;
                        TimeSpan timeOffset = new TimeSpan();
                        lastBlock = DateTime.Now;
                        lastNotification = DateTime.MinValue;
                        lastUINotification = DateTime.MinValue;
                        nextGuiUpdateAt = 0f;

                        if (QueuedRoutine != null)
                            stopSpawning();
                        QueuedRoutine = StartCoroutine(GenerateEventMembers());
                        showInfinity = true;
                    }
                }

                if (!curentlySawning && totalWaves >= configuredWaveCount && currentWave >= configuredWaveCount && members.Count <= 0)
                {
                    Destroy(true);
                    return;
                }
            }


            public void updatePlayers()
            {
                if (_onlinePlayers == null)
                    _onlinePlayers = new List<BasePlayer>();

                List<BasePlayer> previousUiPlayers = _onlinePlayers.ToList();
                _onlinePlayers.Clear();
                IEnumerable<ulong> uiPlayers = warSession != null ? warSession.GetRewardEligiblePlayers() : _authedPlayers;
                foreach (var user in uiPlayers)
                {
                    BasePlayer TCplayer = BasePlayer.FindByID(user);
                    if (TCplayer != null && TCplayer.IsConnected && !_onlinePlayers.Contains(TCplayer))
                        _onlinePlayers.Add(TCplayer);
                }

                foreach (BasePlayer previousPlayer in previousUiPlayers)
                {
                    if (previousPlayer != null && previousPlayer.IsConnected && !_onlinePlayers.Contains(previousPlayer))
                        CuiHelper.DestroyUi(previousPlayer, "RtimerS" + BlockName);
                }
            }

            public void SendClockGUI(BasePlayer current)
            {
                if (current == null)
                    return;

                CuiHelper.DestroyUi(current, "RtimerS" + BlockName);

                TimeSpan ts = lastBlock.AddSeconds(Duration) - DateTime.Now;

                int totalWavesNext = Mathf.Max(1, config.TotalNpcWaves + 1);

                string countDownM = FormatTime(ts);
                string countDownS = FormatTimeS(ts);
                string waveMessage = _.lang.GetMessage("nextWave", _);
                if (currentWave >= totalWavesNext)
                    waveMessage = _.lang.GetMessage("endEvent", _);

                string message = string.Format(_.lang.GetMessage("guiMessage", _), currentWave, totalWavesNext, members.Count, waveMessage, countDownM, countDownS);

                if (_.configData.settings.pauseWave)

                {
                    if (members.Count > 0 || showInfinity)
                        message = string.Format(_.lang.GetMessage("guiMessage", _), currentWave, totalWavesNext, members.Count, waveMessage, "∞", "∞");
                }

                var elements = new CuiElementContainer();

                var BlockMsg = elements.Add(new CuiPanel
                {
                    Image = { Color = "0.55 0.55 0.55 0.99" },
                    RectTransform = { AnchorMin = _.configData.settings.AnchorMin, AnchorMax = _.configData.settings.AnchorMax } }, "Hud", "RtimerS" + BlockName);

                elements.Add(new CuiElement
                {
                    Parent = BlockMsg,
                    Components = { new CuiRawImageComponent { Sprite = "assets/icons/explosion.png", Color = "0.95 0.4 0.02 0.99"},
                    new CuiRectTransformComponent { AnchorMin = "0 0", AnchorMax = "0.13 1" } }
                });

                elements.Add(new CuiLabel
                {
                    RectTransform = { AnchorMin = "0.15 0", AnchorMax = "1 1" },
                    Text = { Text = message, FontSize = 11, Align = TextAnchor.MiddleLeft, }
                }, BlockMsg);

                CuiHelper.AddUi(current, elements);
            }

            public void RemoveNpc(RandomRaider player)
            {
                if (members != null && members.Contains(player))
                    members.Remove(player);
                if (_AllMembers != null && _AllMembers.Contains(player))
                    _AllMembers.Remove(player);
            }

            private void CleanupInvalidMembers()
            {
                if (members == null || members.Count == 0)
                    return;

                for (int i = members.Count - 1; i >= 0; i--)
                {
                    RandomRaider raider = members[i];
                    if (raider == null || raider.IsDestroyed || raider.IsDead() || raider.Health() <= 0f)
                        members.RemoveAt(i);
                }
            }

            private float GetGuiRefreshInterval()
            {
                int aliveMembers = members != null ? members.Count : 0;
                if (aliveMembers >= 18)
                    return 2f;
                if (aliveMembers >= 10)
                    return 1.5f;
                return 1f;
            }

            private float GetRaiderObjectiveRefreshInterval()
            {
                int aliveMembers = members != null ? members.Count : 0;
                if (aliveMembers >= 18)
                    return 0.9f;
                if (aliveMembers >= 10)
                    return 0.65f;
                return 0.45f;
            }

            public void Destroy(bool win = false)
            {
                if (isDestroyed)
                    return;

                isDestroyed = true;

                if (boombox != null)
                    boombox?.Kill();

                if (win && config.WinDrop > 0)
                {
                    List<ulong> rewardPlayers = warSession != null ? warSession.GetRewardEligiblePlayers() : new List<ulong>(_authedPlayers);
                    if (config.lootProfileAirDrop.Count > 0)
                        dropWin(location, config.WinDrop, config.lootProfileAirDrop, rewardPlayers);
                    else dropWin(location, config.WinDrop, config.lootProfileAirDropA, rewardPlayers, true);

                }
                ulong id = 0UL;
                active = false;
                MlrsEventTime = 1;
                Interface.Oxide.CallHook("RandomRaidEventEnd", location);
                Interface.Oxide.CallHook("CobaltWarRaidEventEnd", location);
                warSession?.OnRaidManagerEnded(win);
                stopSpawning(true);
                CleanupTrackedRaidExplosives();

                if (marker != null)
                {
                    marker?.CancelInvoke(marker.DelayedDestroy);
                    marker?.Kill(BaseNetworkable.DestroyMode.None);
                }

                for (int i = members.Count - 1; i >= 0; i--)
                {
                    RandomRaider npc = members[i];
                    if (npc != null && !npc.IsDestroyed && !npc.isMounted)
                    {
                        npc.Kill();
                    }
                }

                HashSet<ulong> raidUiUsers = new HashSet<ulong>();
                foreach (var user in _authedPlayers)
                    raidUiUsers.Add(user);
                if (warSession != null)
                {
                    foreach (var user in warSession.GetRewardEligiblePlayers())
                        raidUiUsers.Add(user);
                }

                foreach (BasePlayer activePlayer in BasePlayer.activePlayerList)
                {
                    if (activePlayer != null && activePlayer.IsConnected)
                        CuiHelper.DestroyUi(activePlayer, "RtimerS" + BlockName);
                }

                foreach (var user in raidUiUsers)
                {
                    BasePlayer TCplayer = BasePlayer.FindByID(user);
                    if (TCplayer != null && TCplayer.IsConnected)
                    {
                        _.SendReply(TCplayer, _.lang.GetMessage("RaidersLeaving", _, TCplayer.UserIDString));
                    }
                }

                _.NextTick(() =>
                {
                    members.Clear();
                    Facepunch.Pool.FreeUnmanaged(ref members);
                    _authedPlayers.Clear();
                    _AllFoundations.Clear();
                    if (_AllRaids.Contains(this))
                        _AllRaids.Remove(this);
                    foreach (BradleyAPC tank in tanks.Where(x => x != null && !x.IsDestroyed).Distinct().ToList())
                        tank.Kill();
                    tanks.Clear();
                    foreach (PatrolHelicopter spawnedHeli in helis.Where(x => x != null && !x.IsDestroyed).Distinct().ToList())
                        spawnedHeli.GetComponent<PatrolHelicopterAI>()?.Retire();
                    helis.Clear();
                    jconfig = null;
                    savedPosition = null;
                    _onlinePlayers = null;
                    location = Vector3.zero;
                });
                UnityEngine.GameObject.Destroy(this.gameObject);
            }

            private List<string> getObjects(object name)
            {
                List<string> kitObject = new List<string>();
                if (name is string || name is int || name is float)
                    return kitObject;
                var json = JsonConvert.SerializeObject(name);
                if (json != null)
                    kitObject = JsonConvert.DeserializeObject<List<string>>(json) as List<string>;
                return kitObject;
            }
            public static void giveItem(BasePlayer RPlayer, int itemID, int total)
            {
                var item = ItemManager.CreateByItemID(itemID, total, 0);
                if (item == null) return;

                if (item.MoveToContainer(RPlayer.inventory.containerBelt, -1, true))
                    return;

                else if (item.MoveToContainer(RPlayer.inventory.containerMain, -1, true))
                    return;

                Vector3 velocity = Vector3.zero;
                item.Drop(RPlayer.transform.position + new Vector3(0.5f, 1f, 0), velocity);
                                _.SendReply(RPlayer, _.lang.GetMessage("RewardDropedOnGround", _, RPlayer.UserIDString));
            }

            public void stopSpawning(bool destroying = false)
            {
                if (QueuedRoutine != null)
                    StopCoroutine(QueuedRoutine);
                QueuedRoutine = null;
                float newTime = config.NextWaveSeconds + (config.TotalNpcs * 0.1f) + 12f;
                totalWaves++;
                if (!destroying && jconfig != null && jconfig.Count > 0)
                {
                    foreach (var key in jconfig)
                    {
                        if (key.juggernautOnWaves.ContainsKey(totalWaves))
                        {
                            if (savedPosition != null && savedPosition.Count > 0)
                            {
                                for (int spawnTotals = 0; spawnTotals < key.juggernautOnWaves[totalWaves]; spawnTotals++)
                                {
                                    Vector3 position = savedPosition.GetRandom();
                                    RandomRaider theNewGuy = SpawnNPC(position, key);
                                    if (theNewGuy != null)
                                    {
                                        members.Add(theNewGuy);
                                        if (theNewGuy != null)
                                            _AllMembers.Add(theNewGuy);
                                        if (debug) _.PrintWarning($"Спавню джаггернаута в точке {position} для волны {totalWaves}");
                                    }
                                }
                            }
                        }
                    }
                }
            }

            public IEnumerator GenerateEventMembers()
            {
                if (config == null)
                {
                    stopSpawning();
                    yield break;
                }

                int configuredWaveCount = Mathf.Max(1, config.TotalNpcWaves + 1);
                if (currentWave >= configuredWaveCount)
                {
                    curentlySawning = false;
                    showInfinity = false;
                    QueuedRoutine = null;

                    if (members.Count <= 0)
                        Destroy(true);

                    yield break;
                }

                currentWave++;
                SpawnWaveSupport(currentWave);
                ArmMlrsForCurrentWave(currentWave <= 1);
                ulong id = 0UL;
                showInfinity = true;
                if (newWave)
                {
                    _.PrintWarning($"Рейд запущен в точке {location}");
                }
                else
                {
                    if (debug) _.PrintWarning($"Следующая волна рейда запущена в точке {location}");
                }
                newWave = false;
                int totalNpc = 0;
                float spawnDictance = 40;
                float radius = 200;
                float spawnStep = GetSafeSpawnCircumferenceStep(radius, config.TotalNpcs);
                List<Vector3> positions = generateSpawnList(location, spawnDictance, spawnStep);

                if (savedPosition.Count <= 0)
                    savedPosition = new List<Vector3>(positions);

                yield return CoroutineEx.waitForSeconds(5f);
                while (positions.Count < config.TotalNpcs)
                {
                    if (radius < 50f)
                    {
                        _.PrintWarning($"Недостаточно точек спавна, попытка рейда в точке {location} остановлена");
                        Destroy();
                        yield break;
                    }
                    radius = radius - 10f;
                    spawnDictance = spawnDictance + 2f;
                    spawnStep = GetSafeSpawnCircumferenceStep(radius, config.TotalNpcs);
                    positions = generateSpawnList(location, spawnDictance, spawnStep);

                    _.PrintWarning($"Недостаточно точек спавна, увеличиваю радиус поиска до {spawnDictance}");
                    yield return CoroutineEx.waitForSeconds(5f);
                }
                yield return CoroutineEx.waitForSeconds(1f);
                while (totalNpc < config.TotalNpcs)
                {
                    Vector3 position = positions.GetRandom();
                    positions.Remove(position);
                    RandomRaider theNewGuy = SpawnNPC(position);
                    if (theNewGuy != null)
                    {
                        members.Add(theNewGuy);
                        yield return CoroutineEx.waitForSeconds(0.1f);
                        if (theNewGuy != null && theNewGuy != null)
                            _AllMembers.Add(theNewGuy);
                        if (!active)
                            active = true;
                    }

                    totalNpc++;
                    yield return CoroutineEx.waitForSeconds(1.0f);
                }
                curentlySawning = false;
                showInfinity = false;
                /* float newTime = config.NextWaveSeconds + (config.TotalNpcs * 0.1f) + 12f;
                   nextWaveTime = Time.time + newTime;
                   totalWaves++; 
                   raidernewID = "";*/
                stopSpawning();
            }

            #region Spawning
            public RandomRaider SpawnNPC(Vector3 pos, juggernautConfig isJug = null)
            {
                pos.y = TerrainMeta.HeightMap.GetHeight(pos);
                object position = FindPointOnNavmesh(pos, 10f);
                if (position is Vector3 && (Vector3)position != Vector3.zero)
                {
                    RandomRaider scientistNPC = InstantiateEntity((Vector3)position, Quaternion.Euler(0, 0, 0));

                    if (scientistNPC == null) return null;

                    scientistNPC.enableSaving = false;
                    scientistNPC.isJug = isJug;
                    scientistNPC.skinID = 8675309;
                    scientistNPC.Spawn();
                    scientistNPC.gameObject.SetActive(true);
                    scientistNPC.manager = this;
                    Interface.Oxide.CallHook("OnRandomRaidRaiderSpawned", location, scientistNPC, isJug);
                    Interface.Oxide.CallHook("OnCobaltWarRaiderSpawned", location, scientistNPC, isJug);
                    _.NextTick(() =>
                    {
                        if (scientistNPC != null)
                        {
                            scientistNPC.InitNewSettings(location, config.Health);
                            if (config.kits.Count > 0)
                            {
                                if (!string.IsNullOrEmpty(sameKit))
                                    scientistNPC.setUpGear(sameKit);
                                else
                                    scientistNPC.setUpGear(config.kits.GetRandom());
                            }
                            else scientistNPC.setUpGear("");
                        }
                    });
                    if (scientistNPC != null)
                    {
                        if (config.NpcNames.Count > 0)
                        {
                            string name = config.NpcNames.GetRandom();
                            scientistNPC.displayName = name;
                            scientistNPC.npcName = name;
                        }
                        else
                        {
                            scientistNPC.displayName = "Боец \"Кобальт\"";
                            scientistNPC.npcName = "Боец \"Кобальт\"";
                        }

                        return scientistNPC;
                    }
                }

                return null;
            }
            
            private static float GetSafeSpawnCircumferenceStep(float radius, int totalNpcs)
            {
                int safeNpcCount = Mathf.Max(1, totalNpcs);
                float calculatedStep = radius / safeNpcCount;
                return Mathf.Clamp(calculatedStep, 4f, 45f);
            }

            private static List<Vector3> generateSpawnList(Vector3 position, float radius = 100, float next = 2f)
            {
                List<Vector3> placement = new List<Vector3>();

                placement = GetCircumferencePositions(position, radius, next, position.y);
                foreach (Vector3 locat in placement.ToList())
                {
                    if (HasCupboard(locat) != null)
                        placement.Remove(locat);

                    if (IsInRockPrefab(locat))
                        placement.Remove(locat);

                    if (CobaltWar.IsBlockedByRockObstruction(locat, 0.35f))
                        placement.Remove(locat);

                    if (IsNearWorldCollider(locat))
                        placement.Remove(locat);
                }
                return placement;
            }

            private static BuildingPrivlidge HasCupboard(Vector3 position)
            {
                BuildingPrivlidge f = null;
                var list = Pool.Get<List<BuildingPrivlidge>>();
                Vis.Entities(position, 5f, list);
                foreach (var i in list)
                {
                    if (i.IsValid() && i is BuildingPrivlidge)
                    {
                        f = i;
                        break;
                    }
                }
                Pool.FreeUnmanaged(ref list);
                return f;
            }

            private static List<Vector3> GetCircumferencePositions(Vector3 center, float radius, float next, float y)
            {
                var positions = new List<Vector3>();
                next = Mathf.Clamp(next, 4f, 45f);
                float degree = 0f;
                int iteration = 0;
                int maxIterations = Mathf.Clamp(Mathf.CeilToInt(360f / next) + 2, 8, 120);

                while (degree < 360f && iteration++ < maxIterations)
                {
                    float angle = (float)(2 * Math.PI / 360) * degree;
                    float x = center.x + radius * (float)Math.Cos(angle);
                    float z = center.z + radius * (float)Math.Sin(angle);
                    var position = new Vector3(x, center.y, z);
                    object success = FindPointOnNavmesh(position, 10f);
                    if (success != null)
                        positions.Add((Vector3)success);

                    degree += next;
                }

                return positions;
            }

            private static NavMeshHit navmeshHit;

            private static RaycastHit raycastHit;

            private static Collider[] _buffer = new Collider[256];

            private const int WORLD_LAYER = 65536;

            public static object FindPointOnNavmesh(Vector3 targetPosition, float maxDistance = 4f)
            {
                for (int i = 0; i < 10; i++)
                {
                    Vector3 position = i == 0 ? targetPosition : targetPosition + (UnityEngine.Random.onUnitSphere * maxDistance);
                    if (NavMesh.SamplePosition(position, out navmeshHit, maxDistance, 1))
                    {
                        if (IsInRockPrefab2(navmeshHit.position))
                            continue;

                        if (IsInRockPrefab(navmeshHit.position))
                            continue;

                        if (CobaltWar.IsBlockedByRockObstruction(navmeshHit.position, 0.35f))
                            continue;

                        if (IsNearWorldCollider(navmeshHit.position))
                            continue;

                        return navmeshHit.position;
                    }
                }
                return null;
            }

            public static bool IsInRockPrefab(Vector3 position)
            {
                Physics.queriesHitBackfaces = true;

                bool isInRock = Physics.Raycast(position, Vector3.up, out raycastHit, 20f, WORLD_LAYER, QueryTriggerInteraction.Ignore) &&
                                blockedColliders.Any(s => raycastHit.collider?.gameObject?.name.Contains(s) ?? false);

                Physics.queriesHitBackfaces = false;

                return isInRock;
            }

            public static bool IsInRockPrefab2(Vector3 position)
            {
                Vector3 p1 = position + new Vector3(0, 20f, 0);
                Vector3 p2 = position + new Vector3(0, -2f, 0);
                Vector3 diff = p2 - p1;
                RaycastHit[] hits;
                hits = Physics.RaycastAll(p1, diff, diff.magnitude);
                if (hits.Length > 0)
                {
                    for (int i = 0; i < hits.Length; i++)
                    {
                        RaycastHit hit = hits[i];
                        if (hit.collider != null)
                        {
                            bool isRock = blockedColliders.Any(s => hit.collider?.gameObject?.name.ToLower().Contains(s) ?? false);
                            if (isRock)
                            {
                                return true;
                            }
                        }
                    }
                }
                return false;
            }

            public static bool IsNearWorldCollider(Vector3 position)
            {
                Physics.queriesHitBackfaces = true;

                int count = Physics.OverlapSphereNonAlloc(position, 2f, _buffer, WORLD_LAYER, QueryTriggerInteraction.Ignore);
                Physics.queriesHitBackfaces = false;

                if (count == 0)
                    return false;

                int removed = 0;
                for (int i = 0; i < count; i++)
                {
                    if (acceptedColliders.Any(s => _buffer[i].gameObject.name.Contains(s)))
                    {
                        removed++;
                    }
                }


                return count - removed > 0;
            }

            private static readonly string[] acceptedColliders = new string[] { "ice_lake", "road", "carpark", "rocket_factory", "range", "train_track", "runway", "_grounds", "concrete_slabs", "lighthouse", "cave", "office", "walkways", "sphere", "tunnel", "industrial", "junkyard" };

            private static readonly string[] blockedColliders = new string[] { "rock", "junk", "range", "invisible", "cliff", "prevent_movement", "formation_" };
            #endregion
        }
        #endregion

        #region RandomRaider Spawn Method
        private static RandomRaider InstantiateEntity(Vector3 position, Quaternion rotation)
        {
            GameObject gameObject = Instantiate.GameObject(GameManager.server.FindPrefab("assets/rust.ai/agents/npcplayer/humannpc/scientist/scientistnpc_full_any.prefab"), position, Quaternion.identity);
            gameObject.name = "assets/rust.ai/agents/npcplayer/humannpc/scientist/scientistnpc_full_any.prefab";
            gameObject.SetActive(false);
            ScientistNPC scientistNPC = gameObject.GetComponent<ScientistNPC>();
            ScientistBrain defaultBrain = gameObject.GetComponent<ScientistBrain>();

            defaultBrain._baseEntity = scientistNPC;

            RandomRaider component = gameObject.AddComponent<RandomRaider>();
            RandomRaiderBrain brains = gameObject.AddComponent<RandomRaiderBrain>();
            brains.Pet = false;
            brains.AllowedToSleep = false;
            CopyFields<NPCPlayer>(scientistNPC, component);

            brains._baseEntity = component;

            UnityEngine.Object.DestroyImmediate(defaultBrain, true);
            UnityEngine.Object.DestroyImmediate(scientistNPC, true);
            UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(gameObject, Rust.Server.EntityScene);
            UnityEngine.Object.Destroy(gameObject.GetComponent<Spawnable>());

            return component;
        }

        private static void CopyFields<T>(T src, T dst)
        {
            var fields = typeof(T).GetFields();

            foreach (var field in fields)
            {
                if (field.IsStatic) continue;
                object value = field.GetValue(src);
                field.SetValue(dst, value);
            }
        }
