                ItemManager.CreateByName("frankensteins.monster.03.head").MoveToContainer(this.inventory.containerWear);
                ItemManager.CreateByName("frankensteins.monster.03.legs").MoveToContainer(this.inventory.containerWear);
                ItemManager.CreateByName("frankensteins.monster.03.torso").MoveToContainer(this.inventory.containerWear);

                switch (UnityEngine.Random.Range(0, 3))
                {
                    case 0:
                        ItemManager.CreateByName("smg.mp5").MoveToContainer(this.inventory.containerBelt, 0);
                        break;
                    case 1:
                        ItemManager.CreateByName("lmg.m249").MoveToContainer(this.inventory.containerBelt, 0);
                        break;
                    case 2:
                        ItemManager.CreateByName("smg.mp5").MoveToContainer(this.inventory.containerBelt, 0);
                        break;
                    default:
                        ItemManager.CreateByName("lmg.m249").MoveToContainer(this.inventory.containerBelt, 0);
                        break;
                }
                this.inventory.containerBelt.OnChanged();
            }

            private void setupweapons()
            {
                _ProjectilesSlot = new List<int>();
                _MeleWeaponSlot = new List<int>();
                _BaseLauncherSlot = new List<int>();
                foreach (Item slot in inventory.containerBelt.itemList)
                {
                    if (slot != null)
                    {
                        BaseEntity heldEntity = slot.GetHeldEntity();
                        if (heldEntity != null)
                        {
                            AttackEntity _attackEntity = heldEntity.GetComponent<AttackEntity>();
                            if (_attackEntity != null)
                            {
                                _attackEntity.deployDelay = 0.5f;

                                if (_attackEntity is BaseLauncher)
                                {
                                    _BaseLauncherSlot.Add(slot.position);
                                    _attackEntity.aiOnlyInRange = false;
                                }
                                else if (_attackEntity is BaseProjectile)
                                {
                                    _ProjectilesSlot.Add(slot.position);
                                    _attackEntity.aiOnlyInRange = false;
                                 //   (_attackEntity as BaseProjectile).reloadTime = 0.1f;

                                    if (_attackEntity.effectiveRange <= 5)
                                        _attackEntity.effectiveRange = 15f;
                                }
                                else _MeleWeaponSlot.Add(slot.position);
                            }
                        }
                    }
                }
                if (debug)
                {
                    _.PrintWarning($"DEBUG: Снарядов: {_ProjectilesSlot.Count}, штурмовиков-базоломов: {_BaseLauncherSlot.Count}, бойцов ближнего боя: {_MeleWeaponSlot.Count}");
                }
            }

            public HeldEntity EquipNewWeapon(int slot = 0)
            {
                if (this.IsDestroyed) return null;
                Item weapon = this.inventory.containerBelt.GetSlot(slot);
                if (weapon != null)
                {
                    HeldEntity heldEntity = weapon.GetHeldEntity() as HeldEntity;
                    if (heldEntity != null)
                    {
                        AttackEntity _attackEntity = heldEntity.GetComponent<AttackEntity>();
                        if (_attackEntity == null) return null;

                        this.UpdateActiveItem(weapon.uid);

                        _attackEntity.SetHeld(true);

                        if (_attackEntity is Chainsaw)
                            (_attackEntity as Chainsaw).ServerNPCStart();
                        heldEntity.SetHeld(true);
                        return heldEntity;
                    }
                }
                return null;
            }

            private BaseEntity UpdateTargets()
            {
                if (manager == null || _ == null)
                {
                    this.Kill();
                    return null;
                }
                if (this.IsDestroyed)
                    return null;

                if (currentTarget != null && (currentTarget.IsDestroyed || currentTarget.Health() <= 0f))
                    currentTarget = null;

                if (nextTargetRefreshTime > Time.time)
                {
                    UpdateMemory();
                    GetRaidReady();
                    return currentTarget;
                }

                nextTargetRefreshTime = Time.time + GetTargetRefreshInterval();

                BaseEntity target = null;
                float delta = -1f;
                foreach (BaseEntity baseEntity in Brain.Senses.Memory.Targets)
                {
                    if (baseEntity == null || baseEntity.Health() <= 0f)
                        continue;

                    BasePlayer playerTarget = baseEntity as BasePlayer;
                    if (playerTarget != null && ShouldIgnorePlayer(playerTarget))
                        continue;

                    if (playerTarget != null && !ShouldInterruptRaidForPlayer(playerTarget))
                        continue;

                    if (!CanSeeTarget(baseEntity))
                        continue;

                    float distanceToTarget = Vector3.Distance(baseEntity.transform.position, transform.position);
                    if (distanceToTarget > Brain.TargetLostRange)
                        continue;

                    float rangeDelta = 1f - Mathf.InverseLerp(1f, Brain.SenseRange, distanceToTarget);

                    float dot = Vector3.Dot((baseEntity.transform.position - eyes.position).normalized, eyes.BodyForward());

                    rangeDelta += Mathf.InverseLerp(Brain.VisionCone, 1f, dot) / 2f;
                    rangeDelta += (Brain.Senses.Memory.IsLOS(baseEntity) ? 2f : 0f);

                    if (rangeDelta <= delta)
                        continue;

                    target = baseEntity;
                    delta = rangeDelta;
                }

                currentTarget = target as BaseCombatEntity;
                if (target != null)
                {
                    Brain.Senses.Memory.Threats.Add(target);
                    Brain.Senses.Memory.SetKnown(target, this, null);
                    lastTargetTime = Time.time + Brain.Senses.MemoryDuration;
                    lastTargetPosition = target.transform.position;
                }
                UpdateMemory();
                GetRaidReady();
                return target;
            }

            private float GetTargetRefreshInterval()
            {
                int aliveRaiders = manager?.members != null ? manager.members.Count : 0;
                if (aliveRaiders >= 18)
                    return 0.85f;
                if (aliveRaiders >= 10)
                    return 0.6f;
                return 0.35f;
            }

            private float nextRaidTime { get; set; }
            public void GetRaidReady()
            {
                if (this.IsDestroyed) return;
                if (this == null || this.IsDestroyed || this.IsDead() || manager == null)
                    return;

                bool needObjectiveRefresh = currentTargetOverride == null || currentTargetOverride.IsDestroyed || currentTargetOverride.Health() <= 0f;
                if (!needObjectiveRefresh && nextRaidTime >= Time.time)
                    return;

                nextRaidTime = Time.time + (needObjectiveRefresh ? 0.75f : 2.5f);
                currentTargetOverride = manager.GetRaidObjective(transform.position, currentTargetOverride);
                if (currentTargetOverride != null)
                {
                    HomePosition = currentTargetOverride.transform.position;
                    if (debug) _.PrintWarning($"Выбрана цель штурма: {currentTargetOverride.ShortPrefabName}");
                }
            }

            private bool HasLiveRaidObjective()
            {
                return currentTargetOverride != null && !currentTargetOverride.IsDestroyed && currentTargetOverride.Health() > 0f;
            }

            private bool ShouldInterruptRaidForPlayer(BasePlayer player)
            {
                if (player == null || player.IsDead() || player.IsSleeping())
                    return false;

                if (!HasLiveRaidObjective())
                    return true;

                float distanceToPlayer = Vector3.Distance(player.transform.position, transform.position);
                if (distanceToPlayer <= 12f)
                    return true;

                if (lastDamagePlayer != null && lastDamagePlayer.userID == player.userID && lastPlayerThreatTime + 12f > Time.time)
                    return true;

                if (Brain != null && Brain.Senses != null && Brain.Senses.Memory != null && Brain.Senses.Memory.IsLOS(player) && distanceToPlayer <= 18f)
                    return true;

                if (manager != null && manager.building != null && !manager.building.IsDestroyed)
                {
                    float distanceToCupboard = Vector3.Distance(player.transform.position, manager.building.transform.position);
                    if (distanceToCupboard <= 8f)
                        return true;
                }

                return false;
            }

            private BasePlayer[] playerQueryResults = new BasePlayer[64];

            private void UpdateMemory()
            {
                if (nextMemoryRefreshTime > Time.time)
                    return;

                nextMemoryRefreshTime = Time.time + GetMemoryRefreshInterval();
                int inSphere = BaseEntity.Query.Server.GetPlayersInSphere(this.transform.position, Brain.SenseRange, playerQueryResults, new Func<BaseEntity, bool>(AiCaresAbout));
                for (int i = 0; i < inSphere; i++)
                {
                    BaseCombatEntity baseCombatEntity = playerQueryResults[i] as BaseCombatEntity;
                    if (baseCombatEntity != null && !baseCombatEntity.EqualNetID(this) && IsVisibleToUs(baseCombatEntity))
                    {
                        Brain.Senses.Memory.SetKnown(baseCombatEntity, this, null);
                    }
                }
            }

            private float GetMemoryRefreshInterval()
            {
                int aliveRaiders = manager?.members != null ? manager.members.Count : 0;
                if (currentTarget == null)
                {
                    if (aliveRaiders >= 18)
                        return 0.75f;
                    if (aliveRaiders >= 10)
                        return 0.55f;
                    return 0.35f;
                }

                if (aliveRaiders >= 18)
                    return 1.05f;
                if (aliveRaiders >= 10)
                    return 0.8f;
                return 0.5f;
            }

            private bool AiCaresAbout(BaseEntity entity)
            {
                BaseCombatEntity baseCombatEntity = entity as BaseCombatEntity;

                if (baseCombatEntity == null || baseCombatEntity.IsDestroyed || baseCombatEntity.transform == null)
                    return false;

                if (baseCombatEntity.Health() <= 0f)
                    return false;

                if (baseCombatEntity is BasePlayer)
                {
                    BasePlayer player = baseCombatEntity as BasePlayer;

                    if (this.userID == player.userID)
                        return false;

                    if (player is global::HumanNPC)
                        return false;

                    if (player is RandomRaider)
                        return false;

                    if (!player.userID.IsSteamId() && !player.IsNpc)
                        return false;

                    return true;
                }

                if (baseCombatEntity is BaseNpc)
                    return false;

                return false;
            }
            public bool IsVisibleToUs(BaseCombatEntity baseCombatEntity)
            {
                if (baseCombatEntity is BasePlayer)
                    return IsPlayerVisibleToUs(baseCombatEntity as BasePlayer, Vector3.zero, 1218519041);
                else return IsVisible(baseCombatEntity.CenterPoint(), eyes.worldStandingPosition, float.PositiveInfinity);
            }

            private bool ShouldIgnorePlayer(BasePlayer player)
            {
                if (player == null || player.IsDead() || player.IsSleeping()) return true;
                return false;
            }

            public Vector3 GetCurrentObjectivePoint()
            {
                if (currentTargetOverride == null || currentTargetOverride.IsDestroyed)
                    GetRaidReady();

                if (currentTargetOverride == null || currentTargetOverride.IsDestroyed)
                    return manager != null ? manager.location + new Vector3(0f, 1f, 0f) : Vector3.zero;

                BuildingBlock block = currentTargetOverride as BuildingBlock;
                if (block != null)
                    return block.CenterPoint();

                Vector3 point = currentTargetOverride.transform.position;
                point.y += currentTargetOverride is BuildingPrivlidge ? 0.8f : 0.5f;
                return point;
            }

            public bool TargetInThrowableRange()
            {
                if (currentTargetOverride == null)
                    return false;
                return !hasWall();
            }

            private static bool IsStructuralEntity(BaseEntity entity)
            {
                if (entity == null)
                    return false;

                if (entity is BuildingBlock || entity is BuildingPrivlidge)
                    return true;

                string shortName = entity.ShortPrefabName ?? string.Empty;
                return shortName.Contains("wall.external") || shortName.Contains("gates.external");
            }

            public bool CanLaunchRocketAt(Vector3 targetPosition)
            {
                if (manager == null || targetPosition == Vector3.zero)
                    return false;

                float minDistance = Mathf.Max(6f, _.configData?.cobaltWar?.npcSiegeRocketMinDistance ?? 14f);
                float maxDistance = Mathf.Max(minDistance + 8f, _.configData?.cobaltWar?.npcSiegeRocketMaxDistance ?? 58f);
                float distance = Vector3.Distance(eyes.position, targetPosition);
                if (distance < minDistance || distance > maxDistance)
                    return false;

                Vector3 origin = eyes.position + eyes.BodyForward() * 0.25f;
                Vector3 adjustedTarget = targetPosition + new Vector3(0f, 0.6f, 0f);

                RaycastHit hit;
                if (!Physics.Linecast(origin, adjustedTarget, out hit, obstructionMask, QueryTriggerInteraction.Ignore))
                    return true;

                BaseEntity hitEntity = hit.GetEntity();
                if (hitEntity == null)
                    return false;

                if (currentTargetOverride != null && hitEntity.net == currentTargetOverride.net)
                    return true;

                return IsStructuralEntity(hitEntity) && Vector3.Distance(hit.point, adjustedTarget) <= 6f;
            }

            public bool CanThrowExplosiveAt(Vector3 targetPosition)
            {
                if (manager == null || targetPosition == Vector3.zero)
                    return false;

                if (currentTargetOverride == null || !IsStructuralEntity(currentTargetOverride))
                    return false;

                float distance = Vector3.Distance(eyes.position, targetPosition);
                if (distance > 10f || distance < 1.5f)
                    return false;

                if (TargetInThrowableRange())
                    return true;

                Vector3 origin = eyes.position + eyes.BodyForward() * 0.2f;
                Vector3 adjustedTarget = targetPosition + new Vector3(0f, 0.35f, 0f);
                RaycastHit hit;
                if (!Physics.Linecast(origin, adjustedTarget, out hit, obstructionMask, QueryTriggerInteraction.Ignore))
                    return true;

                BaseEntity hitEntity = hit.GetEntity();
                if (hitEntity == null)
                    return false;

                if (currentTargetOverride.net != null && hitEntity.net == currentTargetOverride.net)
                    return true;

                return IsStructuralEntity(hitEntity) && Vector3.Distance(hit.point, adjustedTarget) <= 3.5f;
            }

            public bool hasWall()
            {
                RaycastHit hit;
                if (Physics.Raycast(transform.position, transform.TransformDirection(Vector3.forward), out hit, 5.2f, BuildingLayer))
                {
                    return true;
                }

                return false;
            }

