        private object OnEntityKill(BaseNetworkable entity)
        {
            TimedExplosive timedExplosive = entity as TimedExplosive;
            if (timedExplosive != null)
            {
                RandomRaider explosiveOwner = timedExplosive.creatorEntity as RandomRaider;
                explosiveOwner?.manager?.UnregisterTemporaryExplosive(entity);
            }

            DudTimedExplosive dudTimedExplosive = entity as DudTimedExplosive;
            if (dudTimedExplosive != null)
            {
                RandomRaider dudOwner = dudTimedExplosive.creatorEntity as RandomRaider;
                dudOwner?.manager?.UnregisterTemporaryExplosive(entity);
            }

            SupplyDrop container = entity as SupplyDrop;
            if (container != null && container.net != null && supplyDrops.ContainsKey(container.net.ID.Value))
            {
                supplyDrops.Remove(container.net.ID.Value);
            }

            BradleyAPC tank = entity as BradleyAPC;
            if (tank != null && IsTrackedCobaltTank(tank))
            {
                Vector3 cleanupPosition = tank.transform.position;
                UnregisterCobaltTank(tank);
                ScheduleCobaltTankDebrisCleanup(cleanupPosition);
            }

            PatrolHelicopter heli = entity as PatrolHelicopter;
            if (heli != null && IsTrackedCobaltHeli(heli))
            {
                Vector3 cleanupPosition = heli.transform.position;
                UnregisterCobaltHeli(heli);
                ScheduleCobaltHeliDebrisCleanup(cleanupPosition);
            }

            CobaltSupportDroneState supportDroneState = FindCobaltSupportDroneState(entity);
            if (supportDroneState != null)
            {
                CobaltWarSession supportDroneWar = FindWar(supportDroneState.warId);
                if (supportDroneWar != null)
                    supportDroneWar.ScheduleSupportDroneRespawn(supportDroneState);

                DestroyCobaltSupportDrone(supportDroneState);
            }

            BuildingPrivlidge privilege = entity as BuildingPrivlidge;
            if (privilege != null)
                HandleDestroyedRaidCupboard(privilege);

            return null;
        }

        private void HandleDestroyedRaidCupboard(BuildingPrivlidge privilege)
        {
            if (privilege == null || privilege.net == null)
                return;

            ulong cupboardId = privilege.net.ID.Value;
            if (cupboardId == 0UL)
                return;

            foreach (EventRandomManager raid in EventRandomManager._AllRaids.ToList())
            {
                if (raid == null || raid.isDestroyed || !raid.IsTrackingCupboard(cupboardId))
                    continue;

                raid.Destroy(false);
            }

            foreach (CobaltWarSession war in activeCobaltWars.Values.ToList())
            {
                if (war == null || war.IsEnded || war.privilege == null || war.privilege.net == null)
                    continue;

                if (war.privilege.net.ID.Value != cupboardId)
                    continue;

                war.FailWarBecauseCupboardDestroyed();
            }
        }

        private void OnEntityDeath(BaseCombatEntity entity, HitInfo info)
        {
            BuildingPrivlidge privilege = entity as BuildingPrivlidge;
            if (privilege != null)
                HandleDestroyedRaidCupboard(privilege);
        }

