        void startPlayerSearch(BasePlayer player)
        {
            if (HasAnyRaidEventInProgress())
            {
                if (player != null)
                    SendReply(player, lang.GetMessage("MaxEvents", this, player.UserIDString));
                return;
            }

            if (QueuedRoutinePlayer != null)
                ServerMgr.Instance.StopCoroutine(QueuedRoutinePlayer);
            QueuedRoutinePlayer = null;
            QueuedRoutinePlayer = ServerMgr.Instance.StartCoroutine(FindRandomBaseToRaid(configData.settings.mustBeOnlinePlayer, false, player));
            RefreshPlayerInputHookSubscription();
        }

        void startRestartSearch()
        {
            try
            {
                EnsurePlayerDataStructures();
                CobaltDiagnosticLog("idle", $"Автопоиск tick: online={GetOnlineRaidPlayerCount()}, tcData={pcdData?.tcData?.Count ?? 0}, searchRoutineActive={QueuedRoutine != null}, raidSlotBusy={HasAnyRaidEventInProgress()}.");

                if (QueryPauseAutomaticRaidsForPurchaseQueue())
                {
                    CobaltDiagnosticLog("idle", "Автопоиск пропущен: есть очередь покупных рейдов.");
                    return;
                }

                if (pcdData?.tcData == null || pcdData.tcData.Count <= 0)
                {
                    CobaltDiagnosticLog("idle", "Автопоиск пропущен: нет данных tcData.");
                    return;
                }

                if (configData?.settings?.mustBeOnlinePlayer == true && GetOnlineRaidPlayerCount() <= 0)
                {
                    CobaltDiagnosticLog("idle", "Автопоиск пропущен: нет онлайн-игроков.");
                    return;
                }

                if (HasAnyRaidEventInProgress())
                {
                    CobaltDiagnosticLog("idle", "Автопоиск пропущен: слот рейда уже занят.");
                    return;
                }

                if (QueuedRoutine != null)
                {
                    CobaltDiagnosticLog("idle", "Автопоиск пропущен: предыдущий scan еще выполняется.");
                    return;
                }

                CobaltDiagnosticLog("idle", $"Автопоиск запущен: tcData={pcdData.tcData.Count}, online={GetOnlineRaidPlayerCount()}, mustBeOnline={configData.settings.mustBeOnlinePlayer}.");
                QueuedRoutine = ServerMgr.Instance.StartCoroutine(FindRandomBaseToRaid(configData.settings.mustBeOnlinePlayer, true));
                RefreshPlayerInputHookSubscription();
            }
            catch (Exception ex)
            {
                PrintError($"startRestartSearch failed: {ex}");
            }
        }

        void stopSearch()
        {
            if (QueuedRoutine != null)
                ServerMgr.Instance.StopCoroutine(QueuedRoutine);
            if (QueuedRoutinePlayer != null)
                ServerMgr.Instance.StopCoroutine(QueuedRoutinePlayer);

            QueuedRoutine = null;
            QueuedRoutinePlayer = null;
            RefreshPlayerInputHookSubscription();
        }

        [HookMethod("GetRaidPurchaseBases")]
        private object GetRaidPurchaseBases(BasePlayer player)
        {
            List<Dictionary<string, object>> results = new List<Dictionary<string, object>>();
            if (player == null || pcdData == null)
                return results;

            bool removedInvalid = false;
            HashSet<ulong> seen = new HashSet<ulong>();

            BuildingPrivlidge currentPriv = player.GetBuildingPrivilege();
            if (currentPriv != null && currentPriv.IsAuthed(player))
            {
                string currentReason;
                List<BuildingBlock> currentBlocks;
                List<ulong> currentAuthPlayers;
                if (TryPrepareRaidBase(currentPriv, out currentBlocks, out currentAuthPlayers, out currentReason, true))
                    AddRaidPurchaseBaseOption(results, currentPriv, player, currentBlocks, currentAuthPlayers);

                if (currentPriv.net != null)
                    seen.Add(currentPriv.net.ID.Value);
                CachePlayerCupboard(player, currentPriv);
            }

            List<ulong> cupboardIds;
            if (pcdData.tcData.TryGetValue(player.userID.Get(), out cupboardIds))
            {
                foreach (ulong key in cupboardIds.ToList())
                {
                    BuildingPrivlidge privFind = FindEntity(key) as BuildingPrivlidge;
                    if (privFind == null)
                    {
                        cupboardIds.Remove(key);
                        removedInvalid = true;
                        continue;
                    }

                    if (privFind.net != null && seen.Contains(privFind.net.ID.Value))
                        continue;

                    if (!privFind.IsAuthed(player))
                        continue;

                    string failReasonKey;
                    List<BuildingBlock> blocks;
                    List<ulong> authPlayers;
                    if (!TryPrepareRaidBase(privFind, out blocks, out authPlayers, out failReasonKey, true))
                        continue;

                    AddRaidPurchaseBaseOption(results, privFind, player, blocks, authPlayers);
                    if (privFind.net != null)
                        seen.Add(privFind.net.ID.Value);
                }
            }

            if (removedInvalid)
                QueuePlayerDataSave();

            return results;
        }

        [HookMethod("StartRaidPurchase")]
        private object StartRaidPurchase(BasePlayer player, ulong tcNetId, string raidType, bool immediateStart, bool autoRegisterBuyerAsDefender)
        {
            try
            {
                if (player == null)
                    return CreateRaidPurchaseResult(false, "invalid_player", "Unknown player.", string.Empty, raidType);

                CobaltDiagnosticLog("purchase", $"Покупка рейда: player={player.displayName}, raidType={raidType}, tcNetId={tcNetId}, immediate={immediateStart}, autoRegister={autoRegisterBuyerAsDefender}.");

                if (string.IsNullOrEmpty(raidType) || configData?.raidSettings?.raidTypes == null || !configData.raidSettings.raidTypes.ContainsKey(raidType))
                {
                    CobaltDiagnosticLog("purchase", $"Покупка рейда отклонена: player={player.displayName}, raidType={raidType}, reason=invalid_type.");
                    return CreateRaidPurchaseResult(false, "invalid_type", lang.GetMessage("NoConfigType", this, player.UserIDString), string.Empty, raidType);
                }

                if (!IsRaidTypeEnabled(raidType))
                {
                    CobaltDiagnosticLog("purchase", $"Покупка рейда отклонена: player={player.displayName}, raidType={raidType}, reason=disabled_type.");
                    return CreateRaidPurchaseResult(false, "disabled_type", lang.GetMessage("CobaltRaidTypeDisabled", this, player.UserIDString), string.Empty, raidType);
                }

                if (HasAnyRaidEventInProgress())
                {
                    CobaltDiagnosticLog("purchase", $"Покупка рейда отложена: player={player.displayName}, raidType={raidType}, reason=max_events.");
                    return CreateRaidPurchaseResult(false, "max_events", lang.GetMessage("MaxEvents", this, player.UserIDString), string.Empty, raidType);
                }

                if (!immediateStart)
                {
                    int currentOnline;
                    int requiredOnline;
                    if (!MeetsRaidTypeOnlineRequirement(raidType, out currentOnline, out requiredOnline))
                    {
                        string requirementMessage = lang.GetMessage("CobaltMinOnlineRequirement", this, player.UserIDString);
                        CobaltDiagnosticLog("purchase", $"Покупка рейда отклонена: player={player.displayName}, raidType={raidType}, reason=min_online, currentOnline={currentOnline}, requiredOnline={requiredOnline}.");
                        return CreateRaidPurchaseResult(false, "min_online", string.Format(requirementMessage, raidType, requiredOnline, currentOnline), string.Empty, raidType);
                    }
                }

                BuildingPrivlidge privFind = null;
                if (tcNetId != 0UL)
                    privFind = FindEntity(tcNetId) as BuildingPrivlidge;

                if (privFind == null || !privFind.IsAuthed(player))
                {
                    CobaltDiagnosticLog("purchase", $"Покупка рейда отклонена: player={player.displayName}, raidType={raidType}, reason=no_base.");
                    return CreateRaidPurchaseResult(false, "no_base", lang.GetMessage("NoOwnedBaseForRaid", this, player.UserIDString), string.Empty, raidType);
                }

                List<BuildingBlock> block;
                List<ulong> authPlayers;
                string failReasonKey;
                if (!TryPrepareRaidBase(privFind, out block, out authPlayers, out failReasonKey, true))
                {
                    string failMessage = string.IsNullOrEmpty(failReasonKey)
                        ? lang.GetMessage("NoOwnedBaseForRaid", this, player.UserIDString)
                        : lang.GetMessage(failReasonKey, this, player.UserIDString);
                    CobaltDiagnosticLog("purchase", $"Покупка рейда отклонена: player={player.displayName}, raidType={raidType}, reason=invalid_base, detail={failReasonKey ?? "unknown"}.");
                    return CreateRaidPurchaseResult(false, "invalid_base", failMessage, string.Empty, raidType);
                }

                string startFailureMessageKey = GetRaidStartFailureMessageKey(authPlayers, raidType, null, null, immediateStart);
                if (!string.IsNullOrEmpty(startFailureMessageKey))
                {
                    string failureCode = string.Equals(startFailureMessageKey, "CobaltWarCancelledAnotherRaidActive", StringComparison.OrdinalIgnoreCase)
                        ? "max_events"
                        : string.Equals(startFailureMessageKey, "CobaltRaidTypeDisabled", StringComparison.OrdinalIgnoreCase)
                            ? "disabled_type"
                        : "start_blocked";
                    CobaltDiagnosticLog("purchase", $"Покупка рейда отклонена: player={player.displayName}, raidType={raidType}, reason={failureCode}, detail={startFailureMessageKey}.");
                    return CreateRaidPurchaseResult(false, failureCode, lang.GetMessage(startFailureMessageKey, this, player.UserIDString), string.Empty, raidType);
                }

                if (HasStagedWarNear(privFind.transform.position))
                {
                    CobaltDiagnosticLog("purchase", $"Покупка рейда отклонена: player={player.displayName}, raidType={raidType}, reason=max_events, detail=staged_near.");
                    return CreateRaidPurchaseResult(false, "max_events", lang.GetMessage("CobaltWarCancelledAnotherRaidActive", this, player.UserIDString), string.Empty, raidType);
                }

                CobaltWarSession ignoredWar = null;
                bool started = configData.cobaltWar != null && configData.cobaltWar.enabled
                    ? TryScheduleCobaltWar(privFind, player, raidType, block, authPlayers, CobaltWarTrigger.Manual, out ignoredWar, null, 0, immediateStart ? CobaltWarStartMode.Immediate : CobaltWarStartMode.Standard, immediateStart && autoRegisterBuyerAsDefender ? player.userID.Get() : 0UL, immediateStart)
                    : startRandomRaid(privFind.transform.position, authPlayers, raidType, block) != null;

                if (!started)
                {
                    CobaltDiagnosticLog("purchase", $"Покупка рейда не стартовала: player={player.displayName}, raidType={raidType}, reason=start_failed.");
                    return CreateRaidPurchaseResult(false, "start_failed", lang.GetMessage("CobaltWarCancelledStartFailed", this, player.UserIDString), string.Empty, raidType);
                }

                if (ignoredWar != null)
                {
                    ignoredWar.ApplyRaidCooldownNow();
                    CobaltDiagnosticLog("purchase", $"Покупка рейда: cooldown применен сразу после успешного старта, warId={ignoredWar.warId}, owners={ignoredWar.owners.Count}.");
                }

                CobaltDiagnosticLog("purchase", $"Покупка рейда успешна: player={player.displayName}, raidType={raidType}, grid={GetGrid(privFind.transform.position)}.");
                return CreateRaidPurchaseResult(true, "ok", string.Empty, GetGrid(privFind.transform.position), raidType);
            }
            catch (Exception ex)
            {
                CobaltDiagnosticLog("purchase", $"Покупка рейда завершилась исключением: player={player?.displayName ?? "unknown"}, raidType={raidType}, error={ex.Message}.");
                PrintError($"StartRaidPurchase failed for player '{player?.displayName ?? "unknown"}', tcNetId {tcNetId}, raidType '{raidType}': {ex}");
                return CreateRaidPurchaseResult(false, "exception", "Internal purchase error.", string.Empty, raidType);
            }
        }

        [HookMethod("StartExternalRaidBaseEvent")]
        private object StartExternalRaidBaseEvent(BuildingPrivlidge privilege, string raidType, string displayName = null, string externalSourceId = null, bool immediateStart = false, bool bypassOnlineRequirement = false)
        {
            try
            {
                if (privilege == null)
                    return CreateRaidPurchaseResult(false, "no_cupboard", lang.GetMessage("CobaltExternalRaidCupboardMissing", this), string.Empty, raidType);

                CobaltWarSession createdWar;
                string failureCode;
                string failureMessage;
                if (!TryScheduleExternalRaidBaseWar(privilege, raidType, displayName, externalSourceId, out createdWar, out failureCode, out failureMessage, immediateStart, bypassOnlineRequirement))
                    return CreateRaidPurchaseResult(false, string.IsNullOrEmpty(failureCode) ? "start_failed" : failureCode, string.IsNullOrEmpty(failureMessage) ? lang.GetMessage("CobaltExternalRaidStartFailed", this) : failureMessage, GetGrid(privilege.transform.position), raidType);

                return new Dictionary<string, object>
                {
                    ["success"] = true,
                    ["code"] = "ok",
                    ["message"] = string.Empty,
                    ["grid"] = GetGrid(privilege.transform.position),
                    ["raidType"] = raidType,
                    ["warId"] = createdWar != null ? createdWar.warId : 0,
                    ["location"] = privilege.transform.position
                };
            }
            catch (Exception ex)
            {
                PrintError($"StartExternalRaidBaseEvent failed for raidType '{raidType}', display '{displayName ?? "unknown"}', source '{externalSourceId ?? "unknown"}': {ex}");
                return CreateRaidPurchaseResult(false, "start_failed", ex.Message, privilege != null ? GetGrid(privilege.transform.position) : string.Empty, raidType);
            }
        }

