            war.CancelWarForAdmin("CobaltWarCancelledAdmin", true, Mathf.Max(0f, cleanupGraceSeconds));
            return true;
        }

        private void AddRaidPurchaseBaseOption(List<Dictionary<string, object>> results, BuildingPrivlidge privilege, BasePlayer player, List<BuildingBlock> preparedBlocks = null, List<ulong> preparedAuthPlayers = null)
        {
            if (results == null || privilege == null || player == null || privilege.net == null)
                return;

            BuildingManager.Building building = privilege.GetBuilding();
            int blockCount = preparedBlocks != null ? preparedBlocks.Count : (building != null ? building.buildingBlocks.Count : 0);
            int authCount = preparedAuthPlayers != null ? preparedAuthPlayers.Count : (privilege.authorizedPlayers != null ? privilege.authorizedPlayers.Count : 0);
            Vector3 position = privilege.transform.position;

            results.Add(new Dictionary<string, object>
            {
                ["tcNetId"] = privilege.net.ID.Value,
                ["grid"] = GetGrid(position),
                ["x"] = position.x,
                ["y"] = position.y,
                ["z"] = position.z,
                ["distance"] = Vector3.Distance(player.transform.position, position),
                ["authCount"] = authCount,
                ["blockCount"] = blockCount
            });
        }

