        }

        private bool HasAnyPermission(string userId, string primaryPermission, string legacyPermission = null)
        {
            if (string.IsNullOrEmpty(userId))
                return false;

            if (!string.IsNullOrEmpty(primaryPermission) && permission.UserHasPermission(userId, primaryPermission))
                return true;

            if (string.IsNullOrEmpty(legacyPermission))
                return false;

            try
            {
                if (!permission.PermissionExists(legacyPermission))
                    return false;
            }
            catch
            {
            }

            return permission.UserHasPermission(userId, legacyPermission);
        }

        [ChatCommand("randomraid")]
        private void randomRaidChat(BasePlayer player, string command, string[] args)
        {
            if (!HasAnyPermission(player.UserIDString, adminPerm, legacyAdminPerm))
            {
                SendReply(player, lang.GetMessage("MissingPermission", this, player.UserIDString), adminPerm);
                return;
            }

            BuildingPrivlidge priv = null;

            if (args.Length >= 1)
            {
                if (IsImmediateRaidKeyword(args[0]))
                {
                    if (args.Length <= 2)
                    {
                        SendReply(player, lang.GetMessage("usageInstantAdmin", this, player.UserIDString));
                        return;
                    }

                    switch (args[1].ToLower())
                    {
                        case "here":
                            priv = player.GetBuildingPrivilege();
                            if (priv == null)
                                SendReply(player, lang.GetMessage("NeedBuildingPrivHere", this, player.UserIDString));
                            else
                                CallRaidHere(priv, args[2], player, true);
                            return;

                        case "self":
                        case "test":
                            CallRaidOnSelf(player, args[2], args.Skip(3).Any(IsSelfRaidJoinKeyword), true);
                            return;

                        case "nearest":
                        case "near":
                        case "tc":
                            CallRaidNearest(player, args[2], true);
                            return;

                        default:
                            SendReply(player, lang.GetMessage("usageInstantAdmin", this, player.UserIDString));
                            return;
                    }
                }

                switch (args[0].ToLower())
                {
                    case "here":
                        if (args.Length <= 1)
                        {
                            SendReply(player, lang.GetMessage("usageHere", this, player.UserIDString));
                            return;
                        }

                        priv = player.GetBuildingPrivilege();
                        if (priv == null)
                        {
                            SendReply(player, lang.GetMessage("NeedBuildingPrivHere", this, player.UserIDString));
                        }
                        else CallRaidHere(priv, args[1], player, HasImmediateRaidFlag(args, 2));
                        return;

                    case "self":
                    case "test":
                        if (args.Length <= 1)
                        {
                            SendReply(player, lang.GetMessage("usageSelf", this, player.UserIDString));
                            return;
                        }

                        CallRaidOnSelf(player, args[1], args.Skip(2).Any(IsSelfRaidJoinKeyword), HasImmediateRaidFlag(args, 2));
                        return;

                    case "nearest":
                    case "near":
                    case "tc":
                        if (args.Length <= 1)
                        {
                            SendReply(player, lang.GetMessage("usageNearest", this, player.UserIDString));
                            return;
                        }

                        CallRaidNearest(player, args[1], HasImmediateRaidFlag(args, 2));
                        return;

                    case "randomkit":
                    case "kit":
                    case "testkit":
                        GiveAdminRandomDefenderKit(player, args.Length > 1 ? args[1] : null);
                        return;

                    case "random":
                        if (HasAnyRaidEventInProgress())
                        {
                            SendReply(player, lang.GetMessage("MaxEvents", this, player.UserIDString));
                            return;
                        }
                        SendReply(player, lang.GetMessage("SearchingRandomRaid", this, player.UserIDString));
                        startPlayerSearch(player);
                        return;

                    case "reload":
                        SendReply(player, lang.GetMessage("StoppingAllRaids", this, player.UserIDString));
                        StopAllRaids();
                        return;

                    case "stop":
                    case "cancel":
                    case "abort":
                        StopCurrentWarForAdmin(player);
                        return;

                        case "terrain":
                        string names = lang.GetMessage("TerrainScanHeader", this, player.UserIDString);
                        Vector3 p1 = player.transform.position + new Vector3(0, 200f, 0);
                        Vector3 p2 = player.transform.position + new Vector3(0, -200f, 0);
                        Vector3 diff = p2 - p1;
                        RaycastHit[] hits;
                        hits = Physics.RaycastAll(p1, diff, diff.magnitude);
                        if (hits.Length > 0)
                        {
                            for (int i = 0; i < hits.Length; i++)
                            {
                                RaycastHit hit = hits[i];
                                if (hit.collider != null)
                                    names += $"{hit.collider.name},\n";
                            }
                            SendReply(player, $"{names}");
                        }
                        else
                        {
                            names += lang.GetMessage("TerrainScanNone", this, player.UserIDString);
                            SendReply(player, $"{names}");
                        }
                        return;

                    case "item":
                        SendReply(player, lang.GetMessage("RaidItemFeatureDisabled", this, player.UserIDString));
                        return;
                }
            }
            SendReply(player, lang.GetMessage("AdminCommandUsage", this, player.UserIDString));
        }

        [ChatCommand("cobalt")]
        private void cobaltChat(BasePlayer player, string command, string[] args)
        {
            if (player == null)
                return;

            if (args == null || args.Length == 0)
            {
                CobaltWarSession active = FindJoinableWarForPlayer(player);
                if (active == null)
                {
                    SendReply(player, lang.GetMessage("CobaltNoOpenWar", this, player.UserIDString));
                    return;
                }

                if (active.CanReturnDefender(player.userID))
                    active.ReturnDisconnectedDefender(player);
                else
                    active.RegisterDefender(player);
                return;
            }

            switch (args[0].ToLower())
            {
                case "join":
                    {
                        CobaltWarSession active = FindJoinableWarForPlayer(player);
                        if (active == null)
                        {
                            SendReply(player, lang.GetMessage("CobaltNoOpenWar", this, player.UserIDString));
                            return;
                        }

                        if (active.CanReturnDefender(player.userID))
                            active.ReturnDisconnectedDefender(player);
                        else
                            active.RegisterDefender(player);
                        return;
                    }
                case "return":
                    {
                        CobaltWarSession returnWar = FindWarByUiRegisteredPlayer(player.userID);
                        if (returnWar == null || !returnWar.CanReturnDefender(player.userID))
                        {
                            SendReply(player, lang.GetMessage("CobaltReturnUnavailable", this, player.UserIDString));
                            return;
                        }

                        returnWar.ReturnDisconnectedDefender(player);
                        return;
                    }
                case "testjoin":
                case "selfjoin":
                    {
                        if (!HasAnyPermission(player.UserIDString, adminPerm, legacyAdminPerm))
                        {
                            SendReply(player, lang.GetMessage("MissingPermission", this, player.UserIDString), adminPerm);
                            return;
                        }

                        CobaltWarSession ownerWar = FindWarByOwner(player.userID, true);
                        if (ownerWar == null)
                        {
                            SendReply(player, lang.GetMessage("CobaltOwnerTestJoinUnavailable", this, player.UserIDString));
                            return;
                        }

                        ownerWar.RegisterOwnerTestDefender(player);
                        return;
                    }
                case "leave":
                case "quit":
                    {
                        CobaltWarSession defenderWar = FindWarByUiRegisteredPlayer(player.userID);
                        if (defenderWar == null)
                        {
                            SendReply(player, lang.GetMessage("CobaltLeaveUnavailable", this, player.UserIDString));
                            return;
                        }

                        defenderWar.LeaveDefender(player);
                        return;
                    }
                case "close":
                case "hide":
                    {
                        CobaltWarSession uiWar = FindPreferredWarForPlayer(player);
                        if (uiWar == null || uiWar.IsEnded)
                        {
                            CuiHelper.DestroyUi(player, JoinUiName);
                            displayedWarUi.Remove(player.userID);
                            return;
                        }

                        bool canJoin = uiWar.CanJoinDefender(player.userID);
                        bool canLeave = uiWar.CanLeaveDefender(player.userID);
                        SetWarUiDismiss(player.userID, uiWar.warId, uiWar.phase, canJoin || uiWar.CanReturnDefender(player.userID) || uiWar.CanSurrender(player), canLeave);
                        CuiHelper.DestroyUi(player, JoinUiName);
                        displayedWarUi.Remove(player.userID);
                        return;
                    }
                case "status":
                    {
                        DefenderRedeployState redeploy;
                        if (pendingRedeploys.TryGetValue(player.userID, out redeploy))
                        {
                            CobaltWarSession redeployWar = FindWar(redeploy.warId);
                            if (redeployWar != null && !redeployWar.IsEnded)
                            {
                                SendReply(player, lang.GetMessage("CobaltStatusObserver", this, player.UserIDString), redeployWar.targetName, GetGrid(redeployWar.location), Mathf.CeilToInt(Mathf.Max(0f, (float)(redeploy.redeployAt - GrabCurrentTime()))));
                                return;
                            }
                        }

                        CobaltWarSession myWar = FindPreferredWarForPlayer(player);
                        if (myWar != null)
                        {
                                SendReply(player, lang.GetMessage("CobaltStatus", this, player.UserIDString), myWar.targetName, GetGrid(myWar.location), GetCobaltPhaseLabel(myWar.phase, player.UserIDString), Mathf.CeilToInt(Mathf.Max(0f, myWar.phaseEndTime - Time.realtimeSinceStartup)));
                            return;
                        }

                        SendReply(player, lang.GetMessage("CobaltNoOpenWar", this, player.UserIDString));
                        return;
                    }
                case "drone":
                case "drones":
                    {
                        CobaltWarSession ownerWar = FindWarByOwner(player.userID, false);
                        if (ownerWar == null || ownerWar.IsEnded)
                        {
                            SendReply(player, lang.GetMessage("CobaltSupportDroneUnavailable", this, player.UserIDString));
                            return;
                        }

                        string tierKey = args.Length > 1 ? args[1] : null;
                        ownerWar.TryRequestSupportDrone(player, tierKey);
                        return;
                    }
                default:
                    SendReply(player, lang.GetMessage("CobaltCommandUsage", this, player.UserIDString));
                    return;
            }
        }

