        private void UpdateMinimizedUis()
        {
            if (minimizedWarUi.Count <= 0)
            {
                RefreshMinimizedUiTimerState();
                return;
            }

            foreach (var kvp in minimizedWarUi.ToList())
            {
                BasePlayer player = BasePlayer.FindByID(kvp.Key);
                if (player == null || !player.IsConnected) continue;
                CobaltWarSession war;
                if (activeCobaltWars.TryGetValue(kvp.Value, out war) && !war.IsEnded)
                    RenderMinimizedWarUi(player, war);
                else
                {
                    CuiHelper.DestroyUi(player, MinimizedJoinUiName);
                    minimizedWarUi.Remove(kvp.Key);
                    ClearMinimizedWarUiRenderState(kvp.Key);
                }
            }

            RefreshMinimizedUiTimerState();
        }

        private string BuildMinimizedWarUiRenderSignature(CobaltWarSession war, BasePlayer player, string phaseLabel, string timerText)
        {
            return string.Concat(
                war?.warId.ToString() ?? "0", "|",
                player != null ? player.userID.Get().ToString() : "0", "|",
                phaseLabel ?? string.Empty, "|",
                timerText ?? string.Empty);
        }

        private void RenderMinimizedWarUi(BasePlayer player, CobaltWarSession war)
        {
            if (war == null || war.IsEnded)
            {
                CuiHelper.DestroyUi(player, MinimizedJoinUiName);
                ClearMinimizedWarUiRenderState(player.userID);
                return;
            }

            string userId = player.UserIDString;
            string compactPhaseLabel = GetCompactCobaltPhaseLabel(war.phase, userId);
            float remainingSeconds = Mathf.Max(0f, war.phaseEndTime - UnityEngine.Time.realtimeSinceStartup);
            string timeText = $"{Mathf.CeilToInt(remainingSeconds)}с";
            string renderSignature = BuildMinimizedWarUiRenderSignature(war, player, compactPhaseLabel, timeText);

            WarUiRenderState renderState;
            if (minimizedRenderedWarUiState.TryGetValue(player.userID, out renderState)
                && renderState != null
                && renderState.warId == war.warId
                && renderState.signature == renderSignature)
                return;

            CuiHelper.DestroyUi(player, MinimizedJoinUiName);

            var container = new CuiElementContainer();
            string panel = container.Add(new CuiPanel
            {
                Image = { Color = "0.04 0.06 0.09 0.94" },
                RectTransform = { AnchorMin = "0.81 0.845", AnchorMax = "0.99 0.892" },
                CursorEnabled = false
            }, "Overlay", MinimizedJoinUiName);

            container.Add(new CuiPanel
            {
                Image = { Color = "0.95 0.57 0.20 0.12" },
                RectTransform = { AnchorMin = "0 0.94", AnchorMax = "1 1" }
            }, panel);

            string phaseCard = AddWarUiPanel(container, panel, "0.02 0.12", "0.35 0.88", "0.08 0.10 0.14 0.96");
            container.Add(new CuiPanel
            {
                Image = { Color = "0.57 0.43 0.88 0.98" },
                RectTransform = { AnchorMin = "0 0.94", AnchorMax = "1 1" }
            }, phaseCard);
            AddWarUiLabel(container, phaseCard, "0.08 0.18", "0.92 0.82", compactPhaseLabel, 8, TextAnchor.MiddleCenter, "0.97 0.97 0.97 1");

            string timerCard = AddWarUiPanel(container, panel, "0.37 0.12", "0.54 0.88", "0.08 0.10 0.14 0.96");
            container.Add(new CuiPanel
            {
                Image = { Color = "0.26 0.69 0.58 0.98" },
                RectTransform = { AnchorMin = "0 0.94", AnchorMax = "1 1" }
            }, timerCard);
            AddWarUiLabel(container, timerCard, "0.08 0.18", "0.92 0.82", timeText, 8, TextAnchor.MiddleCenter, "0.97 0.97 0.97 1");

            string expandButton = AddWarUiButtonSurface(container, panel, "0.56 0.12", "0.85 0.88", "0.10 0.13 0.17 0.98", $"rr.cobalt.expand {war.warId}");
            container.Add(new CuiPanel
            {
                Image = { Color = "0.25 0.44 0.27 0.98" },
                RectTransform = { AnchorMin = "0 0.94", AnchorMax = "1 1" }
            }, expandButton);
            AddWarUiLabel(container, expandButton, "0.08 0.18", "0.92 0.82", "Открыть", 8, TextAnchor.MiddleCenter, "0.97 0.97 0.97 1");

            string closeButton = AddWarUiButtonSurface(container, panel, "0.87 0.12", "0.98 0.88", "0.10 0.13 0.17 0.98", $"rr.cobalt.closemin {war.warId}");
            container.Add(new CuiPanel
            {
                Image = { Color = "0.56 0.22 0.20 0.98" },
                RectTransform = { AnchorMin = "0 0.94", AnchorMax = "1 1" }
            }, closeButton);
            AddWarUiLabel(container, closeButton, "0.08 0.18", "0.92 0.82", "X", 10, TextAnchor.MiddleCenter, "0.97 0.97 0.97 1");

            CuiHelper.AddUi(player, container);
            minimizedRenderedWarUiState[player.userID] = new WarUiRenderState
            {
                warId = war.warId,
                signature = renderSignature
            };
        }

