        [ConsoleCommand("rr.cobalt.closemin")]
        private void rrCobaltCloseMin(ConsoleSystem.Arg args)
        {
            BasePlayer player = args?.Player();
            if (player == null)
                return;

            int warId = 0;
            if (args.Args != null && args.Args.Length > 0)
                int.TryParse(args.Args[0], out warId);

            CobaltWarSession war = warId != 0 ? FindWar(warId) : FindPreferredWarForPlayer(player);
