                bool canJoin = war.CanJoinDefender(player.userID);
                bool canLeave = war.CanLeaveDefender(player.userID);
                SetWarUiDismiss(player.userID, war.warId, war.phase, canJoin || war.CanReturnDefender(player.userID) || war.CanSurrender(player), canLeave);
            }

            minimizedWarUi.Remove(player.userID);
            CuiHelper.DestroyUi(player, MinimizedJoinUiName);
            ClearMinimizedWarUiRenderState(player.userID);
            RefreshMinimizedUiTimerState();
        }
        [ConsoleCommand("rr.cobalt.close")]
        private void rrCobaltClose(ConsoleSystem.Arg args)
        {
            BasePlayer player = args?.Player();
            if (player == null)
                return;

            if (args.Args == null || args.Args.Length == 0)
            {
                CuiHelper.DestroyUi(player, JoinUiName);
                CuiHelper.DestroyUi(player, MinimizedJoinUiName);
                displayedWarUi.Remove(player.userID);
                minimizedWarUi.Remove(player.userID);
                ClearRenderedWarUiState(player.userID);
                ClearMinimizedWarUiRenderState(player.userID);
                RefreshMinimizedUiTimerState();
                return;
            }

            int warId;
            if (!int.TryParse(args.Args[0], out warId))
            {
                CuiHelper.DestroyUi(player, JoinUiName);
                CuiHelper.DestroyUi(player, MinimizedJoinUiName);
                displayedWarUi.Remove(player.userID);
                minimizedWarUi.Remove(player.userID);
                ClearRenderedWarUiState(player.userID);
                ClearMinimizedWarUiRenderState(player.userID);
                RefreshMinimizedUiTimerState();
                return;
            }

            CobaltWarSession war = FindWar(warId);
            if (war == null || war.IsEnded)
            {
                CuiHelper.DestroyUi(player, JoinUiName);
                CuiHelper.DestroyUi(player, MinimizedJoinUiName);
                displayedWarUi.Remove(player.userID);
                minimizedWarUi.Remove(player.userID);
                ClearWarUiDismiss(player.userID, warId);
                ClearRenderedWarUiState(player.userID, warId);
                ClearMinimizedWarUiRenderState(player.userID, warId);
                RefreshMinimizedUiTimerState();
                return;
            }

            bool canJoin = war.CanJoinDefender(player.userID);
            bool canLeave = war.CanLeaveDefender(player.userID);
            SetWarUiDismiss(player.userID, war.warId, war.phase, canJoin || war.CanReturnDefender(player.userID) || war.CanSurrender(player), canLeave);
            CuiHelper.DestroyUi(player, JoinUiName);
            CuiHelper.DestroyUi(player, MinimizedJoinUiName);
            displayedWarUi.Remove(player.userID);
            minimizedWarUi.Remove(player.userID);
            ClearRenderedWarUiState(player.userID, warId);
            ClearMinimizedWarUiRenderState(player.userID, warId);
            RefreshMinimizedUiTimerState();
        }

