        private void CallRaidOnNpcKills(BasePlayer p, string Rtype, NPCConfig config, bool combined = false)
        {
            List<ulong> tcDataTemp = Pool.Get<List<ulong>>();
            try
            {
                if (p == null)
                    return;

                if (configData.settings.musthavePerm && !HasAnyPermission(p.UserIDString, usePerm, legacyUsePerm))
                    return;

                TouchRaidTargetActivity(p, true);

                TimeSpan protectionRemaining;
                if (IsProtectedRaidTarget(p, out protectionRemaining))
                    return;
                if (IsRaidTargetAfk(p))
                    return;

                string type = "";
                BuildingPrivlidge priv = null;
                Vector3 location = Vector3.zero;
                List<ulong> authPlayers = new List<ulong>();
                List<BuildingBlock> block = new List<BuildingBlock>();

                if (config == null)
                    return;

                int rando = UnityEngine.Random.Range(0, 100);

                if (rando <= config.raidChance && pcdData.tcData.Count > 0)
                {
                    if (pcdData.tcData.ContainsKey(p.userID.Get()))
                    {
                        tcDataTemp.AddRange(pcdData.tcData[p.userID.Get()]);

                        foreach (ulong key in tcDataTemp)
                        {
                            BuildingPrivlidge privFind = FindEntity(key) as BuildingPrivlidge;
                            if (privFind == null)
                                pcdData.tcData[p.userID.Get()].Remove(key);
                            else if (priv == null)
                            {
                                string failReason;
                                List<ulong> authPlayersTemp;
                                if (!TryPrepareRaidBase(privFind, out block, out authPlayersTemp, out failReason))
                                    continue;

                                if (block.Count <= 6)
                                    continue;
                                priv = privFind;
                                location = priv.transform.position;
                                break;
                            }
                        }
                    }

                    if (priv == null)
                        return;

                    if (configData.settingsNPCKILLS.enforceAuth || configData.settingsNPCKILLS.BlockCheck)
                    {
                        int totalAuth = priv.authorizedPlayers.Count();
                        List<string> raidsToUse = Pool.Get<List<string>>();
                        try
                        {
                            raidsToUse.AddRange(config.sendRaids);

                            if (totalAuth > 0)
                            {
                                foreach (var keyNext in config.sendRaids)
                                {
                                    if (!IsRaidTypeEnabled(keyNext) && raidsToUse.Contains(keyNext))
                                        raidsToUse.Remove(keyNext);

                                    if (configData.settingsNPCKILLS.enforceAuth && configData.raidSettings.raidTypes.ContainsKey(keyNext) && totalAuth < configData.raidSettings.raidTypes[keyNext].TotalAuth && raidsToUse.Contains(keyNext))
                                        raidsToUse.Remove(keyNext);

                                    if (configData.settingsNPCKILLS.BlockCheck && raidsToUse.Contains(keyNext) && configData.raidSettings.raidTypes.ContainsKey(keyNext) && block.Count < configData.raidSettings.raidTypes[keyNext].blockMIN)
                                        raidsToUse.Remove(keyNext);

                                    if (raidsToUse.Contains(keyNext) && !IsRaidTypeAllowedByOnline(keyNext, GetOnlineRaidPlayerCount()))
                                        raidsToUse.Remove(keyNext);
                                }
                            }

                            if (raidsToUse.Count <= 0)
                                return;

                            type = raidsToUse.GetRandom();
                        }
                        finally
                        {
                            Pool.FreeUnmanaged(ref raidsToUse);
                        }
                    }
                    else
                    {
                        List<string> onlineAllowedRaids = FilterRaidTypesByOnline(config.sendRaids);
                        try
                        {
                            type = onlineAllowedRaids.Count > 0 ? onlineAllowedRaids.GetRandom() : string.Empty;
                        }
                        finally
                        {
                            onlineAllowedRaids.Clear();
                        }
                    }

                    if (!string.IsNullOrEmpty(type))
                    {
                        foreach (var user in priv.authorizedPlayers)
                        {
                            if (raidData.data.ContainsKey(user) && raidData.data[user].LastRaidedNpcKills >= DateTime.Now)
                                return;

                            if (!authPlayers.Contains(user))
                                authPlayers.Add(user);

                            if (configData.settingsNPCKILLS.warnPlayer)
                            {
                                BasePlayer p2 = BasePlayer.FindByID(user);
                                if (p2 != null)
                                {
                                    TimeSpan newTime = TimeSpan.FromSeconds(config.raidDelay);

                                    if (configData.settings.gameTip)
                                        GameTipMessage(p2, string.Format(lang.GetMessage("warningRevengeGridNpc", this, p2.UserIDString), GetGrid(priv.transform.position), FormatTime(newTime), FormatTimeS(newTime)));
                                    else
                                        SendReply(p2, lang.GetMessage("warningRevengeGridNpc", this, p2.UserIDString), GetGrid(priv.transform.position), FormatTime(newTime), FormatTimeS(newTime));

                                    if (configData.settings.worldMarker)
                                        LocateBaseWithMarker(p2, priv.transform.position, configData.settings.worldMarkerTime);
                                }
                            }
                        }

                        ulong targetUserId = p != null ? p.userID.Get() : 0UL;
                        ScheduleTriggeredRaidAttempt(priv, targetUserId, type, config.raidDelay, CobaltWarTrigger.Random, (startedAuthPlayers, startedBlocks) =>
                        {
                            string npcTargetName = p != null ? p.displayName : lang.GetMessage("DiscordUnknownPlayer", this);
                            foreach (var userid in startedAuthPlayers)
                            {
                                if (!raidData.data.ContainsKey(userid))
                                    raidData.data.Add(userid, new rData() { LastRaidedNpcKills = DateTime.Now.AddMinutes(config.chanceCooldown) });
                                else
                                    raidData.data[userid].LastRaidedNpcKills = DateTime.Now.AddMinutes(config.chanceCooldown);
                            }
                            SaveRaidData();

                            if (configData.settingsNPCKILLS.resetKills)
                            {
                                foreach (var userid in startedAuthPlayers)
                                {
                                    if (logData.pLogs.ContainsKey(userid) && logData.pLogs[userid].NPCKILLS != null)
                                        logData.pLogs[userid].NPCKILLS.Clear();
                                }
                            }

                            if (config.resetKillCount && p != null && logData.pLogs.ContainsKey(p.userID.Get()))
                            {
                                if (combined)
                                    logData.pLogs[p.userID.Get()]._totalNpcKills = 0;
                                else if (logData.pLogs[p.userID.Get()].NPCKILLS != null && logData.pLogs[p.userID.Get()].NPCKILLS.ContainsKey(Rtype))
                                    logData.pLogs[p.userID.Get()].NPCKILLS[Rtype] = 0;
                            }

                            if (configData.settingsNPCKILLS.resetKills || config.resetKillCount)
                                SaveLogData();

                            LogToFile("NpcKillsRaids", $"[{DateTime.Now}] Рейд за убийства NPC запущен в точке {priv.transform.position} для игрока {npcTargetName}", this);
                            if (configData.settings.DiscordWebHook)
                                ServerMgr.Instance.StartCoroutine(SendToDiscord(ConVar.Server.hostname, npcTargetName, priv.transform.position.ToString(), string.Format(lang.GetMessage("DiscordTypeNpcKills", this), type)));
                        });
                    }
                }
            }
            finally
            {
                Pool.FreeUnmanaged(ref tcDataTemp);
            }
        }

        private void CallRaidHere(BuildingPrivlidge privFind, string Rtype, BasePlayer p, bool immediateStart = false)
        {
            if (!configData.raidSettings.raidTypes.ContainsKey(Rtype))
            {
                SendReply(p, lang.GetMessage("NoConfigType", this, p.UserIDString), Rtype);
                return;
            }

            if (!IsRaidTypeEnabled(Rtype))
            {
                SendReply(p, lang.GetMessage("CobaltRaidTypeDisabled", this, p.UserIDString));
                return;
            }

            raidConfig config = configData.raidSettings.raidTypes[Rtype];

            if (config == null)
            {
                SendReply(p, lang.GetMessage("NoConfigType", this, p.UserIDString), Rtype);
                return;
            }

            int currentOnline;
            int requiredOnline;
            if (!MeetsRaidTypeOnlineRequirement(Rtype, out currentOnline, out requiredOnline))
            {
                SendReply(p, lang.GetMessage("CobaltMinOnlineRequirement", this, p.UserIDString), Rtype, requiredOnline, currentOnline);
                return;
            }

            List<ulong> authPlayers;
            List<BuildingBlock> block;
            string failReasonKey;
            if (!TryPrepareRaidBase(privFind, out block, out authPlayers, out failReasonKey, true))
            {
                SendReply(p, lang.GetMessage(string.IsNullOrEmpty(failReasonKey) ? "terrainBlocked" : failReasonKey, this, p.UserIDString));
                return;
            }

            BasePlayer targetPlayer = authPlayers.Select(FindPlayerByIdOrSleeping).FirstOrDefault(x => x != null) ?? p;
            CobaltWarSession ignoredWar;
            bool started = configData.cobaltWar != null && configData.cobaltWar.enabled
                ? TryScheduleCobaltWar(privFind, targetPlayer, Rtype, block, authPlayers, CobaltWarTrigger.Manual, out ignoredWar, null, 0, immediateStart ? CobaltWarStartMode.Immediate : CobaltWarStartMode.Standard, 0UL)
                : startRandomRaid(privFind.transform.position, authPlayers, Rtype, block) != null;

            if (!started)
            {
                SendReply(p, lang.GetMessage("MaxEvents", this, p.UserIDString));
                return;
            }

            SendReply(p, lang.GetMessage(immediateStart ? "AdminRaidStartedInstant" : "AdminRaidStarted", this, p.UserIDString));
        }

        private void CallRaidOnSelf(BasePlayer player, string raidType, bool autoRegisterOwnerTest = false, bool immediateStart = false)
        {
            if (player == null)
                return;

            if (!configData.raidSettings.raidTypes.ContainsKey(raidType))
            {
                SendReply(player, lang.GetMessage("NoConfigType", this, player.UserIDString), raidType);
                return;
            }

            if (!IsRaidTypeEnabled(raidType))
            {
                SendReply(player, lang.GetMessage("CobaltRaidTypeDisabled", this, player.UserIDString));
                return;
            }

            if (!immediateStart)
            {
                int currentOnline;
                int requiredOnline;
                if (!MeetsRaidTypeOnlineRequirement(raidType, out currentOnline, out requiredOnline))
                {
                    SendReply(player, lang.GetMessage("CobaltMinOnlineRequirement", this, player.UserIDString), raidType, requiredOnline, currentOnline);
                    return;
                }
            }

            BuildingPrivlidge privFind;
            List<BuildingBlock> block;
            List<ulong> authPlayers;
            BuildingPrivlidge currentPriv = player.GetBuildingPrivilege();
            if (currentPriv != null && currentPriv.IsAuthed(player))
            {
                string currentReason;
                if (!TryPrepareRaidBase(currentPriv, out block, out authPlayers, out currentReason, true))
                {
                    if (!string.IsNullOrEmpty(currentReason))
                        SendReply(player, lang.GetMessage(currentReason, this, player.UserIDString));
                    else
                        SendReply(player, lang.GetMessage("NoOwnedBaseForRaid", this, player.UserIDString));
                    return;
                }

                privFind = currentPriv;
                CachePlayerCupboard(player, currentPriv);
            }
            else if (!TryGetPlayerBase(player, out privFind, out block, out authPlayers, true, true) || privFind == null)
            {
                SendReply(player, lang.GetMessage("NoOwnedBaseForRaid", this, player.UserIDString));
                return;
            }

            CobaltWarSession ignoredWar;
            bool started = configData.cobaltWar != null && configData.cobaltWar.enabled
                ? TryScheduleCobaltWar(privFind, player, raidType, block, authPlayers, CobaltWarTrigger.Manual, out ignoredWar, null, 0, immediateStart ? CobaltWarStartMode.Immediate : CobaltWarStartMode.Standard, immediateStart && autoRegisterOwnerTest ? player.userID.Get() : 0UL, immediateStart)
                : startRandomRaid(privFind.transform.position, authPlayers, raidType, block) != null;

            if (!started)
            {
                SendReply(player, lang.GetMessage("MaxEvents", this, player.UserIDString));
                return;
            }

            SendReply(player, lang.GetMessage(immediateStart ? "AdminSelfRaidStartedInstant" : "AdminSelfRaidStarted", this, player.UserIDString), raidType, GetGrid(privFind.transform.position));

            if (configData.cobaltWar != null && configData.cobaltWar.enabled)
            {
                if (!immediateStart)
                {
                    if (autoRegisterOwnerTest)
                    {
                        CobaltWarSession ownerWar = FindWarByOwner(player.userID, true);
                        if (ownerWar != null)
                            ownerWar.RegisterOwnerTestDefender(player);
                        else
                            SendReply(player, lang.GetMessage("CobaltOwnerTestJoinHint", this, player.UserIDString));
                    }
                    else
                        SendReply(player, lang.GetMessage("CobaltOwnerTestJoinHint", this, player.UserIDString));
                }
            }
        }

        private void CallRaidNearest(BasePlayer player, string raidType, bool immediateStart = false)
        {
            if (player == null)
                return;

            if (!configData.raidSettings.raidTypes.ContainsKey(raidType))
