            int currentOnline;
            int requiredOnline;
            if (!MeetsRaidTypeOnlineRequirement(raidType, out currentOnline, out requiredOnline))
            {
                SendReply(player, lang.GetMessage("CobaltMinOnlineRequirement", this, player.UserIDString), raidType, requiredOnline, currentOnline);
