                ? TryScheduleCobaltWar(privFind, targetPlayer, raidType, blocks, authPlayers, CobaltWarTrigger.Manual, out ignoredWar, null, 0, immediateStart ? CobaltWarStartMode.Immediate : CobaltWarStartMode.Standard, 0UL)
                : startRandomRaid(privFind.transform.position, authPlayers, raidType, blocks) != null;

            if (!started)
            {
                SendReply(player, lang.GetMessage("MaxEvents", this, player.UserIDString));
                return;
            }

            SendReply(player, lang.GetMessage(immediateStart ? "AdminNearestRaidStartedInstant" : "AdminNearestRaidStarted", this, player.UserIDString), GetGrid(privFind.transform.position), raidType);
        }
