        #region Patrol Helicopter
        public static PatrolHelicopter spawnHeli(EventRandomManager newManager, Vector3 location, copterConfig theConfig, int formationIndex = 0)
        {
            float angle = 315f + (formationIndex * 55f);
            float radius = 210f + (formationIndex % 2) * 20f;
            Vector3 horizontalOffset = Quaternion.Euler(0f, angle, 0f) * Vector3.forward * radius;
            Vector3 spawnLocation = location + horizontalOffset + new Vector3(0f, 100f + (formationIndex * 6f), 0f);
            PatrolHelicopter heli = GameManager.server.CreateEntity("assets/prefabs/npc/patrol helicopter/patrolhelicopter.prefab", spawnLocation, new Quaternion(), true) as PatrolHelicopter;
            if (heli == null)
                return null;

            PatrolHelicopterAI ai = heli.GetComponent<PatrolHelicopterAI>();
            attackHelicopterAI newAI = heli.gameObject.AddComponent<attackHelicopterAI>();
            if (ai == null || newAI == null) return null;

            newAI.setupManager(newManager);

            heli.startHealth = theConfig.startHealth;
            heli.InitializeHealth(theConfig.startHealth, theConfig.startHealth);
            heli.health = theConfig.startHealth;
            heli.maxCratesToSpawn = theConfig.maxCratesToSpawn;
            newAI.totalStrafe = theConfig.totalStrafe;
            newAI.strafeTime = theConfig.strafeTime;

            location.y = location.y + 50;
            ai.SetInitialDestination(location, 0.25f);
            heli.skinID = 8675309;
            heli.Spawn();
            heli.transform.position = spawnLocation;
            _.RegisterCobaltHeli(heli);
            location.y = location.y + 50;
            Interface.Oxide.CallHook("OnRandomRaidHeliSpawned", location, heli);
            Interface.Oxide.CallHook("OnCobaltWarHeliSpawned", location, heli);
            return heli;
        }

        public class attackHelicopterAI : MonoBehaviour
        {
            private PatrolHelicopter heli { get; set; }
            private PatrolHelicopterAI heliAI { get; set; }
            private EventRandomManager manager { get; set; }
            private bool isRetire { get; set; }
            private bool Active { get; set; }
            private DateTime strafe { get; set; }
            private float nextRuntimeMaintainAt { get; set; }
            private float nextZoneClearAt { get; set; }
            public int totalStrafe { get; set; }
            public float strafeTime { get; set; }
            public Vector3 location { get; set; }

            private void Awake()
            {
                heli = GetComponent<PatrolHelicopter>();
                heliAI = GetComponent<PatrolHelicopterAI>();
            }

            public void setupManager(EventRandomManager newManager)
            {
                manager = newManager;
                location = manager.location;
                strafe = DateTime.Now.AddSeconds(strafeTime);
                Active = true;
                nextRuntimeMaintainAt = 0f;
                nextZoneClearAt = 0f;
                MaintainRuntimeState();
                InvokeRepeating("MaintainRuntimeState", 0.75f, 0.75f);
                UpdateMono();
                InvokeRepeating("UpdateMono", 6.0f, 6.0f);
            }

            public bool AtDestination() => (double)Vector3.Distance(this.transform.position, location) < 50;

            private void MaintainRuntimeState()
            {
                if (isRetire || !Active || heli == null || heliAI == null || heliAI._currentState == PatrolHelicopterAI.aiState.DEATH) return;
                if (!isRetire && manager != null && manager.isDestroyed)
                {
                    isRetire = true;
                    heliAI.Retire();
                    return;
                }

                float now = UnityEngine.Time.realtimeSinceStartup;
                if (now < nextRuntimeMaintainAt)
                    return;

                nextRuntimeMaintainAt = now + 0.5f;

                if (heliAI.CanStrafe())
                    heliAI.lastStrafeTime = now + 30f;

                if (now >= nextZoneClearAt)
                {
                    nextZoneClearAt = now + 1.5f;
                    if (heliAI.dangerZones.Count > 0)
                        heliAI.dangerZones.Clear();
                    if (heliAI.noGoZones.Count > 0)
                        heliAI.noGoZones.Clear();
                }
        }

            private void UpdateMono()
            {
                if (isRetire || !Active || heli == null || heliAI == null || heliAI._currentState == PatrolHelicopterAI.aiState.DEATH) return;

                if (!AtDestination() && heliAI._currentState != PatrolHelicopterAI.aiState.STRAFE && heliAI.interestZoneOrigin != location)
                {
                    heliAI.spawnTime = UnityEngine.Time.realtimeSinceStartup;
                    heliAI.hasInterestZone = true;
                    heliAI.interestZoneOrigin = location;
                    heliAI.ExitCurrentState();
                    heliAI.State_Move_Enter(location);
                }
                else if (heliAI._currentState == PatrolHelicopterAI.aiState.MOVE && AtDestination())
                {
                    heliAI.spawnTime = UnityEngine.Time.realtimeSinceStartup;
                    heliAI.interestZoneOrigin = location;
                    heliAI.State_Orbit_Enter(30.0f);
                }
                else if (totalStrafe > 0 && strafe < DateTime.Now && heliAI._currentState != PatrolHelicopterAI.aiState.STRAFE)
                {
                    if (heliAI._targetList.Count > 0)
                    {
                        BasePlayer stPlayer = heliAI._targetList[0].ply;
                        if (stPlayer != null)
                        {
                            heliAI.State_Strafe_Enter(stPlayer, false);
                            strafe = DateTime.Now.AddSeconds(strafeTime);
                            totalStrafe--;
                        }
                    }
                }
                if (manager == null || manager.isDestroyed && heliAI != null && !heli.IsDestroyed)
                {
                    isRetire = true;
                    heliAI.Retire();
                }
            }

            private void OnDestroy()
            {
                if (heli != null && !heli.IsDestroyed)
                    heli.Kill();
                CancelInvoke("MaintainRuntimeState");
                CancelInvoke("UpdateMono");
            }
        }

        public class CobaltSupportDroneController : FacepunchBehaviour
        {
            private CobaltWar plugin;
            private CobaltWarSession war;
            private EventRandomManager manager;
            private Drone drone;
            private AutoTurret turret;
            private string tierKey;
            private SupportDroneTierConfig tier;
            private float orbitAngle;
            private float nextRetargetAt;
            private float nextAuthRefreshAt;
            private float nextReloadAt;
            private float nextNetworkUpdateAt;
            private float nextTurretReadyAt;
            private BaseCombatEntity currentTarget;

            public BaseCombatEntity CurrentTarget => currentTarget;
            public uint DroneNetId => drone != null && drone.net != null ? (uint)drone.net.ID.Value : 0U;

            public void Initialize(CobaltWar plugin, CobaltWarSession war, EventRandomManager manager, Drone drone, AutoTurret turret, string tierKey, SupportDroneTierConfig tier)
            {
                this.plugin = plugin;
                this.war = war;
                this.manager = manager;
                this.drone = drone;
                this.turret = turret;
                this.tierKey = tierKey;
                this.tier = tier;
                this.orbitAngle = UnityEngine.Random.Range(0f, 360f);
                this.nextRetargetAt = 0f;
                this.nextAuthRefreshAt = 0f;
                this.nextReloadAt = Time.time + 1f;
                this.nextNetworkUpdateAt = 0f;
                this.nextTurretReadyAt = 0f;
            }

            private void FixedUpdate()
            {
                if (plugin == null || war == null || war.IsEnded || manager == null || manager.isDestroyed || drone == null || drone.IsDestroyed || turret == null || turret.IsDestroyed)
                {
                    CleanupController();
                    return;
                }

                KeepDronePhysicsAlive();

                if (Time.time >= nextTurretReadyAt)
                {
                    nextTurretReadyAt = Time.time + 1f;
                    plugin.EnsureSupportDroneTurretReady(turret, tier);
                }

                if (Time.time >= nextAuthRefreshAt)
                {
                    nextAuthRefreshAt = Time.time + 3f;
                    plugin.AuthorizeCobaltSupportDroneTurret(turret, war);
                }

                if (Time.time >= nextRetargetAt || currentTarget == null || currentTarget.IsDestroyed || currentTarget.Health() <= 0f)
                {
                    currentTarget = FindBestTarget();
                    nextRetargetAt = Time.time + 1.25f;
                }

                plugin.UpdateCobaltSupportDroneRuntimeState(DroneNetId, drone.transform.position, currentTarget);

                Vector3 desiredPosition = currentTarget != null && !currentTarget.IsDestroyed
                    ? GetCombatHoverPosition(currentTarget)
                    : GetOrbitPosition();

                if (plugin != null)
                {
                    float spacing = Mathf.Max(6f, tier != null ? tier.keepDistance * 0.7f : 8f);
                    Vector3 separation = plugin.GetSupportDroneSeparationOffset(war.warId, DroneNetId, drone.transform.position, spacing);
                    desiredPosition += separation;
                }

                MoveDrone(desiredPosition);
                UpdateDroneFacing(desiredPosition);
                UpdateTurretTarget();
                TryReloadTurret();
            }

            private void KeepDronePhysicsAlive()
            {
                if (drone == null || drone.IsDestroyed)
                    return;

                drone.enableGrounding = false;
                drone.keepAboveTerrain = false;
                drone.playerCheckRadius = 0f;
                drone.collisionDisableTime = 0f;
                drone.killInTerrain = false;
                drone.currentInput.throttle = 1.0f;
                drone.isGrounded = false;
                drone.lastCollision = -1000d;
                drone.lastGroundCheck = 0f;
                drone.lastPlayerCheck = 999f;

                if (drone.body != null)
                {
                    if (drone.body.isKinematic)
                        drone.body.isKinematic = false;

                    drone.body.useGravity = false;
                    drone.body.drag = 0.3f;
                    drone.body.angularDrag = 0.6f;
                    drone.body.WakeUp();
                }
            }

            private BaseCombatEntity FindBestTarget()
            {
                float maxDistance = Mathf.Max(18f, tier != null ? tier.maxTargetDistance : 55f);
                float maxDistanceSqr = maxDistance * maxDistance;
                Vector3 center = manager != null ? manager.location : war.location;
                BaseCombatEntity bestTarget = null;
                float bestScore = float.MaxValue;
                uint droneNetId = DroneNetId;

                if (manager.members == null)
                    manager.members = Facepunch.Pool.Get<List<RandomRaider>>();

                foreach (RandomRaider raider in manager.members)
                {
                    if (raider == null)
                        continue;

                    if ((raider.transform.position - center).sqrMagnitude > maxDistanceSqr)
                        continue;

                    if (!plugin.IsSupportDroneEnemy(war, raider))
                        continue;

                    float score = Vector3.Distance(raider.transform.position, center) * 0.6f
                        + Vector3.Distance(raider.transform.position, drone.transform.position) * 0.2f
                        + plugin.GetSupportDroneTargetPenalty(war.warId, droneNetId, raider, center);
                    if (score > maxDistance || score >= bestScore)
                        continue;

                    bestScore = score;
                    bestTarget = raider;
                }

                if (bestTarget != null)
                    return bestTarget;

                foreach (BasePlayer player in BasePlayer.activePlayerList)
                {
                    if (player == null || !player.IsConnected || player.IsDead() || player.IsNpc || player.InSafeZone())
                        continue;
                    if (!plugin.IsSupportDroneEnemy(war, player))
                        continue;
                    if ((player.transform.position - center).sqrMagnitude > maxDistanceSqr)
                        continue;

                    float score = Vector3.Distance(player.transform.position, center) * 0.65f
                        + Vector3.Distance(player.transform.position, drone.transform.position) * 0.25f
                        + plugin.GetSupportDroneTargetPenalty(war.warId, droneNetId, player, center);
                    if (score < bestScore)
                    {
                        bestScore = score;
                        bestTarget = player;
                    }
                }

                return bestTarget;
            }

            private Vector3 GetOrbitPosition()
            {
                Vector3 center = manager != null ? manager.location : war.location;
                float radius = Mathf.Max(10f, tier != null ? tier.orbitRadius : 24f);
                float hoverHeight = Mathf.Max(10f, tier != null ? tier.hoverHeight : 18f);
                int formationCount = 1;
                int formationIndex = plugin != null ? plugin.GetSupportDroneFormationIndex(war.warId, DroneNetId, out formationCount) : 0;
                formationCount = Mathf.Max(1, formationCount);

                orbitAngle = Mathf.Repeat(orbitAngle + Time.fixedDeltaTime * (20f + (formationIndex % 3) * 4f), 360f);
                float slotAngle = (360f / formationCount) * formationIndex;
                float totalAngle = orbitAngle + slotAngle;
                float radiusOffset = ((formationIndex % 2) == 0 ? 1f : -1f) * Mathf.Min(6f, radius * 0.18f);
                float adjustedRadius = Mathf.Max(8f, radius + radiusOffset);
                float adjustedHeight = hoverHeight + ((formationIndex % 3) - 1) * 1.25f;
                Vector3 offset = Quaternion.Euler(0f, totalAngle, 0f) * Vector3.forward * adjustedRadius;
                return new Vector3(center.x + offset.x, center.y + adjustedHeight, center.z + offset.z);
            }

            private Vector3 GetCombatHoverPosition(BaseCombatEntity target)
            {
                if (target == null || target.IsDestroyed)
                    return GetOrbitPosition();

                Vector3 center = manager != null ? manager.location : war.location;
                Vector3 targetPosition = target.CenterPoint();
                float hoverHeight = Mathf.Max(10f, tier != null ? tier.hoverHeight : 18f);
                float keepDistance = Mathf.Max(10f, tier != null ? tier.keepDistance : 18f);
                Vector3 direction = center - targetPosition;
                direction.y = 0f;
                if (direction.sqrMagnitude <= 0.01f)
                    direction = drone.transform.position - targetPosition;
                direction.y = 0f;
                if (direction.sqrMagnitude <= 0.01f)
                    direction = Quaternion.Euler(0f, orbitAngle, 0f) * Vector3.forward;
                direction.Normalize();

                int targetSlot = 0;
                int targetGroupCount = plugin != null ? plugin.GetSupportDroneTargetOccupancy(war.warId, DroneNetId, target, out targetSlot) : 0;
                targetGroupCount = Mathf.Max(1, targetGroupCount);

                int formationCount = 1;
                int formationIndex = plugin != null ? plugin.GetSupportDroneFormationIndex(war.warId, DroneNetId, out formationCount) : 0;
                formationCount = Mathf.Max(1, formationCount);

                float slotAngle = targetGroupCount <= 1
                    ? (360f / formationCount) * formationIndex
                    : (360f / targetGroupCount) * targetSlot;
                Vector3 rotatedDirection = Quaternion.Euler(0f, slotAngle, 0f) * direction;
                int ring = Mathf.Max(0, targetSlot / 3);
                float radialDistance = keepDistance + ring * Mathf.Max(4f, keepDistance * 0.4f);

                Vector3 hover = targetPosition + rotatedDirection * radialDistance;
                hover.y = Mathf.Max(center.y + hoverHeight, targetPosition.y + hoverHeight * 0.45f + ((targetSlot % 3) - 1) * 1.1f);
                return hover;
            }

            private void MoveDrone(Vector3 desiredPosition)
            {
                if (drone == null || drone.IsDestroyed)
                    return;

                Vector3 current = drone.transform.position;
                Vector3 delta = desiredPosition - current;
                float distance = delta.magnitude;
                float moveSpeed = Mathf.Max(3f, tier != null ? tier.moveSpeed : 7f);

                if (drone.body != null)
                {
                    Vector3 desiredVelocity = distance <= 0.25f
                        ? Vector3.zero
                        : delta.normalized * Mathf.Min(moveSpeed, Mathf.Max(1.5f, distance * 0.85f));

                    desiredVelocity.y = Mathf.Clamp(delta.y * 0.9f, -moveSpeed, moveSpeed);
                    drone.body.velocity = Vector3.Lerp(drone.body.velocity, desiredVelocity, 0.22f);
                }
                else
                {
                    drone.transform.position = Vector3.MoveTowards(current, desiredPosition, moveSpeed * Time.fixedDeltaTime);
                }

                if (Time.time >= nextNetworkUpdateAt)
                {
                    nextNetworkUpdateAt = Time.time + 0.35f;
                    drone.SendNetworkUpdate();
                    turret.SendNetworkUpdate();
                }
            }

            private void UpdateDroneFacing(Vector3 desiredPosition)
            {
                if (drone == null || drone.IsDestroyed)
                    return;

                Vector3 focusPoint = currentTarget != null && !currentTarget.IsDestroyed
                    ? currentTarget.CenterPoint()
                    : desiredPosition;

                Vector3 direction = focusPoint - drone.transform.position;
                if (direction.sqrMagnitude <= 0.01f)
                    return;

                direction.y = Mathf.Clamp(direction.y, -0.25f, 0.25f);
                Quaternion desiredRotation = Quaternion.LookRotation(direction.normalized, Vector3.up);
                drone.transform.rotation = Quaternion.RotateTowards(drone.transform.rotation, desiredRotation, Time.fixedDeltaTime * 180f);
            }

            private void UpdateTurretTarget()
            {
                if (turret == null || turret.IsDestroyed)
                    return;

                if (!plugin.IsSupportDroneEnemy(war, currentTarget))
                {
                    turret.target = null;
                    return;
                }

                if (Vector3.Distance(currentTarget.transform.position, drone.transform.position) > Mathf.Max(15f, turret.sightRange + 8f))
                {
                    turret.target = null;
                    return;
                }

                if (turret.target == currentTarget)
                    return;

                turret.SetPeacekeepermode(false);
                turret.target = currentTarget;
                turret.SetTarget(currentTarget);
                turret.OnEntityEnterTrigger(currentTarget);
            }

            private void TryReloadTurret()
            {
                if (Time.time < nextReloadAt || turret == null || turret.IsDestroyed)
                    return;

                nextReloadAt = Time.time + 1.5f;
                BaseProjectile weapon = turret.GetAttachedWeapon() as BaseProjectile;
                if (weapon == null)
                    return;

                if (weapon.primaryMagazine != null && weapon.primaryMagazine.contents <= 1)
                {
                    turret.UpdateTotalAmmo();
                    turret.EnsureReloaded();
                    turret.Reload();
                }
            }

            private void CleanupController()
            {
                currentTarget = null;
                if (turret != null && !turret.IsDestroyed)
                    turret.target = null;
                UnityEngine.Object.Destroy(this);
            }
        }

        public class CobaltTankController : FacepunchBehaviour
        {
            private CobaltWar plugin;
            private EventRandomManager manager;
            private BradleyAPC tank;
            private Vector3 anchorPosition;
            private Vector3 moveTarget;
            private bool indirectFireOnly;
            private int tankIndex;
            private float nextShellAt;
            private float nextTargetRefreshAt;
            private float nextMoveDecisionAt;
            private float moveStartedAt;
            private float lastMoveProgressAt;
            private float lastMoveDistance;
            private float nextEmergencyRelocateAt;
            private float nextHullSyncAt;
            private BaseCombatEntity currentObjective;
            private bool isRelocating;
            private bool reverseRecoveryActive;
            private float reverseRecoveryUntil;
            private int reverseRecoveryAttempts;
            private float reverseTurnDirection;
            private float nextObstacleProbeAt;
            private bool cachedBuildingBlocked;

            public void Initialize(CobaltWar plugin, EventRandomManager manager, BradleyAPC tank, Vector3 anchorPosition, bool indirectFireOnly, int tankIndex)
            {
                this.plugin = plugin;
                this.manager = manager;
                this.tank = tank;
                this.anchorPosition = anchorPosition;
                this.moveTarget = anchorPosition;
                this.indirectFireOnly = indirectFireOnly;
                this.tankIndex = tankIndex;
                this.nextShellAt = Time.time + UnityEngine.Random.Range(2.25f, 4.25f) + (tankIndex * 0.8f);
                this.nextTargetRefreshAt = 0f;
                this.nextMoveDecisionAt = Time.time + Mathf.Max(8f, plugin.configData?.cobaltWar?.tankRepositionIntervalSeconds ?? 18f);
                this.moveStartedAt = Time.time;
                this.lastMoveProgressAt = Time.time;
                this.lastMoveDistance = float.MaxValue;
                this.nextEmergencyRelocateAt = 0f;
                this.nextHullSyncAt = 0f;
                this.isRelocating = false;
                this.reverseRecoveryActive = false;
                this.reverseRecoveryUntil = 0f;
                this.reverseRecoveryAttempts = 0;
                this.reverseTurnDirection = tankIndex % 2 == 0 ? 1f : -1f;
                this.nextObstacleProbeAt = 0f;
                this.cachedBuildingBlocked = false;
            }

            private void FixedUpdate()
            {
                if (plugin == null || manager == null || manager.isDestroyed || tank == null || tank.IsDestroyed)
                {
                    CleanupController();
                    return;
                }

                if (Time.time >= nextTargetRefreshAt || currentObjective == null || currentObjective.IsDestroyed)
                {
                    currentObjective = manager.GetTankObjective(tank.transform.position, currentObjective);
                    nextTargetRefreshAt = Time.time + 1.15f;
                }

                if (currentObjective != null && !currentObjective.IsDestroyed)
                    tank.mainGunTarget = currentObjective;
                else
                    tank.mainGunTarget = null;

                tank.DoWeaponAiming();

                if (!reverseRecoveryActive && (Time.time >= nextMoveDecisionAt || NeedsNewMoveTarget()))
                    RefreshMoveTarget();

                UpdateMovement();

                if (Time.time >= nextShellAt)
                    FireStructuralShell();
            }

            private bool NeedsNewMoveTarget()
            {
                if (tank == null || tank.IsDestroyed || moveTarget == Vector3.zero)
                    return true;

                if (reverseRecoveryActive)
                    return false;

                if (isRelocating)
                {
                    float tolerance = Mathf.Max(5f, plugin.configData?.cobaltWar?.tankDestinationTolerance ?? 9f);
                    if (Vector3.Distance(tank.transform.position, moveTarget) <= tolerance)
                        return false;

                    float stuckWindow = Mathf.Max(6f, (plugin.configData?.cobaltWar?.tankRepositionIntervalSeconds ?? 18f) * 0.55f);
                    return Time.time - lastMoveProgressAt >= stuckWindow;
                }

                if (currentObjective != null && !currentObjective.IsDestroyed)
                {
                    Vector3 impactPoint = GetImpactPoint(currentObjective);
                    if (impactPoint != Vector3.zero && !plugin.HasTankFireSolution(tank.transform.position, impactPoint, indirectFireOnly))
                        return true;
                }

                return Time.time - moveStartedAt >= Mathf.Max(12f, (plugin.configData?.cobaltWar?.tankRepositionIntervalSeconds ?? 18f) * 1.35f);
            }

            private void RefreshMoveTarget()
            {
                ClearReverseRecovery(true);
                float repositionInterval = Mathf.Max(8f, plugin.configData?.cobaltWar?.tankRepositionIntervalSeconds ?? 18f);
                nextMoveDecisionAt = Time.time + repositionInterval;
                moveStartedAt = Time.time;

                Vector3 nextPosition;
                bool nextIndirect;
                if (plugin.TryFindTankSpawn(manager, tankIndex, out nextPosition, out nextIndirect))
                {
                    float minMoveDistance = Mathf.Max(12f, plugin.configData?.cobaltWar?.tankMinimumMoveDistance ?? 20f);
                    if (Vector3.Distance(tank.transform.position, nextPosition) >= minMoveDistance)
                    {
                        moveTarget = nextPosition;
                        indirectFireOnly = nextIndirect;
                        isRelocating = true;
                        lastMoveDistance = Vector3.Distance(tank.transform.position, moveTarget);
                        lastMoveProgressAt = Time.time;
                        ApplyBrakes(false);
                        return;
                    }
                }

                isRelocating = false;
                moveTarget = anchorPosition != Vector3.zero ? anchorPosition : tank.transform.position;
                ApplyBrakes(true);
            }

            private void ApplyBrakes(bool enabled)
            {
                if (tank == null || tank.IsDestroyed)
                    return;

                tank.ApplyBrakeTorque(enabled ? 1f : 0f, true);
                tank.ApplyBrakeTorque(enabled ? 1f : 0f, false);
                if (enabled)
                {
                    tank.leftThrottle = 0f;
                    tank.rightThrottle = 0f;
                    tank.throttle = 0f;
                    tank.turning = 0f;
                }
            }

            private static Vector3 Direction2D(Vector3 target, Vector3 from)
            {
                Vector3 direction = target - from;
                direction.y = 0f;
                return direction.sqrMagnitude <= 0.001f ? Vector3.zero : direction.normalized;
            }

            private void RelocateTank(Vector3 position, bool indirectMode)
            {
                if (tank == null || tank.IsDestroyed || position == Vector3.zero)
                    return;

                ClearReverseRecovery(true);

                Vector3 facing = Direction2D(plugin.GetTankTargetPosition(manager), position);
                if (facing == Vector3.zero)
                    facing = tank.transform.forward;

                if (tank.myRigidBody != null)
                {
                    tank.myRigidBody.velocity = Vector3.zero;
                    tank.myRigidBody.angularVelocity = Vector3.zero;
                }

                tank.transform.position = position;
                tank.transform.rotation = Quaternion.LookRotation(facing, Vector3.up);
                tank.ServerRotation = tank.transform.rotation;
                tank.SendNetworkUpdateImmediate();

                moveTarget = position;
                anchorPosition = position;
                indirectFireOnly = indirectMode;
                isRelocating = false;
                lastMoveDistance = 0f;
                lastMoveProgressAt = Time.time;
                ApplyBrakes(true);
            }

            private void StopRelocation(bool updateAnchor)
            {
                if (tank == null || tank.IsDestroyed)
                    return;

                ClearReverseRecovery(true);

                if (updateAnchor)
                    anchorPosition = tank.transform.position;

                moveTarget = anchorPosition != Vector3.zero ? anchorPosition : tank.transform.position;
                isRelocating = false;
                lastMoveDistance = 0f;
                lastMoveProgressAt = Time.time;
                ApplyBrakes(true);
            }

            private void AlignHullToObjective()
            {
                if (tank == null || tank.IsDestroyed)
                    return;

                Vector3 focusPoint = currentObjective != null && !currentObjective.IsDestroyed
                    ? GetImpactPoint(currentObjective)
                    : plugin.GetTankTargetPosition(manager);

                Vector3 facing = Direction2D(focusPoint, tank.transform.position);
                if (facing == Vector3.zero)
                    return;

                Quaternion desiredRotation = Quaternion.LookRotation(facing, Vector3.up);
                tank.transform.rotation = Quaternion.RotateTowards(tank.transform.rotation, desiredRotation, Time.fixedDeltaTime * 55f);
                tank.ServerRotation = tank.transform.rotation;
                if (Time.time >= nextHullSyncAt)
                {
                    nextHullSyncAt = Time.time + 0.15f;
                    tank.SendNetworkUpdate();
                }
            }

            private void ApplyTrackedMovement(float throttle, float turning)
            {
                if (tank == null || tank.IsDestroyed || tank.myRigidBody == null)
                    return;

                tank.turning = Mathf.Clamp(turning, -1f, 1f);
                tank.throttle = Mathf.Clamp(throttle, -1f, 1f);
                tank.leftThrottle = tank.throttle;
                tank.rightThrottle = tank.throttle;

                if (tank.turning > 0f)
                {
                    tank.rightThrottle = -tank.turning;
                    tank.leftThrottle = tank.turning;
                }
                else if (tank.turning < 0f)
                {
                    tank.leftThrottle = tank.turning;
                    tank.rightThrottle = -tank.turning;
                }

                float throttleBias = tank.throttle;
                tank.leftThrottle = Mathf.Clamp(tank.leftThrottle + throttleBias, -1f, 1f);
                tank.rightThrottle = Mathf.Clamp(tank.rightThrottle + throttleBias, -1f, 1f);

                Vector3 velocity = tank.myRigidBody.velocity;
                float forwardVelocity = velocity.sqrMagnitude > 0.01f ? velocity.magnitude * Mathf.Abs(Vector3.Dot(velocity.normalized, tank.transform.forward)) : 0f;
                float t = Mathf.InverseLerp(2f, 1f, forwardVelocity);
                float torqueAmount = Mathf.Lerp(tank.moveForceMax, tank.turnForce, t);
                float frictionScale = Mathf.InverseLerp(5f, 1.5f, forwardVelocity);
                tank.ScaleSidewaysFriction(1f - frictionScale);
                tank.SetMotorTorque(tank.leftThrottle, false, torqueAmount);
                tank.SetMotorTorque(tank.rightThrottle, true, torqueAmount);
                tank.impactDamager.damageEnabled = velocity.magnitude > 2f && tank.throttle > 0f;
            }

            private void DriveTowards(Vector3 destination)
            {
                if (tank == null || tank.IsDestroyed || tank.myRigidBody == null)
                    return;

                Vector3 direction = Direction2D(destination, tank.transform.position);
                if (direction == Vector3.zero)
                {
                    StopRelocation(true);
                    return;
                }

                float rightDot = Vector3.Dot(direction, tank.transform.right);
                float negativeRightDot = Vector3.Dot(direction, -tank.transform.right);
                float turning;
                if (Vector3.Dot(direction, -tank.transform.forward) > rightDot)
                    turning = rightDot >= negativeRightDot ? 1f : -1f;
                else
                    turning = Mathf.Clamp(rightDot * 3f, -1f, 1f);

                float distance = Vector3.Distance(tank.transform.position, destination);
                float throttle = (0.15f + Mathf.InverseLerp(0f, 24f, distance)) * (1f - Mathf.InverseLerp(0f, 0.35f, Mathf.Abs(turning)));
                ApplyTrackedMovement(throttle, turning);
            }

            private void ClearReverseRecovery(bool resetAttempts)
            {
                reverseRecoveryActive = false;
                reverseRecoveryUntil = 0f;
                if (resetAttempts)
                    reverseRecoveryAttempts = 0;
            }

            private float DetermineReverseTurnDirection()
            {
                Vector3 referencePoint = moveTarget != Vector3.zero
                    ? moveTarget
                    : (currentObjective != null && !currentObjective.IsDestroyed
                        ? GetImpactPoint(currentObjective)
                        : plugin.GetTankTargetPosition(manager));

                Vector3 referenceDirection = Direction2D(referencePoint, tank.transform.position);
                if (referenceDirection != Vector3.zero)
                {
                    float rightDot = Vector3.Dot(referenceDirection, tank.transform.right);
                    if (Mathf.Abs(rightDot) > 0.1f)
                        return rightDot > 0f ? -1f : 1f;
                }

                return ((tankIndex + reverseRecoveryAttempts) % 2 == 0) ? 1f : -1f;
            }

            private bool TryStartReverseRecovery()
            {
                if (tank == null || tank.IsDestroyed)
                    return false;

                ConfigData.CobaltWarSettings settings = plugin.configData?.cobaltWar;
                if (settings == null || !settings.enableTankReverseRecovery)
                    return false;

                int maxAttempts = Mathf.Max(1, settings.tankReverseRecoveryMaxAttempts);
                if (reverseRecoveryActive || reverseRecoveryAttempts >= maxAttempts)
                    return false;

                reverseRecoveryAttempts++;
                reverseRecoveryActive = true;
                reverseRecoveryUntil = Time.time + Mathf.Max(0.5f, settings.tankReverseRecoverySeconds);
                reverseTurnDirection = DetermineReverseTurnDirection();
                nextShellAt = Mathf.Max(nextShellAt, reverseRecoveryUntil + 0.25f);
                ApplyBrakes(false);
                return true;
            }

            private bool UpdateReverseRecovery(bool unsafeProximity, bool buildingBlocked)
            {
                if (!reverseRecoveryActive)
                    return true;

                ConfigData.CobaltWarSettings settings = plugin.configData?.cobaltWar;
                if (settings == null)
                    return false;

                ApplyBrakes(false);
                ApplyTrackedMovement(-Mathf.Clamp(settings.tankReverseRecoveryThrottle, 0.1f, 1f), reverseTurnDirection * Mathf.Clamp(settings.tankReverseRecoveryTurnStrength, 0f, 1f));

                if (Time.time < reverseRecoveryUntil)
                    return true;

                reverseRecoveryActive = false;
                reverseRecoveryUntil = 0f;
                nextTargetRefreshAt = 0f;
                nextMoveDecisionAt = Mathf.Min(nextMoveDecisionAt, Time.time + 1.25f);
                float unsafeDistance = Mathf.Max(16f, (plugin.configData?.cobaltWar?.tankMinimumMoveDistance ?? 20f) * 0.85f);
                unsafeProximity = (tank.transform.position - manager.location).sqrMagnitude < unsafeDistance * unsafeDistance;
                buildingBlocked = ProbeMovementObstacleNow();

                if (!unsafeProximity && !buildingBlocked)
                {
                    lastMoveDistance = Vector3.Distance(tank.transform.position, moveTarget);
                    lastMoveProgressAt = Time.time;
                    reverseRecoveryAttempts = 0;
                    return true;
                }

                return TryStartReverseRecovery();
            }

            private void TryEmergencyRelocate(bool force = false)
            {
                if (!force && Time.time < nextEmergencyRelocateAt)
                    return;

                nextEmergencyRelocateAt = Time.time + 4f;
                Vector3 safePosition;
                bool indirectMode;
                if (plugin.TryFindTankSpawn(manager, tankIndex, out safePosition, out indirectMode))
                {
                    RelocateTank(safePosition, indirectMode);
                    nextMoveDecisionAt = Time.time + Mathf.Max(8f, plugin.configData?.cobaltWar?.tankRepositionIntervalSeconds ?? 18f);
                }
            }

            private void UpdateMovement()
            {
                if (tank == null || tank.IsDestroyed)
                    return;

                float tolerance = Mathf.Max(5f, plugin.configData?.cobaltWar?.tankDestinationTolerance ?? 9f);
                float unsafeDistance = Mathf.Max(16f, (plugin.configData?.cobaltWar?.tankMinimumMoveDistance ?? 20f) * 0.85f);
                float unsafeDistanceSqr = unsafeDistance * unsafeDistance;
                bool unsafeProximity = (tank.transform.position - manager.location).sqrMagnitude < unsafeDistanceSqr;
                bool buildingBlocked = IsMovementObstacleBlocked();
                if (reverseRecoveryActive)
                {
                    if (!UpdateReverseRecovery(unsafeProximity, buildingBlocked))
                        TryEmergencyRelocate(true);
                    return;
                }

                if (unsafeProximity)
                {
                    if (!TryStartReverseRecovery())
                        TryEmergencyRelocate(true);
                    return;
                }

                if (buildingBlocked)
                {
                    if (!TryStartReverseRecovery())
                        TryEmergencyRelocate(true);
                    return;
                }

                if (!isRelocating)
                {
                    ApplyBrakes(true);
                    AlignHullToObjective();
                    return;
                }

                float distanceToTarget = Vector3.Distance(tank.transform.position, moveTarget);
                if (distanceToTarget <= tolerance)
                {
                    StopRelocation(true);
                    return;
                }

                ApplyBrakes(false);
                DriveTowards(moveTarget);

                if (distanceToTarget + 0.75f < lastMoveDistance)
                {
                    lastMoveDistance = distanceToTarget;
                    lastMoveProgressAt = Time.time;
                    reverseRecoveryAttempts = 0;
                }

                float stuckWindow = Mathf.Max(6f, (plugin.configData?.cobaltWar?.tankRepositionIntervalSeconds ?? 18f) * 0.55f);
                if (Time.time - lastMoveProgressAt >= stuckWindow)
                {
                    if (TryStartReverseRecovery())
                    {
                        lastMoveProgressAt = Time.time;
                        return;
                    }

                    TryEmergencyRelocate(true);
                }
            }

            private bool IsMovementObstacleBlocked()
            {
                if (tank == null || tank.IsDestroyed)
                    return false;

                if (Time.time >= nextObstacleProbeAt)
                    ProbeMovementObstacleNow();

                return cachedBuildingBlocked;
            }

            private bool ProbeMovementObstacleNow()
            {
                if (tank == null || tank.IsDestroyed)
                    return false;

                nextObstacleProbeAt = Time.time + 0.2f;
                cachedBuildingBlocked = Physics.CheckSphere(tank.transform.position + Vector3.up, 5f, BuildingLayer, QueryTriggerInteraction.Ignore);
                return cachedBuildingBlocked;
            }

            private Vector3 GetImpactPoint(BaseCombatEntity entity)
            {
                if (entity == null)
                    return manager != null ? manager.location + Vector3.up : Vector3.zero;

                BuildingBlock block = entity as BuildingBlock;
                if (block != null)
                    return block.CenterPoint();

                Vector3 point = entity.transform.position;
                if (entity is BuildingPrivlidge)
                    point += new Vector3(0f, 0.8f, 0f);
                else
                    point += new Vector3(0f, 0.5f, 0f);

                return point;
            }

            private bool IsStructuralCombatEntity(BaseCombatEntity entity)
            {
                if (entity == null || entity.IsDestroyed)
                    return false;

                if (entity is BuildingBlock || entity is BuildingPrivlidge)
                    return true;

                string shortPrefabName = entity.ShortPrefabName ?? string.Empty;
                return shortPrefabName.Contains("wall.external") || shortPrefabName.Contains("gates.external");
            }

            private float GetTankStructureDamageRadius()
            {
                return Mathf.Max(2f, plugin.configData.cobaltWar.tankShellExplosionRadius * 0.85f);
            }

            private float GetTankStructureBoundsRadius()
            {
                return Mathf.Max(50f, plugin.configData.cobaltWar.combatRadius + 25f);
            }

            private bool IsInsideTankRaidBounds(BaseCombatEntity entity)
            {
                return entity != null && !entity.IsDestroyed && Vector3.Distance(entity.transform.position, manager.location) <= GetTankStructureBoundsRadius();
            }

            private bool TryResolveShellTarget(out BaseCombatEntity resolvedTarget, out Vector3 impactPoint)
            {
                resolvedTarget = currentObjective != null && !currentObjective.IsDestroyed
                    ? currentObjective
                    : manager.GetTankObjective(tank.transform.position, currentObjective);

                impactPoint = resolvedTarget != null && !resolvedTarget.IsDestroyed
                    ? GetImpactPoint(resolvedTarget)
                    : plugin.GetTankTargetPosition(manager);

                if (impactPoint == Vector3.zero)
                    return false;

                if (indirectFireOnly)
                {
                    currentObjective = resolvedTarget;
                    return true;
                }

                RaycastHit hit;
                Vector3 fireOrigin = tank.transform.position + new Vector3(0f, 2.4f, 0f);
                Vector3 fireTarget = impactPoint + new Vector3(0f, 1.2f, 0f);
                int fireMask = LayerMask.GetMask("World", "Terrain", "Construction");

                if (!Physics.Linecast(fireOrigin, fireTarget, out hit, fireMask, QueryTriggerInteraction.Ignore))
                {
                    currentObjective = resolvedTarget;
                    return true;
                }

                if (hit.collider == null)
                {
                    if (resolvedTarget != null && !resolvedTarget.IsDestroyed)
                    {
                        currentObjective = resolvedTarget;
                        return true;
                    }

                    return false;
                }

                BaseCombatEntity hitEntity = hit.GetEntity() as BaseCombatEntity;
                if (hitEntity != null && IsStructuralCombatEntity(hitEntity) && IsInsideTankRaidBounds(hitEntity))
                {
                    resolvedTarget = hitEntity;
                    impactPoint = GetImpactPoint(hitEntity);
                    currentObjective = hitEntity;
                    return impactPoint != Vector3.zero;
                }

                if (resolvedTarget != null && !resolvedTarget.IsDestroyed && IsStructuralCombatEntity(resolvedTarget) && IsInsideTankRaidBounds(resolvedTarget))
                {
                    currentObjective = resolvedTarget;
                    return true;
                }

                return indirectFireOnly;
            }

            private void FireStructuralShell()
            {
                if (tank == null || tank.IsDestroyed || manager == null || manager.isDestroyed)
                    return;

                if (reverseRecoveryActive)
                {
                    nextShellAt = Time.time + 0.45f;
                    return;
                }

                float movementSpeed = tank.myRigidBody != null ? tank.myRigidBody.velocity.magnitude : 0f;
                BaseCombatEntity shellTarget;
                Vector3 impactPoint;
                if (!TryResolveShellTarget(out shellTarget, out impactPoint))
                {
                    shellTarget = manager.GetTankObjective(tank.transform.position, null);
                    impactPoint = shellTarget != null && !shellTarget.IsDestroyed
                        ? GetImpactPoint(shellTarget)
                        : plugin.GetTankTargetPosition(manager);

                    float maxAttackDistance = Mathf.Max(40f, plugin.configData?.cobaltWar?.tankAttackDistance ?? 160f);
                    if (impactPoint == Vector3.zero || Vector3.Distance(tank.transform.position, impactPoint) > maxAttackDistance)
                    {
                        nextTargetRefreshAt = 0f;
                        nextShellAt = Time.time + 0.8f;
                        if (!isRelocating)
                            RefreshMoveTarget();
                        return;
                    }
                }

                currentObjective = shellTarget;
                float destinationTolerance = Mathf.Max(6f, plugin.configData?.cobaltWar?.tankDestinationTolerance ?? 9f);
                float distanceToImpactPoint = impactPoint != Vector3.zero ? Vector3.Distance(tank.transform.position, impactPoint) : float.MaxValue;
                float maxAttackDistanceCurrent = Mathf.Max(40f, plugin.configData?.cobaltWar?.tankAttackDistance ?? 160f);
                bool closeAttackWindow = distanceToImpactPoint <= maxAttackDistanceCurrent * 0.65f;
                float relocatingDistance = Vector3.Distance(tank.transform.position, moveTarget);
                float relocatingSpeedLimit = indirectFireOnly ? 3.75f : (closeAttackWindow ? 3.25f : 2.1f);
                if (isRelocating && relocatingDistance > destinationTolerance * 1.2f && movementSpeed > relocatingSpeedLimit)
                {
                    nextShellAt = Time.time + 0.5f;
                    return;
                }

                if (currentObjective != null && !currentObjective.IsDestroyed)
                {
                    float structureDamage = Mathf.Max(10f, plugin.configData.cobaltWar.tankShellDamageBuildings);
                    HitInfo hitInfo = new HitInfo(tank, currentObjective, Rust.DamageType.Explosion, structureDamage, impactPoint);
                    currentObjective.Hurt(hitInfo);
                }

                float structureSplashRadius = GetTankStructureDamageRadius();
                List<BaseCombatEntity> splashEntities = Pool.Get<List<BaseCombatEntity>>();
                try
                {
                    Vis.Entities(impactPoint, structureSplashRadius + 1.5f, splashEntities);

                    foreach (BaseCombatEntity entity in splashEntities)
                    {
                        if (entity == null || entity.IsDestroyed || entity.Health() <= 0f || entity == currentObjective)
                            continue;

                        if (!IsStructuralCombatEntity(entity) || !IsInsideTankRaidBounds(entity))
                            continue;

                        float distanceToImpact = Vector3.Distance(entity.transform.position, impactPoint);
                        if (distanceToImpact > structureSplashRadius)
                            continue;

                        float scaledStructureDamage = Mathf.Lerp(plugin.configData.cobaltWar.tankShellDamageBuildings, plugin.configData.cobaltWar.tankShellDamageBuildings * 0.35f, Mathf.Clamp01(distanceToImpact / structureSplashRadius));
                        HitInfo splashHit = new HitInfo(tank, entity, Rust.DamageType.Explosion, scaledStructureDamage, impactPoint);
                        entity.Hurt(splashHit);
                    }
                }
                finally
                {
                    Pool.FreeUnmanaged(ref splashEntities);
                }

                Effect.server.Run("assets/prefabs/weapons/beancan grenade/effects/beancan_grenade_explosion.prefab", impactPoint);
                nextTargetRefreshAt = 0f;

                float splashRadius = Mathf.Max(1f, plugin.configData.cobaltWar.tankShellExplosionRadius);
                float maxPlayerDamage = Mathf.Max(1f, plugin.configData.cobaltWar.tankShellDamagePlayers);
                foreach (BasePlayer player in BasePlayer.activePlayerList)
                {
                    if (player == null || !player.IsConnected || player.IsDead() || player.IsNpc)
                        continue;

                    if (manager.warSession != null)
                    {
                        if (!manager.warSession.IsInsideCombatArea(player.transform.position))
                            continue;
                        if (manager.warSession.IsFriendlyParticipant(player.userID))
                            continue;
                    }
                    else if (Vector3.Distance(player.transform.position, manager.location) > Mathf.Max(30f, plugin.configData.cobaltWar.combatRadius))
                    {
                        continue;
                    }

                    float protectionRemaining;
                    if (plugin.HasDefenderRespawnProtection(player.userID, out protectionRemaining))
                        continue;

                    float distance = Vector3.Distance(player.transform.position, impactPoint);
                    if (distance > splashRadius)
                        continue;

                    float scaledDamage = Mathf.Lerp(maxPlayerDamage, maxPlayerDamage * 0.25f, Mathf.Clamp01(distance / splashRadius));
                    player.Hurt(scaledDamage, Rust.DamageType.Explosion, tank, false);
                }

                float baseInterval = Mathf.Max(6f, plugin.configData?.cobaltWar?.tankShellIntervalSeconds ?? 12f);
                float intervalScale = 1f;

                if (currentObjective is BuildingPrivlidge)
                    intervalScale *= 0.68f;
                else if (currentObjective is BuildingBlock)
                    intervalScale *= 0.78f;
                else if (currentObjective != null)
                    intervalScale *= 0.86f;

                if (distanceToImpactPoint <= maxAttackDistanceCurrent * 0.45f)
                    intervalScale *= 0.8f;
                else if (distanceToImpactPoint <= maxAttackDistanceCurrent * 0.7f)
                    intervalScale *= 0.9f;

                if (movementSpeed <= 1.2f)
                    intervalScale *= 0.82f;
                else if (movementSpeed <= 2.4f)
                    intervalScale *= 0.92f;

                if (indirectFireOnly)
                    intervalScale *= 0.9f;

                float interval = Mathf.Clamp(baseInterval * intervalScale, 4.25f, baseInterval);
                nextShellAt = Time.time + interval + UnityEngine.Random.Range(0.1f, 0.55f);
            }

            private void CleanupController()
            {
                if (manager != null && tank != null)
                    manager.tanks.Remove(tank);

                UnityEngine.Object.Destroy(this);
            }

            private void OnDestroy()
            {
                if (manager != null && tank != null)
                    manager.tanks.Remove(tank);

                currentObjective = null;
            }
        }
        #endregion

        #region Localization
        public static void GameTipMessage(BasePlayer player, string message)
        {
            if (player != null && player.userID.IsSteamId())
            {
                player?.SendConsoleCommand("gametip.hidegametip");
                player?.SendConsoleCommand("gametip.showgametip", message);
                _.timer.Once(_.configData.settings.gameTipTime, () => player?.SendConsoleCommand("gametip.hidegametip"));
            }
        }

